/*
 * These non-portable interfaces are exported by libSystem but are not exposed
 * by every Command Line Tools SDK's user-space headers.  Their ABI has been
 * stable since macOS 10.12 and mirrors the Darwin guarded-fd syscall surface.
 */
typedef uint64_t aqt_guardid_t;

extern int guarded_open_np(
    const char *path,
    const aqt_guardid_t *guard,
    unsigned int guardflags,
    int flags,
    ...
);
extern int guarded_close_np(int fd, const aqt_guardid_t *guard);
extern int change_fdguard_np(
    int fd,
    const aqt_guardid_t *guard,
    unsigned int guardflags,
    const aqt_guardid_t *new_guard,
    unsigned int new_guardflags,
    int *fdflags
);

#define AQT_GUARD_CLOSE (1U << 0)
#define AQT_GUARD_DUP (1U << 1)
#define AQT_GUARD_FLAGS (AQT_GUARD_CLOSE | AQT_GUARD_DUP)
#endif

