    AqtIssuerChoreographyRecordKey recovery_capability_key;
    AqtIssuerChoreographyRecordKey binder_key;
    uint64_t lifetime_generation;
    uint64_t scope_generation;
    uint64_t binding_generation;
    uint64_t prepared_state_revision;
    uint64_t authorization_serial;
    uint64_t status_state_revision;
