static int
aqt_issuer_choreography_string_manifest_matches(
    const char *const *observed,
    const char *const *expected,
    size_t count
)
{
    size_t index;

    for (index = 0; index < count; index++) {
        size_t other;

        if (observed[index] == NULL
            || expected[index] == NULL
            || strcmp(observed[index], expected[index]) != 0) {
            return 0;
        }
        for (other = index + 1U; other < count; other++) {
            if (observed[other] == NULL
                || strcmp(observed[index], observed[other]) == 0) {
                return 0;
            }
        }
    }
    return 1;
}

