static int
aqt_issuer_choreography_controller_abandon_latched_lineage_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerAbandonRequest *request,
    const AqtIssuerChoreographyStateValue *expected
)
{
    const AqtIssuerChoreographyControllerDurabilityRequest *durability;
    AqtIssuerChoreographyAuthorityCell *cell;
    AqtIssuerChoreographyState *state;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *post_effect;
    AqtIssuerChoreographyRecord *checkpoint;
    AqtIssuerChoreographyRecord *receipt;
    AqtIssuerChoreographyControllerDurabilityBinding *binding;
    AqtIssuerChoreographyStateValue prepared;
    AqtIssuerChoreographyStateValue durable;

    if (shadow == NULL || request == NULL || expected == NULL
        || request->controller_checkpoint_is_present > 1U
        || !aqt_issuer_choreography_controller_abandon_source_value_is_exact(
            expected
        )) {
        return 0;
    }
    durability = &request->durability;
    cell = shadow->choreography_authority_cell;
    state = &shadow->choreography_state;
    lease = durability->lease_record;
    recovery = durability->recovery_record;
    post_effect = durability->post_effect_record;
    checkpoint = request->controller_checkpoint_record;
    receipt = durability->controller_receipt_record;
    binding = receipt != NULL
        ? receipt->controller_durability_binding : NULL;
    if (durability->operation_tag
            != AQT_CHOREOGRAPHY_OPERATION_ABANDON_CONTROLLER
        || cell == NULL || cell->alive != 1U
        || cell->pending_scope_generation != 0U
        || cell->persistent_state_revision != expected->revision
        || cell->binding_generation != expected->binding_generation
        || cell->current_scope_generation != expected->scope_generation
        || !shadow->choreography_state_present
        || memcmp(&state->value, expected, sizeof(*expected)) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin, sizeof(state->failclosed_origin)
        )
        || lease == NULL || recovery == NULL || post_effect == NULL
        || receipt == NULL || binding == NULL
        || (request->controller_checkpoint_is_present
            ? checkpoint == NULL : checkpoint != NULL)
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] != NULL
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != receipt
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            receipt,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        )
        || !aqt_issuer_choreography_record_key_equals(
            &lease->key,
            &expected->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &recovery->key,
            &expected->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &post_effect->key,
            &expected->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ]
        )
        || !aqt_issuer_choreography_memory_is_zero(
            &lease->payload, sizeof(lease->payload)
        )
        || !aqt_issuer_choreography_memory_is_zero(
            &recovery->payload, sizeof(recovery->payload)
        )
        || !aqt_issuer_choreography_memory_is_zero(
            &post_effect->payload, sizeof(post_effect->payload)
        )
        || receipt->prepared_at_revision != expected->revision - 2U
        || memcmp(
            &receipt->payload.controller_receipt,
            &expected->controller_receipt,
            sizeof(expected->controller_receipt)
        ) != 0
        || !aqt_issuer_choreography_controller_durability_binding_is_exact(
            binding
        )
        || !aqt_issuer_choreography_controller_durability_binding_matches_record(
            binding, receipt, cell
        )) {
        return 0;
    }
    if (request->controller_checkpoint_is_present
        && (!checkpoint->wrapper_live || !checkpoint->wrapper_was_created
            || !aqt_issuer_choreography_record_is_exact_locked(
                checkpoint,
                cell,
                AQT_CHOREOGRAPHY_RECORD_WITNESS,
                AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
            )
            || checkpoint->status
                != AQT_CHOREOGRAPHY_WITNESS_DEPENDENCY_TOMBSTONE
            || checkpoint->prepared_at_revision != expected->revision - 3U
            || checkpoint->install_or_terminal_state_revision
                != expected->revision - 1U
            || request->controller_checkpoint_initial_status_revision
                != expected->revision - 1U
            || !aqt_issuer_choreography_record_key_equals(
                &checkpoint->key, &expected->controller_checkpoint.key
            )
            || memcmp(
                &checkpoint->payload.controller_checkpoint,
                &expected->controller_checkpoint,
                sizeof(expected->controller_checkpoint)
            ) != 0)) {
        return 0;
    }
    aqt_issuer_choreography_controller_durability_binding_source_value(
        binding, &prepared
    );
    aqt_issuer_choreography_build_controller_durable_candidate_locked(
        &prepared, binding->binding_sha256, &durable
    );
    return prepared.revision == expected->revision - 1U
        && memcmp(&durable, expected, sizeof(durable)) == 0
        && aqt_issuer_choreography_controller_durability_binding_matches_publications(
            binding,
            &prepared,
            lease,
            recovery,
            post_effect,
            durability->lease_initial_status_revision,
            durability->recovery_initial_status_revision,
            durability->post_effect_initial_status_revision,
            durability->source_lifecycle_revision,
            durability->source_was_burned,
            durability->source_launch_lease
        );
}

