static int
aqt_require_active_module(PyObject *module)
{
    AqtModuleState *state;

    if (!PyModule_CheckExact(module)) {
        PyErr_SetString(PyExc_RuntimeError, "native descriptor module identity is invalid");
        return -1;
    }
    if (PyInterpreterState_Get() != PyInterpreterState_Main()) {
        PyErr_SetString(PyExc_RuntimeError, "native descriptor module interpreter is invalid");
        return -1;
    }
    state = (AqtModuleState *)PyModule_GetState(module);
    if (state == NULL) {
        if (!PyErr_Occurred()) {
            PyErr_SetString(PyExc_RuntimeError, "native descriptor module is not active");
        }
        return -1;
    }
    if (state->initialized != 2) {
        PyErr_SetString(PyExc_RuntimeError, "native descriptor module is not active");
        return -1;
    }
    if (state->origin_pid != getpid()) {
        PyErr_SetString(PyExc_RuntimeError, "native descriptor module process is invalid");
        return -1;
    }
#if defined(AQT_NATIVE_EMBEDDED_LAUNCHER)
    if (atomic_load_explicit(
            &aqt_process_module_activation,
            memory_order_acquire
        ) != 2) {
        PyErr_SetString(PyExc_RuntimeError, "native descriptor process activation is invalid");
        return -1;
    }
#endif
    return 0;
}

