static int
aqt_issuer_manifests_are_exact(void)
{
    const unsigned int expected_policy = (1U << 15) - 1U;
    size_t authority_index;
    size_t full_index;

    if (strcmp(
            aqt_issuer_prototype_stage_name,
            "_stage_topology_observation_issuer_projection_type"
        ) != 0
        || aqt_issuer_type_policy_manifest != expected_policy) {
        return 0;
    }

    for (full_index = 0; full_index < 84; full_index++) {
        AqtTopologyObservationIssuerMemberKind expected_kind =
            full_index == 0
                ? AQT_ISSUER_MEMBER_TP_INIT
                : full_index == 1
                ? AQT_ISSUER_MEMBER_CLASSMETHOD
                : (full_index == 2 || full_index == 3)
                    ? AQT_ISSUER_MEMBER_GETSET
                    : full_index == 8
                        ? AQT_ISSUER_MEMBER_TP_REPR
                        : AQT_ISSUER_MEMBER_METHOD;
        AqtTopologyObservationIssuerAuthenticationTag expected_authentication =
            full_index == 4
                ? AQT_ISSUER_AUTH_OPEN
                : (full_index == 59 || full_index == 60)
                    ? AQT_ISSUER_AUTH_CHOREOGRAPHY
                    : full_index == 79
                        ? AQT_ISSUER_AUTH_CURSOR
                        : full_index == 80
                            ? AQT_ISSUER_AUTH_CREATED
                            : full_index == 81
                                ? AQT_ISSUER_AUTH_STAGED_UNRELEASED
                                : full_index == 82
                                    ? AQT_ISSUER_AUTH_FINAL_ACTION_STAGED_UNRELEASED
                                    : AQT_ISSUER_AUTH_NONE;
        size_t other_index;

        if (aqt_issuer_full_member_manifest[full_index].name == NULL
            || aqt_issuer_full_member_manifest[full_index].name[0] == '\0'
            || aqt_issuer_full_member_manifest[full_index].kind != expected_kind
            || aqt_issuer_full_authentication_manifest[full_index]
                != expected_authentication) {
            return 0;
        }
        for (other_index = full_index + 1; other_index < 84; other_index++) {
            if (strcmp(
                    aqt_issuer_full_member_manifest[full_index].name,
                    aqt_issuer_full_member_manifest[other_index].name
                ) == 0) {
                return 0;
            }
        }
    }
    for (authority_index = 0;
         authority_index < AQT_ISSUER_METHOD_COUNT;
         authority_index++) {
        size_t mapped_index = authority_index < 28
            ? authority_index + 13
            : authority_index < 48
                ? authority_index + 14
                : 83;

        if (strcmp(
                aqt_issuer_authority_method_names[authority_index],
                aqt_issuer_full_member_manifest[mapped_index].name
            ) != 0) {
            return 0;
        }
    }
    return 1;
}

