static int
aqt_issuer_choreography_parse_controller_checkpoint_payload(
    PyObject *payload,
    AqtIssuerChoreographyControllerPreparationRequest *request
)
{
    PyObject *claim_object;

    if (!PyTuple_CheckExact(payload) || PyTuple_GET_SIZE(payload) != 3) {
        PyErr_SetString(
            PyExc_TypeError,
            "native issuer choreography controller-checkpoint payload is invalid"
        );
        return -1;
    }
    claim_object = PyTuple_GET_ITEM(payload, 0);
    if (!Py_IS_TYPE(claim_object, &AqtIssuerChoreographyWitnessType)
        || aqt_issuer_choreography_parse_controller_outcome_kind(
            PyTuple_GET_ITEM(payload, 1),
            &request->outcome_kind
        ) < 0
        || aqt_issuer_choreography_parse_recovery_time_selector(
            PyTuple_GET_ITEM(payload, 2),
            &request->selector
        ) < 0) {
        PyErr_Clear();
        PyErr_SetString(
            PyExc_TypeError,
            "native issuer choreography controller-checkpoint payload is invalid"
        );
        return -1;
    }
    request->claim_record =
        ((AqtIssuerChoreographyWitness *)claim_object)->record;
    return 0;
}

static int
aqt_issuer_choreography_parse_controller_receipt_payload(
    PyObject *payload,
    AqtIssuerChoreographyControllerReceiptPreparationRequest *request
)
{
    AqtIssuerChoreographyControllerReceiptProjection *receipt;
    AqtIssuerChoreographyProjection5 *projection;
    PyObject *claim_object;
    PyObject *checkpoint_object;
    PyObject *locator_object;
    int contract_v1;
    int contract_v2;
    int confirmed;
    int release_unconfirmed;
    int sequence_unconfirmed;
    int success_unconfirmed;

    if (request == NULL
        || !PyTuple_CheckExact(payload)
        || PyTuple_GET_SIZE(payload) != 13) {
        PyErr_SetString(
            PyExc_TypeError,
            "native issuer choreography controller-receipt payload is invalid"
        );
        return -1;
    }
    memset(request, 0, sizeof(*request));
    receipt = &request->receipt_projection;
    projection = &receipt->projection;
    claim_object = PyTuple_GET_ITEM(payload, 0);
    checkpoint_object = PyTuple_GET_ITEM(payload, 1);
    locator_object = PyTuple_GET_ITEM(payload, 12);
    if (!Py_IS_TYPE(claim_object, &AqtIssuerChoreographyWitnessType)
        || !Py_IS_TYPE(
            checkpoint_object,
            &AqtIssuerChoreographyWitnessType
        )
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 2),
            projection->operation_id,
            sizeof(projection->operation_id),
            36U,
            36U,
            "operation_id",
            NULL
        ) < 0
        || !aqt_issuer_choreography_uuid4_is_exact(projection->operation_id)
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 3),
            projection->approval_sha256,
            sizeof(projection->approval_sha256),
            64U,
            64U,
            "approval_sha256",
            NULL
        ) < 0
        || !aqt_issuer_choreography_sha256_is_exact(
            projection->approval_sha256
        )
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 4),
            projection->claim_sha256,
            sizeof(projection->claim_sha256),
            64U,
            64U,
            "claim_sha256",
            NULL
        ) < 0
        || !aqt_issuer_choreography_sha256_is_exact(projection->claim_sha256)
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 5),
            projection->retained_artifact_sha256,
            sizeof(projection->retained_artifact_sha256),
            64U,
            64U,
            "retained_artifact_sha256",
            NULL
        ) < 0
        || !aqt_issuer_choreography_sha256_is_exact(
            projection->retained_artifact_sha256
        )
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 6),
            projection->artifact_directory,
            sizeof(projection->artifact_directory),
            1U,
            sizeof(projection->artifact_directory) - 1U,
            "artifact_directory",
            &projection->artifact_directory_length
        ) < 0
        || !aqt_issuer_choreography_root_text_is_exact(
            projection->artifact_directory,
            projection->artifact_directory_length
        )
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 7),
            receipt->admission_sha256,
            sizeof(receipt->admission_sha256),
            64U,
            64U,
            "admission_sha256",
            NULL
        ) < 0
        || !aqt_issuer_choreography_sha256_is_exact(
            receipt->admission_sha256
        )
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 8),
            receipt->contract_version,
            sizeof(receipt->contract_version),
            1U,
            sizeof(receipt->contract_version) - 1U,
            "contract_version",
            NULL
        ) < 0
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 9),
            receipt->status,
            sizeof(receipt->status),
            1U,
            sizeof(receipt->status) - 1U,
            "status",
            NULL
        ) < 0
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 10),
            receipt->reason,
            sizeof(receipt->reason),
            1U,
            sizeof(receipt->reason) - 1U,
            "reason",
            NULL
        ) < 0
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 11),
            receipt->outcome_sha256,
            sizeof(receipt->outcome_sha256),
            64U,
            64U,
            "outcome_sha256",
            NULL
        ) < 0
        || !aqt_issuer_choreography_sha256_is_exact(
            receipt->outcome_sha256
        )) {
        goto invalid;
    }
    if (locator_object != Py_None) {
        if (aqt_issuer_choreography_copy_unicode(
                locator_object,
                receipt->locator_sha256,
                sizeof(receipt->locator_sha256),
                64U,
                64U,
                "locator_sha256",
                NULL
            ) < 0
            || !aqt_issuer_choreography_sha256_is_exact(
                receipt->locator_sha256
            )) {
            goto invalid;
        }
        receipt->locator_is_present = 1U;
    }
    contract_v1 = aqt_issuer_choreography_fixed_text_equals(
        receipt->contract_version,
        sizeof(receipt->contract_version),
        aqt_issuer_choreography_controller_contract_names[0]
    );
    contract_v2 = aqt_issuer_choreography_fixed_text_equals(
        receipt->contract_version,
        sizeof(receipt->contract_version),
        aqt_issuer_choreography_controller_contract_names[1]
    );
    confirmed = aqt_issuer_choreography_fixed_text_equals(
        receipt->status,
        sizeof(receipt->status),
        aqt_issuer_choreography_controller_status_names[0]
    ) && aqt_issuer_choreography_fixed_text_equals(
        receipt->reason,
        sizeof(receipt->reason),
        aqt_issuer_choreography_controller_reason_names[0]
    );
    release_unconfirmed = aqt_issuer_choreography_fixed_text_equals(
        receipt->status,
        sizeof(receipt->status),
        aqt_issuer_choreography_controller_status_names[1]
    ) && aqt_issuer_choreography_fixed_text_equals(
        receipt->reason,
        sizeof(receipt->reason),
        aqt_issuer_choreography_controller_reason_names[1]
    );
    sequence_unconfirmed = aqt_issuer_choreography_fixed_text_equals(
        receipt->status,
        sizeof(receipt->status),
        aqt_issuer_choreography_controller_status_names[1]
    ) && aqt_issuer_choreography_fixed_text_equals(
        receipt->reason,
        sizeof(receipt->reason),
        aqt_issuer_choreography_controller_reason_names[2]
    );
    success_unconfirmed = aqt_issuer_choreography_fixed_text_equals(
        receipt->status,
        sizeof(receipt->status),
        aqt_issuer_choreography_controller_status_names[1]
    ) && aqt_issuer_choreography_fixed_text_equals(
        receipt->reason,
        sizeof(receipt->reason),
        aqt_issuer_choreography_controller_reason_names[3]
    );
    if ((!contract_v1 && !contract_v2)
        || !(confirmed || release_unconfirmed
            || sequence_unconfirmed || success_unconfirmed)
        || (contract_v1 && receipt->locator_is_present)
        || (contract_v2
            && receipt->locator_is_present
                != (unsigned int)(confirmed || success_unconfirmed))) {
        goto invalid;
    }
    request->claim_record =
        ((AqtIssuerChoreographyWitness *)claim_object)->record;
    request->checkpoint_record =
        ((AqtIssuerChoreographyWitness *)checkpoint_object)->record;
    return 0;

invalid:
    PyErr_Clear();
    PyErr_SetString(
        PyExc_TypeError,
        "native issuer choreography controller-receipt payload is invalid"
    );
    return -1;
}

static int
aqt_issuer_choreography_parse_recovery_receipt_payload(
    PyObject *payload,
    AqtIssuerChoreographyRecoveryPreparationRequest *request
)
{
    AqtIssuerChoreographyRecoveryReceiptProjection *receipt =
        &request->receipt_projection;
    AqtIssuerChoreographyProjection5 *projection = &receipt->projection;
    PyObject *claim_object;
    PyObject *checkpoint_object;

    if (!PyTuple_CheckExact(payload) || PyTuple_GET_SIZE(payload) != 8) {
        PyErr_SetString(
            PyExc_TypeError,
            "native recovery-receipt payload must be an exact len-8 tuple"
        );
        return -1;
    }
    claim_object = PyTuple_GET_ITEM(payload, 0);
    checkpoint_object = PyTuple_GET_ITEM(payload, 1);
    if (!Py_IS_TYPE(claim_object, &AqtIssuerChoreographyWitnessType)
        || !Py_IS_TYPE(checkpoint_object, &AqtIssuerChoreographyWitnessType)) {
        PyErr_SetString(
            PyExc_TypeError,
            "native recovery-receipt dependencies are invalid"
        );
        return -1;
    }
    memset(receipt, 0, sizeof(*receipt));
    if (aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 2),
            projection->operation_id,
            sizeof(projection->operation_id),
            36U,
            36U,
            "operation_id",
            NULL
        ) < 0
        || !aqt_issuer_choreography_uuid4_is_exact(projection->operation_id)
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 3),
            projection->approval_sha256,
            sizeof(projection->approval_sha256),
            64U,
            64U,
            "approval_sha256",
            NULL
        ) < 0
        || !aqt_issuer_choreography_sha256_is_exact(
            projection->approval_sha256
        )
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 4),
            projection->claim_sha256,
            sizeof(projection->claim_sha256),
            64U,
            64U,
            "claim_sha256",
            NULL
        ) < 0
        || !aqt_issuer_choreography_sha256_is_exact(projection->claim_sha256)
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 5),
            projection->retained_artifact_sha256,
            sizeof(projection->retained_artifact_sha256),
            64U,
            64U,
            "retained_artifact_sha256",
            NULL
        ) < 0
        || !aqt_issuer_choreography_sha256_is_exact(
            projection->retained_artifact_sha256
        )
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 6),
            projection->artifact_directory,
            sizeof(projection->artifact_directory),
            1U,
            sizeof(projection->artifact_directory) - 1U,
            "artifact_directory",
            &projection->artifact_directory_length
        ) < 0
        || !aqt_issuer_choreography_root_text_is_exact(
            projection->artifact_directory,
            projection->artifact_directory_length
        )
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(payload, 7),
            receipt->outcome_sha256,
            sizeof(receipt->outcome_sha256),
            64U,
            64U,
            "outcome_sha256",
            NULL
        ) < 0
        || !aqt_issuer_choreography_sha256_is_exact(receipt->outcome_sha256)) {
        if (!PyErr_Occurred()) {
            PyErr_SetString(
                PyExc_ValueError,
                "native recovery-receipt payload is invalid"
            );
        }
        return -1;
    }
    memcpy(
        receipt->status,
        aqt_issuer_choreography_recovery_receipt_literals[0],
        strlen(aqt_issuer_choreography_recovery_receipt_literals[0]) + 1U
    );
    memcpy(
        receipt->reason,
        aqt_issuer_choreography_recovery_receipt_literals[1],
        strlen(aqt_issuer_choreography_recovery_receipt_literals[1]) + 1U
    );
    request->kind = AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT;
    request->claim_record =
        ((AqtIssuerChoreographyWitness *)claim_object)->record;
    request->checkpoint_record =
        ((AqtIssuerChoreographyWitness *)checkpoint_object)->record;
    return 0;
}

static AqtIssuerChoreographyRecord *
aqt_allocate_issuer_choreography_record(
    AqtIssuerChoreographyAuthorityCell *cell,
    unsigned int record_class,
    unsigned int kind,
    uint64_t scope_generation
)
{
    AqtIssuerChoreographyRecord *record;
    PyInterpreterState *current_interpreter;
    pid_t current_pid;
    uint64_t serial;

    if (cell == NULL
        || scope_generation == 0U
        || record_class > AQT_CHOREOGRAPHY_RECORD_WITNESS
        || (record_class == AQT_CHOREOGRAPHY_RECORD_AUTHORITY
            && kind >= AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT)
        || (record_class == AQT_CHOREOGRAPHY_RECORD_WITNESS
            && kind >= AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT)) {
        PyErr_SetString(PyExc_RuntimeError, "native choreography record kind is invalid");
        return NULL;
    }
    record = PyMem_Calloc(1, sizeof(*record));
    if (record == NULL) {
        PyErr_NoMemory();
        return NULL;
    }
    current_pid = getpid();
    current_interpreter = PyInterpreterState_Get();
    aqt_lock_owner_list_or_fail_stop();
    if (!cell->alive
        || cell->origin_pid != current_pid
        || cell->origin_interpreter != current_interpreter
        || (scope_generation != cell->current_scope_generation
            && scope_generation != cell->pending_scope_generation)
        || cell->checked_serial == UINT64_MAX) {
        aqt_unlock_owner_list_or_fail_stop();
        PyMem_Free(record);
        PyErr_SetString(PyExc_RuntimeError, "native choreography record owner is unavailable");
        return NULL;
    }
    serial = ++cell->checked_serial;
    record->key.lifetime_generation = cell->lifetime_generation;
    record->key.scope_generation = scope_generation;
    record->key.serial = serial;
    record->prepared_at_revision = cell->persistent_state_revision;
    record->install_or_terminal_state_revision = 0U;
    record->record_class = record_class;
    record->kind = kind;
    record->status = record_class == AQT_CHOREOGRAPHY_RECORD_AUTHORITY
        ? AQT_CHOREOGRAPHY_AUTHORITY_PREPARED
        : AQT_CHOREOGRAPHY_WITNESS_PREPARED;
    record->wrapper_live = 0U;
    record->wrapper_was_created = 0U;
    record->cell = cell;
    atomic_init(&record->reference_count, 1U);
    aqt_issuer_choreography_authority_cell_incref(cell);
    aqt_unlock_owner_list_or_fail_stop();
    return record;
}

static PyObject *
aqt_issuer_choreography_reject_clone(
    PyObject *self,
    PyObject *Py_UNUSED(ignored)
)
{
    (void)self;
    PyErr_SetString(PyExc_TypeError, "native choreography handles cannot be cloned");
    return NULL;
}

static PyObject *
aqt_issuer_choreography_reject_clone_argument(
    PyObject *self,
    PyObject *ignored
)
{
    (void)self;
    (void)ignored;
    PyErr_SetString(PyExc_TypeError, "native choreography handles cannot be cloned");
    return NULL;
}

