static void
aqt_issuer_choreography_authority_dealloc(
    AqtIssuerChoreographyAuthority *wrapper
)
{
    AqtIssuerChoreographyRecord *record;

    aqt_lock_owner_list_or_fail_stop();
    record = wrapper->record;
    wrapper->record = NULL;
    if (record != NULL) {
        if (!record->wrapper_live) {
            abort();
        }
        record->wrapper_live = 0U;
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (wrapper->weakreflist != NULL) {
        PyObject_ClearWeakRefs((PyObject *)wrapper);
    }
    aqt_issuer_choreography_record_decref(record);
    PyObject_Del(wrapper);
}

static void
aqt_issuer_choreography_witness_dealloc(
    AqtIssuerChoreographyWitness *wrapper
)
{
    AqtIssuerChoreographyRecord *record;

    aqt_lock_owner_list_or_fail_stop();
    record = wrapper->record;
    wrapper->record = NULL;
    if (record != NULL) {
        if (!record->wrapper_live) {
            abort();
        }
        record->wrapper_live = 0U;
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (wrapper->weakreflist != NULL) {
        PyObject_ClearWeakRefs((PyObject *)wrapper);
    }
    aqt_issuer_choreography_record_decref(record);
    PyObject_Del(wrapper);
}

static void
aqt_issuer_claimed_fence_authorization_dealloc(
    AqtIssuerClaimedFenceAuthorization *authorization
)
{
    AqtIssuerChoreographyRecord *binder_record;

    aqt_lock_owner_list_or_fail_stop();
    binder_record = authorization->binder_record;
    authorization->binder_record = NULL;
    if (binder_record != NULL
        && (authorization->authorization_serial == 0U
            || binder_record->claimed_fence_authorization_serial
                != authorization->authorization_serial)) {
        abort();
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (authorization->weakreflist != NULL) {
        PyObject_ClearWeakRefs((PyObject *)authorization);
    }
    aqt_issuer_choreography_record_decref(binder_record);
    PyObject_Del(authorization);
}

static AqtIssuerClaimedFenceAuthorization *
aqt_allocate_issuer_claimed_fence_authorization(void)
{
    AqtIssuerClaimedFenceAuthorization *authorization = PyObject_New(
        AqtIssuerClaimedFenceAuthorization,
        &AqtIssuerClaimedFenceAuthorizationType
    );

    if (authorization == NULL) {
        return NULL;
    }
    authorization->weakreflist = NULL;
    authorization->binder_record = NULL;
    memset(
        &authorization->lease_key,
        0,
        sizeof(*authorization) - offsetof(
            AqtIssuerClaimedFenceAuthorization,
            lease_key
        )
    );
    return authorization;
}

static PyObject *
aqt_allocate_issuer_choreography_wrapper(
    AqtIssuerChoreographyRecord *record
)
{
    PyObject *result;

    if (record->record_class == AQT_CHOREOGRAPHY_RECORD_AUTHORITY) {
        AqtIssuerChoreographyAuthority *wrapper = PyObject_New(
            AqtIssuerChoreographyAuthority,
            &AqtIssuerChoreographyAuthorityType
        );
        if (wrapper == NULL) {
            return NULL;
        }
        wrapper->weakreflist = NULL;
        wrapper->record = record;
        result = (PyObject *)wrapper;
    }
    else {
        AqtIssuerChoreographyWitness *wrapper = PyObject_New(
            AqtIssuerChoreographyWitness,
            &AqtIssuerChoreographyWitnessType
        );
        if (wrapper == NULL) {
            return NULL;
        }
        wrapper->weakreflist = NULL;
        wrapper->record = record;
        result = (PyObject *)wrapper;
    }
    aqt_lock_owner_list_or_fail_stop();
    if (record->wrapper_live || record->wrapper_was_created) {
        aqt_unlock_owner_list_or_fail_stop();
        if (record->record_class == AQT_CHOREOGRAPHY_RECORD_AUTHORITY) {
            ((AqtIssuerChoreographyAuthority *)result)->record = NULL;
        }
        else {
            ((AqtIssuerChoreographyWitness *)result)->record = NULL;
        }
        Py_DECREF(result);
        PyErr_SetString(PyExc_RuntimeError, "native choreography record is already wrapped");
        return NULL;
    }
    record->wrapper_live = 1U;
    record->wrapper_was_created = 1U;
    aqt_unlock_owner_list_or_fail_stop();
    return result;
}

static int
aqt_issuer_choreography_current_claim_payload_is_exact(
    const AqtIssuerChoreographyClaimSummary *claim_payload,
    const AqtIssuerChoreographyStateValue *state_value
)
{
    return claim_payload != NULL
        && state_value != NULL
        && state_value->phase == AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED
        && state_value->roots_are_present == 1U
        && aqt_issuer_choreography_record_key_is_empty(&claim_payload->key)
        && aqt_issuer_choreography_projection5_is_exact(
            &claim_payload->projection,
            state_value
        )
        && aqt_issuer_choreography_sha256_is_exact(
            claim_payload->binding_sha256
        );
}

static int
aqt_issuer_choreography_current_state_source_is_exact_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    unsigned int required_phase,
    const AqtIssuerChoreographyClaimSummary *claim_payload,
    pid_t current_pid,
    PyInterpreterState *current_interpreter,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    const AqtIssuerChoreographyAuthorityCell *cell;
    const AqtIssuerChoreographyState *state;
    const AqtIssuerChoreographyStateValue *value;
    const AqtIssuerActivationProjection *projection;
    const AqtIssuerChoreographyRecord *lease_record;
    const AqtIssuerChoreographyRecord *recovery_record;

    if (shadow == NULL
        || (required_phase != AQT_CHOREOGRAPHY_PHASE_UNBOUND
            && required_phase != AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED)
        || current_pid <= 0
        || current_interpreter == NULL
        || current_thread == NULL
        || current_thread_id == 0U
        || shadow->origin_pid != current_pid
        || shadow->origin_interpreter != current_interpreter
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        || shadow->poisoned != 0U
        || shadow->closed != 0U
        || shadow->busy != 0U
        || shadow->runtime_ready != 0U
        || !shadow->choreography_state_present
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)) {
        return 0;
    }
    cell = shadow->choreography_authority_cell;
    state = &shadow->choreography_state;
    value = &state->value;
    projection = shadow->projection;
    lease_record = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery_record = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    if (cell == NULL
        || cell->alive != 1U
        || cell->action_live != 1U
        || cell->lifecycle_disposition != AQT_CHOREOGRAPHY_CELL_ACTIVE
        || cell->pending_scope_generation != 0U
        || value->revision != cell->persistent_state_revision
        || value->binding_generation != cell->binding_generation
        || value->scope_generation != cell->current_scope_generation
        || value->phase != required_phase
        || value->action_active != 1U
        || lease_record == NULL
        || recovery_record == NULL
        || lease_record->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery_record->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || !aqt_issuer_choreography_record_key_equals(
            &lease_record->key,
            &value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &recovery_record->key,
            &value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        || projection == NULL
        || !aqt_issuer_choreography_dynamic_root_text_is_exact(
            projection->artifact_directory,
            projection->artifact_directory_length
        )
        || !aqt_issuer_choreography_dynamic_root_text_is_exact(
            projection->ignored_root,
            projection->ignored_root_length
        )) {
        return 0;
    }
    if (claim_payload != NULL
        && (!aqt_issuer_choreography_current_claim_payload_is_exact(
                claim_payload,
                value
            )
            || claim_payload->projection.artifact_directory_length
                != projection->artifact_directory_length
            || memcmp(
                claim_payload->projection.artifact_directory,
                projection->artifact_directory,
                projection->artifact_directory_length + 1U
            ) != 0)) {
        return 0;
    }
    return claim_payload != NULL
        || required_phase == AQT_CHOREOGRAPHY_PHASE_UNBOUND;
}

static void
aqt_issuer_choreography_capture_current_state_source_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyCurrentPreparationSource *source
)
{
    const AqtIssuerActivationProjection *projection = shadow->projection;

    memset(source, 0, sizeof(*source));
    source->cell = shadow->choreography_authority_cell;
    source->state = shadow->choreography_state;
    source->artifact_directory_length =
        projection->artifact_directory_length;
    memcpy(
        source->artifact_directory,
        projection->artifact_directory,
        projection->artifact_directory_length + 1U
    );
    source->ignored_root_length = projection->ignored_root_length;
    memcpy(
        source->ignored_root,
        projection->ignored_root,
        projection->ignored_root_length + 1U
    );
    source->origin_pid = shadow->origin_pid;
    source->origin_interpreter = shadow->origin_interpreter;
    source->origin_thread_state = shadow->activation_thread_state;
    source->origin_thread_id = shadow->activation_thread_id;
}

static int
aqt_issuer_choreography_current_state_source_matches_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    unsigned int required_phase,
    const AqtIssuerChoreographyClaimSummary *claim_payload,
    const AqtIssuerChoreographyCurrentPreparationSource *source,
    pid_t current_pid,
    PyInterpreterState *current_interpreter,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    const AqtIssuerActivationProjection *projection;

    if (source == NULL
        || !aqt_issuer_choreography_current_state_source_is_exact_locked(
            shadow,
            required_phase,
            claim_payload,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        )
        || source->cell != shadow->choreography_authority_cell
        || source->origin_pid != shadow->origin_pid
        || source->origin_interpreter != shadow->origin_interpreter
        || source->origin_thread_state != shadow->activation_thread_state
        || source->origin_thread_id != shadow->activation_thread_id
        || memcmp(
            &source->state,
            &shadow->choreography_state,
            sizeof(source->state)
        ) != 0) {
        return 0;
    }
    projection = shadow->projection;
    return projection != NULL
        && source->artifact_directory_length
            == projection->artifact_directory_length
        && source->ignored_root_length == projection->ignored_root_length
        && memcmp(
            source->artifact_directory,
            projection->artifact_directory,
            source->artifact_directory_length + 1U
        ) == 0
        && memcmp(
            source->ignored_root,
            projection->ignored_root,
            source->ignored_root_length + 1U
        ) == 0;
}

static int
aqt_issuer_choreography_current_state_prepare_preflight(
    AqtTopologyObservationIssuerShadow *shadow,
    unsigned int required_phase,
    const AqtIssuerChoreographyClaimSummary *claim_payload
)
{
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    int exact;

    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0) {
        return -1;
    }
    if (atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer foreign-fork interposition does not match current-State preparation"
        );
        return -1;
    }
    aqt_lock_owner_list_or_fail_stop();
    exact = aqt_issuer_choreography_current_state_source_is_exact_locked(
        shadow,
        required_phase,
        claim_payload,
        current_pid,
        current_interpreter,
        current_thread,
        current_thread_id
    );
    aqt_unlock_owner_list_or_fail_stop();
    if (!exact) {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer current-State choreography preparation is unavailable"
        );
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_prepare_preflight(
    AqtTopologyObservationIssuerShadow *shadow
)
{
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        || shadow->choreography_state_present
        || !aqt_issuer_shadow_invariants_are_exact(shadow)
        || !aqt_issuer_shadow_has_live_lease(shadow)) {
        if (!PyErr_Occurred()) {
            PyErr_SetString(
                PyExc_RuntimeError,
                "native issuer choreography preparation is unavailable"
            );
        }
        return -1;
    }
    if (atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer foreign-fork interposition does not match preparation"
        );
        return -1;
    }
    return 0;
}

static PyObject *aqt_allocate_unpublished_issuer_choreography_wrapper(
    unsigned int record_class
);

static void aqt_publish_unpublished_issuer_choreography_wrapper_locked(
    PyObject *wrapper,
    AqtIssuerChoreographyRecord *record
);

static int
aqt_issuer_choreography_post_effect_preparation_source_is_exact_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    pid_t current_pid,
    PyInterpreterState *current_interpreter,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    const AqtIssuerChoreographyAuthorityCell *cell;
    const AqtIssuerChoreographyState *state;
    const AqtIssuerChoreographyStateValue *value;
    const AqtIssuerChoreographyRecord *lease;
    const AqtIssuerChoreographyRecord *recovery;
    const AqtIssuerChoreographyRecord *claim;

    if (shadow == NULL
        || current_pid <= 0
        || current_interpreter == NULL
        || current_thread == NULL
        || current_thread_id == 0U
        || shadow->origin_pid != current_pid
        || shadow->origin_interpreter != current_interpreter
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        || shadow->revision != 3U
        || shadow->poisoned != 0U
        || shadow->closed != 0U
        || shadow->busy != 0U
        || shadow->runtime_ready != 0U
        || !shadow->choreography_state_present
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->projection == NULL
        || aqt_issuer_projection_is_roots_only(shadow->projection)) {
        return 0;
    }
    cell = shadow->choreography_authority_cell;
    state = &shadow->choreography_state;
    value = &state->value;
    lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    claim = state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
    ];
    return cell != NULL
        && cell->alive == 1U
        && cell->action_live == 1U
        && cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_ACTIVE
        && cell->pending_scope_generation == 0U
        && value->revision == cell->persistent_state_revision
        && value->binding_generation == cell->binding_generation
        && value->scope_generation == cell->current_scope_generation
        && aqt_issuer_choreography_post_effect_source_value_is_exact(value)
        && aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )
        && lease != NULL
        && recovery != NULL
        && claim != NULL
        && state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] == NULL
        && state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] == NULL
        && state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] == NULL
        && lease->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && claim->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        && aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        && aqt_issuer_choreography_record_key_equals(
            &lease->key,
            &value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        && aqt_issuer_choreography_record_key_equals(
            &recovery->key,
            &value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        && aqt_issuer_choreography_record_key_equals(
            &claim->key,
            &value->claim.key
        )
        && memcmp(&claim->payload.claim, &value->claim, sizeof(value->claim))
            == 0;
}

static int
aqt_issuer_choreography_post_effect_preparation_source_matches_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyCurrentPreparationSource *source,
    pid_t current_pid,
    PyInterpreterState *current_interpreter,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    const AqtIssuerActivationProjection *projection;

    if (source == NULL
        || !aqt_issuer_choreography_post_effect_preparation_source_is_exact_locked(
            shadow,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        )
        || source->cell != shadow->choreography_authority_cell
        || source->origin_pid != shadow->origin_pid
        || source->origin_interpreter != shadow->origin_interpreter
        || source->origin_thread_state != shadow->activation_thread_state
        || source->origin_thread_id != shadow->activation_thread_id
        || memcmp(
            &source->state,
            &shadow->choreography_state,
            sizeof(source->state)
        ) != 0) {
        return 0;
    }
    projection = shadow->projection;
    return projection != NULL
        && source->artifact_directory_length
            == projection->artifact_directory_length
        && source->ignored_root_length == projection->ignored_root_length
        && memcmp(
            source->artifact_directory,
            projection->artifact_directory,
            source->artifact_directory_length + 1U
        ) == 0
        && memcmp(
            source->ignored_root,
            projection->ignored_root,
            source->ignored_root_length + 1U
        ) == 0;
}

static PyObject *
aqt_issuer_choreography_prepare_post_effect_authority(
    AqtModuleState *module_state,
    AqtTopologyObservationIssuerShadow *shadow
)
{
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerChoreographyCurrentPreparationSource source;
    AqtIssuerChoreographyAuthorityCell *cell;
    AqtIssuerChoreographyRecord *record = NULL;
    AqtIssuerFailure failure = {0};
    PyObject *wrapper = NULL;
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    PyThreadState *current_thread = PyThreadState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    int configured_kind = -1;
    int source_changed = 0;
    int plan_began = 0;

    memset(&source, 0, sizeof(source));
    if (module_state == NULL
        || aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0) {
        return NULL;
    }
    if (atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer foreign-fork interposition does not match post-effect preparation"
        );
        return NULL;
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    cell = shadow->choreography_authority_cell;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_post_effect_preparation_source_is_exact_locked(
            shadow,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        )
        || aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            0,
            -1,
            0U,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography post-effect outcome capability preparation is unavailable"
        );
        return NULL;
    }
    plan_began = 1;
    aqt_issuer_choreography_capture_current_state_source_locked(
        shadow,
        &source
    );
    aqt_unlock_owner_list_or_fail_stop();

    record = aqt_allocate_issuer_choreography_record(
        cell,
        AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
        AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY,
        source.state.value.scope_generation
    );
    if (record == NULL) {
        aqt_issuer_failure_capture_python(&failure);
        goto cleanup;
    }
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_post_effect_preparation_source_matches_locked(
            shadow,
            &source,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        )) {
        source_changed = 1;
    }
    else {
        configured_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_AUTHORITY_POST_ALLOC,
            1,
            current_pid,
            current_interpreter
        );
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (source_changed) {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography post-effect preparation source changed after allocation"
        );
        aqt_issuer_failure_capture_python(&failure);
        goto cleanup;
    }
    if (configured_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, configured_kind);
        goto cleanup;
    }
    wrapper = aqt_allocate_unpublished_issuer_choreography_wrapper(
        AQT_CHOREOGRAPHY_RECORD_AUTHORITY
    );
    if (wrapper == NULL) {
        aqt_issuer_failure_capture_python(&failure);
        goto cleanup;
    }
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_post_effect_preparation_source_matches_locked(
            shadow,
            &source,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        )
        || record->cell != cell
        || record->key.scope_generation != source.state.value.scope_generation
        || record->prepared_at_revision != source.state.value.revision
        || record->status != AQT_CHOREOGRAPHY_AUTHORITY_PREPARED
        || record->install_or_terminal_state_revision != 0U
        || record->claimed_fence_authorization_serial != 0U
        || record->wrapper_live
        || record->wrapper_was_created
        || !aqt_issuer_choreography_memory_is_zero(
            &record->payload,
            sizeof(record->payload)
        )) {
        source_changed = 1;
    }
    else {
        aqt_publish_unpublished_issuer_choreography_wrapper_locked(
            wrapper,
            record
        );
        record = NULL;
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (source_changed) {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography post-effect preparation source changed before publication"
        );
        aqt_issuer_failure_capture_python(&failure);
        goto cleanup;
    }
    aqt_lock_owner_list_or_fail_stop();
    configured_kind = aqt_issuer_choreography_fault_take_locked(
        fault_plan,
        shadow,
        AQT_CHOREOGRAPHY_FAULT_AUTHORITY_PRE_RETURN,
        1,
        current_pid,
        current_interpreter
    );
    if (configured_kind < 0) {
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (configured_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, configured_kind);
        goto cleanup;
    }
    return wrapper;

cleanup:
    if (PyErr_Occurred()) {
        aqt_issuer_failure_capture_python(&failure);
    }
    Py_CLEAR(wrapper);
    aqt_issuer_choreography_record_decref(record);
    if (plan_began) {
        aqt_lock_owner_list_or_fail_stop();
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
    }
    return aqt_issuer_choreography_failure_raise(&failure);
}

static PyObject *
aqt_issuer_choreography_prepare_record(
    AqtModuleState *module_state,
    AqtTopologyObservationIssuerShadow *shadow,
    unsigned int record_class,
    unsigned int kind,
    int fault_group,
    int post_alloc_point,
    int pre_return_point,
    const AqtIssuerChoreographyClaimSummary *claim_payload
)
{
    AqtIssuerChoreographyFaultPlan *fault_plan =
        &module_state->issuer_choreography_fault_plan;
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyRecord *record = NULL;
    AqtIssuerFailure failure = {0};
    PyObject *wrapper = NULL;
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    PyThreadState *current_thread = PyThreadState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    uint64_t pending_scope = 0U;
    int configured_kind = -1;
    int plan_began = 0;

    if (aqt_issuer_choreography_prepare_preflight(shadow) < 0) {
        return NULL;
    }
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        || shadow->choreography_state_present
        || cell == NULL
        || !cell->alive
        || !cell->action_live
        || cell->lifecycle_disposition != AQT_CHOREOGRAPHY_CELL_ACTIVE
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || (claim_payload != NULL
            && (shadow->projection == NULL
                || shadow->projection->artifact_directory == NULL
                || shadow->projection->artifact_directory_length
                    != claim_payload->projection.artifact_directory_length
                || memcmp(
                    shadow->projection->artifact_directory,
                    claim_payload->projection.artifact_directory,
                    claim_payload->projection.artifact_directory_length + 1U
                ) != 0))) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography preparation changed during preflight"
        );
        return NULL;
    }
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            fault_group,
            -1,
            0U,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography fault plan does not match preparation"
        );
        return NULL;
    }
    plan_began = 1;
    if (cell->pending_scope_generation == 0U) {
        if (cell->current_scope_generation == UINT64_MAX) {
            aqt_unlock_owner_list_or_fail_stop();
            PyErr_SetString(
                PyExc_OverflowError,
                "native issuer choreography pending scope generation is exhausted"
            );
            aqt_issuer_failure_capture_python(&failure);
            goto cleanup;
        }
        cell->pending_scope_generation = cell->current_scope_generation + 1U;
    }
    pending_scope = cell->pending_scope_generation;
    aqt_unlock_owner_list_or_fail_stop();

    record = aqt_allocate_issuer_choreography_record(
        cell,
        record_class,
        kind,
        pending_scope
    );
    if (record == NULL) {
        aqt_issuer_failure_capture_python(&failure);
        goto cleanup;
    }
    if (claim_payload != NULL) {
        record->payload.claim = *claim_payload;
        record->payload.claim.key = record->key;
    }
    aqt_lock_owner_list_or_fail_stop();
    configured_kind = aqt_issuer_choreography_fault_take_locked(
        fault_plan,
        shadow,
        post_alloc_point,
        1,
        current_pid,
        current_interpreter
    );
    aqt_unlock_owner_list_or_fail_stop();
    if (configured_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, configured_kind);
        goto cleanup;
    }
    wrapper = aqt_allocate_issuer_choreography_wrapper(record);
    if (wrapper == NULL) {
        aqt_issuer_failure_capture_python(&failure);
        goto cleanup;
    }
    record = NULL;
    aqt_lock_owner_list_or_fail_stop();
    configured_kind = aqt_issuer_choreography_fault_take_locked(
        fault_plan,
        shadow,
        pre_return_point,
        1,
        current_pid,
        current_interpreter
    );
    aqt_unlock_owner_list_or_fail_stop();
    if (configured_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, configured_kind);
        goto cleanup;
    }
    aqt_lock_owner_list_or_fail_stop();
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    return wrapper;

cleanup:
    if (PyErr_Occurred()) {
        aqt_issuer_failure_capture_python(&failure);
    }
    Py_CLEAR(wrapper);
    aqt_issuer_choreography_record_decref(record);
    if (plan_began) {
        aqt_lock_owner_list_or_fail_stop();
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
    }
    return aqt_issuer_choreography_failure_raise(&failure);
}

static int
aqt_issuer_choreography_controller_preparation_source_is_exact_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerPreparationRequest *request,
    pid_t current_pid,
    PyInterpreterState *current_interpreter,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    const AqtIssuerChoreographyAuthorityCell *cell;
    const AqtIssuerChoreographyState *state;
    const AqtIssuerChoreographyStateValue *value;
    const AqtIssuerChoreographyRecord *lease;
    const AqtIssuerChoreographyRecord *recovery;
    const AqtIssuerChoreographyRecord *claim;
    const AqtIssuerChoreographyRecord *post_effect;
    int source_is_burned;

    if (shadow == NULL
        || request == NULL
        || request->outcome_kind > AQT_CHOREOGRAPHY_OUTCOME_FAILURE
        || request->selector >= AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT
        || current_pid <= 0
        || current_interpreter == NULL
        || current_thread == NULL
        || current_thread_id == 0U
        || shadow->origin_pid != current_pid
        || shadow->origin_interpreter != current_interpreter
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || (shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
            && shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED)
        || shadow->closed != 0U
        || shadow->busy != 0U
        || shadow->runtime_ready != 0U
        || !shadow->choreography_state_present
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)) {
        return 0;
    }
    source_is_burned = shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED;
    if ((request->outcome_kind == AQT_CHOREOGRAPHY_OUTCOME_SUCCESS
            && source_is_burned)
        || (source_is_burned
            ? (shadow->revision != 4U
                || shadow->poisoned != 1U
                || shadow->projection == NULL
                || !aqt_issuer_projection_is_roots_only(shadow->projection))
            : (shadow->revision != 3U
                || shadow->poisoned != 0U
                || shadow->projection == NULL
                || aqt_issuer_projection_is_roots_only(shadow->projection)))) {
        return 0;
    }
    cell = shadow->choreography_authority_cell;
    state = &shadow->choreography_state;
    value = &state->value;
    lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    post_effect = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
    ];
    claim = state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
    ];
    return cell != NULL
        && cell->alive == 1U
        && cell->action_live == (unsigned int)!source_is_burned
        && cell->lifecycle_disposition
            == (source_is_burned
                ? AQT_CHOREOGRAPHY_CELL_BURNED
                : AQT_CHOREOGRAPHY_CELL_ACTIVE)
        && cell->pending_scope_generation == 0U
        && value->revision == cell->persistent_state_revision
        && value->binding_generation == cell->binding_generation
        && value->scope_generation == cell->current_scope_generation
        && aqt_issuer_choreography_controller_source_value_is_exact(value)
        && aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )
        && lease != NULL
        && recovery != NULL
        && post_effect != NULL
        && claim != NULL
        && claim == request->claim_record
        && claim->wrapper_live
        && claim->wrapper_was_created
        && state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] == NULL
        && state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] == NULL
        && lease->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && post_effect->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && claim->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        && aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        && aqt_issuer_choreography_record_key_equals(
            &lease->key,
            &value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        && aqt_issuer_choreography_record_key_equals(
            &recovery->key,
            &value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        && aqt_issuer_choreography_record_key_equals(
            &post_effect->key,
            &value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ]
        )
        && aqt_issuer_choreography_record_key_equals(
            &claim->key,
            &value->claim.key
        )
        && memcmp(&claim->payload.claim, &value->claim, sizeof(value->claim))
            == 0;
}

static int
aqt_issuer_choreography_controller_preparation_source_matches_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerPreparationRequest *request,
    const AqtIssuerChoreographyCurrentPreparationSource *source,
    pid_t current_pid,
    PyInterpreterState *current_interpreter,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    const AqtIssuerActivationProjection *projection;

    if (source == NULL
        || !aqt_issuer_choreography_controller_preparation_source_is_exact_locked(
            shadow,
            request,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        )
        || source->cell != shadow->choreography_authority_cell
        || source->origin_pid != shadow->origin_pid
        || source->origin_interpreter != shadow->origin_interpreter
        || source->origin_thread_state != shadow->activation_thread_state
        || source->origin_thread_id != shadow->activation_thread_id
        || memcmp(
            &source->state,
            &shadow->choreography_state,
            sizeof(source->state)
        ) != 0) {
        return 0;
    }
    projection = shadow->projection;
    return projection != NULL
        && source->artifact_directory_length
            == projection->artifact_directory_length
        && source->ignored_root_length == projection->ignored_root_length
        && memcmp(
            source->artifact_directory,
            projection->artifact_directory,
            source->artifact_directory_length + 1U
        ) == 0
        && memcmp(
            source->ignored_root,
            projection->ignored_root,
            source->ignored_root_length + 1U
        ) == 0;
}

static void
aqt_issuer_choreography_build_controller_preparation_payload_locked(
    const AqtIssuerChoreographyControllerPreparationRequest *request,
    const AqtIssuerChoreographyStateValue *value,
    uint64_t sampled_now,
    AqtIssuerChoreographyRecordPayload *payload
)
{
    AqtIssuerChoreographyControllerCheckpointProjection *projection;

    memset(payload, 0, sizeof(*payload));
    projection = &payload->controller_checkpoint.projection;
    projection->claim_key = value->claim.key;
    projection->outcome_kind = request->outcome_kind;
    projection->artifact_directory_length = value->artifact_directory_length;
    memcpy(
        projection->artifact_directory,
        value->artifact_directory,
        sizeof(projection->artifact_directory)
    );
    projection->ignored_root_length = value->ignored_root_length;
    memcpy(
        projection->ignored_root,
        value->ignored_root,
        sizeof(projection->ignored_root)
    );
    projection->started_monotonic_ns = value->started_monotonic_ns;
    projection->action_deadline_monotonic_ns =
        value->action_deadline_monotonic_ns;
    projection->selected_deadline_monotonic_ns =
        request->outcome_kind == AQT_CHOREOGRAPHY_OUTCOME_SUCCESS
            ? value->action_deadline_monotonic_ns
            : value->retention_deadline_monotonic_ns;
    switch (request->selector) {
        case AQT_CHOREOGRAPHY_TIME_SAME:
        case AQT_CHOREOGRAPHY_TIME_ROLLBACK:
            projection->observed_monotonic_ns = value->last_monotonic_ns;
            break;
        case AQT_CHOREOGRAPHY_TIME_SAMPLE:
            projection->observed_monotonic_ns = sampled_now;
            break;
        case AQT_CHOREOGRAPHY_TIME_ACTION_DEADLINE:
            projection->observed_monotonic_ns =
                value->action_deadline_monotonic_ns;
            break;
        case AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE:
            projection->observed_monotonic_ns =
                value->retention_deadline_monotonic_ns;
            break;
        default:
            abort();
    }
}

static PyObject *
aqt_issuer_choreography_prepare_controller_checkpoint(
    AqtModuleState *module_state,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerPreparationRequest *request
)
{
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerChoreographyCurrentPreparationSource source;
    AqtIssuerChoreographyRecordPayload payload;
    AqtIssuerChoreographyAuthorityCell *cell;
    AqtIssuerChoreographyRecord *record = NULL;
    AqtIssuerFailure failure = {0};
    PyObject *wrapper = NULL;
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    PyThreadState *current_thread = PyThreadState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    uint64_t sampled_now = 0U;
    int configured_kind = -1;
    int plan_began = 0;
    int source_changed = 0;
    int sample_error = 0;

    memset(&source, 0, sizeof(source));
    memset(&payload, 0, sizeof(payload));
    if (module_state == NULL
        || shadow == NULL
        || request == NULL
        || aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0) {
        return NULL;
    }
    if (atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography controller checkpoint is unavailable"
        );
        return NULL;
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_controller_preparation_source_is_exact_locked(
            shadow,
            request,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        )
        || aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            1,
            -1,
            0U,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography controller checkpoint is unavailable"
        );
        return NULL;
    }
    plan_began = 1;
    if (request->selector == AQT_CHOREOGRAPHY_TIME_SAMPLE
        && aqt_issuer_choreography_sample_continuous_ns(&sampled_now) < 0) {
        sample_error = errno != 0 ? errno : EIO;
    }
    aqt_issuer_choreography_capture_current_state_source_locked(shadow, &source);
    if (!sample_error) {
        aqt_issuer_choreography_build_controller_preparation_payload_locked(
            request,
            &source.state.value,
            sampled_now,
            &payload
        );
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (sample_error) {
        aqt_issuer_failure_record_errno(&failure, sample_error);
        goto cleanup;
    }
    cell = source.cell;
    record = aqt_allocate_issuer_choreography_record(
        cell,
        AQT_CHOREOGRAPHY_RECORD_WITNESS,
        AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT,
        source.state.value.scope_generation
    );
    if (record == NULL) {
        aqt_issuer_failure_capture_python(&failure);
        goto cleanup;
    }
    record->payload = payload;
    record->payload.controller_checkpoint.key = record->key;
    record->prepared_time_selector_present = 1U;
    record->prepared_time_selector = request->selector;
    record->prepared_source_last_monotonic_ns =
        source.state.value.last_monotonic_ns;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_controller_preparation_source_matches_locked(
            shadow,
            request,
            &source,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        )
        || record->cell != cell
        || record->key.scope_generation != source.state.value.scope_generation
        || record->prepared_at_revision != source.state.value.revision
        || record->status != AQT_CHOREOGRAPHY_WITNESS_PREPARED
        || record->install_or_terminal_state_revision != 0U
        || record->wrapper_live
        || record->wrapper_was_created
        || !aqt_issuer_choreography_record_is_exact_locked(
            record,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )) {
        source_changed = 1;
    }
    else {
        configured_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_WITNESS_POST_ALLOC,
            1,
            current_pid,
            current_interpreter
        );
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (source_changed) {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography controller checkpoint is unavailable"
        );
        aqt_issuer_failure_capture_python(&failure);
        goto cleanup;
    }
    if (configured_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, configured_kind);
        goto cleanup;
    }
    wrapper = aqt_allocate_unpublished_issuer_choreography_wrapper(
        AQT_CHOREOGRAPHY_RECORD_WITNESS
    );
    if (wrapper == NULL) {
        aqt_issuer_failure_capture_python(&failure);
        goto cleanup;
    }
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_controller_preparation_source_matches_locked(
            shadow,
            request,
            &source,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            record,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )
        || record->wrapper_live
        || record->wrapper_was_created) {
        source_changed = 1;
    }
    else {
        aqt_publish_unpublished_issuer_choreography_wrapper_locked(
            wrapper,
            record
        );
        record = NULL;
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (source_changed) {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography controller checkpoint is unavailable"
        );
        aqt_issuer_failure_capture_python(&failure);
        goto cleanup;
    }
    aqt_lock_owner_list_or_fail_stop();
    configured_kind = aqt_issuer_choreography_fault_take_locked(
        fault_plan,
        shadow,
        AQT_CHOREOGRAPHY_FAULT_WITNESS_PRE_RETURN,
        1,
        current_pid,
        current_interpreter
    );
    if (configured_kind < 0) {
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (configured_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, configured_kind);
        goto cleanup;
    }
    return wrapper;

cleanup:
    if (PyErr_Occurred()) {
        aqt_issuer_failure_capture_python(&failure);
    }
    Py_CLEAR(wrapper);
    aqt_issuer_choreography_record_decref(record);
    if (plan_began) {
        aqt_lock_owner_list_or_fail_stop();
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
    }
    return aqt_issuer_choreography_failure_raise(&failure);
}

static int
aqt_issuer_choreography_controller_receipt_preparation_source_is_exact_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerReceiptPreparationRequest *request,
    pid_t current_pid,
    PyInterpreterState *current_interpreter,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    const AqtIssuerChoreographyAuthorityCell *cell;
    const AqtIssuerChoreographyState *state;
    const AqtIssuerChoreographyStateValue *value;
    const AqtIssuerChoreographyRecord *lease;
    const AqtIssuerChoreographyRecord *recovery;
    const AqtIssuerChoreographyRecord *claim;
    const AqtIssuerChoreographyRecord *post_effect;
    const AqtIssuerChoreographyRecord *checkpoint;
    const AqtIssuerChoreographyControllerReceiptProjection *receipt;
    int source_is_burned;
    int confirmed;
    int failure_shape;

    if (shadow == NULL || request == NULL
        || current_pid <= 0 || current_interpreter == NULL
        || current_thread == NULL || current_thread_id == 0U
        || shadow->origin_pid != current_pid
        || shadow->origin_interpreter != current_interpreter
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || (shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
            && shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED)
        || shadow->closed != 0U || shadow->busy != 0U
        || shadow->runtime_ready != 0U
        || !shadow->choreography_state_present
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)) {
        return 0;
    }
    source_is_burned = shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED;
    if (source_is_burned
        ? (shadow->revision != 4U || shadow->poisoned != 1U
            || shadow->projection == NULL
            || !aqt_issuer_projection_is_roots_only(shadow->projection))
        : (shadow->revision != 3U || shadow->poisoned != 0U
            || shadow->projection == NULL
            || aqt_issuer_projection_is_roots_only(shadow->projection))) {
        return 0;
    }
    cell = shadow->choreography_authority_cell;
    state = &shadow->choreography_state;
    value = &state->value;
    lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    post_effect = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
    ];
    claim = state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
    ];
    checkpoint = state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
    ];
    receipt = &request->receipt_projection;
    confirmed = aqt_issuer_choreography_fixed_text_equals(
        receipt->status,
        sizeof(receipt->status),
        aqt_issuer_choreography_controller_status_names[0]
    ) && aqt_issuer_choreography_fixed_text_equals(
        receipt->reason,
        sizeof(receipt->reason),
        aqt_issuer_choreography_controller_reason_names[0]
    );
    failure_shape = aqt_issuer_choreography_fixed_text_equals(
        receipt->status,
        sizeof(receipt->status),
        aqt_issuer_choreography_controller_status_names[1]
    ) && (aqt_issuer_choreography_fixed_text_equals(
            receipt->reason,
            sizeof(receipt->reason),
            aqt_issuer_choreography_controller_reason_names[1]
        ) || aqt_issuer_choreography_fixed_text_equals(
            receipt->reason,
            sizeof(receipt->reason),
            aqt_issuer_choreography_controller_reason_names[2]
        ) || aqt_issuer_choreography_fixed_text_equals(
            receipt->reason,
            sizeof(receipt->reason),
            aqt_issuer_choreography_controller_reason_names[3]
        ));
    return cell != NULL && cell->alive == 1U
        && cell->action_live == (unsigned int)!source_is_burned
        && cell->lifecycle_disposition
            == (source_is_burned
                ? AQT_CHOREOGRAPHY_CELL_BURNED
                : AQT_CHOREOGRAPHY_CELL_ACTIVE)
        && cell->pending_scope_generation == 0U
        && value->revision == cell->persistent_state_revision
        && value->binding_generation == cell->binding_generation
        && value->scope_generation == cell->current_scope_generation
        && value->phase == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONSUMING
        && value->action_active == 0U
        && value->revision <= UINT64_MAX - 2U
        && aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )
        && state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] == NULL
        && aqt_issuer_choreography_record_key_is_empty(
            &value->controller_receipt.key
        )
        && lease != NULL && recovery != NULL && post_effect != NULL
        && claim != NULL && checkpoint != NULL
        && request->claim_record == claim
        && request->checkpoint_record == checkpoint
        && claim->wrapper_live && claim->wrapper_was_created
        && checkpoint->wrapper_live && checkpoint->wrapper_was_created
        && lease->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && post_effect->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && claim->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        && checkpoint->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        && aqt_issuer_choreography_record_is_exact_locked(
            lease, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            recovery, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            post_effect, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            claim, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            checkpoint, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )
        && aqt_issuer_choreography_record_payload_matches_state(
            claim, value, AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        && aqt_issuer_choreography_record_payload_matches_state(
            checkpoint,
            value,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )
        && memcmp(
            &receipt->projection,
            &value->claim.projection,
            sizeof(receipt->projection)
        ) == 0
        && (checkpoint->payload.controller_checkpoint.projection.outcome_kind
                == AQT_CHOREOGRAPHY_OUTCOME_SUCCESS
            ? confirmed && !source_is_burned
            : failure_shape);
}

static int
aqt_issuer_choreography_controller_receipt_preparation_source_matches_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerReceiptPreparationRequest *request,
    const AqtIssuerChoreographyCurrentPreparationSource *source,
    pid_t current_pid,
    PyInterpreterState *current_interpreter,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    const AqtIssuerActivationProjection *projection;

    if (source == NULL
        || !aqt_issuer_choreography_controller_receipt_preparation_source_is_exact_locked(
            shadow,
            request,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        )
        || source->cell != shadow->choreography_authority_cell
        || source->origin_pid != shadow->origin_pid
        || source->origin_interpreter != shadow->origin_interpreter
        || source->origin_thread_state != shadow->activation_thread_state
        || source->origin_thread_id != shadow->activation_thread_id
        || memcmp(
            &source->state,
            &shadow->choreography_state,
            sizeof(source->state)
        ) != 0) {
        return 0;
    }
    projection = shadow->projection;
    return projection != NULL
        && source->artifact_directory_length
            == projection->artifact_directory_length
        && source->ignored_root_length == projection->ignored_root_length
        && memcmp(
            source->artifact_directory,
            projection->artifact_directory,
            source->artifact_directory_length + 1U
        ) == 0
        && memcmp(
            source->ignored_root,
            projection->ignored_root,
            source->ignored_root_length + 1U
        ) == 0;
}

static void
aqt_issuer_choreography_build_controller_receipt_preparation_payload_locked(
    const AqtIssuerChoreographyControllerReceiptPreparationRequest *request,
    const AqtIssuerChoreographyStateValue *value,
    AqtIssuerChoreographyRecordPayload *payload
)
{
    memset(payload, 0, sizeof(*payload));
    payload->controller_receipt.mode = AQT_CHOREOGRAPHY_RECEIPT_PREPARED;
    payload->controller_receipt.projection = request->receipt_projection;
    payload->controller_receipt.claim_tombstone = value->claim;
    payload->controller_receipt.checkpoint_tombstone =
        value->controller_checkpoint;
}

