static PyObject *
aqt_issuer_choreography_controller_receipt_summary_snapshot(
    const AqtIssuerChoreographyControllerReceiptSummary *summary
)
{
    PyObject *result = PyTuple_New(6);
    PyObject *key = NULL;
    PyObject *mode = NULL;
    PyObject *projection5 = NULL;
    PyObject *locator = NULL;
    PyObject *projection = NULL;
    PyObject *claim = NULL;
    PyObject *checkpoint = NULL;
    PyObject *binding = NULL;

    if (result != NULL) {
        key = aqt_issuer_choreography_record_key_snapshot(&summary->key);
    }
    if (key != NULL) {
        mode = PyUnicode_FromString(
            summary->mode == AQT_CHOREOGRAPHY_RECEIPT_DURABLE
                ? "durable"
                : "prepared"
        );
    }
    if (mode != NULL) {
        projection5 = aqt_issuer_choreography_projection5_snapshot(
            &summary->projection.projection
        );
    }
    if (projection5 != NULL) {
        locator = summary->projection.locator_is_present
            ? PyUnicode_FromString(summary->projection.locator_sha256)
            : Py_NewRef(Py_None);
    }
    if (locator != NULL) {
        projection = Py_BuildValue(
            "(NsssssN)",
            projection5,
            summary->projection.admission_sha256,
            summary->projection.contract_version,
            summary->projection.status,
            summary->projection.reason,
            summary->projection.outcome_sha256,
            locator
        );
        projection5 = NULL;
        locator = NULL;
    }
    if (projection != NULL) {
        claim = aqt_issuer_choreography_claim_summary_snapshot(
            &summary->claim_tombstone
        );
    }
    if (claim != NULL) {
        checkpoint = aqt_issuer_choreography_controller_checkpoint_summary_snapshot(
            &summary->checkpoint_tombstone
        );
    }
    if (checkpoint != NULL) {
        binding = summary->mode == AQT_CHOREOGRAPHY_RECEIPT_DURABLE
            ? PyUnicode_FromString(summary->durability_binding_sha256)
            : Py_NewRef(Py_None);
    }
    if (result == NULL || key == NULL || mode == NULL
        || projection == NULL || claim == NULL || checkpoint == NULL
        || binding == NULL) {
        Py_XDECREF(binding);
        Py_XDECREF(checkpoint);
        Py_XDECREF(claim);
        Py_XDECREF(projection);
        Py_XDECREF(locator);
        Py_XDECREF(projection5);
        Py_XDECREF(mode);
        Py_XDECREF(key);
        Py_XDECREF(result);
        return NULL;
    }
    PyTuple_SET_ITEM(result, 0, key);
    PyTuple_SET_ITEM(result, 1, mode);
    PyTuple_SET_ITEM(result, 2, projection);
    PyTuple_SET_ITEM(result, 3, claim);
    PyTuple_SET_ITEM(result, 4, checkpoint);
    PyTuple_SET_ITEM(result, 5, binding);
    return result;
}

static PyObject *
aqt_issuer_choreography_empty_snapshot(void)
{
    return PyTuple_New(0);
}

static int
aqt_issuer_choreography_state_snapshot_phase_is_available(
    unsigned int phase
)
{
    switch (phase) {
        case AQT_CHOREOGRAPHY_PHASE_UNBOUND:
        case AQT_CHOREOGRAPHY_PHASE_BINDER_ISSUED:
        case AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED:
        case AQT_CHOREOGRAPHY_PHASE_ARMED:
        case AQT_CHOREOGRAPHY_PHASE_RECOVERY_CONSUMING:
        case AQT_CHOREOGRAPHY_PHASE_RECOVERY_CONFIRMED:
        case AQT_CHOREOGRAPHY_PHASE_RECOVERY_UNCONFIRMED:
        case AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED:
        case AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONSUMING:
        case AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONFIRMED:
        case AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED:
        case AQT_CHOREOGRAPHY_PHASE_EXPIRED:
        case AQT_CHOREOGRAPHY_PHASE_REVOKED:
            return 1;
        default:
            return 0;
    }
}

static int
aqt_issuer_choreography_state_snapshot_post_effect_key_is_present(
    const AqtIssuerChoreographyStateValue *value
)
{
    return value != NULL
        && !aqt_issuer_choreography_record_key_is_empty(
            &value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ]
        );
}

static int
aqt_issuer_choreography_state_snapshot_controller_checkpoint_key_is_present(
    const AqtIssuerChoreographyStateValue *value
)
{
    return value != NULL
        && !aqt_issuer_choreography_record_key_is_empty(
            &value->controller_checkpoint.key
        );
}

static PyObject *
aqt_issuer_choreography_state_snapshot(
    AqtTopologyObservationIssuerShadow *shadow
)
{
    AqtIssuerChoreographyStateValue value;
    AqtIssuerChoreographyAuthorityCell *cell;
    PyObject *result = NULL;
    PyObject *values[AQT_ISSUER_CHOREOGRAPHY_STATE_SNAPSHOT_TUPLE_SIZE] = {
        NULL
    };
    PyThreadState *current_thread = PyThreadState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    uint64_t lifecycle_revision;
    uint64_t persistent_revision;
    uint64_t binding_generation;
    uint64_t current_scope_generation;
    uint64_t sampled_now = 0U;
    int state_present;
    int effective_action = 0;
    int sample_error = 0;
    Py_ssize_t index;

    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        if (!PyErr_Occurred()) {
            PyErr_SetString(
                PyExc_RuntimeError,
                "native issuer choreography snapshot owner is invalid"
            );
        }
        return NULL;
    }
    aqt_lock_owner_list_or_fail_stop();
    cell = shadow->choreography_authority_cell;
    if (cell == NULL || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography snapshot changed during capture"
        );
        return NULL;
    }
    lifecycle_revision = shadow->revision;
    persistent_revision = cell->persistent_state_revision;
    binding_generation = cell->binding_generation;
    current_scope_generation = cell->current_scope_generation;
    state_present = shadow->choreography_state_present != 0U;
    memset(&value, 0, sizeof(value));
    if (state_present) {
        const AqtIssuerChoreographyRecord *lease_record =
            shadow->choreography_state.authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ];

        value = shadow->choreography_state.value;
        if (!aqt_issuer_choreography_state_snapshot_phase_is_available(
                value.phase
            )) {
            aqt_unlock_owner_list_or_fail_stop();
            PyErr_SetString(
                PyExc_RuntimeError,
                "native issuer choreography snapshot phase is unavailable"
            );
            return NULL;
        }
        if (value.action_active
            && shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
            && cell->action_live
            && shadow->activation_thread_state == current_thread
            && shadow->activation_thread_id == current_thread_id
            && aqt_issuer_shadow_has_live_lease_locked(shadow)
            && lease_record != NULL
            && lease_record->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED) {
            if (aqt_issuer_choreography_sample_continuous_ns(&sampled_now) < 0) {
                sample_error = errno != 0 ? errno : EIO;
            }
            else {
                effective_action = sampled_now
                    < value.action_deadline_monotonic_ns;
            }
        }
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (sample_error != 0) {
        errno = sample_error;
        return PyErr_SetFromErrno(PyExc_OSError);
    }

    values[0] = PyUnicode_FromString(
        AQT_NATIVE_ISSUER_CHOREOGRAPHY_STATE_CONTRACT
    );
    values[1] = PyLong_FromUnsignedLongLong(
        (unsigned long long)lifecycle_revision
    );
    values[2] = PyBool_FromLong((long)state_present);
    values[3] = PyLong_FromUnsignedLongLong(
        (unsigned long long)persistent_revision
    );
    values[4] = PyLong_FromUnsignedLongLong(
        (unsigned long long)binding_generation
    );
    values[5] = PyLong_FromUnsignedLongLong(
        (unsigned long long)current_scope_generation
    );
    values[6] = state_present
        ? PyUnicode_FromString(aqt_issuer_choreography_phase_names[value.phase])
        : Py_NewRef(Py_None);
    values[7] = PyBool_FromLong((long)(state_present && value.action_active));
    values[8] = PyBool_FromLong((long)effective_action);
    values[9] = state_present
        ? PyLong_FromUnsignedLongLong(
            (unsigned long long)value.last_monotonic_ns
        )
        : Py_NewRef(Py_None);
    values[10] = state_present
        ? PyLong_FromUnsignedLongLong(
            (unsigned long long)value.started_monotonic_ns
        )
        : Py_NewRef(Py_None);
    values[11] = state_present
        ? PyLong_FromUnsignedLongLong(
            (unsigned long long)value.action_deadline_monotonic_ns
        )
        : Py_NewRef(Py_None);
    values[12] = state_present
        ? PyLong_FromUnsignedLongLong(
            (unsigned long long)value.retention_deadline_monotonic_ns
        )
        : Py_NewRef(Py_None);
    values[13] = state_present && value.roots_are_present
        ? Py_BuildValue("(ss)", value.artifact_directory, value.ignored_root)
        : aqt_issuer_choreography_empty_snapshot();
    values[14] = state_present
        && !aqt_issuer_choreography_record_key_is_empty(
            &value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        ? aqt_issuer_choreography_record_key_snapshot(
            &value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        : Py_NewRef(Py_None);
    values[15] = state_present
        && !aqt_issuer_choreography_record_key_is_empty(
            &value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        ? aqt_issuer_choreography_record_key_snapshot(
            &value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        : Py_NewRef(Py_None);
    values[16] = state_present
        && !aqt_issuer_choreography_record_key_is_empty(&value.claim.key)
        ? aqt_issuer_choreography_claim_summary_snapshot(&value.claim)
        : Py_NewRef(Py_None);
    values[17] = state_present
        && !aqt_issuer_choreography_record_key_is_empty(&value.claim.key)
        ? PyUnicode_FromString(value.retained_claim_binding_sha256)
        : Py_NewRef(Py_None);
    values[18] = state_present
        && !aqt_issuer_choreography_record_key_is_empty(
            &value.recovery_checkpoint.key
        )
        ? aqt_issuer_choreography_recovery_checkpoint_summary_snapshot(
            &value.recovery_checkpoint
        )
        : Py_NewRef(Py_None);
    values[19] = state_present
        && !aqt_issuer_choreography_record_key_is_empty(
            &value.recovery_receipt.key
        )
        ? aqt_issuer_choreography_recovery_receipt_summary_snapshot(
            &value.recovery_receipt
        )
        : Py_NewRef(Py_None);
    values[20] = state_present
        && !aqt_issuer_choreography_record_key_is_empty(
            &value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
            ]
        )
        ? aqt_issuer_choreography_record_key_snapshot(
            &value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
            ]
        )
        : Py_NewRef(Py_None);
    values[21] = state_present
        && aqt_issuer_choreography_state_snapshot_post_effect_key_is_present(
            &value
        )
        ? aqt_issuer_choreography_record_key_snapshot(
            &value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ]
        )
        : Py_NewRef(Py_None);
    values[22] = state_present
        && !aqt_issuer_choreography_record_key_is_empty(
            &value.controller_checkpoint.key
        )
        ? aqt_issuer_choreography_controller_checkpoint_summary_snapshot(
            &value.controller_checkpoint
        )
        : Py_NewRef(Py_None);
    values[23] = state_present
        && !aqt_issuer_choreography_record_key_is_empty(
            &value.controller_receipt.key
        )
        ? aqt_issuer_choreography_controller_receipt_summary_snapshot(
            &value.controller_receipt
        )
        : Py_NewRef(Py_None);
    result = PyTuple_New(AQT_ISSUER_CHOREOGRAPHY_STATE_SNAPSHOT_TUPLE_SIZE);
    if (result == NULL) {
        goto error;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_STATE_SNAPSHOT_TUPLE_SIZE;
         index++) {
        if (values[index] == NULL) {
            goto error;
        }
        PyTuple_SET_ITEM(result, index, values[index]);
        values[index] = NULL;
    }
    return result;

error:
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_STATE_SNAPSHOT_TUPLE_SIZE;
         index++) {
        Py_XDECREF(values[index]);
    }
    Py_XDECREF(result);
    return NULL;
}

static PyObject *
aqt_issuer_choreography_handle_snapshot(PyObject *candidate)
{
    AqtIssuerChoreographyRecord copied_record;
    AqtIssuerChoreographyRecord *record;
    PyObject *result = NULL;
    PyObject *values[AQT_ISSUER_CHOREOGRAPHY_HANDLE_SNAPSHOT_TUPLE_SIZE] = {
        NULL
    };
    unsigned int effective_status;
    uint64_t effective_revision;
    const char *record_class_name;
    const char *kind_name;
    const char *status_name;
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    pid_t current_pid = getpid();
    Py_ssize_t index;

    if (Py_IS_TYPE(candidate, &AqtIssuerChoreographyAuthorityType)) {
        record = ((AqtIssuerChoreographyAuthority *)candidate)->record;
    }
    else if (Py_IS_TYPE(candidate, &AqtIssuerChoreographyWitnessType)) {
        record = ((AqtIssuerChoreographyWitness *)candidate)->record;
    }
    else {
        PyErr_SetString(
            PyExc_TypeError,
            "candidate must be an exact native choreography handle"
        );
        return NULL;
    }
    aqt_lock_owner_list_or_fail_stop();
    if (record == NULL
        || record->cell == NULL
        || record->cell->origin_pid != current_pid
        || record->cell->origin_interpreter != current_interpreter
        || !record->wrapper_live
        || !record->wrapper_was_created
        || !aqt_issuer_choreography_record_is_exact_locked(
            record,
            record->cell,
            record->record_class,
            record->kind
        )) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native choreography handle is invalid"
        );
        return NULL;
    }
    effective_status = aqt_issuer_choreography_record_effective_status_locked(
        record,
        current_pid,
        current_interpreter
    );
    effective_revision =
        aqt_issuer_choreography_record_effective_status_revision_locked(
            record,
            current_pid,
            current_interpreter
        );
    copied_record = *record;
    aqt_unlock_owner_list_or_fail_stop();

    record_class_name = copied_record.record_class
            == AQT_CHOREOGRAPHY_RECORD_AUTHORITY
        ? "authority"
        : "witness";
    kind_name = copied_record.record_class == AQT_CHOREOGRAPHY_RECORD_AUTHORITY
        ? aqt_issuer_choreography_authority_kind_names[copied_record.kind]
        : aqt_issuer_choreography_witness_kind_names[copied_record.kind];
    status_name = copied_record.record_class
            == AQT_CHOREOGRAPHY_RECORD_AUTHORITY
        ? aqt_issuer_choreography_authority_status_names[effective_status]
        : aqt_issuer_choreography_witness_status_names[effective_status];
    values[0] = PyUnicode_FromString(
        AQT_NATIVE_ISSUER_CHOREOGRAPHY_HANDLE_CONTRACT
    );
    values[1] = PyUnicode_FromString(record_class_name);
    values[2] = PyUnicode_FromString(kind_name);
    values[3] = PyLong_FromUnsignedLongLong(
        (unsigned long long)copied_record.key.serial
    );
    values[4] = PyLong_FromUnsignedLongLong(
        (unsigned long long)copied_record.key.lifetime_generation
    );
    values[5] = PyUnicode_FromString(status_name);
    values[6] = PyLong_FromUnsignedLongLong(
        (unsigned long long)effective_revision
    );
    if (copied_record.record_class == AQT_CHOREOGRAPHY_RECORD_AUTHORITY) {
        values[7] = aqt_issuer_choreography_record_key_snapshot(
            &copied_record.key
        );
    }
    else if (copied_record.kind == AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM) {
        values[7] = aqt_issuer_choreography_claim_summary_snapshot(
            &copied_record.payload.claim
        );
    }
    else if (copied_record.kind
            == AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT) {
        values[7] = aqt_issuer_choreography_recovery_checkpoint_summary_snapshot(
            &copied_record.payload.recovery_checkpoint
        );
    }
    else if (copied_record.kind
            == AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT) {
        values[7] = aqt_issuer_choreography_recovery_receipt_summary_snapshot(
            &copied_record.payload.recovery_receipt
        );
    }
    else if (copied_record.kind
            == AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT) {
        values[7] = aqt_issuer_choreography_controller_checkpoint_summary_snapshot(
            &copied_record.payload.controller_checkpoint
        );
    }
    else if (copied_record.kind
            == AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT) {
        values[7] = aqt_issuer_choreography_controller_receipt_summary_snapshot(
            &copied_record.payload.controller_receipt
        );
    }
    else {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native choreography witness snapshot kind is unavailable"
        );
        goto error;
    }
    result = PyTuple_New(AQT_ISSUER_CHOREOGRAPHY_HANDLE_SNAPSHOT_TUPLE_SIZE);
    if (result == NULL) {
        goto error;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_HANDLE_SNAPSHOT_TUPLE_SIZE;
         index++) {
        if (values[index] == NULL) {
            goto error;
        }
        PyTuple_SET_ITEM(result, index, values[index]);
        values[index] = NULL;
    }
    return result;

error:
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_HANDLE_SNAPSHOT_TUPLE_SIZE;
         index++) {
        Py_XDECREF(values[index]);
    }
    Py_XDECREF(result);
    return NULL;
}

static PyObject *
aqt_issuer_claimed_fence_authorization_snapshot(
    AqtIssuerClaimedFenceAuthorization *authorization
)
{
    AqtIssuerClaimedFenceAuthorization copied;
    PyObject *result = NULL;
    PyObject *values[
        AQT_ISSUER_CLAIMED_FENCE_AUTHORIZATION_SNAPSHOT_TUPLE_SIZE
    ] = {NULL};
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    PyThreadState *current_thread = PyThreadState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    unsigned int effective_status;
    uint64_t effective_revision;
    Py_ssize_t index;

    aqt_lock_owner_list_or_fail_stop();
    if (authorization == NULL
        || authorization->binder_record == NULL
        || authorization->origin_pid != current_pid
        || authorization->origin_interpreter != current_interpreter
        || authorization->binder_record->cell == NULL
        || authorization->binder_record->cell->origin_pid != current_pid
        || authorization->binder_record->cell->origin_interpreter
            != current_interpreter
        || !aqt_issuer_claimed_fence_authorization_is_exact_locked(
            authorization
        )) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native claimed-fence authorization is invalid"
        );
        return NULL;
    }
    effective_status =
        aqt_issuer_claimed_fence_authorization_effective_status_locked(
            authorization,
            current_pid,
            current_interpreter
        );
    effective_revision =
        aqt_issuer_claimed_fence_authorization_effective_status_revision_locked(
            authorization,
            current_pid,
            current_interpreter
        );
    copied = *authorization;
    aqt_unlock_owner_list_or_fail_stop();

    values[0] = PyUnicode_FromString(
        AQT_NATIVE_ISSUER_CLAIMED_FENCE_AUTHORIZATION_CONTRACT
    );
    values[1] = PyLong_FromUnsignedLongLong(
        (unsigned long long)copied.lifetime_generation
    );
    values[2] = PyLong_FromUnsignedLongLong(
        (unsigned long long)copied.scope_generation
    );
    values[3] = PyLong_FromUnsignedLongLong(
        (unsigned long long)copied.binding_generation
    );
    values[4] = PyLong_FromUnsignedLongLong(
        (unsigned long long)copied.prepared_state_revision
    );
    values[5] = PyLong_FromUnsignedLongLong(
        (unsigned long long)copied.authorization_serial
    );
    values[6] = PyUnicode_FromString(
        aqt_issuer_claimed_fence_authorization_status_names[effective_status]
    );
    values[7] = PyLong_FromUnsignedLongLong(
        (unsigned long long)effective_revision
    );
    values[8] = aqt_issuer_choreography_record_key_snapshot(
        &copied.lease_key
    );
    values[9] = aqt_issuer_choreography_record_key_snapshot(
        &copied.recovery_capability_key
    );
    values[10] = aqt_issuer_choreography_record_key_snapshot(
        &copied.binder_key
    );
    values[11] = Py_BuildValue(
        "(ss)",
        copied.artifact_directory,
        copied.ignored_root
    );
    values[12] = PyBool_FromLong(copied.origin_pid == current_pid);
    values[13] = PyBool_FromLong(
        copied.origin_interpreter == current_interpreter
    );
    values[14] = PyBool_FromLong(
        copied.origin_thread_state == current_thread
            && copied.origin_thread_id == current_thread_id
    );
    result = PyTuple_New(
        AQT_ISSUER_CLAIMED_FENCE_AUTHORIZATION_SNAPSHOT_TUPLE_SIZE
    );
    if (result == NULL) {
        goto error;
    }
    for (index = 0;
         index < AQT_ISSUER_CLAIMED_FENCE_AUTHORIZATION_SNAPSHOT_TUPLE_SIZE;
         index++) {
        if (values[index] == NULL) {
            goto error;
        }
        PyTuple_SET_ITEM(result, index, values[index]);
        values[index] = NULL;
    }
    return result;

error:
    for (index = 0;
         index < AQT_ISSUER_CLAIMED_FENCE_AUTHORIZATION_SNAPSHOT_TUPLE_SIZE;
         index++) {
        Py_XDECREF(values[index]);
    }
    Py_XDECREF(result);
    return NULL;
}

static int
aqt_issuer_choreography_register_retry_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyRecord *lease_record,
    const AqtIssuerChoreographyRecord *recovery_record
)
{
    const AqtIssuerChoreographyState *state = &shadow->choreography_state;

    return shadow->choreography_state_present
        && state->value.phase == AQT_CHOREOGRAPHY_PHASE_UNBOUND
        && state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] == lease_record
        && state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] == recovery_record
        && aqt_issuer_choreography_record_key_equals(
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ],
            &lease_record->key
        )
        && aqt_issuer_choreography_record_key_equals(
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ],
            &recovery_record->key
        )
        && lease_record->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && recovery_record->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED;
}

static int
aqt_issuer_choreography_register_pair_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyRecord *lease_record,
    const AqtIssuerChoreographyRecord *recovery_record
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    uint64_t cell_references;

    if (cell == NULL
        || shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        || shadow->choreography_state_present
        || !cell->alive
        || !cell->action_live
        || cell->lifecycle_disposition != AQT_CHOREOGRAPHY_CELL_ACTIVE
        || cell->pending_scope_generation == 0U
        || lease_record == NULL
        || recovery_record == NULL
        || lease_record == recovery_record
        || lease_record->cell != cell
        || recovery_record->cell != cell
        || lease_record->record_class != AQT_CHOREOGRAPHY_RECORD_AUTHORITY
        || recovery_record->record_class != AQT_CHOREOGRAPHY_RECORD_AUTHORITY
        || lease_record->kind
            != AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        || recovery_record->kind
            != AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        || lease_record->prepared_at_revision
            != cell->persistent_state_revision
        || recovery_record->prepared_at_revision
            != cell->persistent_state_revision
        || lease_record->install_or_terminal_state_revision != 0U
        || recovery_record->install_or_terminal_state_revision != 0U
        || !lease_record->wrapper_live
        || !recovery_record->wrapper_live
        || !lease_record->wrapper_was_created
        || !recovery_record->wrapper_was_created
        || lease_record->key.scope_generation
            != cell->pending_scope_generation
        || recovery_record->key.scope_generation
            != cell->pending_scope_generation
        || lease_record->key.lifetime_generation != cell->lifetime_generation
        || recovery_record->key.lifetime_generation
            != cell->lifetime_generation
        || lease_record->key.serial == recovery_record->key.serial
        || !aqt_issuer_choreography_memory_is_zero(
            &lease_record->payload,
            sizeof(lease_record->payload)
        )
        || !aqt_issuer_choreography_memory_is_zero(
            &recovery_record->payload,
            sizeof(recovery_record->payload)
        )) {
        return 0;
    }
    cell_references = atomic_load_explicit(
        &cell->reference_count,
        memory_order_acquire
    );
    return cell_references == 3U
        && lease_record->status == AQT_CHOREOGRAPHY_AUTHORITY_PREPARED
        && recovery_record->status == AQT_CHOREOGRAPHY_AUTHORITY_PREPARED
        && aqt_issuer_choreography_record_is_exact_locked(
            lease_record,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            recovery_record,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        );
}

static void
aqt_issuer_choreography_build_unbound_state_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyRecord *lease_record,
    AqtIssuerChoreographyRecord *recovery_record,
    uint64_t sampled_now
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState state;
    uint64_t next_revision;
    uint64_t next_binding;
    uint64_t scope;

    if (cell->persistent_state_revision == UINT64_MAX
        || cell->binding_generation == UINT64_MAX
        || sampled_now > UINT64_MAX - AQT_ISSUER_CHOREOGRAPHY_RETENTION_INTERVAL_NS
        || cell->pending_scope_generation == 0U) {
        abort();
    }
    next_revision = cell->persistent_state_revision + 1U;
    next_binding = cell->binding_generation + 1U;
    scope = cell->pending_scope_generation;
    memset(&state, 0, sizeof(state));
    state.value.revision = next_revision;
    state.value.binding_generation = next_binding;
    state.value.scope_generation = scope;
    state.value.last_monotonic_ns = sampled_now;
    state.value.started_monotonic_ns = sampled_now;
    state.value.action_deadline_monotonic_ns = sampled_now
        + AQT_ISSUER_CHOREOGRAPHY_ACTION_INTERVAL_NS;
    state.value.retention_deadline_monotonic_ns = sampled_now
        + AQT_ISSUER_CHOREOGRAPHY_RETENTION_INTERVAL_NS;
    state.value.phase = AQT_CHOREOGRAPHY_PHASE_UNBOUND;
    state.value.action_active = 1U;
    state.value.authority_keys[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ] = lease_record->key;
    state.value.authority_keys[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ] = recovery_record->key;
    state.value.authority_record_presence_mask =
        (1U << AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE)
        | (1U
            << AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY);
    state.value.authority_statuses[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ] = AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED;
    state.value.authority_statuses[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ] = AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED;
    state.authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ] = lease_record;
    state.authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ] = recovery_record;
    aqt_issuer_choreography_record_incref(lease_record);
    aqt_issuer_choreography_record_incref(recovery_record);
    lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED;
    recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED;
    lease_record->install_or_terminal_state_revision = next_revision;
    recovery_record->install_or_terminal_state_revision = next_revision;
    cell->persistent_state_revision = next_revision;
    cell->binding_generation = next_binding;
    cell->current_scope_generation = scope;
    cell->pending_scope_generation = 0U;
    shadow->choreography_state = state;
    shadow->choreography_state_present = 1U;
}

static int
aqt_issuer_choreography_register_cleanup_reconcile_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyRecord *lease_record,
    AqtIssuerChoreographyRecord *recovery_record,
    uint64_t expected_revision,
    uint64_t expected_binding,
    uint64_t selected_scope,
    int state_was_stored,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;

    if (!state_was_stored) {
        if (!shadow->choreography_state_present
            && cell->persistent_state_revision == expected_revision
            && cell->binding_generation == expected_binding
            && cell->pending_scope_generation == selected_scope) {
            uint64_t terminal_revision =
                aqt_issuer_choreography_scope_retire_locked(
                    cell,
                    AQT_CHOREOGRAPHY_SCOPE_RETIREMENT_FAILCLOSED_CLEANUP,
                    NULL
                );

            lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
            recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
            lease_record->install_or_terminal_state_revision =
                terminal_revision;
            recovery_record->install_or_terminal_state_revision =
                terminal_revision;
        }
        return !shadow->choreography_state_present
            && cell->persistent_state_revision == expected_revision + 1U
            && cell->binding_generation == expected_binding
            && cell->pending_scope_generation == 0U
            && cell->current_scope_generation == selected_scope + 1U
            && cell->last_scope_retirement.kind
                == AQT_CHOREOGRAPHY_SCOPE_RETIREMENT_FAILCLOSED_CLEANUP
            && cell->last_scope_retirement.old_scope_generation
                == selected_scope
            && cell->last_scope_retirement.binding_generation
                == expected_binding
            && cell->last_scope_retirement.retirement_state_revision
                == expected_revision + 1U
            && !cell->last_scope_retirement.terminal_key_is_present
            && lease_record->status == AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
            && recovery_record->status
                == AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
            && lease_record->install_or_terminal_state_revision
                == expected_revision + 1U
            && recovery_record->install_or_terminal_state_revision
                == expected_revision + 1U;
    }
    if (shadow->choreography_state_present
        && shadow->choreography_state.value.phase
            == AQT_CHOREOGRAPHY_PHASE_UNBOUND
        && shadow->choreography_state.value.revision
            == expected_revision + 1U) {
        AqtIssuerChoreographyState *state = &shadow->choreography_state;
        uint64_t terminal_revision;

        if (cell->persistent_state_revision == UINT64_MAX) {
            abort();
        }
        terminal_revision = cell->persistent_state_revision + 1U;
        cell->persistent_state_revision = terminal_revision;
        state->value.revision = terminal_revision;
        state->value.phase = AQT_CHOREOGRAPHY_PHASE_REVOKED;
        state->value.action_active = 0U;
        state->value.roots_are_present = 0U;
        memset(
            state->value.artifact_directory,
            0,
            sizeof(state->value.artifact_directory)
        );
        memset(
            state->value.ignored_root,
            0,
            sizeof(state->value.ignored_root)
        );
        state->value.artifact_directory_length = 0U;
        state->value.ignored_root_length = 0U;
        state->value.authority_record_presence_mask = 0U;
        state->value.authority_statuses[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        state->value.authority_statuses[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        lease_record->install_or_terminal_state_revision = terminal_revision;
        recovery_record->install_or_terminal_state_revision = terminal_revision;
        if (detached->count != 0U
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] != lease_record
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] != recovery_record) {
            abort();
        }
        detached->records[detached->count++] = lease_record;
        detached->records[detached->count++] = recovery_record;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] = NULL;
    }
    return shadow->choreography_state_present
        && cell->persistent_state_revision == expected_revision + 2U
        && cell->binding_generation == expected_binding + 1U
        && cell->current_scope_generation == selected_scope
        && cell->pending_scope_generation == 0U
        && shadow->choreography_state.value.phase
            == AQT_CHOREOGRAPHY_PHASE_REVOKED
        && shadow->choreography_state.value.revision
            == expected_revision + 2U
        && shadow->choreography_state.authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] == NULL
        && shadow->choreography_state.authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] == NULL
        && lease_record->status == AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        && recovery_record->status == AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        && lease_record->install_or_terminal_state_revision
            == expected_revision + 2U
        && recovery_record->install_or_terminal_state_revision
            == expected_revision + 2U;
}

static void
aqt_issuer_choreography_detached_records_release(
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    size_t index;

    for (index = 0; index < detached->count; index++) {
        aqt_issuer_choreography_record_decref(detached->records[index]);
        detached->records[index] = NULL;
    }
    detached->count = 0U;
}

static PyObject *
aqt_allocate_unpublished_issuer_choreography_wrapper(
    unsigned int record_class
)
{
    if (record_class == AQT_CHOREOGRAPHY_RECORD_AUTHORITY) {
        AqtIssuerChoreographyAuthority *wrapper = PyObject_New(
            AqtIssuerChoreographyAuthority,
            &AqtIssuerChoreographyAuthorityType
        );

        if (wrapper == NULL) {
            return NULL;
        }
        wrapper->weakreflist = NULL;
        wrapper->record = NULL;
        return (PyObject *)wrapper;
    }
    if (record_class == AQT_CHOREOGRAPHY_RECORD_WITNESS) {
        AqtIssuerChoreographyWitness *wrapper = PyObject_New(
            AqtIssuerChoreographyWitness,
            &AqtIssuerChoreographyWitnessType
        );

        if (wrapper == NULL) {
            return NULL;
        }
        wrapper->weakreflist = NULL;
        wrapper->record = NULL;
        return (PyObject *)wrapper;
    }
    PyErr_SetString(
        PyExc_RuntimeError,
        "native current-State choreography wrapper class is invalid"
    );
    return NULL;
}

