static int
aqt_issuer_choreography_parse_checkpoint_time_selector(
    PyObject *candidate,
    unsigned int *selector
)
{
    size_t index;

    if (!PyUnicode_CheckExact(candidate)) {
        PyErr_SetString(
            PyExc_TypeError,
            "native issuer choreography checkpoint time selector is invalid"
        );
        return -1;
    }
    for (index = 0; index < AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT; index++) {
        int comparison = PyUnicode_CompareWithASCIIString(
            candidate,
            aqt_issuer_choreography_time_selector_names[index]
        );

        if (comparison == 0) {
            *selector = (unsigned int)index;
            return 0;
        }
        if (comparison == -1 && PyErr_Occurred()) {
            return -1;
        }
    }
    PyErr_SetString(
        PyExc_RuntimeError,
        "native issuer choreography checkpoint time selector is unavailable"
    );
    return -1;
}

