static int
aqt_issuer_choreography_parse_roots2(
    PyObject *candidate,
    AqtIssuerChoreographyRoots2 *roots
)
{
    memset(roots, 0, sizeof(*roots));
    if (!PyTuple_CheckExact(candidate) || PyTuple_GET_SIZE(candidate) != 2) {
        PyErr_SetString(
            PyExc_TypeError,
            "native issuer choreography recovery claim binder roots are invalid"
        );
        return -1;
    }
    if (aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(candidate, 0),
            roots->artifact_directory,
            sizeof(roots->artifact_directory),
            1U,
            sizeof(roots->artifact_directory) - 1U,
            "artifact_directory",
            &roots->artifact_directory_length
        ) < 0
        || aqt_issuer_choreography_copy_unicode(
            PyTuple_GET_ITEM(candidate, 1),
            roots->ignored_root,
            sizeof(roots->ignored_root),
            1U,
            sizeof(roots->ignored_root) - 1U,
            "ignored_root",
            &roots->ignored_root_length
        ) < 0
        || !aqt_issuer_choreography_root_text_is_exact(
            roots->artifact_directory,
            roots->artifact_directory_length
        )
        || !aqt_issuer_choreography_root_text_is_exact(
            roots->ignored_root,
            roots->ignored_root_length
        )
        || roots->ignored_root_length
            > SIZE_MAX - (sizeof("/" AQT_TRUSTED_TIME_DIRECTORY_NAME) - 1U)
        || roots->artifact_directory_length
            != roots->ignored_root_length
                + sizeof("/" AQT_TRUSTED_TIME_DIRECTORY_NAME) - 1U
        || memcmp(
            roots->artifact_directory,
            roots->ignored_root,
            roots->ignored_root_length
        ) != 0
        || memcmp(
            roots->artifact_directory + roots->ignored_root_length,
            "/" AQT_TRUSTED_TIME_DIRECTORY_NAME,
            sizeof("/" AQT_TRUSTED_TIME_DIRECTORY_NAME)
        ) != 0) {
        if (!PyErr_Occurred()) {
            PyErr_SetString(
                PyExc_ValueError,
                "native issuer choreography recovery claim binder roots are invalid"
            );
        }
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_early_transition_source_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyEarlyTransitionRequest *request,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *state_lease;
    AqtIssuerChoreographyRecord *state_recovery;
    AqtIssuerChoreographyRecord *state_binder;
    unsigned int required_phase;

    if (request == NULL
        || request->operation_tag < AQT_CHOREOGRAPHY_OPERATION_ISSUE_BINDER
        || request->operation_tag > AQT_CHOREOGRAPHY_OPERATION_ARM_CLAIM
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || cell == NULL
        || cell->alive != 1U
        || cell->action_live != 1U
        || cell->lifecycle_disposition != AQT_CHOREOGRAPHY_CELL_ACTIVE
        || cell->pending_scope_generation != 0U
        || !shadow->choreography_state_present
        || state->value.action_active != 1U
        || state->value.revision > UINT64_MAX - 2U
        || state->value.revision != cell->persistent_state_revision
        || state->value.binding_generation != cell->binding_generation
        || state->value.scope_generation != cell->current_scope_generation) {
        return 0;
    }
    required_phase = request->operation_tag
            == AQT_CHOREOGRAPHY_OPERATION_ISSUE_BINDER
        ? AQT_CHOREOGRAPHY_PHASE_UNBOUND
        : request->operation_tag == AQT_CHOREOGRAPHY_OPERATION_ADMIT_BINDER
            ? AQT_CHOREOGRAPHY_PHASE_BINDER_ISSUED
            : AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED;
    if (state->value.phase != required_phase) {
        return 0;
    }
    state_lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    state_recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    state_binder = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
    ];
    if (state_lease == NULL
        || state_recovery == NULL
        || state_lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || state_recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED) {
        return 0;
    }
    if (request->operation_tag == AQT_CHOREOGRAPHY_OPERATION_ISSUE_BINDER) {
        return state_binder == NULL
            && request->authorization != NULL
            && aqt_issuer_claimed_fence_authorization_is_exact_locked(
                request->authorization
            )
            && request->authorization->status
                == AQT_CLAIMED_FENCE_AUTHORIZATION_PREPARED
            && aqt_issuer_choreography_issue_authorization_source_is_current_locked(
                cell,
                state,
                request->authorization,
                current_thread,
                current_thread_id
            );
    }
    if (state_binder == NULL
        || request->binder_record != state_binder
        || !state_binder->wrapper_live
        || state_binder->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED) {
        return 0;
    }
    if (request->operation_tag == AQT_CHOREOGRAPHY_OPERATION_ADMIT_BINDER) {
        return 1;
    }
    if (request->claim_record == NULL
        || !request->claim_record->wrapper_live) {
        return 0;
    }
    return request->lease_record == state_lease
        && request->recovery_record == state_recovery
        && state_lease->wrapper_live
        && state_recovery->wrapper_live
        && request->claim_record->cell == cell
        && request->claim_record->record_class
            == AQT_CHOREOGRAPHY_RECORD_WITNESS
        && request->claim_record->kind
            == AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        && request->claim_record->status == AQT_CHOREOGRAPHY_WITNESS_PREPARED
        && request->claim_record->prepared_at_revision == state->value.revision
        && request->claim_record->install_or_terminal_state_revision == 0U
        && request->claim_record->key.scope_generation
            == state->value.scope_generation
        && aqt_issuer_choreography_record_is_exact_locked(
            request->claim_record,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        && aqt_issuer_choreography_record_key_equals(
            &request->claim_record->payload.claim.key,
            &request->claim_record->key
        )
        && aqt_issuer_choreography_projection5_is_exact(
            &request->claim_record->payload.claim.projection,
            &state->value
        )
        && aqt_issuer_choreography_sha256_is_exact(
            request->claim_record->payload.claim.binding_sha256
        );
}

static int
aqt_issuer_choreography_checkpoint_source_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyRecord *lease_record,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *state_lease;
    AqtIssuerChoreographyRecord *state_recovery;

    if (!aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || cell == NULL
        || cell->action_live != 1U
        || cell->lifecycle_disposition != AQT_CHOREOGRAPHY_CELL_ACTIVE
        || !shadow->choreography_state_present
        || state->value.phase != AQT_CHOREOGRAPHY_PHASE_UNBOUND
        || state->value.action_active != 1U
        || state->value.revision > UINT64_MAX - 2U
        || cell->persistent_state_revision != state->value.revision
        || cell->binding_generation != state->value.binding_generation
        || cell->current_scope_generation != state->value.scope_generation
        || cell->pending_scope_generation != 0U
        || lease_record == NULL
        || !lease_record->wrapper_live) {
        return 0;
    }
    state_lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    state_recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    return state_lease == lease_record
        && state_recovery != NULL
        && state_recovery != lease_record
        && lease_record->cell == cell
        && state_recovery->cell == cell
        && lease_record->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && state_recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && aqt_issuer_choreography_record_key_equals(
            &lease_record->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        && aqt_issuer_choreography_record_key_equals(
            &state_recovery->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        );
}

static void
aqt_issuer_choreography_build_checkpoint_candidate_locked(
    const AqtIssuerChoreographyStateValue *source,
    unsigned int selector,
    uint64_t sampled_now,
    AqtIssuerChoreographyStateValue *candidate
)
{
    uint64_t observed = source->last_monotonic_ns;
    int revoked = 0;

    switch (selector) {
        case AQT_CHOREOGRAPHY_TIME_SAME:
            break;
        case AQT_CHOREOGRAPHY_TIME_SAMPLE:
            if (sampled_now < source->last_monotonic_ns
                || sampled_now >= source->retention_deadline_monotonic_ns) {
                revoked = 1;
            }
            else {
                observed = sampled_now;
                revoked = sampled_now >= source->action_deadline_monotonic_ns;
            }
            break;
        case AQT_CHOREOGRAPHY_TIME_ROLLBACK:
            revoked = 1;
            break;
        case AQT_CHOREOGRAPHY_TIME_ACTION_DEADLINE:
            observed = source->action_deadline_monotonic_ns;
            revoked = 1;
            break;
        default:
            abort();
    }
    if (revoked) {
        aqt_issuer_choreography_build_checkpoint_revoked_value(
            source,
            source->revision + 1U,
            observed,
            candidate
        );
        return;
    }
    *candidate = *source;
    candidate->revision++;
    candidate->last_monotonic_ns = observed;
}

static void
aqt_issuer_choreography_publish_checkpoint_candidate_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyStateValue *candidate,
    AqtIssuerChoreographyRecord *lease_record,
    AqtIssuerChoreographyRecord *recovery_record,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;

    if (cell == NULL
        || cell->persistent_state_revision == UINT64_MAX
        || candidate->revision != cell->persistent_state_revision + 1U
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease_record
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery_record) {
        abort();
    }
    if (candidate->phase == AQT_CHOREOGRAPHY_PHASE_REVOKED) {
        if (detached->count != 0U) {
            abort();
        }
        detached->records[detached->count++] = lease_record;
        detached->records[detached->count++] = recovery_record;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] = NULL;
        lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        lease_record->install_or_terminal_state_revision = candidate->revision;
        recovery_record->install_or_terminal_state_revision =
            candidate->revision;
    }
    else if (candidate->phase != AQT_CHOREOGRAPHY_PHASE_UNBOUND) {
        abort();
    }
    state->value = *candidate;
    memset(&state->failclosed_origin, 0, sizeof(state->failclosed_origin));
    cell->persistent_state_revision = candidate->revision;
}

static void
aqt_issuer_choreography_build_checkpoint_failclosed_origin(
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *committed,
    int committed_is_present,
    const AqtIssuerChoreographyStateValue *target,
    AqtIssuerChoreographyFailclosedOrigin *origin
)
{
    memset(origin, 0, sizeof(*origin));
    origin->is_present = 1U;
    origin->operation_group = 3U;
    origin->operation_tag = AQT_CHOREOGRAPHY_OPERATION_CHECKPOINT;
    origin->expected = *expected;
    origin->committed_is_present = committed_is_present ? 1U : 0U;
    if (committed_is_present) {
        origin->committed = *committed;
    }
    origin->target_policy = AQT_CHOREOGRAPHY_FAILCLOSED_REVOKED;
    origin->target = *target;
}

static void
aqt_issuer_choreography_checkpoint_capture_authority_failure(
    int *saved_errno,
    int *authority_proof_failed
)
{
    *saved_errno = errno != 0 ? errno : EIO;
    *authority_proof_failed = 1;
}

static int
aqt_issuer_choreography_checkpoint_cleanup_reconcile_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *committed,
    int committed_is_present,
    AqtIssuerChoreographyRecord *lease_record,
    AqtIssuerChoreographyRecord *recovery_record,
    int authority_proof_failed,
    AqtIssuerActivationProjection **prepared_roots,
    AqtIssuerActivationProjection **detached_projection,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyStateValue target;
    AqtIssuerChoreographyFailclosedOrigin origin;
    uint64_t target_revision = expected->revision
        + (committed_is_present ? 2U : 1U);
    uint64_t target_last = committed_is_present
        ? committed->last_monotonic_ns
        : expected->last_monotonic_ns;

    aqt_issuer_choreography_build_checkpoint_revoked_value(
        expected,
        target_revision,
        target_last,
        &target
    );
    aqt_issuer_choreography_build_checkpoint_failclosed_origin(
        expected,
        committed,
        committed_is_present,
        &target,
        &origin
    );
    if (state->failclosed_origin.is_present) {
        return cell != NULL
            && cell->persistent_state_revision == target_revision
            && memcmp(&state->value, &target, sizeof(target)) == 0
            && memcmp(&state->failclosed_origin, &origin, sizeof(origin)) == 0
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] == NULL
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] == NULL
            && lease_record->status == AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
            && recovery_record->status == AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
            && lease_record->install_or_terminal_state_revision
                == target_revision
            && recovery_record->install_or_terminal_state_revision
                == target_revision
            && (authority_proof_failed
                ? shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED
                    && shadow->revision == 4U
                    && aqt_issuer_projection_is_roots_only(shadow->projection)
                    && aqt_issuer_shadow_has_live_lease_locked(shadow)
                : shadow->state
                        == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
                    && shadow->revision == 3U)
            && aqt_issuer_choreography_cell_is_exact_locked(shadow);
    }
    if (cell == NULL
        || cell->persistent_state_revision
            != expected->revision + (committed_is_present ? 1U : 0U)
        || !shadow->choreography_state_present
        || (committed_is_present
            ? memcmp(&state->value, committed, sizeof(*committed)) != 0
            : memcmp(&state->value, expected, sizeof(*expected)) != 0)) {
        return 0;
    }
    if (state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != NULL) {
        if (detached->count != 0U
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] != lease_record
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] != recovery_record) {
            abort();
        }
        detached->records[detached->count++] = lease_record;
        detached->records[detached->count++] = recovery_record;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] = NULL;
    }
    else if (detached->count != 2U
        || detached->records[0] != lease_record
        || detached->records[1] != recovery_record) {
        abort();
    }
    lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    lease_record->install_or_terminal_state_revision = target_revision;
    recovery_record->install_or_terminal_state_revision = target_revision;
    state->value = target;
    state->failclosed_origin = origin;
    cell->persistent_state_revision = target_revision;
    if (authority_proof_failed) {
        if (*prepared_roots == NULL
            || *detached_projection != NULL
            || shadow->projection == NULL) {
            abort();
        }
        *detached_projection = shadow->projection;
        shadow->projection = *prepared_roots;
        *prepared_roots = NULL;
        shadow->state = AQT_ISSUER_NATIVE_STATE_BURNED;
        shadow->revision = 4U;
        shadow->poisoned = 1U;
        aqt_issuer_choreography_cell_publish_lifecycle_locked(
            shadow,
            AQT_CHOREOGRAPHY_CELL_BURNED,
            0U
        );
    }
    return aqt_issuer_choreography_checkpoint_failclosed_origin_is_exact_locked(
            state
        )
        && aqt_issuer_choreography_cell_is_exact_locked(shadow);
}

static void
aqt_issuer_choreography_publish_early_transition_candidate_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyEarlyTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *candidate,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease_record = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    AqtIssuerChoreographyRecord *recovery_record = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    AqtIssuerChoreographyRecord *binder_record = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
    ];

    if (cell == NULL
        || candidate->revision != cell->persistent_state_revision + 1U
        || request->operation_tag < AQT_CHOREOGRAPHY_OPERATION_ISSUE_BINDER
        || request->operation_tag > AQT_CHOREOGRAPHY_OPERATION_ARM_CLAIM) {
        abort();
    }
    if (request->operation_tag == AQT_CHOREOGRAPHY_OPERATION_ISSUE_BINDER) {
        if (candidate->phase != AQT_CHOREOGRAPHY_PHASE_BINDER_ISSUED
            || binder_record != NULL
            || request->binder_record == NULL
            || request->authorization == NULL
            || request->authorization->status
                != AQT_CLAIMED_FENCE_AUTHORIZATION_CONSUMED) {
            abort();
        }
        aqt_issuer_choreography_record_incref(request->binder_record);
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] = request->binder_record;
        request->binder_record->status = AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED;
        request->binder_record->install_or_terminal_state_revision =
            candidate->revision;
    }
    else if (request->operation_tag
            == AQT_CHOREOGRAPHY_OPERATION_ADMIT_BINDER) {
        if (candidate->phase != AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED
            || binder_record != request->binder_record) {
            abort();
        }
    }
    else if (candidate->phase == AQT_CHOREOGRAPHY_PHASE_ARMED) {
        if (binder_record != request->binder_record
            || request->claim_record == NULL) {
            abort();
        }
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] = NULL;
        aqt_issuer_choreography_detached_record_append_locked(
            detached,
            binder_record
        );
        binder_record->status = AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED;
        binder_record->install_or_terminal_state_revision = candidate->revision;
        aqt_issuer_choreography_record_incref(request->claim_record);
        state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] = request->claim_record;
        request->claim_record->status = AQT_CHOREOGRAPHY_WITNESS_INSTALLED;
        request->claim_record->install_or_terminal_state_revision =
            candidate->revision;
    }
    else if (candidate->phase == AQT_CHOREOGRAPHY_PHASE_REVOKED
        || candidate->phase == AQT_CHOREOGRAPHY_PHASE_EXPIRED) {
        if (lease_record == NULL
            || recovery_record == NULL
            || binder_record != request->binder_record
            || request->claim_record == NULL) {
            abort();
        }
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] = NULL;
        aqt_issuer_choreography_detached_record_append_locked(
            detached,
            lease_record
        );
        aqt_issuer_choreography_detached_record_append_locked(
            detached,
            recovery_record
        );
        aqt_issuer_choreography_detached_record_append_locked(
            detached,
            binder_record
        );
        lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        binder_record->status = AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED;
        lease_record->install_or_terminal_state_revision = candidate->revision;
        recovery_record->install_or_terminal_state_revision = candidate->revision;
        binder_record->install_or_terminal_state_revision = candidate->revision;
        request->claim_record->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        request->claim_record->install_or_terminal_state_revision =
            candidate->revision;
    }
    else {
        abort();
    }
    state->value = *candidate;
    memset(&state->failclosed_origin, 0, sizeof(state->failclosed_origin));
    cell->persistent_state_revision = candidate->revision;
}

static void
aqt_issuer_choreography_build_early_transition_failclosed_origin(
    unsigned int operation_tag,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *committed,
    int committed_is_present,
    unsigned int target_policy,
    const AqtIssuerChoreographyStateValue *target,
    AqtIssuerChoreographyFailclosedOrigin *origin
)
{
    memset(origin, 0, sizeof(*origin));
    origin->is_present = 1U;
    origin->operation_group = 3U;
    origin->operation_tag = operation_tag;
    origin->expected = *expected;
    origin->committed_is_present = committed_is_present ? 1U : 0U;
    if (committed_is_present) {
        origin->committed = *committed;
    }
    origin->target_policy = target_policy;
    origin->target = *target;
}

static void
aqt_issuer_choreography_build_early_transition_cleanup_target_locked(
    unsigned int operation_tag,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *committed,
    int committed_is_present,
    int terminal_proof_completed,
    unsigned int *target_policy,
    AqtIssuerChoreographyStateValue *target
)
{
    uint64_t target_revision = expected->revision
        + (committed_is_present ? 2U : 1U);

    *target_policy = AQT_CHOREOGRAPHY_FAILCLOSED_REVOKED;
    if (!committed_is_present
        || operation_tag != AQT_CHOREOGRAPHY_OPERATION_ARM_CLAIM
        || committed->phase == AQT_CHOREOGRAPHY_PHASE_REVOKED) {
        aqt_issuer_choreography_build_checkpoint_revoked_value(
            expected,
            target_revision,
            expected->last_monotonic_ns,
            target
        );
        return;
    }
    if (committed->phase == AQT_CHOREOGRAPHY_PHASE_EXPIRED) {
        *target_policy = AQT_CHOREOGRAPHY_FAILCLOSED_EXPIRED;
        *target = *committed;
        target->revision++;
        return;
    }
    if (committed->phase != AQT_CHOREOGRAPHY_PHASE_ARMED) {
        abort();
    }
    if (terminal_proof_completed) {
        *target_policy = AQT_CHOREOGRAPHY_FAILCLOSED_ARMED;
        *target = *committed;
        target->revision++;
        target->action_active = 0U;
        return;
    }
    *target_policy = AQT_CHOREOGRAPHY_FAILCLOSED_RECOVERY_UNCONFIRMED;
    aqt_issuer_choreography_build_early_recovery_unconfirmed_value(
        committed,
        target
    );
}

static int
aqt_issuer_choreography_early_transition_cleanup_records_are_exact_locked(
    const AqtIssuerChoreographyEarlyTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *committed,
    int committed_is_present,
    unsigned int target_policy,
    uint64_t target_revision,
    const AqtIssuerChoreographyState *state,
    const AqtIssuerChoreographyAuthorityCell *cell
)
{
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *binder = request->binder_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;

    if (lease == NULL
        || recovery == NULL
        || binder == NULL
        || cell == NULL
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            binder,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        )) {
        return 0;
    }
    if (request->operation_tag == AQT_CHOREOGRAPHY_OPERATION_ISSUE_BINDER) {
        if (request->authorization == NULL
            || !aqt_issuer_claimed_fence_authorization_is_exact_locked(
                request->authorization
            )
            || request->authorization->binder_record != binder
            || request->authorization->status
                != AQT_CLAIMED_FENCE_AUTHORIZATION_CONSUMED
            || request->authorization->status_state_revision
                != expected->revision + 1U) {
            return 0;
        }
    }
    else if (request->authorization != NULL) {
        return 0;
    }
    if (target_policy == AQT_CHOREOGRAPHY_FAILCLOSED_ARMED) {
        return committed_is_present
            && claim != NULL
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] == lease
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] == recovery
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
            ] == NULL
            && state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
            ] == claim
            && lease->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && binder->status == AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED
            && binder->install_or_terminal_state_revision == committed->revision
            && claim->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
            && claim->install_or_terminal_state_revision == committed->revision;
    }
    if (state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != NULL
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != NULL
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != NULL
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || lease->install_or_terminal_state_revision != target_revision
        || recovery->install_or_terminal_state_revision != target_revision) {
        return 0;
    }
    if (request->operation_tag == AQT_CHOREOGRAPHY_OPERATION_ISSUE_BINDER
        || request->operation_tag == AQT_CHOREOGRAPHY_OPERATION_ADMIT_BINDER
        || !committed_is_present) {
        if (binder->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
            || binder->install_or_terminal_state_revision != target_revision) {
            return 0;
        }
    }
    else if (binder->status != AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED
        || binder->install_or_terminal_state_revision != committed->revision) {
        return 0;
    }
    if (request->operation_tag != AQT_CHOREOGRAPHY_OPERATION_ARM_CLAIM) {
        return claim == NULL;
    }
    return claim != NULL
        && aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        && claim->status == AQT_CHOREOGRAPHY_WITNESS_CLEARED
        && claim->install_or_terminal_state_revision
            == (committed_is_present
                    && (committed->phase == AQT_CHOREOGRAPHY_PHASE_REVOKED
                        || committed->phase == AQT_CHOREOGRAPHY_PHASE_EXPIRED)
                ? committed->revision
                : target_revision);
}

static int
aqt_issuer_choreography_early_transition_cleanup_reconcile_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyEarlyTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *committed,
    int committed_is_present,
    int terminal_proof_completed,
    AqtIssuerActivationProjection **prepared_roots,
    AqtIssuerActivationProjection **detached_projection,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease_record = request->lease_record;
    AqtIssuerChoreographyRecord *recovery_record = request->recovery_record;
    AqtIssuerChoreographyRecord *binder_record = request->binder_record;
    AqtIssuerChoreographyRecord *claim_record = request->claim_record;
    AqtIssuerChoreographyStateValue target;
    AqtIssuerChoreographyFailclosedOrigin origin;
    unsigned int target_policy;

    aqt_issuer_choreography_build_early_transition_cleanup_target_locked(
        request->operation_tag,
        expected,
        committed,
        committed_is_present,
        terminal_proof_completed,
        &target_policy,
        &target
    );
    aqt_issuer_choreography_build_early_transition_failclosed_origin(
        request->operation_tag,
        expected,
        committed,
        committed_is_present,
        target_policy,
        &target,
        &origin
    );
    if (state->failclosed_origin.is_present) {
        return cell != NULL
            && cell->persistent_state_revision == target.revision
            && memcmp(&state->value, &target, sizeof(target)) == 0
            && memcmp(&state->failclosed_origin, &origin, sizeof(origin)) == 0
            && shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED
            && shadow->revision == 4U
            && shadow->poisoned == 1U
            && cell->action_live == 0U
            && aqt_issuer_projection_is_roots_only(shadow->projection)
            && aqt_issuer_choreography_early_transition_cleanup_records_are_exact_locked(
                request,
                expected,
                committed,
                committed_is_present,
                target_policy,
                target.revision,
                state,
                cell
            )
            && aqt_issuer_choreography_cell_is_exact_locked(shadow);
    }
    if (cell == NULL
        || cell->persistent_state_revision
            != expected->revision + (committed_is_present ? 1U : 0U)
        || memcmp(
            &state->value,
            committed_is_present ? committed : expected,
            sizeof(*expected)
        ) != 0) {
        return 0;
    }
    if (target_policy == AQT_CHOREOGRAPHY_FAILCLOSED_ARMED) {
        if (state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] != lease_record
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] != recovery_record
            || state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
            ] != claim_record) {
            abort();
        }
    }
    else {
        size_t index;

        for (index = 0;
             index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
             index++) {
            AqtIssuerChoreographyRecord *record =
                state->authority_records[index];

            if (record != NULL) {
                aqt_issuer_choreography_detached_record_append_locked(
                    detached,
                    record
                );
                state->authority_records[index] = NULL;
            }
        }
        for (index = 0;
             index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
             index++) {
            AqtIssuerChoreographyRecord *record = state->witness_records[index];

            if (record != NULL) {
                aqt_issuer_choreography_detached_record_append_locked(
                    detached,
                    record
                );
                state->witness_records[index] = NULL;
            }
        }
        lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        lease_record->install_or_terminal_state_revision = target.revision;
        recovery_record->install_or_terminal_state_revision = target.revision;
        if (request->operation_tag
                == AQT_CHOREOGRAPHY_OPERATION_ISSUE_BINDER
            || request->operation_tag
                == AQT_CHOREOGRAPHY_OPERATION_ADMIT_BINDER
            || !committed_is_present) {
            binder_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
            binder_record->install_or_terminal_state_revision = target.revision;
        }
        if (claim_record != NULL
            && (!committed_is_present
                || committed->phase == AQT_CHOREOGRAPHY_PHASE_ARMED)) {
            claim_record->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
            claim_record->install_or_terminal_state_revision = target.revision;
        }
    }
    state->value = target;
    state->failclosed_origin = origin;
    cell->persistent_state_revision = target.revision;
    if (shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY) {
        if (*prepared_roots == NULL
            || *detached_projection != NULL
            || shadow->projection == NULL) {
            abort();
        }
        *detached_projection = shadow->projection;
        shadow->projection = *prepared_roots;
        *prepared_roots = NULL;
        shadow->state = AQT_ISSUER_NATIVE_STATE_BURNED;
        shadow->revision = 4U;
        shadow->poisoned = 1U;
        aqt_issuer_choreography_cell_publish_lifecycle_locked(
            shadow,
            AQT_CHOREOGRAPHY_CELL_BURNED,
            0U
        );
    }
    return aqt_issuer_choreography_early_transition_failclosed_origin_is_exact_locked(
            state
        )
        && aqt_issuer_choreography_early_transition_cleanup_records_are_exact_locked(
            request,
            expected,
            committed,
            committed_is_present,
            target_policy,
            target.revision,
            state,
            cell
        )
        && aqt_issuer_choreography_cell_is_exact_locked(shadow);
}

static PyObject *
aqt_issuer_choreography_checkpoint(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyAuthority *lease_wrapper,
    unsigned int selector
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerChoreographyRecord *lease_record;
    AqtIssuerChoreographyRecord *recovery_record = NULL;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerFailure failure = {0};
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    uint64_t sampled_now = 0U;
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int saved_errno = 0;
    int authority_proof_failed = 0;
    int candidate_was_stored = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int index;

    if (module_state == NULL) {
        return NULL;
    }
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        return NULL;
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        if (!PyErr_Occurred()) {
            PyErr_SetString(
                PyExc_RuntimeError,
                "native issuer choreography checkpoint owner is invalid"
            );
        }
        return NULL;
    }
    prepared_roots = aqt_clone_issuer_roots_projection(shadow->projection);
    if (prepared_roots == NULL) {
        return NULL;
    }
    lease_record = lease_wrapper->record;
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography checkpoint owner changed"
        );
    }
    if (shadow->choreography_state_present
        && shadow->choreography_state.value.phase
            == AQT_CHOREOGRAPHY_PHASE_REVOKED) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography checkpoint is unavailable"
        );
    }
    if (!aqt_issuer_choreography_checkpoint_source_is_exact_locked(
            shadow,
            lease_record,
            current_thread,
            current_thread_id
        )) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography checkpoint source is invalid"
        );
    }
    if (fault_plan->row_count != 0
        && fault_plan->group == 3
        && atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography checkpoint fault and fork plans conflict"
        );
    }
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            AQT_CHOREOGRAPHY_OPERATION_CHECKPOINT,
            shadow->choreography_state.value.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography fault plan does not match checkpoint"
        );
    }
    recovery_record = shadow->choreography_state.authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    expected = shadow->choreography_state.value;
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    memset(&candidate, 0, sizeof(candidate));
    if (selector == AQT_CHOREOGRAPHY_TIME_SAMPLE
        && aqt_issuer_choreography_sample_continuous_ns(&sampled_now) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
    }
    if (saved_errno == 0
        && aqt_issuer_external_projection_matches(shadow->projection) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
        authority_proof_failed = 1;
    }
    if (saved_errno == 0
        && aqt_validate_launch_lock_core_locked(shadow->launch_lease) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
        authority_proof_failed = 1;
    }
    if (saved_errno == 0) {
        aqt_run_issuer_external_projection_barrier(module_state);
        if (aqt_issuer_external_projection_matches(shadow->projection) < 0) {
            aqt_issuer_choreography_checkpoint_capture_authority_failure(
                &saved_errno,
                &authority_proof_failed
            );
        }
    }
    if (saved_errno == 0) {
        aqt_issuer_choreography_build_checkpoint_candidate_locked(
            &expected,
            selector,
            sampled_now,
            &candidate
        );
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && saved_errno == 0) {
        if (fork_point
                != AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_choreography_transition_locked(
                shadow,
                AQT_CHOREOGRAPHY_OPERATION_CHECKPOINT,
                &expected,
                &candidate,
                1,
                lease_record,
                recovery_record,
                NULL,
                NULL,
                NULL,
                NULL,
                0U,
                0U,
                0U,
                0U,
                0U,
                0U,
                0U,
                0,
                0,
                NULL
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT;
        }
        aqt_issuer_choreography_publish_checkpoint_candidate_locked(
            shadow,
            &candidate,
            lease_record,
            recovery_record,
            &detached
        );
        candidate_was_stored = 1;
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
        if (primary_kind < 0
            && !aqt_issuer_choreography_cell_is_exact_locked(shadow)) {
            abort();
        }
        if (primary_kind < 0) {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
        }
    }
    if (primary_kind < 0 && saved_errno == 0) {
        if (fork_was_triggered) {
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
        }
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        if (fork_was_triggered
            && aqt_issuer_foreign_fork_wait_for_value(
                &module_state->issuer_foreign_fork_plan.worker_completed,
                1
            ) < 0) {
            aqt_fail_stop(
                "native issuer checkpoint foreign-fork worker timed out"
            );
        }
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        aqt_issuer_choreography_detached_records_release(&detached);
        Py_RETURN_NONE;
    }
    if (fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
        aqt_issuer_foreign_fork_bind_choreography_transition_locked(
            shadow,
            AQT_CHOREOGRAPHY_OPERATION_CHECKPOINT,
            &expected,
            &candidate,
            candidate_was_stored,
            lease_record,
            recovery_record,
            NULL,
            NULL,
            NULL,
            NULL,
            0U,
            0U,
            0U,
            0U,
            0U,
            0U,
            0U,
            0,
            0,
            NULL
        );
        if (aqt_issuer_foreign_fork_interpose_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ) < 0) {
            abort();
        }
        fork_was_triggered = 1;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_checkpoint_cleanup_reconcile_locked(
                shadow,
                &expected,
                &candidate,
                candidate_was_stored,
                lease_record,
                recovery_record,
                authority_proof_failed,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography checkpoint cleanup attempt failed"
            );
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_checkpoint_cleanup_reconcile_locked(
            shadow,
            &expected,
            &candidate,
            candidate_was_stored,
            lease_record,
            recovery_record,
            authority_proof_failed,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography checkpoint cleanup confirmation failed"
        );
    }
    if (fork_was_triggered) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed,
            1
        ) < 0) {
        aqt_fail_stop(
            "native issuer checkpoint cleanup foreign-fork worker timed out"
        );
    }
    aqt_clear_issuer_external_projection_barrier(module_state);
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    else {
        aqt_issuer_failure_record_errno(&failure, saved_errno);
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0) {
            aqt_issuer_failure_record_synthetic(
                &failure,
                cleanup_kinds[index]
            );
        }
    }
    return aqt_issuer_choreography_failure_raise(&failure);
}

static int
aqt_issuer_choreography_early_claim_proof_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyEarlyTransitionRequest *request,
    int installed
)
{
    AqtIssuerChoreographyRecord *record = request->claim_record;
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;

    if (record == NULL
        || cell == NULL
        || !record->wrapper_live
        || !aqt_issuer_choreography_record_is_exact_locked(
            record,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )) {
        errno = EINVAL;
        return -1;
    }
    if (!installed) {
        if (state->value.phase != AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED
            || record->status != AQT_CHOREOGRAPHY_WITNESS_PREPARED
            || record->prepared_at_revision != state->value.revision
            || record->install_or_terminal_state_revision != 0U
            || !aqt_issuer_choreography_projection5_is_exact(
                &record->payload.claim.projection,
                &state->value
            )) {
            errno = EINVAL;
            return -1;
        }
        return 0;
    }
    if (state->value.phase != AQT_CHOREOGRAPHY_PHASE_ARMED
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != record
        || record->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        || record->install_or_terminal_state_revision != state->value.revision
        || memcmp(
            &record->payload.claim,
            &state->value.claim,
            sizeof(state->value.claim)
        ) != 0) {
        errno = EINVAL;
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_early_authority_proof_locked(
    AqtModuleState *module_state,
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyEarlyTransitionRequest *request,
    int claim_proof,
    int installed_claim,
    int consume_barrier
)
{
    if (claim_proof
        && aqt_issuer_choreography_early_claim_proof_locked(
            shadow,
            request,
            installed_claim
        ) < 0) {
        return -1;
    }
    if (aqt_issuer_external_projection_matches(shadow->projection) < 0
        || aqt_validate_launch_lock_core_locked(shadow->launch_lease) < 0
        || (!consume_barrier
            && aqt_issuer_external_projection_matches(shadow->projection) < 0)) {
        return -1;
    }
    if (consume_barrier) {
        aqt_run_issuer_external_projection_barrier(module_state);
        if (aqt_issuer_external_projection_matches(shadow->projection) < 0) {
            return -1;
        }
    }
    return 0;
}

static int
aqt_issuer_choreography_active_foreign_fork_point_locked(
    AqtTopologyObservationIssuerShadow *shadow
)
{
    AqtIssuerForeignForkPlan *plan = atomic_load_explicit(
        &aqt_active_issuer_foreign_fork_plan,
        memory_order_acquire
    );

    if (plan == NULL) {
        return -1;
    }
    if (plan->shadow != shadow
        || plan->origin_pid != getpid()
        || (plan->point
                != AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            && plan->point
                != AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT)) {
        abort();
    }
    return plan->point;
}

static PyObject *
aqt_issuer_choreography_early_transition(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyEarlyTransitionRequest *request
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerChoreographyCurrentPreparationSource authorization_source;
    AqtIssuerChoreographyRecord *supplied_lease;
    AqtIssuerChoreographyRecord *supplied_recovery;
    AqtIssuerChoreographyRecord *supplied_binder;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerFailure failure = {0};
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    uint64_t sampled_now = 0U;
    const char *ordinary_message = NULL;
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int saved_errno = 0;
    int candidate_was_stored = 0;
    int terminal_proof_completed = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int fork_commit_completed = 0;
    int take_result = 1;
    int index;

    memset(&authorization_source, 0, sizeof(authorization_source));
    memset(&expected, 0, sizeof(expected));
    memset(&candidate, 0, sizeof(candidate));
    if (module_state == NULL || request == NULL) {
        return NULL;
    }
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        return NULL;
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        PyErr_Clear();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography recovery claim binder is unavailable"
        );
        return NULL;
    }
    prepared_roots = aqt_clone_issuer_roots_projection(shadow->projection);
    if (prepared_roots == NULL) {
        return NULL;
    }
    supplied_lease = request->lease_record;
    supplied_recovery = request->recovery_record;
    supplied_binder = request->binder_record;
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_early_transition_source_is_exact_locked(
            shadow,
            request,
            current_thread,
            current_thread_id
        )) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography recovery claim binder is unavailable"
        );
    }
    if (fault_plan->row_count != 0
        && fault_plan->group == 3
        && atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography transition fault and fork plans conflict"
        );
    }
    expected = shadow->choreography_state.value;
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            (int)request->operation_tag,
            expected.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography fault plan does not match transition"
        );
    }
    if (request->operation_tag == AQT_CHOREOGRAPHY_OPERATION_ISSUE_BINDER) {
        const AqtIssuerChoreographyRecordKey *supplied_lease_key =
            supplied_lease != NULL ? &supplied_lease->key : NULL;
        const AqtIssuerChoreographyRecordKey *supplied_recovery_key =
            supplied_recovery != NULL ? &supplied_recovery->key : NULL;
        const AqtIssuerChoreographyRecordKey *supplied_binder_key =
            supplied_binder != NULL ? &supplied_binder->key : NULL;

        aqt_issuer_choreography_capture_current_state_source_locked(
            shadow,
            &authorization_source
        );
        request->lease_record = shadow->choreography_state.authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ];
        request->recovery_record = shadow->choreography_state.authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ];
        request->binder_record = request->authorization->binder_record;
        take_result = aqt_issuer_claimed_fence_authorization_take_locked(
            request->authorization,
            &authorization_source,
            supplied_lease_key,
            supplied_recovery_key,
            supplied_binder_key,
            request->roots.artifact_directory,
            request->roots.artifact_directory_length,
            request->roots.ignored_root,
            request->roots.ignored_root_length,
            expected.revision + 1U,
            current_pid,
            current_interpreter,
            current_thread,
            current_thread_id
        );
        if (take_result != 1) {
            ordinary_message =
                "native issuer choreography recovery claim binder is unavailable";
        }
    }
    else {
        request->lease_record = shadow->choreography_state.authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ];
        request->recovery_record = shadow->choreography_state.authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ];
    }
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    if (ordinary_message == NULL
        && request->operation_tag == AQT_CHOREOGRAPHY_OPERATION_ARM_CLAIM
        && request->selector == AQT_CHOREOGRAPHY_TIME_SAMPLE
        && aqt_issuer_choreography_sample_continuous_ns(&sampled_now) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
    }
    if (ordinary_message == NULL && saved_errno == 0) {
        int proof_result = 0;

        if (request->operation_tag != AQT_CHOREOGRAPHY_OPERATION_ARM_CLAIM) {
            proof_result = aqt_issuer_choreography_early_authority_proof_locked(
                module_state,
                shadow,
                request,
                0,
                0,
                1
            );
        }
        if (proof_result == 0
            && request->operation_tag == AQT_CHOREOGRAPHY_OPERATION_ARM_CLAIM) {
            proof_result = aqt_issuer_choreography_early_authority_proof_locked(
                module_state,
                shadow,
                request,
                1,
                0,
                0
            );
        }

        if (proof_result < 0) {
            saved_errno = errno != 0 ? errno : EIO;
        }
    }
    if (ordinary_message == NULL && saved_errno == 0) {
        if (request->operation_tag
                == AQT_CHOREOGRAPHY_OPERATION_ISSUE_BINDER) {
            aqt_issuer_choreography_build_issue_binder_candidate_locked(
                &expected,
                &request->binder_record->key,
                &request->roots,
                &candidate
            );
        }
        else if (request->operation_tag
                == AQT_CHOREOGRAPHY_OPERATION_ADMIT_BINDER) {
            aqt_issuer_choreography_build_admit_binder_candidate_locked(
                &expected,
                &candidate
            );
        }
        else {
            aqt_issuer_choreography_build_arm_claim_candidate_locked(
                &expected,
                &request->claim_record->payload.claim,
                request->selector,
                sampled_now,
                &candidate
            );
        }
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && ordinary_message == NULL && saved_errno == 0) {
        if (fork_point
                != AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_choreography_transition_locked(
                shadow,
                request->operation_tag,
                &expected,
                &candidate,
                1,
                request->lease_record,
                request->recovery_record,
                request->binder_record,
                request->claim_record,
                NULL,
                NULL,
                0U,
                0U,
                0U,
                0U,
                0U,
                0U,
                0U,
                0,
                0,
                request->authorization
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT;
        }
        aqt_issuer_choreography_publish_early_transition_candidate_locked(
            shadow,
            request,
            &candidate,
            &detached
        );
        candidate_was_stored = 1;
        if (request->operation_tag
                == AQT_CHOREOGRAPHY_OPERATION_ARM_CLAIM
            && (candidate.phase == AQT_CHOREOGRAPHY_PHASE_REVOKED
                || candidate.phase == AQT_CHOREOGRAPHY_PHASE_EXPIRED)) {
            ordinary_message =
                "native issuer choreography recovery retention deadline is unavailable";
        }
        else {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
                1,
                current_pid,
                current_interpreter
            );
        }
        if (fork_was_triggered) {
            if (!aqt_issuer_choreography_cell_is_exact_locked(shadow)) {
                abort();
            }
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
            aqt_unlock_owner_list_or_fail_stop();
            if (aqt_issuer_foreign_fork_wait_for_value(
                    &module_state->issuer_foreign_fork_plan.worker_completed,
                    1
                ) < 0) {
                aqt_fail_stop(
                    "native issuer early-transition foreign-fork worker timed out"
                );
            }
            aqt_lock_owner_list_or_fail_stop();
            if (!aqt_issuer_choreography_cell_is_exact_locked(shadow)
                || !shadow->choreography_state_present
                || memcmp(
                    &shadow->choreography_state.value,
                    &candidate,
                    sizeof(candidate)
                ) != 0
                || !aqt_issuer_choreography_memory_is_zero(
                    &shadow->choreography_state.failclosed_origin,
                    sizeof(shadow->choreography_state.failclosed_origin)
                )) {
                aqt_fail_stop(
                    "native issuer early-transition changed across foreign fork"
                );
            }
        }
        if (primary_kind < 0 && ordinary_message == NULL
            && request->operation_tag
                == AQT_CHOREOGRAPHY_OPERATION_ARM_CLAIM) {
            if (aqt_issuer_choreography_early_authority_proof_locked(
                    module_state,
                    shadow,
                    request,
                    1,
                    1,
                    1
                ) < 0) {
                saved_errno = errno != 0 ? errno : EIO;
            }
            else {
                terminal_proof_completed = 1;
            }
        }
        if (primary_kind < 0 && ordinary_message == NULL && saved_errno == 0) {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
        }
    }
    if (primary_kind < 0 && ordinary_message == NULL && saved_errno == 0) {
        if (!aqt_issuer_choreography_cell_is_exact_locked(shadow)) {
            abort();
        }
        if (fork_was_triggered && !fork_commit_completed) {
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
        }
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        if (fork_was_triggered
            && aqt_issuer_foreign_fork_wait_for_value(
                &module_state->issuer_foreign_fork_plan.worker_completed,
                1
            ) < 0) {
            aqt_fail_stop(
                "native issuer early-transition foreign-fork worker timed out"
            );
        }
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        aqt_issuer_choreography_detached_records_release(&detached);
        Py_RETURN_NONE;
    }
    if (fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
        aqt_issuer_foreign_fork_bind_choreography_transition_locked(
            shadow,
            request->operation_tag,
            &expected,
            &candidate,
            candidate_was_stored,
            request->lease_record,
            request->recovery_record,
            request->binder_record,
            request->claim_record,
            NULL,
            NULL,
            0U,
            0U,
            0U,
            0U,
            0U,
            0U,
            0U,
            0,
            0,
            request->authorization
        );
        if (aqt_issuer_foreign_fork_interpose_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ) < 0) {
            abort();
        }
        fork_was_triggered = 1;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_early_transition_cleanup_reconcile_locked(
                shadow,
                request,
                &expected,
                &candidate,
                candidate_was_stored,
                terminal_proof_completed,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography early-transition cleanup attempt failed"
            );
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_early_transition_cleanup_reconcile_locked(
            shadow,
            request,
            &expected,
            &candidate,
            candidate_was_stored,
            terminal_proof_completed,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography early-transition cleanup confirmation failed"
        );
    }
    if (fork_was_triggered && !fork_commit_completed) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
        fork_commit_completed = 1;
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed,
            1
        ) < 0) {
        aqt_fail_stop(
            "native issuer early-transition cleanup foreign-fork worker timed out"
        );
    }
    aqt_clear_issuer_external_projection_barrier(module_state);
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    else if (saved_errno != 0) {
        aqt_issuer_failure_record_errno(&failure, saved_errno);
    }
    else if (ordinary_message != NULL) {
        PyErr_SetString(PyExc_RuntimeError, ordinary_message);
        aqt_issuer_failure_capture_python(&failure);
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0) {
            aqt_issuer_failure_record_synthetic(&failure, cleanup_kinds[index]);
        }
    }
    return aqt_issuer_choreography_failure_raise(&failure);
}

static PyObject *
aqt_issuer_choreography_issue_binder(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyEarlyTransitionRequest *request
)
{
    return aqt_issuer_choreography_early_transition(module, shadow, request);
}

static PyObject *
aqt_issuer_choreography_admit_binder(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyEarlyTransitionRequest *request
)
{
    return aqt_issuer_choreography_early_transition(module, shadow, request);
}

static PyObject *
aqt_issuer_choreography_arm_claim(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyEarlyTransitionRequest *request
)
{
    return aqt_issuer_choreography_early_transition(module, shadow, request);
}

static int
aqt_issuer_choreography_salvage_fault_plan_is_compatible_locked(
    const AqtIssuerChoreographyFaultPlan *plan,
    unsigned int source_phase,
    unsigned int selector
)
{
    size_t index;

    if (plan == NULL || source_phase > AQT_CHOREOGRAPHY_PHASE_ARMED) {
        return 0;
    }
    if (plan->row_count == 0 || plan->group != 3) {
        return 1;
    }
    if (source_phase == AQT_CHOREOGRAPHY_PHASE_ARMED) {
        return 0;
    }
    if (selector != AQT_CHOREOGRAPHY_TIME_ROLLBACK
        && selector != AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE) {
        return 1;
    }
    for (index = 0; index < AQT_ISSUER_CHOREOGRAPHY_FAULT_ROWS; index++) {
        const AqtIssuerChoreographyFaultRow *row = &plan->rows[index];

        if (row->active
            && (row->point
                    == AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE
                || row->point
                    == AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN)) {
            return 0;
        }
    }
    return 1;
}

static int
aqt_issuer_choreography_salvage_source_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographySalvageTransitionRequest *request,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *binder = request->binder_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    int source_is_claim_admitted;
    int lifecycle_is_active;
    int lifecycle_is_burned;

    if (request == NULL
        || request->operation_tag != AQT_CHOREOGRAPHY_OPERATION_SALVAGE_CLAIM
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || cell == NULL
        || cell->alive != 1U
        || cell->pending_scope_generation != 0U
        || !shadow->choreography_state_present
        || state->value.revision > UINT64_MAX - 2U
        || state->value.revision != cell->persistent_state_revision
        || state->value.binding_generation != cell->binding_generation
        || state->value.scope_generation != cell->current_scope_generation
        || !aqt_issuer_choreography_salvage_source_value_is_exact(
            &state->value
        )) {
        return 0;
    }
    source_is_claim_admitted = state->value.phase
        == AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED;
    if ((source_is_claim_admitted
            && request->selector == AQT_CHOREOGRAPHY_TIME_SAME)
        || (!source_is_claim_admitted
            && request->selector != AQT_CHOREOGRAPHY_TIME_SAME)
        || request->selector >= AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT) {
        return 0;
    }
    lifecycle_is_active =
        shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        && shadow->revision == 3U
        && shadow->poisoned == 0U
        && cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_ACTIVE
        && cell->action_live == 1U
        && shadow->projection != NULL
        && !aqt_issuer_projection_is_roots_only(shadow->projection);
    lifecycle_is_burned =
        shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED
        && (shadow->revision == 3U || shadow->revision == 4U)
        && shadow->poisoned == 1U
        && cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_BURNED
        && cell->action_live == 0U
        && aqt_issuer_projection_is_roots_only(shadow->projection);
    if ((source_is_claim_admitted && !lifecycle_is_active)
        || (!source_is_claim_admitted
            && !lifecycle_is_active && !lifecycle_is_burned)) {
        return 0;
    }
    lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    if (lease == NULL || recovery == NULL || binder == NULL || claim == NULL
        || request->lease_record != lease
        || request->recovery_record != recovery
        || !binder->wrapper_live || !claim->wrapper_live
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            binder,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || !aqt_issuer_choreography_record_key_equals(
            &lease->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &recovery->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )) {
        return 0;
    }
    if (source_is_claim_admitted) {
        return state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
            ] == binder
            && state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
            ] == NULL
            && binder->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && aqt_issuer_choreography_record_key_equals(
                &binder->key,
                &state->value.authority_keys[
                    AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
                ]
            )
            && claim->status == AQT_CHOREOGRAPHY_WITNESS_PREPARED
            && claim->prepared_at_revision == state->value.revision
            && claim->install_or_terminal_state_revision == 0U
            && claim->key.scope_generation == state->value.scope_generation
            && aqt_issuer_choreography_record_key_equals(
                &claim->payload.claim.key,
                &claim->key
            )
            && aqt_issuer_choreography_projection5_is_exact(
                &claim->payload.claim.projection,
                &state->value
            )
            && aqt_issuer_choreography_sha256_is_exact(
                claim->payload.claim.binding_sha256
            );
    }
    return state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] == NULL
        && state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] == claim
        && binder->status == AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED
        && claim->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        && binder->key.lifetime_generation == cell->lifetime_generation
        && binder->key.scope_generation == state->value.scope_generation
        && binder->install_or_terminal_state_revision != 0U
        && binder->install_or_terminal_state_revision
            == claim->install_or_terminal_state_revision
        && memcmp(
            &claim->payload.claim,
            &state->value.claim,
            sizeof(state->value.claim)
        ) == 0;
}

static int
aqt_issuer_choreography_salvage_selected_records_proof_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographySalvageTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    int installed
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *binder = request->binder_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    int source_is_claim_admitted = expected->phase
        == AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED;

    if (cell == NULL || lease == NULL || recovery == NULL
        || binder == NULL || claim == NULL
        || !binder->wrapper_live || !claim->wrapper_live
        || !aqt_issuer_choreography_cell_is_exact_locked(shadow)
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            binder,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || lease->install_or_terminal_state_revision
            != request->lease_initial_status_revision
        || recovery->install_or_terminal_state_revision
            != request->recovery_initial_status_revision) {
        errno = EINVAL;
        return -1;
    }
    if (source_is_claim_admitted && !installed) {
        if (state->value.phase != AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
            ] != binder
            || state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
            ] != NULL
            || binder->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            || binder->install_or_terminal_state_revision
                != request->binder_initial_status_revision
            || claim->status != AQT_CHOREOGRAPHY_WITNESS_PREPARED
            || claim->prepared_at_revision != state->value.revision
            || claim->install_or_terminal_state_revision != 0U
            || !aqt_issuer_choreography_projection5_is_exact(
                &claim->payload.claim.projection,
                &state->value
            )) {
            errno = EINVAL;
            return -1;
        }
        return 0;
    }
    if (state->value.phase != AQT_CHOREOGRAPHY_PHASE_ARMED
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != claim
        || binder->status != AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED
        || claim->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        || binder->install_or_terminal_state_revision
            != claim->install_or_terminal_state_revision
        || (source_is_claim_admitted
            ? binder->install_or_terminal_state_revision
                    != state->value.revision
                || claim->install_or_terminal_state_revision
                    != state->value.revision
            : binder->install_or_terminal_state_revision
                    != request->binder_initial_status_revision
                || claim->install_or_terminal_state_revision
                    != request->claim_initial_status_revision)
        || memcmp(
            &claim->payload.claim,
            &state->value.claim,
            sizeof(state->value.claim)
        ) != 0) {
        errno = EINVAL;
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_salvage_authority_proof_locked(
    AqtModuleState *module_state,
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographySalvageTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    int installed,
    int consume_barrier,
    unsigned int *authority_proof_failed
)
{
    int active = shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY;

    if (aqt_issuer_choreography_salvage_selected_records_proof_locked(
            shadow,
            request,
            expected,
            installed
        ) < 0) {
        return -1;
    }
    if (active
        && aqt_issuer_external_projection_matches(shadow->projection) < 0) {
        *authority_proof_failed = 1;
        return -1;
    }
    if (aqt_validate_launch_lock_core_locked(shadow->launch_lease) < 0) {
        *authority_proof_failed = 1;
        return -1;
    }
    if (consume_barrier) {
        aqt_run_issuer_external_projection_barrier(module_state);
    }
    if (active) {
        if (aqt_issuer_external_projection_matches(shadow->projection) < 0) {
            *authority_proof_failed = 1;
            return -1;
        }
    }
    else if (aqt_validate_launch_lock_core_locked(shadow->launch_lease) < 0) {
        *authority_proof_failed = 1;
        return -1;
    }
    return 0;
}

static void
aqt_issuer_choreography_resolve_salvage_candidate_locked(
    const AqtIssuerChoreographyStateValue *expected,
    AqtIssuerChoreographySalvageTransitionRequest *request,
    uint64_t sampled_now,
    AqtIssuerChoreographyStateValue *candidate
)
{
    uint64_t observed = expected->last_monotonic_ns;

    request->semantic_false = 0U;
    if (expected->phase == AQT_CHOREOGRAPHY_PHASE_ARMED) {
        request->observed_monotonic_ns = observed;
        *candidate = *expected;
        return;
    }
    switch (request->selector) {
        case AQT_CHOREOGRAPHY_TIME_SAMPLE:
            observed = sampled_now;
            request->semantic_false = sampled_now < expected->last_monotonic_ns
                || sampled_now >= expected->retention_deadline_monotonic_ns;
            break;
        case AQT_CHOREOGRAPHY_TIME_ROLLBACK:
            request->semantic_false = 1U;
            break;
        case AQT_CHOREOGRAPHY_TIME_ACTION_DEADLINE:
            observed = expected->action_deadline_monotonic_ns;
            break;
        case AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE:
            observed = expected->retention_deadline_monotonic_ns;
            request->semantic_false = 1U;
            break;
        default:
            abort();
    }
    request->observed_monotonic_ns = observed;
    if (request->semantic_false) {
        aqt_issuer_choreography_build_checkpoint_revoked_value(
            expected,
            expected->revision + 1U,
            expected->last_monotonic_ns,
            candidate
        );
        return;
    }
    aqt_issuer_choreography_build_salvage_armed_candidate_locked(
        expected,
        &request->claim_record->payload.claim,
        observed,
        candidate
    );
}

static void
aqt_issuer_choreography_publish_salvage_candidate_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographySalvageTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *candidate,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;

    if (cell == NULL
        || !aqt_issuer_choreography_salvage_candidate_value_is_exact(
            &state->value,
            candidate
        )
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != request->lease_record
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != request->recovery_record
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] != request->binder_record
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != NULL
        || request->binder_record->status
            != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || request->claim_record->status
            != AQT_CHOREOGRAPHY_WITNESS_PREPARED) {
        abort();
    }
    state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
    ] = NULL;
    aqt_issuer_choreography_detached_record_append_locked(
        detached,
        request->binder_record
    );
    request->binder_record->status = AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED;
    request->binder_record->install_or_terminal_state_revision =
        candidate->revision;
    aqt_issuer_choreography_record_incref(request->claim_record);
    state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
    ] = request->claim_record;
    request->claim_record->status = AQT_CHOREOGRAPHY_WITNESS_INSTALLED;
    request->claim_record->install_or_terminal_state_revision =
        candidate->revision;
    state->value = *candidate;
    memset(&state->failclosed_origin, 0, sizeof(state->failclosed_origin));
    cell->persistent_state_revision = candidate->revision;
}

static int
aqt_issuer_choreography_salvage_lifecycle_is_exact_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographySalvageTransitionRequest *request
)
{
    const AqtIssuerChoreographyAuthorityCell *cell;

    if (shadow == NULL || request == NULL
        || request->source_was_burned > 1U
        || request->semantic_false > 1U
        || request->authority_proof_failed > 1U
        || request->source_lifecycle_revision == 0U
        || request->source_projection == NULL
        || request->source_launch_lease == NULL
        || shadow->launch_lease != request->source_launch_lease
        || shadow->closed != 0U
        || shadow->lease_was_closed != 0U
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)) {
        return 0;
    }
    cell = shadow->choreography_authority_cell;
    if (cell == NULL) {
        return 0;
    }
    if (request->authority_proof_failed && !request->source_was_burned) {
        return shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED
            && shadow->revision == 4U
            && shadow->poisoned == 1U
            && shadow->projection != request->source_projection
            && aqt_issuer_projection_is_roots_only(shadow->projection)
            && cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_BURNED
            && cell->action_live == 0U;
    }
    if (shadow->projection != request->source_projection
        || shadow->revision != request->source_lifecycle_revision) {
        return 0;
    }
    if (request->source_was_burned) {
        return shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED
            && shadow->poisoned == 1U
            && aqt_issuer_projection_is_roots_only(shadow->projection)
            && cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_BURNED
            && cell->action_live == 0U;
    }
    return shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        && shadow->revision == 3U
        && shadow->poisoned == 0U
        && !aqt_issuer_projection_is_roots_only(shadow->projection)
        && cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_ACTIVE
        && cell->action_live == 1U;
}

static int
aqt_issuer_choreography_salvage_cleanup_records_are_exact_locked(
    const AqtIssuerChoreographySalvageTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *committed,
    int committed_is_present,
    const AqtIssuerChoreographyState *state,
    const AqtIssuerChoreographyAuthorityCell *cell
)
{
    const AqtIssuerChoreographyStateValue *target = &state->value;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *binder = request->binder_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    uint64_t binder_revision;
    unsigned int binder_status;
    size_t index;

    if (cell == NULL || lease == NULL || recovery == NULL
        || binder == NULL || claim == NULL
        || expected == NULL || committed == NULL
        || committed_is_present < 0 || committed_is_present > 1
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            binder,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )) {
        return 0;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        if (state->authority_records[index] != NULL) {
            return 0;
        }
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        if (state->witness_records[index] != NULL) {
            return 0;
        }
    }
    if (lease->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || lease->install_or_terminal_state_revision != target->revision
        || recovery->install_or_terminal_state_revision != target->revision) {
        return 0;
    }
    if (expected->phase == AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED) {
        binder_status = committed_is_present || request->semantic_false
            ? AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED
            : AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        binder_revision = committed_is_present
            ? committed->revision
            : target->revision;
        if (!aqt_issuer_choreography_record_key_equals(
                &binder->key,
                &expected->authority_keys[
                    AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
                ]
            )
            || claim->prepared_at_revision != expected->revision) {
            return 0;
        }
    }
    else {
        binder_status = AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED;
        binder_revision = request->binder_initial_status_revision;
        if (binder->key.lifetime_generation != cell->lifetime_generation
            || binder->key.scope_generation != expected->scope_generation
            || binder_revision == 0U
            || binder_revision != request->claim_initial_status_revision) {
            return 0;
        }
    }
    if (binder->status != binder_status
        || binder->install_or_terminal_state_revision != binder_revision
        || claim->status != AQT_CHOREOGRAPHY_WITNESS_CLEARED
        || claim->install_or_terminal_state_revision != target->revision) {
        return 0;
    }
    if (target->phase == AQT_CHOREOGRAPHY_PHASE_RECOVERY_UNCONFIRMED) {
        if (memcmp(
                &claim->payload.claim,
                &target->claim,
                sizeof(target->claim)
            ) != 0) {
            return 0;
        }
    }
    else if (target->phase != AQT_CHOREOGRAPHY_PHASE_REVOKED
        || !aqt_issuer_choreography_projection5_is_exact(
            &claim->payload.claim.projection,
            expected
        )
        || !aqt_issuer_choreography_sha256_is_exact(
            claim->payload.claim.binding_sha256
        )) {
        return 0;
    }
    return 1;
}

static int
aqt_issuer_choreography_salvage_cleanup_reconcile_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographySalvageTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *committed,
    int committed_is_present,
    AqtIssuerActivationProjection **prepared_roots,
    AqtIssuerActivationProjection **detached_projection,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyStateValue target;
    AqtIssuerChoreographyFailclosedOrigin origin;
    size_t index;

    aqt_issuer_choreography_build_salvage_cleanup_target_locked(
        expected,
        committed,
        committed_is_present,
        &target
    );
    aqt_issuer_choreography_build_salvage_failclosed_origin(
        expected,
        committed,
        committed_is_present,
        &target,
        &origin
    );
    if (cell != NULL
        && cell->persistent_state_revision == target.revision
        && memcmp(&state->value, &target, sizeof(target)) == 0
        && memcmp(&state->failclosed_origin, &origin, sizeof(origin)) == 0) {
        return aqt_issuer_choreography_salvage_lifecycle_is_exact_locked(
                shadow,
                request
            )
            && aqt_issuer_choreography_salvage_cleanup_records_are_exact_locked(
                request,
                expected,
                committed,
                committed_is_present,
                state,
                cell
            )
            && aqt_issuer_choreography_salvage_failclosed_origin_is_exact_locked(
                state
            )
            && aqt_issuer_choreography_cell_is_exact_locked(shadow);
    }
    if (cell == NULL
        || cell->persistent_state_revision
            != expected->revision + (committed_is_present ? 1U : 0U)
        || memcmp(
            &state->value,
            committed_is_present ? committed : expected,
            sizeof(*expected)
        ) != 0
        || !aqt_issuer_choreography_failclosed_origin_is_exact_locked(state)) {
        return 0;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->authority_records[index];

        if (record != NULL) {
            aqt_issuer_choreography_detached_record_append_locked(
                detached,
                record
            );
            state->authority_records[index] = NULL;
        }
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->witness_records[index];

        if (record != NULL) {
            aqt_issuer_choreography_detached_record_append_locked(
                detached,
                record
            );
            state->witness_records[index] = NULL;
        }
    }
    request->lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    request->lease_record->install_or_terminal_state_revision = target.revision;
    request->recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    request->recovery_record->install_or_terminal_state_revision =
        target.revision;
    if (expected->phase == AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED) {
        request->binder_record->status =
            committed_is_present || request->semantic_false
            ? AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED
            : AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->binder_record->install_or_terminal_state_revision =
            committed_is_present ? committed->revision : target.revision;
    }
    request->claim_record->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
    request->claim_record->install_or_terminal_state_revision = target.revision;
    state->value = target;
    state->failclosed_origin = origin;
    cell->persistent_state_revision = target.revision;
    if (request->authority_proof_failed) {
        aqt_issuer_choreography_recovery_burn_locked(
            shadow,
            prepared_roots,
            detached_projection
        );
    }
    return aqt_issuer_choreography_salvage_lifecycle_is_exact_locked(
            shadow,
            request
        )
        && aqt_issuer_choreography_salvage_cleanup_records_are_exact_locked(
            request,
            expected,
            committed,
            committed_is_present,
            state,
            cell
        )
        && aqt_issuer_choreography_salvage_failclosed_origin_is_exact_locked(
            state
        )
        && aqt_issuer_choreography_cell_is_exact_locked(shadow);
}

static int
aqt_issuer_choreography_checkpoint_g_salvage_transition_self_test(void)
{
    static const char artifact_directory[] = "/tmp/aqt-g/trusted-time";
    static const char ignored_root[] = "/tmp/aqt-g";
    static const char operation_id[] =
        "123e4567-e89b-42d3-a456-426614174000";
    AqtIssuerChoreographyStateValue unbound;
    AqtIssuerChoreographyStateValue binder_issued;
    AqtIssuerChoreographyStateValue claim_admitted;
    AqtIssuerChoreographyStateValue armed;
    AqtIssuerChoreographyStateValue target;
    AqtIssuerChoreographyRoots2 roots;
    AqtIssuerChoreographyClaimSummary claim;
    AqtIssuerChoreographyAuthorityCell cell;
    AqtIssuerChoreographyRecord lease_record;
    AqtIssuerChoreographyRecord recovery_record;
    AqtIssuerChoreographyRecord binder_record;
    AqtIssuerChoreographyRecord claim_record;
    AqtIssuerChoreographySalvageTransitionRequest request;
    AqtIssuerChoreographyState state;
    AqtIssuerChoreographyRecordKey binder_key = {1U, 3U, 3U};

    memset(&unbound, 0, sizeof(unbound));
    unbound.revision = 7U;
    unbound.binding_generation = 2U;
    unbound.scope_generation = 3U;
    unbound.started_monotonic_ns = 100U;
    unbound.last_monotonic_ns = 100U;
    unbound.action_deadline_monotonic_ns =
        100U + AQT_ISSUER_CHOREOGRAPHY_ACTION_INTERVAL_NS;
    unbound.retention_deadline_monotonic_ns =
        100U + AQT_ISSUER_CHOREOGRAPHY_RETENTION_INTERVAL_NS;
    unbound.phase = AQT_CHOREOGRAPHY_PHASE_UNBOUND;
    unbound.action_active = 1U;
    unbound.authority_keys[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ] = (AqtIssuerChoreographyRecordKey){1U, 3U, 1U};
    unbound.authority_keys[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ] = (AqtIssuerChoreographyRecordKey){1U, 3U, 2U};
    unbound.authority_record_presence_mask =
        (1U << AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE)
        | (1U
            << AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY);
    unbound.authority_statuses[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ] = AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED;
    unbound.authority_statuses[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ] = AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED;
    memset(&roots, 0, sizeof(roots));
    memcpy(
        roots.artifact_directory,
        artifact_directory,
        sizeof(artifact_directory)
    );
    roots.artifact_directory_length = sizeof(artifact_directory) - 1U;
    memcpy(roots.ignored_root, ignored_root, sizeof(ignored_root));
    roots.ignored_root_length = sizeof(ignored_root) - 1U;
    aqt_issuer_choreography_build_issue_binder_candidate_locked(
        &unbound,
        &binder_key,
        &roots,
        &binder_issued
    );
    aqt_issuer_choreography_build_admit_binder_candidate_locked(
        &binder_issued,
        &claim_admitted
    );
    if (!aqt_issuer_choreography_salvage_source_value_is_exact(
            &claim_admitted
        )) {
        return 0;
    }
    memset(&claim, 0, sizeof(claim));
    claim.key = (AqtIssuerChoreographyRecordKey){1U, 3U, 4U};
    memcpy(claim.projection.operation_id, operation_id, sizeof(operation_id));
    memset(claim.projection.approval_sha256, 'a', 64U);
    memset(claim.projection.claim_sha256, 'b', 64U);
    memset(claim.projection.retained_artifact_sha256, 'c', 64U);
    memcpy(
        claim.projection.artifact_directory,
        artifact_directory,
        sizeof(artifact_directory)
    );
    claim.projection.artifact_directory_length =
        sizeof(artifact_directory) - 1U;
    memset(claim.binding_sha256, 'd', 64U);
    aqt_issuer_choreography_build_salvage_armed_candidate_locked(
        &claim_admitted,
        &claim,
        claim_admitted.last_monotonic_ns,
        &armed
    );
    if (!aqt_issuer_choreography_salvage_candidate_value_is_exact(
            &claim_admitted,
            &armed
        )
        || armed.phase != AQT_CHOREOGRAPHY_PHASE_ARMED
        || armed.revision != claim_admitted.revision + 1U
        || armed.action_active != 1U) {
        return 0;
    }
    armed.claim.binding_sha256[0] = 'e';
    if (aqt_issuer_choreography_salvage_candidate_value_is_exact(
            &claim_admitted,
            &armed
        )) {
        return 0;
    }
    armed.claim.binding_sha256[0] = 'd';
    memset(&claim_record, 0, sizeof(claim_record));
    claim_record.payload.claim = claim;
    memset(&request, 0, sizeof(request));
    request.operation_tag = AQT_CHOREOGRAPHY_OPERATION_SALVAGE_CLAIM;
    request.selector = AQT_CHOREOGRAPHY_TIME_ROLLBACK;
    request.claim_record = &claim_record;
    aqt_issuer_choreography_resolve_salvage_candidate_locked(
        &claim_admitted,
        &request,
        UINT64_MAX,
        &target
    );
    if (!request.semantic_false
        || request.observed_monotonic_ns
            != claim_admitted.last_monotonic_ns
        || target.phase != AQT_CHOREOGRAPHY_PHASE_REVOKED
        || target.last_monotonic_ns != claim_admitted.last_monotonic_ns) {
        return 0;
    }
    aqt_issuer_choreography_build_salvage_cleanup_target_locked(
        &claim_admitted,
        &armed,
        0,
        &target
    );
    memset(&state, 0, sizeof(state));
    state.value = target;
    aqt_issuer_choreography_build_salvage_failclosed_origin(
        &claim_admitted,
        &armed,
        0,
        &target,
        &state.failclosed_origin
    );
    if (!aqt_issuer_choreography_salvage_failclosed_origin_is_exact_locked(
            &state
        )) {
        return 0;
    }
    state.failclosed_origin.operation_tag =
        AQT_CHOREOGRAPHY_OPERATION_ARM_CLAIM;
    if (aqt_issuer_choreography_salvage_failclosed_origin_is_exact_locked(
            &state
        )) {
        return 0;
    }
    state.failclosed_origin.operation_tag =
        AQT_CHOREOGRAPHY_OPERATION_SALVAGE_CLAIM;
    aqt_issuer_choreography_build_salvage_cleanup_target_locked(
        &claim_admitted,
        &armed,
        1,
        &target
    );
    state.value = target;
    aqt_issuer_choreography_build_salvage_failclosed_origin(
        &claim_admitted,
        &armed,
        1,
        &target,
        &state.failclosed_origin
    );
    if (!aqt_issuer_choreography_salvage_failclosed_origin_is_exact_locked(
            &state
        )
        || target.phase != AQT_CHOREOGRAPHY_PHASE_RECOVERY_UNCONFIRMED
        || target.last_monotonic_ns != armed.last_monotonic_ns) {
        return 0;
    }

    aqt_issuer_choreography_build_salvage_cleanup_target_locked(
        &armed,
        &armed,
        0,
        &target
    );
    memset(&cell, 0, sizeof(cell));
    atomic_init(&cell.reference_count, 1U);
    cell.lifetime_generation = 1U;
    cell.current_scope_generation = armed.scope_generation;
    cell.persistent_state_revision = target.revision;
    cell.binding_generation = armed.binding_generation;
    cell.checked_serial = 4U;
    cell.alive = 1U;
    cell.action_live = 1U;
    cell.lifecycle_disposition = AQT_CHOREOGRAPHY_CELL_ACTIVE;

    memset(&lease_record, 0, sizeof(lease_record));
    atomic_init(&lease_record.reference_count, 1U);
    lease_record.cell = &cell;
    lease_record.key = armed.authority_keys[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    lease_record.install_or_terminal_state_revision = target.revision;
    lease_record.record_class = AQT_CHOREOGRAPHY_RECORD_AUTHORITY;
    lease_record.kind = AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE;
    lease_record.status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    lease_record.wrapper_live = 1U;
    lease_record.wrapper_was_created = 1U;

    memset(&recovery_record, 0, sizeof(recovery_record));
    atomic_init(&recovery_record.reference_count, 1U);
    recovery_record.cell = &cell;
    recovery_record.key = armed.authority_keys[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    recovery_record.install_or_terminal_state_revision = target.revision;
    recovery_record.record_class = AQT_CHOREOGRAPHY_RECORD_AUTHORITY;
    recovery_record.kind =
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY;
    recovery_record.status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    recovery_record.wrapper_live = 1U;
    recovery_record.wrapper_was_created = 1U;

    memset(&binder_record, 0, sizeof(binder_record));
    atomic_init(&binder_record.reference_count, 1U);
    binder_record.cell = &cell;
    binder_record.key = binder_key;
    binder_record.prepared_at_revision = unbound.revision;
    binder_record.install_or_terminal_state_revision = armed.revision;
    binder_record.record_class = AQT_CHOREOGRAPHY_RECORD_AUTHORITY;
    binder_record.kind =
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER;
    binder_record.status = AQT_CHOREOGRAPHY_AUTHORITY_CONSUMED;
    binder_record.wrapper_live = 1U;
    binder_record.wrapper_was_created = 1U;

    memset(&claim_record, 0, sizeof(claim_record));
    atomic_init(&claim_record.reference_count, 1U);
    claim_record.cell = &cell;
    claim_record.key = claim.key;
    claim_record.payload.claim = target.claim;
    claim_record.prepared_at_revision = claim_admitted.revision;
    claim_record.install_or_terminal_state_revision = target.revision;
    claim_record.record_class = AQT_CHOREOGRAPHY_RECORD_WITNESS;
    claim_record.kind = AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM;
    claim_record.status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
    claim_record.wrapper_live = 1U;
    claim_record.wrapper_was_created = 1U;

    memset(&request, 0, sizeof(request));
    request.operation_tag = AQT_CHOREOGRAPHY_OPERATION_SALVAGE_CLAIM;
    request.lease_record = &lease_record;
    request.recovery_record = &recovery_record;
    request.binder_record = &binder_record;
    request.claim_record = &claim_record;
    request.lease_initial_status_revision = unbound.revision;
    request.recovery_initial_status_revision = unbound.revision;
    request.binder_initial_status_revision = armed.revision;
    request.claim_initial_status_revision = armed.revision;
    memset(&state, 0, sizeof(state));
    state.value = target;
    if (!aqt_issuer_choreography_salvage_cleanup_records_are_exact_locked(
            &request,
            &armed,
            &armed,
            0,
            &state,
            &cell
        )) {
        return 0;
    }
    request.binder_initial_status_revision--;
    if (aqt_issuer_choreography_salvage_cleanup_records_are_exact_locked(
            &request,
            &armed,
            &armed,
            0,
            &state,
            &cell
        )) {
        return 0;
    }
    request.binder_initial_status_revision++;
    request.claim_initial_status_revision--;
    if (aqt_issuer_choreography_salvage_cleanup_records_are_exact_locked(
            &request,
            &armed,
            &armed,
            0,
            &state,
            &cell
        )) {
        return 0;
    }
    request.claim_initial_status_revision++;
    binder_record.install_or_terminal_state_revision--;
    if (aqt_issuer_choreography_salvage_cleanup_records_are_exact_locked(
            &request,
            &armed,
            &armed,
            0,
            &state,
            &cell
        )) {
        return 0;
    }
    binder_record.install_or_terminal_state_revision++;
    claim_record.install_or_terminal_state_revision--;
    if (aqt_issuer_choreography_salvage_cleanup_records_are_exact_locked(
            &request,
            &armed,
            &armed,
            0,
            &state,
            &cell
        )) {
        return 0;
    }
    claim_record.install_or_terminal_state_revision++;
    memset(&request, 0, sizeof(request));
    request.operation_tag = AQT_CHOREOGRAPHY_OPERATION_SALVAGE_CLAIM;
    request.selector = AQT_CHOREOGRAPHY_TIME_SAME;
    request.claim_record = &claim_record;
    aqt_issuer_choreography_resolve_salvage_candidate_locked(
        &armed,
        &request,
        UINT64_MAX,
        &target
    );
    return !request.semantic_false
        && request.observed_monotonic_ns == armed.last_monotonic_ns
        && memcmp(&target, &armed, sizeof(target)) == 0;
}

static AqtIssuerForeignForkPlan *
aqt_issuer_choreography_salvage_request_point6_cancel_locked(
    AqtTopologyObservationIssuerShadow *shadow
)
{
    AqtIssuerForeignForkPlan *plan = atomic_load_explicit(
        &aqt_active_issuer_foreign_fork_plan,
        memory_order_acquire
    );

    if (plan == NULL
        || plan->shadow != shadow
        || plan->origin_pid != getpid()
        || plan->point
            != AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
        || atomic_load_explicit(&plan->stage, memory_order_acquire)
            != AQT_ISSUER_FOREIGN_FORK_ARMED
        || atomic_load_explicit(&plan->worker_ready, memory_order_acquire)
            != 1) {
        aqt_fail_stop(
            "native issuer salvage point6 cancellation binding is invalid"
        );
    }
    atomic_store_explicit(
        &plan->cancel_requested,
        1,
        memory_order_release
    );
    return plan;
}

static void
aqt_issuer_choreography_salvage_finish_point6_cancel(
    AqtIssuerForeignForkPlan *plan
)
{
    if (plan == NULL
        || aqt_issuer_foreign_fork_wait_for_value(
            &plan->worker_completed,
            1
        ) < 0
        || aqt_issuer_foreign_fork_join(plan) < 0) {
        aqt_fail_stop("native issuer salvage point6 cancellation timed out");
    }
    aqt_issuer_foreign_fork_clear_joined_plan(plan);
}

static PyObject *
aqt_issuer_choreography_salvage_claim(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographySalvageTransitionRequest *request
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerForeignForkPlan *cancelled_plan = NULL;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerFailure failure = {0};
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    uint64_t sampled_now = 0U;
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int saved_errno = 0;
    int candidate_was_stored = 0;
    int terminal_proof_completed = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int fork_commit_completed = 0;
    int source_is_claim_admitted;
    int index;

    memset(&expected, 0, sizeof(expected));
    memset(&candidate, 0, sizeof(candidate));
    if (module_state == NULL || request == NULL) {
        return NULL;
    }
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        aqt_clear_issuer_external_projection_barrier(module_state);
        return NULL;
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        PyErr_Clear();
        aqt_clear_issuer_external_projection_barrier(module_state);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography recovery claim salvage is unavailable"
        );
    }
    if (shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY) {
        prepared_roots = aqt_clone_issuer_roots_projection(shadow->projection);
        if (prepared_roots == NULL) {
            aqt_clear_issuer_external_projection_barrier(module_state);
            return NULL;
        }
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (shadow->choreography_state_present) {
        AqtIssuerChoreographyState *state = &shadow->choreography_state;

        request->lease_record = state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ];
        request->recovery_record = state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ];
    }
    if (!aqt_issuer_choreography_salvage_source_is_exact_locked(
            shadow,
            request,
            current_thread,
            current_thread_id
        )) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography recovery claim salvage is unavailable"
        );
    }
    source_is_claim_admitted = shadow->choreography_state.value.phase
        == AQT_CHOREOGRAPHY_PHASE_CLAIM_ADMITTED;
    request->source_was_burned =
        shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED ? 1U : 0U;
    request->source_lifecycle_revision = shadow->revision;
    request->source_projection = shadow->projection;
    request->source_launch_lease = shadow->launch_lease;
    request->lease_initial_status_revision =
        request->lease_record->install_or_terminal_state_revision;
    request->recovery_initial_status_revision =
        request->recovery_record->install_or_terminal_state_revision;
    request->binder_initial_status_revision =
        request->binder_record->install_or_terminal_state_revision;
    request->claim_initial_status_revision =
        request->claim_record->install_or_terminal_state_revision;
    expected = shadow->choreography_state.value;
    if (!aqt_issuer_choreography_salvage_fault_plan_is_compatible_locked(
            fault_plan,
            expected.phase,
            request->selector
        )) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography recovery claim salvage is unavailable"
        );
    }
    if (fault_plan->row_count != 0
        && fault_plan->group == 3
        && atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography salvage fault and fork plans conflict"
        );
    }
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    if (fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
        && (!source_is_claim_admitted
            || request->selector == AQT_CHOREOGRAPHY_TIME_ROLLBACK
            || request->selector
                == AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE)) {
        cancelled_plan =
            aqt_issuer_choreography_salvage_request_point6_cancel_locked(
                shadow
            );
        aqt_unlock_owner_list_or_fail_stop();
        aqt_issuer_choreography_salvage_finish_point6_cancel(cancelled_plan);
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography recovery claim salvage is unavailable"
        );
    }
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            AQT_CHOREOGRAPHY_OPERATION_SALVAGE_CLAIM,
            expected.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography recovery claim salvage is unavailable"
        );
    }
    if (source_is_claim_admitted
        && request->selector == AQT_CHOREOGRAPHY_TIME_SAMPLE
        && aqt_issuer_choreography_sample_continuous_ns(&sampled_now) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
    }
    if (saved_errno == 0) {
        aqt_issuer_choreography_resolve_salvage_candidate_locked(
            &expected,
            request,
            sampled_now,
            &candidate
        );
        if (aqt_issuer_choreography_salvage_authority_proof_locked(
                module_state,
                shadow,
                request,
                &expected,
                0,
                0,
                &request->authority_proof_failed
            ) < 0) {
            saved_errno = errno != 0 ? errno : EIO;
            request->semantic_false = 0U;
        }
    }
    if (saved_errno != 0
        && fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT) {
        cancelled_plan =
            aqt_issuer_choreography_salvage_request_point6_cancel_locked(
                shadow
            );
        aqt_unlock_owner_list_or_fail_stop();
        aqt_issuer_choreography_salvage_finish_point6_cancel(cancelled_plan);
        aqt_lock_owner_list_or_fail_stop();
        fork_point = -1;
        if (memcmp(
                &shadow->choreography_state.value,
                &expected,
                sizeof(expected)
            ) != 0
            || !aqt_issuer_choreography_salvage_source_is_exact_locked(
                shadow,
                request,
                current_thread,
                current_thread_id
            )
            || !fault_plan->operation_active
            || fault_plan->operation_tag
                != AQT_CHOREOGRAPHY_OPERATION_SALVAGE_CLAIM
            || fault_plan->operation_expected_revision != expected.revision) {
            aqt_fail_stop(
                "native issuer salvage source changed across point6 cancellation"
            );
        }
    }
    if (saved_errno == 0 && source_is_claim_admitted) {
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
        if (primary_kind >= 0) {
            request->semantic_false = 0U;
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
        && request->semantic_false) {
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        cancelled_plan =
            aqt_issuer_choreography_salvage_request_point6_cancel_locked(
                shadow
            );
        aqt_unlock_owner_list_or_fail_stop();
        aqt_issuer_choreography_salvage_finish_point6_cancel(cancelled_plan);
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography recovery claim salvage is unavailable"
        );
    }
    if (primary_kind < 0 && saved_errno == 0
        && source_is_claim_admitted && !request->semantic_false) {
        if (fork_point
                != AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_choreography_transition_locked(
                shadow,
                AQT_CHOREOGRAPHY_OPERATION_SALVAGE_CLAIM,
                &expected,
                &candidate,
                1,
                request->lease_record,
                request->recovery_record,
                request->binder_record,
                request->claim_record,
                NULL,
                NULL,
                request->lease_initial_status_revision,
                request->recovery_initial_status_revision,
                request->binder_initial_status_revision,
                request->claim_initial_status_revision,
                0U,
                0U,
                request->observed_monotonic_ns,
                0,
                0,
                NULL
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT;
        }
        aqt_issuer_choreography_publish_salvage_candidate_locked(
            shadow,
            request,
            &candidate,
            &detached
        );
        candidate_was_stored = 1;
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
        if (fork_was_triggered) {
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
            aqt_unlock_owner_list_or_fail_stop();
            if (aqt_issuer_foreign_fork_wait_for_value(
                    &module_state->issuer_foreign_fork_plan.worker_completed,
                    1
                ) < 0) {
                aqt_fail_stop(
                    "native issuer salvage foreign-fork worker timed out"
                );
            }
            aqt_lock_owner_list_or_fail_stop();
            if (!shadow->choreography_state_present
                || memcmp(
                    &shadow->choreography_state.value,
                    &candidate,
                    sizeof(candidate)
                ) != 0
                || !aqt_issuer_choreography_memory_is_zero(
                    &shadow->choreography_state.failclosed_origin,
                    sizeof(shadow->choreography_state.failclosed_origin)
                )) {
                aqt_fail_stop(
                    "native issuer salvage changed across foreign fork"
                );
            }
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && !request->semantic_false) {
        if (aqt_issuer_choreography_salvage_authority_proof_locked(
                module_state,
                shadow,
                request,
                &expected,
                source_is_claim_admitted ? 1 : 0,
                1,
                &request->authority_proof_failed
            ) < 0) {
            saved_errno = errno != 0 ? errno : EIO;
        }
        else {
            terminal_proof_completed = 1;
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && !request->semantic_false && terminal_proof_completed) {
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
            primary_kind = AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR;
        }
        else if (source_is_claim_admitted) {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && !request->semantic_false) {
        if (!aqt_issuer_choreography_cell_is_exact_locked(shadow)) {
            abort();
        }
        if (fork_was_triggered && !fork_commit_completed) {
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
        }
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        if (fork_was_triggered && !fork_commit_completed
            && aqt_issuer_foreign_fork_wait_for_value(
                &module_state->issuer_foreign_fork_plan.worker_completed,
                1
            ) < 0) {
            aqt_fail_stop(
                "native issuer salvage foreign-fork worker timed out"
            );
        }
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        aqt_free_issuer_projection(&detached_projection);
        aqt_issuer_choreography_detached_records_release(&detached);
        Py_RETURN_TRUE;
    }
    if (fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
        request->observed_monotonic_ns = candidate_was_stored
            ? candidate.last_monotonic_ns
            : (request->semantic_false
                    || expected.phase == AQT_CHOREOGRAPHY_PHASE_ARMED
                ? expected.last_monotonic_ns
                : 0U);
        aqt_issuer_foreign_fork_bind_choreography_transition_locked(
            shadow,
            AQT_CHOREOGRAPHY_OPERATION_SALVAGE_CLAIM,
            &expected,
            &candidate,
            candidate_was_stored,
            request->lease_record,
            request->recovery_record,
            request->binder_record,
            request->claim_record,
            NULL,
            NULL,
            request->lease_initial_status_revision,
            request->recovery_initial_status_revision,
            request->binder_initial_status_revision,
            request->claim_initial_status_revision,
            0U,
            0U,
            request->observed_monotonic_ns,
            request->semantic_false,
            request->authority_proof_failed,
            NULL
        );
        if (aqt_issuer_foreign_fork_interpose_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ) < 0) {
            abort();
        }
        fork_was_triggered = 1;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_salvage_cleanup_reconcile_locked(
                shadow,
                request,
                &expected,
                &candidate,
                candidate_was_stored,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography salvage cleanup attempt failed"
            );
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_salvage_cleanup_reconcile_locked(
            shadow,
            request,
            &expected,
            &candidate,
            candidate_was_stored,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography salvage cleanup confirmation failed"
        );
    }
    if (fork_was_triggered && !fork_commit_completed) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
        fork_commit_completed = 1;
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered && fork_commit_completed
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed,
            1
        ) < 0) {
        aqt_fail_stop(
            "native issuer salvage cleanup foreign-fork worker timed out"
        );
    }
    aqt_clear_issuer_external_projection_barrier(module_state);
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    else if (saved_errno != 0) {
        aqt_issuer_failure_record_errno(&failure, saved_errno);
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0) {
            aqt_issuer_failure_record_synthetic(
                &failure,
                cleanup_kinds[index]
            );
        }
    }
    if (!failure.has_selected && request->semantic_false) {
        Py_RETURN_FALSE;
    }
    return aqt_issuer_choreography_failure_raise(&failure);
}

static int
aqt_issuer_choreography_post_effect_transition_source_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyPostEffectTransitionRequest *request,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *claim;
    AqtIssuerChoreographyRecord *post_effect;

    if (request == NULL
        || request->operation_tag
            != AQT_CHOREOGRAPHY_OPERATION_ARM_POST_EFFECT
        || request->selector >= AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        || shadow->revision != 3U
        || shadow->poisoned != 0U
        || shadow->closed != 0U
        || shadow->busy != 0U
        || shadow->runtime_ready != 0U
        || shadow->projection == NULL
        || aqt_issuer_projection_is_roots_only(shadow->projection)
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || cell == NULL
        || cell->alive != 1U
        || cell->action_live != 1U
        || cell->lifecycle_disposition != AQT_CHOREOGRAPHY_CELL_ACTIVE
        || cell->pending_scope_generation != 0U
        || !shadow->choreography_state_present
        || state->value.revision > UINT64_MAX - 2U
        || state->value.revision != cell->persistent_state_revision
        || state->value.binding_generation != cell->binding_generation
        || state->value.scope_generation != cell->current_scope_generation
        || !aqt_issuer_choreography_post_effect_source_value_is_exact(
            &state->value
        )
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )) {
        return 0;
    }
    lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    claim = state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
    ];
    post_effect = request->post_effect_record;
    return lease != NULL && recovery != NULL && claim != NULL
        && post_effect != NULL
        && request->lease_record == lease
        && request->recovery_record == recovery
        && request->claim_record == claim
        && state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] == NULL
        && state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] == NULL
        && state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] == NULL
        && lease->wrapper_live && recovery->wrapper_live
        && claim->wrapper_live && post_effect->wrapper_live
        && lease->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        && claim->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        && post_effect->status == AQT_CHOREOGRAPHY_AUTHORITY_PREPARED
        && post_effect->prepared_at_revision == state->value.revision
        && post_effect->install_or_terminal_state_revision == 0U
        && post_effect->key.lifetime_generation == cell->lifetime_generation
        && post_effect->key.scope_generation == state->value.scope_generation
        && aqt_issuer_choreography_memory_is_zero(
            &post_effect->payload,
            sizeof(post_effect->payload)
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        && aqt_issuer_choreography_record_key_equals(
            &lease->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        && aqt_issuer_choreography_record_key_equals(
            &recovery->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        && aqt_issuer_choreography_record_key_equals(
            &claim->key,
            &state->value.claim.key
        )
        && memcmp(
            &claim->payload.claim,
            &state->value.claim,
            sizeof(state->value.claim)
        ) == 0;
}

static int
aqt_issuer_choreography_post_effect_selected_records_proof_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyPostEffectTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    int installed
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    AqtIssuerChoreographyRecord *post_effect = request->post_effect_record;

    if (cell == NULL || lease == NULL || recovery == NULL
        || claim == NULL || post_effect == NULL
        || !lease->wrapper_live || !recovery->wrapper_live
        || !claim->wrapper_live || !post_effect->wrapper_live
        || !aqt_issuer_choreography_cell_is_exact_locked(shadow)
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || post_effect->prepared_at_revision != expected->revision
        || !aqt_issuer_choreography_memory_is_zero(
            &post_effect->payload,
            sizeof(post_effect->payload)
        )
        || memcmp(
            &claim->payload.claim,
            &expected->claim,
            sizeof(expected->claim)
        ) != 0) {
        errno = EINVAL;
        return -1;
    }
    if (!installed) {
        if (memcmp(&state->value, expected, sizeof(*expected)) != 0
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] != lease
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] != recovery
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ] != NULL
            || state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
            ] != claim
            || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            || claim->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
            || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_PREPARED
            || lease->install_or_terminal_state_revision
                != request->lease_initial_status_revision
            || recovery->install_or_terminal_state_revision
                != request->recovery_initial_status_revision
            || claim->install_or_terminal_state_revision
                != request->claim_initial_status_revision
            || post_effect->install_or_terminal_state_revision != 0U) {
            errno = EINVAL;
            return -1;
        }
        return 0;
    }
    if (state->value.phase != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != claim
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || claim->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || lease->install_or_terminal_state_revision
            != request->lease_initial_status_revision
        || recovery->install_or_terminal_state_revision
            != request->recovery_initial_status_revision
        || claim->install_or_terminal_state_revision
            != request->claim_initial_status_revision
        || post_effect->install_or_terminal_state_revision
            != state->value.revision
        || !aqt_issuer_choreography_record_key_equals(
            &post_effect->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ]
        )) {
        errno = EINVAL;
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_post_effect_authority_proof_locked(
    AqtModuleState *module_state,
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyPostEffectTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    int installed,
    int consume_barrier,
    unsigned int *authority_proof_failed
)
{
    if (aqt_issuer_choreography_post_effect_selected_records_proof_locked(
            shadow,
            request,
            expected,
            installed
        ) < 0) {
        return -1;
    }
    if (aqt_issuer_external_projection_matches(shadow->projection) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    if (aqt_validate_launch_lock_core_locked(shadow->launch_lease) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    if (consume_barrier) {
        aqt_run_issuer_external_projection_barrier(module_state);
    }
    if (aqt_issuer_external_projection_matches(shadow->projection) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    return 0;
}

static void
aqt_issuer_choreography_publish_post_effect_candidate_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyPostEffectTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *candidate,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    AqtIssuerChoreographyRecord *post_effect = request->post_effect_record;
    uint64_t revision = candidate->revision;

    if (cell == NULL
        || !aqt_issuer_choreography_post_effect_candidate_value_is_exact(
            &state->value,
            candidate
        )
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != claim
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_PREPARED) {
        abort();
    }
    if (candidate->phase == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED) {
        aqt_issuer_choreography_record_incref(post_effect);
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] = post_effect;
        post_effect->status = AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED;
        post_effect->install_or_terminal_state_revision = revision;
    }
    else if (candidate->phase == AQT_CHOREOGRAPHY_PHASE_REVOKED) {
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] = NULL;
        state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] = NULL;
        aqt_issuer_choreography_detached_record_append_locked(detached, lease);
        aqt_issuer_choreography_detached_record_append_locked(detached, recovery);
        aqt_issuer_choreography_detached_record_append_locked(detached, claim);
        lease->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        recovery->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        claim->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        post_effect->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        lease->install_or_terminal_state_revision = revision;
        recovery->install_or_terminal_state_revision = revision;
        claim->install_or_terminal_state_revision = revision;
        post_effect->install_or_terminal_state_revision = revision;
    }
    else if (candidate->phase == AQT_CHOREOGRAPHY_PHASE_ARMED
        && candidate->action_active == 0U) {
        post_effect->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        post_effect->install_or_terminal_state_revision = revision;
    }
    else {
        abort();
    }
    state->value = *candidate;
    memset(&state->failclosed_origin, 0, sizeof(state->failclosed_origin));
    cell->persistent_state_revision = revision;
}

static int
aqt_issuer_choreography_post_effect_cleanup_lifecycle_is_exact_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyPostEffectTransitionRequest *request
)
{
    const AqtIssuerChoreographyAuthorityCell *cell;

    if (shadow == NULL || request == NULL
        || request->source_lifecycle_revision != 3U
        || request->source_projection == NULL
        || aqt_issuer_projection_is_roots_only(request->source_projection)
        || request->source_projection == shadow->projection
        || request->source_launch_lease == NULL
        || request->source_launch_lease != shadow->launch_lease
        || shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED
        || shadow->revision != 4U
        || shadow->poisoned != 1U
        || shadow->closed != 0U
        || shadow->lease_was_closed != 0U
        || !aqt_issuer_projection_is_roots_only(shadow->projection)
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)) {
        return 0;
    }
    cell = shadow->choreography_authority_cell;
    return cell != NULL
        && cell->alive == 1U
        && cell->action_live == 0U
        && cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_BURNED;
}

static int
aqt_issuer_choreography_post_effect_cleanup_records_are_exact_locked(
    const AqtIssuerChoreographyPostEffectTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *committed,
    int committed_is_present,
    const AqtIssuerChoreographyState *state,
    const AqtIssuerChoreographyAuthorityCell *cell
)
{
    const AqtIssuerChoreographyStateValue *target;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *claim;
    AqtIssuerChoreographyRecord *post_effect;
    uint64_t terminal_revision;
    size_t index;

    if (request == NULL || expected == NULL || committed == NULL
        || state == NULL || cell == NULL
        || committed_is_present < 0 || committed_is_present > 1) {
        return 0;
    }
    target = &state->value;
    lease = request->lease_record;
    recovery = request->recovery_record;
    claim = request->claim_record;
    post_effect = request->post_effect_record;
    terminal_revision = target->revision;
    if (lease == NULL || recovery == NULL || claim == NULL
        || post_effect == NULL
        || !lease->wrapper_live || !recovery->wrapper_live
        || !claim->wrapper_live || !post_effect->wrapper_live
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || post_effect->prepared_at_revision != expected->revision
        || post_effect->key.lifetime_generation
            != expected->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ].lifetime_generation
        || post_effect->key.scope_generation != expected->scope_generation
        || !aqt_issuer_choreography_memory_is_zero(
            &post_effect->payload,
            sizeof(post_effect->payload)
        )
        || memcmp(
            &claim->payload.claim,
            &expected->claim,
            sizeof(expected->claim)
        ) != 0) {
        return 0;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->authority_records[index];
        unsigned int present =
            (target->authority_record_presence_mask & (1U << index)) != 0U;

        if (present != (record != NULL)) {
            return 0;
        }
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->witness_records[index];
        unsigned int present =
            (target->witness_record_presence_mask & (1U << index)) != 0U;

        if (present != (record != NULL)) {
            return 0;
        }
    }
    if (target->phase == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED) {
        return committed_is_present
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] == lease
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] == recovery
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ] == post_effect
            && state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
            ] == claim
            && lease->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && claim->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
            && post_effect->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && lease->install_or_terminal_state_revision
                == request->lease_initial_status_revision
            && recovery->install_or_terminal_state_revision
                == request->recovery_initial_status_revision
            && claim->install_or_terminal_state_revision
                == request->claim_initial_status_revision
            && post_effect->install_or_terminal_state_revision
                == committed->revision
            && memcmp(
                &target->authority_keys[
                    AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
                ],
                &post_effect->key,
                sizeof(post_effect->key)
            ) == 0;
    }
    if (target->phase == AQT_CHOREOGRAPHY_PHASE_ARMED) {
        return !committed_is_present
            && target->action_active == 0U
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] == lease
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] == recovery
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ] == NULL
            && state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
            ] == claim
            && lease->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && claim->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
            && post_effect->status == AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
            && lease->install_or_terminal_state_revision
                == request->lease_initial_status_revision
            && recovery->install_or_terminal_state_revision
                == request->recovery_initial_status_revision
            && claim->install_or_terminal_state_revision
                == request->claim_initial_status_revision
            && post_effect->install_or_terminal_state_revision
                == terminal_revision;
    }
    if (target->phase != AQT_CHOREOGRAPHY_PHASE_REVOKED
        && target->phase != AQT_CHOREOGRAPHY_PHASE_RECOVERY_UNCONFIRMED
        && target->phase != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED) {
        return 0;
    }
    if (state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != NULL
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != NULL
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != NULL
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || claim->status != AQT_CHOREOGRAPHY_WITNESS_CLEARED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || lease->install_or_terminal_state_revision != terminal_revision
        || recovery->install_or_terminal_state_revision != terminal_revision
        || claim->install_or_terminal_state_revision != terminal_revision
        || post_effect->install_or_terminal_state_revision
            != terminal_revision) {
        return 0;
    }
    return target->phase == AQT_CHOREOGRAPHY_PHASE_REVOKED
        || (memcmp(
                &claim->payload.claim,
                &target->claim,
                sizeof(target->claim)
            ) == 0
            && (target->phase != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED
                || aqt_issuer_choreography_record_key_equals(
                    &post_effect->key,
                    &target->authority_keys[
                        AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
                    ]
                )));
}

static int
aqt_issuer_choreography_post_effect_cleanup_reconcile_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyPostEffectTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int candidate_was_stored,
    int terminal_proof_completed,
    AqtIssuerActivationProjection **prepared_roots,
    AqtIssuerActivationProjection **detached_projection,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyStateValue target;
    AqtIssuerChoreographyFailclosedOrigin origin;
    unsigned int target_policy;
    int committed_is_present = candidate_was_stored
        && candidate->phase == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED;
    size_t index;

    aqt_issuer_choreography_build_post_effect_cleanup_target_locked(
        expected,
        candidate,
        candidate_was_stored,
        committed_is_present,
        terminal_proof_completed,
        &target,
        &target_policy
    );
    aqt_issuer_choreography_build_post_effect_failclosed_origin(
        expected,
        candidate,
        committed_is_present,
        target_policy,
        &target,
        &origin
    );
    if (cell != NULL
        && cell->persistent_state_revision == target.revision
        && memcmp(&state->value, &target, sizeof(target)) == 0
        && memcmp(&state->failclosed_origin, &origin, sizeof(origin)) == 0) {
        return aqt_issuer_choreography_post_effect_cleanup_lifecycle_is_exact_locked(
                shadow,
                request
            )
            && aqt_issuer_choreography_post_effect_cleanup_records_are_exact_locked(
                request,
                expected,
                candidate,
                committed_is_present,
                state,
                cell
            )
            && aqt_issuer_choreography_post_effect_failclosed_origin_is_exact_locked(
                state
            )
            && aqt_issuer_choreography_cell_is_exact_locked(shadow);
    }
    if (cell == NULL
        || cell->persistent_state_revision
            != expected->revision + (candidate_was_stored ? 1U : 0U)
        || memcmp(
            &state->value,
            candidate_was_stored ? candidate : expected,
            sizeof(state->value)
        ) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )) {
        return 0;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->authority_records[index];

        if (record != NULL
            && (target.authority_record_presence_mask & (1U << index)) == 0U) {
            aqt_issuer_choreography_detached_record_append_locked(
                detached,
                record
            );
            state->authority_records[index] = NULL;
        }
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->witness_records[index];

        if (record != NULL
            && (target.witness_record_presence_mask & (1U << index)) == 0U) {
            aqt_issuer_choreography_detached_record_append_locked(
                detached,
                record
            );
            state->witness_records[index] = NULL;
        }
    }
    if (target.phase == AQT_CHOREOGRAPHY_PHASE_ARMED) {
        request->post_effect_record->status =
            AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->post_effect_record->install_or_terminal_state_revision =
            target.revision;
    }
    else if (target.phase != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED) {
        request->lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->recovery_record->status =
            AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->claim_record->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        request->post_effect_record->status =
            AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->lease_record->install_or_terminal_state_revision =
            target.revision;
        request->recovery_record->install_or_terminal_state_revision =
            target.revision;
        request->claim_record->install_or_terminal_state_revision =
            target.revision;
        request->post_effect_record->install_or_terminal_state_revision =
            target.revision;
    }
    state->value = target;
    state->failclosed_origin = origin;
    cell->persistent_state_revision = target.revision;
    aqt_issuer_choreography_recovery_burn_locked(
        shadow,
        prepared_roots,
        detached_projection
    );
    return aqt_issuer_choreography_post_effect_cleanup_lifecycle_is_exact_locked(
            shadow,
            request
        )
        && aqt_issuer_choreography_post_effect_cleanup_records_are_exact_locked(
            request,
            expected,
            candidate,
            committed_is_present,
            state,
            cell
        )
        && aqt_issuer_choreography_post_effect_failclosed_origin_is_exact_locked(
            state
        )
        && aqt_issuer_choreography_cell_is_exact_locked(shadow);
}

static PyObject *
aqt_issuer_choreography_post_effect_transition(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyPostEffectTransitionRequest *request
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerFailure failure = {0};
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    uint64_t sampled_now = 0U;
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int saved_errno = 0;
    int semantic_error = 0;
    int candidate_was_stored = 0;
    int committed_is_present = 0;
    int terminal_proof_completed = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int fork_commit_completed = 0;
    int index;

    memset(&expected, 0, sizeof(expected));
    memset(&candidate, 0, sizeof(candidate));
    if (module_state == NULL || request == NULL) {
        return NULL;
    }
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        aqt_clear_issuer_external_projection_barrier(module_state);
        return NULL;
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        PyErr_Clear();
        aqt_clear_issuer_external_projection_barrier(module_state);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography post-effect outcome transition is unavailable"
        );
    }
    prepared_roots = aqt_clone_issuer_roots_projection(shadow->projection);
    if (prepared_roots == NULL) {
        aqt_clear_issuer_external_projection_barrier(module_state);
        return NULL;
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_post_effect_transition_source_is_exact_locked(
            shadow,
            request,
            current_thread,
            current_thread_id
        )) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography post-effect outcome transition is unavailable"
        );
    }
    expected = shadow->choreography_state.value;
    request->source_lifecycle_revision = shadow->revision;
    request->source_projection = shadow->projection;
    request->source_launch_lease = shadow->launch_lease;
    request->lease_initial_status_revision =
        request->lease_record->install_or_terminal_state_revision;
    request->recovery_initial_status_revision =
        request->recovery_record->install_or_terminal_state_revision;
    request->claim_initial_status_revision =
        request->claim_record->install_or_terminal_state_revision;
    request->post_effect_initial_status_revision =
        request->post_effect_record->install_or_terminal_state_revision;
    if (fault_plan->row_count != 0
        && fault_plan->group == 3
        && atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography post-effect fault and fork plans conflict"
        );
    }
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            AQT_CHOREOGRAPHY_OPERATION_ARM_POST_EFFECT,
            expected.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography post-effect outcome transition is unavailable"
        );
    }
    if (request->selector == AQT_CHOREOGRAPHY_TIME_SAMPLE
        && aqt_issuer_choreography_sample_continuous_ns(&sampled_now) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
    }
    if (saved_errno == 0) {
        aqt_issuer_choreography_resolve_post_effect_candidate_locked(
            &expected,
            &request->post_effect_record->key,
            request->selector,
            sampled_now,
            &candidate
        );
        request->observed_monotonic_ns = candidate.last_monotonic_ns;
        if (aqt_issuer_choreography_post_effect_authority_proof_locked(
                module_state,
                shadow,
                request,
                &expected,
                0,
                0,
                &request->authority_proof_failed
            ) < 0) {
            saved_errno = errno != 0 ? errno : EIO;
        }
    }
    if (saved_errno == 0) {
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && saved_errno == 0) {
        aqt_issuer_choreography_publish_post_effect_candidate_locked(
            shadow,
            request,
            &candidate,
            &detached
        );
        candidate_was_stored = 1;
        committed_is_present = candidate.phase
            == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED;
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_post_effect_transition_locked(
                shadow,
                &expected,
                &candidate,
                1,
                request
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = 1;
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
            aqt_unlock_owner_list_or_fail_stop();
            if (aqt_issuer_foreign_fork_wait_for_value(
                    &module_state->issuer_foreign_fork_plan.worker_completed,
                    1
                ) < 0) {
                aqt_fail_stop(
                    "native issuer post-effect foreign-fork worker timed out"
                );
            }
            aqt_lock_owner_list_or_fail_stop();
            if (memcmp(
                    &shadow->choreography_state.value,
                    &candidate,
                    sizeof(candidate)
                ) != 0
                || !aqt_issuer_choreography_memory_is_zero(
                    &shadow->choreography_state.failclosed_origin,
                    sizeof(shadow->choreography_state.failclosed_origin)
                )) {
                aqt_fail_stop(
                    "native issuer post-effect changed across foreign fork"
                );
            }
        }
        if (committed_is_present) {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
                1,
                current_pid,
                current_interpreter
            );
        }
        else {
            semantic_error = 1;
        }
    }
    if (primary_kind < 0 && saved_errno == 0 && committed_is_present) {
        if (aqt_issuer_choreography_post_effect_authority_proof_locked(
                module_state,
                shadow,
                request,
                &expected,
                1,
                1,
                &request->authority_proof_failed
            ) < 0) {
            saved_errno = errno != 0 ? errno : EIO;
        }
        else {
            terminal_proof_completed = 1;
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && committed_is_present && terminal_proof_completed) {
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
            primary_kind = AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR;
        }
        else {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
        }
    }
    if (primary_kind < 0 && saved_errno == 0 && !semantic_error) {
        if (!aqt_issuer_choreography_cell_is_exact_locked(shadow)) {
            abort();
        }
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        aqt_free_issuer_projection(&detached_projection);
        aqt_issuer_choreography_detached_records_release(&detached);
        Py_RETURN_NONE;
    }
    if (fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
        request->observed_monotonic_ns = committed_is_present
            ? candidate.last_monotonic_ns
            : expected.last_monotonic_ns;
        aqt_issuer_foreign_fork_bind_post_effect_transition_locked(
            shadow,
            &expected,
            candidate_was_stored ? &candidate : NULL,
            committed_is_present,
            request
        );
        if (aqt_issuer_foreign_fork_interpose_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ) < 0) {
            abort();
        }
        fork_was_triggered = 1;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_post_effect_cleanup_reconcile_locked(
                shadow,
                request,
                &expected,
                &candidate,
                candidate_was_stored,
                terminal_proof_completed,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography post-effect cleanup attempt failed"
            );
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_post_effect_cleanup_reconcile_locked(
            shadow,
            request,
            &expected,
            &candidate,
            candidate_was_stored,
            terminal_proof_completed,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography post-effect cleanup confirmation failed"
        );
    }
    if (fork_was_triggered && !fork_commit_completed) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
        fork_commit_completed = 1;
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered && fork_commit_completed
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed,
            1
        ) < 0) {
        aqt_fail_stop(
            "native issuer post-effect cleanup foreign-fork worker timed out"
        );
    }
    aqt_clear_issuer_external_projection_barrier(module_state);
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    else if (saved_errno != 0) {
        aqt_issuer_failure_record_errno(&failure, saved_errno);
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0
            && (!semantic_error
                || cleanup_kinds[index]
                    != AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR)) {
            aqt_issuer_failure_record_synthetic(
                &failure,
                cleanup_kinds[index]
            );
        }
    }
    if (failure.has_selected) {
        return aqt_issuer_choreography_failure_raise(&failure);
    }
    return aqt_issuer_choreography_runtime_error(
        "native issuer choreography post-effect outcome transition is unavailable"
    );
}

static PyObject *
aqt_issuer_choreography_arm_post_effect(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyPostEffectTransitionRequest *request
)
{
    return aqt_issuer_choreography_post_effect_transition(
        module,
        shadow,
        request
    );
}

static int
aqt_issuer_choreography_post_effect_requirement_source_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyPostEffectRequirementRequest *request,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *claim;
    AqtIssuerChoreographyRecord *post_effect;

    if (request == NULL
        || request->operation_tag
            != AQT_CHOREOGRAPHY_OPERATION_REQUIRE_POST_EFFECT
        || request->selector > AQT_CHOREOGRAPHY_TIME_ACTION_DEADLINE
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
        || shadow->revision != 3U
        || shadow->poisoned != 0U
        || shadow->closed != 0U
        || shadow->busy != 0U
        || shadow->runtime_ready != 0U
        || shadow->projection == NULL
        || aqt_issuer_projection_is_roots_only(shadow->projection)
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || cell == NULL
        || cell->alive != 1U
        || cell->action_live != 1U
        || cell->lifecycle_disposition != AQT_CHOREOGRAPHY_CELL_ACTIVE
        || cell->pending_scope_generation != 0U
        || !shadow->choreography_state_present
        || state->value.revision > UINT64_MAX - 2U
        || state->value.revision != cell->persistent_state_revision
        || state->value.binding_generation != cell->binding_generation
        || state->value.scope_generation != cell->current_scope_generation
        || !aqt_issuer_choreography_post_effect_requirement_source_value_is_exact(
            &state->value
        )
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )) {
        return 0;
    }
    lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    post_effect = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
    ];
    claim = state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
    ];
    if (lease == NULL || recovery == NULL || claim == NULL
        || post_effect == NULL
        || request->lease_record != lease
        || request->post_effect_record != post_effect
        || request->claim_record != claim
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != NULL
        || !lease->wrapper_live || !claim->wrapper_live
        || !post_effect->wrapper_live
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || claim->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || lease->install_or_terminal_state_revision == 0U
        || recovery->install_or_terminal_state_revision == 0U
        || claim->install_or_terminal_state_revision == 0U
        || post_effect->install_or_terminal_state_revision == 0U
        || lease->install_or_terminal_state_revision > state->value.revision
        || recovery->install_or_terminal_state_revision > state->value.revision
        || claim->install_or_terminal_state_revision > state->value.revision
        || post_effect->install_or_terminal_state_revision
            > state->value.revision
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_key_equals(
            &lease->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &recovery->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &post_effect->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &claim->key,
            &state->value.claim.key
        )
        || memcmp(
            &claim->payload.claim,
            &state->value.claim,
            sizeof(state->value.claim)
        ) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &post_effect->payload,
            sizeof(post_effect->payload)
        )
        ) {
        return 0;
    }
    request->recovery_record = recovery;
    return 1;
}

static int
aqt_issuer_choreography_post_effect_requirement_selected_records_proof_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyPostEffectRequirementRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int installed
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    AqtIssuerChoreographyRecord *post_effect = request->post_effect_record;
    const AqtIssuerChoreographyStateValue *required_value =
        installed ? candidate : expected;

    if (cell == NULL || lease == NULL || recovery == NULL
        || claim == NULL || post_effect == NULL
        || !lease->wrapper_live || !claim->wrapper_live
        || !post_effect->wrapper_live
        || !aqt_issuer_choreography_cell_is_exact_locked(shadow)
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || memcmp(
            &claim->payload.claim,
            &expected->claim,
            sizeof(expected->claim)
        ) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &post_effect->payload,
            sizeof(post_effect->payload)
        )
        || required_value == NULL
        || memcmp(&state->value, required_value, sizeof(*required_value)) != 0
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != claim
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || claim->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || lease->install_or_terminal_state_revision
            != request->lease_initial_status_revision
        || recovery->install_or_terminal_state_revision
            != request->recovery_initial_status_revision
        || claim->install_or_terminal_state_revision
            != request->claim_initial_status_revision
        || post_effect->install_or_terminal_state_revision
            != request->post_effect_initial_status_revision
        || !aqt_issuer_choreography_record_key_equals(
            &lease->key,
            &required_value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &recovery->key,
            &required_value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &post_effect->key,
            &required_value->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ]
        )) {
        errno = EINVAL;
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_post_effect_requirement_authority_proof_locked(
    AqtModuleState *module_state,
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyPostEffectRequirementRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int installed,
    int consume_barrier,
    unsigned int *authority_proof_failed
)
{
    if (aqt_issuer_choreography_post_effect_requirement_selected_records_proof_locked(
            shadow,
            request,
            expected,
            candidate,
            installed
        ) < 0) {
        return -1;
    }
    if (aqt_issuer_external_projection_matches(shadow->projection) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    if (aqt_validate_launch_lock_core_locked(shadow->launch_lease) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    if (consume_barrier) {
        aqt_run_issuer_external_projection_barrier(module_state);
    }
    if (aqt_issuer_external_projection_matches(shadow->projection) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    return 0;
}

static void
aqt_issuer_choreography_publish_post_effect_requirement_candidate_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyPostEffectRequirementRequest *request,
    const AqtIssuerChoreographyStateValue *candidate,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    AqtIssuerChoreographyRecord *post_effect = request->post_effect_record;
    uint64_t revision = candidate->revision;

    if (cell == NULL
        || !aqt_issuer_choreography_post_effect_requirement_candidate_value_is_exact(
            &state->value,
            candidate
        )
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != claim) {
        abort();
    }
    if (candidate->phase
            == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED) {
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] = NULL;
        state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] = NULL;
        aqt_issuer_choreography_detached_record_append_locked(detached, lease);
        aqt_issuer_choreography_detached_record_append_locked(detached, recovery);
        aqt_issuer_choreography_detached_record_append_locked(detached, post_effect);
        aqt_issuer_choreography_detached_record_append_locked(detached, claim);
        lease->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        recovery->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        post_effect->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        claim->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        lease->install_or_terminal_state_revision = revision;
        recovery->install_or_terminal_state_revision = revision;
        post_effect->install_or_terminal_state_revision = revision;
        claim->install_or_terminal_state_revision = revision;
    }
    else if (candidate->phase != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED) {
        abort();
    }
    state->value = *candidate;
    memset(&state->failclosed_origin, 0, sizeof(state->failclosed_origin));
    cell->persistent_state_revision = revision;
}

static int
aqt_issuer_choreography_post_effect_requirement_cleanup_lifecycle_is_exact_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyPostEffectRequirementRequest *request
)
{
    const AqtIssuerChoreographyAuthorityCell *cell;

    if (shadow == NULL || request == NULL
        || request->source_lifecycle_revision != 3U
        || request->source_projection == NULL
        || aqt_issuer_projection_is_roots_only(request->source_projection)
        || request->source_projection == shadow->projection
        || request->source_launch_lease == NULL
        || request->source_launch_lease != shadow->launch_lease
        || shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED
        || shadow->revision != 4U
        || shadow->poisoned != 1U
        || shadow->closed != 0U
        || shadow->lease_was_closed != 0U
        || !aqt_issuer_projection_is_roots_only(shadow->projection)
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)) {
        return 0;
    }
    cell = shadow->choreography_authority_cell;
    return cell != NULL
        && cell->alive == 1U
        && cell->action_live == 0U
        && cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_BURNED;
}

static int
aqt_issuer_choreography_post_effect_requirement_cleanup_records_are_exact_locked(
    const AqtIssuerChoreographyPostEffectRequirementRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int candidate_was_stored,
    const AqtIssuerChoreographyState *state,
    const AqtIssuerChoreographyAuthorityCell *cell
)
{
    const AqtIssuerChoreographyStateValue *target;
    const AqtIssuerChoreographyFailclosedOrigin *origin;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *claim;
    AqtIssuerChoreographyRecord *post_effect;
    uint64_t terminal_revision;
    size_t index;

    if (request == NULL || expected == NULL || candidate == NULL
        || state == NULL || cell == NULL
        || candidate_was_stored < 0 || candidate_was_stored > 1) {
        return 0;
    }
    target = &state->value;
    origin = &state->failclosed_origin;
    lease = request->lease_record;
    recovery = request->recovery_record;
    claim = request->claim_record;
    post_effect = request->post_effect_record;
    terminal_revision = target->revision;
    if (lease == NULL || recovery == NULL || claim == NULL
        || post_effect == NULL
        || !lease->wrapper_live || !claim->wrapper_live
        || !post_effect->wrapper_live
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || memcmp(
            &claim->payload.claim,
            &expected->claim,
            sizeof(expected->claim)
        ) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &post_effect->payload,
            sizeof(post_effect->payload)
        )
        || !aqt_issuer_choreography_post_effect_requirement_immutable_lineage_is_exact_locked(
            lease,
            recovery,
            claim,
            post_effect,
            expected,
            target
        )) {
        return 0;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        unsigned int present =
            (target->authority_record_presence_mask & (1U << index)) != 0U;

        if (present != (state->authority_records[index] != NULL)) {
            return 0;
        }
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        unsigned int present =
            (target->witness_record_presence_mask & (1U << index)) != 0U;

        if (present != (state->witness_records[index] != NULL)) {
            return 0;
        }
    }
    if (origin->committed_is_present) {
        if (!candidate_was_stored
            || memcmp(
                &origin->committed,
                candidate,
                sizeof(*candidate)
            ) != 0) {
            return 0;
        }
    }
    else if (candidate_was_stored) {
        if (memcmp(target, candidate, sizeof(*candidate)) != 0) {
            return 0;
        }
    }
    else if (target->phase
            != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED) {
        return 0;
    }
    if (target->phase == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED) {
        return target->action_active == 0U
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] == lease
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] == recovery
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ] == post_effect
            && state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
            ] == claim
            && lease->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && claim->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
            && post_effect->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && lease->install_or_terminal_state_revision
                == request->lease_initial_status_revision
            && recovery->install_or_terminal_state_revision
                == request->recovery_initial_status_revision
            && claim->install_or_terminal_state_revision
                == request->claim_initial_status_revision
            && post_effect->install_or_terminal_state_revision
                == request->post_effect_initial_status_revision
            && aqt_issuer_choreography_record_key_equals(
                &post_effect->key,
                &target->authority_keys[
                    AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
                ]
            );
    }
    if (target->phase != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != NULL
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != NULL
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != NULL
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || claim->status != AQT_CHOREOGRAPHY_WITNESS_CLEARED
        || lease->install_or_terminal_state_revision != terminal_revision
        || recovery->install_or_terminal_state_revision != terminal_revision
        || post_effect->install_or_terminal_state_revision != terminal_revision
        || claim->install_or_terminal_state_revision != terminal_revision
        || memcmp(&claim->payload.claim, &target->claim, sizeof(target->claim))
            != 0
        || !aqt_issuer_choreography_record_key_equals(
            &post_effect->key,
            &target->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ]
        )) {
        return 0;
    }
    return 1;
}

static int
aqt_issuer_choreography_post_effect_requirement_cleanup_reconcile_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyPostEffectRequirementRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int candidate_was_stored,
    int terminal_proof_completed,
    AqtIssuerActivationProjection **prepared_roots,
    AqtIssuerActivationProjection **detached_projection,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyStateValue target;
    AqtIssuerChoreographyFailclosedOrigin origin;
    unsigned int target_policy;
    int committed_is_present;
    size_t index;

    aqt_issuer_choreography_build_post_effect_requirement_cleanup_target_locked(
        expected,
        candidate,
        candidate_was_stored,
        terminal_proof_completed,
        &target,
        &target_policy,
        &committed_is_present
    );
    aqt_issuer_choreography_build_post_effect_requirement_failclosed_origin(
        expected,
        candidate,
        committed_is_present,
        target_policy,
        &target,
        &origin
    );
    if (cell != NULL
        && cell->persistent_state_revision == target.revision
        && memcmp(&state->value, &target, sizeof(target)) == 0
        && memcmp(&state->failclosed_origin, &origin, sizeof(origin)) == 0) {
        return aqt_issuer_choreography_post_effect_requirement_cleanup_lifecycle_is_exact_locked(
                shadow,
                request
            )
            && aqt_issuer_choreography_post_effect_requirement_cleanup_records_are_exact_locked(
                request,
                expected,
                candidate,
                candidate_was_stored,
                state,
                cell
            )
            && aqt_issuer_choreography_post_effect_requirement_failclosed_origin_is_exact_locked(
                state
            )
            && aqt_issuer_choreography_cell_is_exact_locked(shadow);
    }
    if (cell == NULL
        || cell->persistent_state_revision
            != expected->revision + (candidate_was_stored ? 1U : 0U)
        || memcmp(
            &state->value,
            candidate_was_stored ? candidate : expected,
            sizeof(state->value)
        ) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )) {
        return 0;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->authority_records[index];

        if (record != NULL
            && (target.authority_record_presence_mask & (1U << index)) == 0U) {
            aqt_issuer_choreography_detached_record_append_locked(
                detached,
                record
            );
            state->authority_records[index] = NULL;
        }
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->witness_records[index];

        if (record != NULL
            && (target.witness_record_presence_mask & (1U << index)) == 0U) {
            aqt_issuer_choreography_detached_record_append_locked(
                detached,
                record
            );
            state->witness_records[index] = NULL;
        }
    }
    if (target.phase
            == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED) {
        request->lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->recovery_record->status =
            AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->post_effect_record->status =
            AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->claim_record->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        request->lease_record->install_or_terminal_state_revision =
            target.revision;
        request->recovery_record->install_or_terminal_state_revision =
            target.revision;
        request->post_effect_record->install_or_terminal_state_revision =
            target.revision;
        request->claim_record->install_or_terminal_state_revision =
            target.revision;
    }
    else if (target.phase != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED
        || target.action_active != 0U) {
        return 0;
    }
    state->value = target;
    state->failclosed_origin = origin;
    cell->persistent_state_revision = target.revision;
    aqt_issuer_choreography_recovery_burn_locked(
        shadow,
        prepared_roots,
        detached_projection
    );
    return aqt_issuer_choreography_post_effect_requirement_cleanup_lifecycle_is_exact_locked(
            shadow,
            request
        )
        && aqt_issuer_choreography_post_effect_requirement_cleanup_records_are_exact_locked(
            request,
            expected,
            candidate,
            candidate_was_stored,
            state,
            cell
        )
        && aqt_issuer_choreography_post_effect_requirement_failclosed_origin_is_exact_locked(
            state
        )
        && aqt_issuer_choreography_cell_is_exact_locked(shadow);
}

static PyObject *
aqt_issuer_choreography_post_effect_requirement_transition(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyPostEffectRequirementRequest *request
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerFailure failure = {0};
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    uint64_t sampled_now = 0U;
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int saved_errno = 0;
    int semantic_error = 0;
    int candidate_was_stored = 0;
    int committed_is_present = 0;
    int terminal_proof_completed = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int fork_commit_completed = 0;
    int index;

    memset(&expected, 0, sizeof(expected));
    memset(&candidate, 0, sizeof(candidate));
    if (module_state == NULL || request == NULL) {
        return NULL;
    }
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        aqt_clear_issuer_external_projection_barrier(module_state);
        return NULL;
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        PyErr_Clear();
        aqt_clear_issuer_external_projection_barrier(module_state);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography active post-effect outcome retention is unavailable"
        );
    }
    prepared_roots = aqt_clone_issuer_roots_projection(shadow->projection);
    if (prepared_roots == NULL) {
        aqt_clear_issuer_external_projection_barrier(module_state);
        return NULL;
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_post_effect_requirement_source_is_exact_locked(
            shadow,
            request,
            current_thread,
            current_thread_id
        )) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography active post-effect outcome retention is unavailable"
        );
    }
    expected = shadow->choreography_state.value;
    request->source_lifecycle_revision = shadow->revision;
    request->source_projection = shadow->projection;
    request->source_launch_lease = shadow->launch_lease;
    request->lease_initial_status_revision =
        request->lease_record->install_or_terminal_state_revision;
    request->recovery_initial_status_revision =
        request->recovery_record->install_or_terminal_state_revision;
    request->claim_initial_status_revision =
        request->claim_record->install_or_terminal_state_revision;
    request->post_effect_initial_status_revision =
        request->post_effect_record->install_or_terminal_state_revision;
    if (fault_plan->row_count != 0
        && fault_plan->group == 3
        && atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography post-effect fault and fork plans conflict"
        );
    }
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            AQT_CHOREOGRAPHY_OPERATION_REQUIRE_POST_EFFECT,
            expected.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography active post-effect outcome retention is unavailable"
        );
    }
    if (request->selector == AQT_CHOREOGRAPHY_TIME_SAMPLE
        && aqt_issuer_choreography_sample_continuous_ns(&sampled_now) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
    }
    if (saved_errno == 0) {
        aqt_issuer_choreography_resolve_post_effect_requirement_candidate_locked(
            &expected,
            request->selector,
            sampled_now,
            &candidate
        );
        request->observed_monotonic_ns = candidate.last_monotonic_ns;
        if (aqt_issuer_choreography_post_effect_requirement_authority_proof_locked(
                module_state,
                shadow,
                request,
                &expected,
                &candidate,
                0,
                0,
                &request->authority_proof_failed
            ) < 0) {
            saved_errno = errno != 0 ? errno : EIO;
        }
    }
    if (saved_errno == 0) {
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && saved_errno == 0) {
        aqt_issuer_choreography_publish_post_effect_requirement_candidate_locked(
            shadow,
            request,
            &candidate,
            &detached
        );
        candidate_was_stored = 1;
        committed_is_present = candidate.phase
                == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED
            && candidate.action_active == 1U;
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_post_effect_requirement_locked(
                shadow,
                &expected,
                &candidate,
                1,
                request
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = 1;
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
            aqt_unlock_owner_list_or_fail_stop();
            if (aqt_issuer_foreign_fork_wait_for_value(
                    &module_state->issuer_foreign_fork_plan.worker_completed,
                    1
                ) < 0) {
                aqt_fail_stop(
                    "native issuer post-effect requirement foreign-fork worker timed out"
                );
            }
            aqt_lock_owner_list_or_fail_stop();
            if (memcmp(
                    &shadow->choreography_state.value,
                    &candidate,
                    sizeof(candidate)
                ) != 0
                || !aqt_issuer_choreography_memory_is_zero(
                    &shadow->choreography_state.failclosed_origin,
                    sizeof(shadow->choreography_state.failclosed_origin)
                )) {
                aqt_fail_stop(
                    "native issuer post-effect requirement changed across foreign fork"
                );
            }
        }
        if (committed_is_present) {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
                1,
                current_pid,
                current_interpreter
            );
        }
        else {
            semantic_error = 1;
        }
    }
    if (primary_kind < 0 && saved_errno == 0 && committed_is_present) {
        if (aqt_issuer_choreography_post_effect_requirement_authority_proof_locked(
                module_state,
                shadow,
                request,
                &expected,
                &candidate,
                1,
                1,
                &request->authority_proof_failed
            ) < 0) {
            saved_errno = errno != 0 ? errno : EIO;
        }
        else {
            terminal_proof_completed = 1;
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && committed_is_present && terminal_proof_completed) {
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
            primary_kind = AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR;
        }
        else {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
        }
    }
    if (primary_kind < 0 && saved_errno == 0 && !semantic_error) {
        if (!aqt_issuer_choreography_cell_is_exact_locked(shadow)) {
            abort();
        }
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        aqt_free_issuer_projection(&detached_projection);
        aqt_issuer_choreography_detached_records_release(&detached);
        Py_RETURN_NONE;
    }
    if (fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
        request->observed_monotonic_ns = candidate_was_stored
            ? candidate.last_monotonic_ns
            : expected.last_monotonic_ns;
        aqt_issuer_foreign_fork_bind_post_effect_requirement_locked(
            shadow,
            &expected,
            candidate_was_stored ? &candidate : NULL,
            candidate_was_stored,
            request
        );
        if (aqt_issuer_foreign_fork_interpose_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ) < 0) {
            abort();
        }
        fork_was_triggered = 1;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_post_effect_requirement_cleanup_reconcile_locked(
                shadow,
                request,
                &expected,
                &candidate,
                candidate_was_stored,
                terminal_proof_completed,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography post-effect requirement cleanup attempt failed"
            );
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_post_effect_requirement_cleanup_reconcile_locked(
            shadow,
            request,
            &expected,
            &candidate,
            candidate_was_stored,
            terminal_proof_completed,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography post-effect requirement cleanup confirmation failed"
        );
    }
    if (fork_was_triggered && !fork_commit_completed) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
        fork_commit_completed = 1;
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered && fork_commit_completed
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed,
            1
        ) < 0) {
        aqt_fail_stop(
            "native issuer post-effect requirement cleanup foreign-fork worker timed out"
        );
    }
    aqt_clear_issuer_external_projection_barrier(module_state);
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    else if (saved_errno != 0) {
        aqt_issuer_failure_record_errno(&failure, saved_errno);
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0
            && (!semantic_error
                || cleanup_kinds[index]
                    != AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR)) {
            aqt_issuer_failure_record_synthetic(
                &failure,
                cleanup_kinds[index]
            );
        }
    }
    if (failure.has_selected) {
        return aqt_issuer_choreography_failure_raise(&failure);
    }
    return aqt_issuer_choreography_runtime_error(
        "native issuer choreography active post-effect outcome retention is unavailable"
    );
}

static PyObject *
aqt_issuer_choreography_require_post_effect(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyPostEffectRequirementRequest *request
)
{
    return aqt_issuer_choreography_post_effect_requirement_transition(
        module,
        shadow,
        request
    );
}

static int
aqt_issuer_choreography_controller_transition_source_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerTransitionRequest *request,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *claim;
    AqtIssuerChoreographyRecord *post_effect;
    AqtIssuerChoreographyRecord *checkpoint =
        request != NULL ? request->controller_checkpoint_record : NULL;
    unsigned int outcome_kind;
    int source_was_burned;

    if (request == NULL
        || request->operation_tag != AQT_CHOREOGRAPHY_OPERATION_BEGIN_CONTROLLER
        || request->selector >= AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT
        || checkpoint == NULL
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || (shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
            && shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED)
        || shadow->closed != 0U
        || shadow->busy != 0U
        || shadow->runtime_ready != 0U
        || shadow->projection == NULL
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || cell == NULL
        || cell->alive != 1U
        || cell->pending_scope_generation != 0U
        || !shadow->choreography_state_present
        || state->value.revision > UINT64_MAX - 2U
        || state->value.revision != cell->persistent_state_revision
        || state->value.binding_generation != cell->binding_generation
        || state->value.scope_generation != cell->current_scope_generation
        || !aqt_issuer_choreography_controller_source_value_is_exact(
            &state->value
        )
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )
        || !checkpoint->wrapper_live
        || !checkpoint->wrapper_was_created
        || checkpoint->status != AQT_CHOREOGRAPHY_WITNESS_PREPARED
        || checkpoint->prepared_at_revision != state->value.revision
        || checkpoint->install_or_terminal_state_revision != 0U
        || checkpoint->prepared_time_selector_present != 1U
        || checkpoint->prepared_time_selector != request->selector
        || checkpoint->prepared_source_last_monotonic_ns
            != state->value.last_monotonic_ns
        || !aqt_issuer_choreography_record_is_exact_locked(
            checkpoint,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )
        || !aqt_issuer_choreography_controller_checkpoint_summary_matches_value(
            &checkpoint->payload.controller_checkpoint,
            &state->value,
            0
        )) {
        return 0;
    }
    outcome_kind = checkpoint->payload.controller_checkpoint.projection
        .outcome_kind;
    source_was_burned = shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED;
    if ((outcome_kind == AQT_CHOREOGRAPHY_OUTCOME_SUCCESS
            && source_was_burned)
        || (source_was_burned
            ? (shadow->revision != 4U
                || shadow->poisoned != 1U
                || !aqt_issuer_projection_is_roots_only(shadow->projection)
                || cell->action_live != 0U
                || cell->lifecycle_disposition
                    != AQT_CHOREOGRAPHY_CELL_BURNED)
            : (shadow->revision != 3U
                || shadow->poisoned != 0U
                || aqt_issuer_projection_is_roots_only(shadow->projection)
                || cell->action_live != 1U
                || cell->lifecycle_disposition
                    != AQT_CHOREOGRAPHY_CELL_ACTIVE))) {
        return 0;
    }
    lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    post_effect = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
    ];
    claim = state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
    ];
    if (lease == NULL || recovery == NULL || claim == NULL
        || post_effect == NULL
        || request->post_effect_record != post_effect
        || request->claim_record != claim
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != NULL
        || !claim->wrapper_live || !post_effect->wrapper_live
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || claim->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || lease->install_or_terminal_state_revision == 0U
        || recovery->install_or_terminal_state_revision == 0U
        || claim->install_or_terminal_state_revision == 0U
        || post_effect->install_or_terminal_state_revision == 0U
        || lease->install_or_terminal_state_revision > state->value.revision
        || recovery->install_or_terminal_state_revision > state->value.revision
        || claim->install_or_terminal_state_revision > state->value.revision
        || post_effect->install_or_terminal_state_revision
            > state->value.revision
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_post_effect_requirement_immutable_lineage_is_exact_locked(
            lease,
            recovery,
            claim,
            post_effect,
            &state->value,
            &state->value
        )) {
        return 0;
    }
    request->lease_record = lease;
    request->recovery_record = recovery;
    request->outcome_kind = outcome_kind;
    request->source_was_burned = source_was_burned ? 1U : 0U;
    return 1;
}

static int
aqt_issuer_choreography_controller_selected_records_proof_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int installed
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    AqtIssuerChoreographyRecord *post_effect = request->post_effect_record;
    AqtIssuerChoreographyRecord *checkpoint =
        request->controller_checkpoint_record;
    const AqtIssuerChoreographyStateValue *required_value =
        installed ? candidate : expected;

    if (cell == NULL || lease == NULL || recovery == NULL || claim == NULL
        || post_effect == NULL || checkpoint == NULL
        || !aqt_issuer_choreography_controller_candidate_matches_request(
            request,
            expected,
            candidate
        )
        || !claim->wrapper_live || !post_effect->wrapper_live
        || !checkpoint->wrapper_live
        || !aqt_issuer_choreography_cell_is_exact_locked(shadow)
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            checkpoint,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )
        || checkpoint->prepared_at_revision != expected->revision
        || checkpoint->prepared_time_selector_present != 1U
        || checkpoint->prepared_time_selector != request->selector
        || checkpoint->prepared_source_last_monotonic_ns
            != expected->last_monotonic_ns
        || checkpoint->payload.controller_checkpoint.projection.outcome_kind
            != request->outcome_kind
        || checkpoint->payload.controller_checkpoint.projection
                .observed_monotonic_ns
            != request->observed_monotonic_ns
        || !aqt_issuer_choreography_controller_checkpoint_summary_matches_value(
            &checkpoint->payload.controller_checkpoint,
            expected,
            installed
        )
        || !aqt_issuer_choreography_post_effect_requirement_immutable_lineage_is_exact_locked(
            lease,
            recovery,
            claim,
            post_effect,
            expected,
            required_value
        )
        || memcmp(&state->value, required_value, sizeof(*required_value)) != 0
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != claim
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || claim->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || lease->install_or_terminal_state_revision
            != request->lease_initial_status_revision
        || recovery->install_or_terminal_state_revision
            != request->recovery_initial_status_revision
        || claim->install_or_terminal_state_revision
            != request->claim_initial_status_revision
        || post_effect->install_or_terminal_state_revision
            != request->post_effect_initial_status_revision) {
        errno = EINVAL;
        return -1;
    }
    if (installed) {
        if (candidate == NULL
            || candidate->phase
                != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONSUMING
            || state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
            ] != checkpoint
            || checkpoint->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
            || checkpoint->install_or_terminal_state_revision
                != candidate->revision
            || memcmp(
                &checkpoint->payload.controller_checkpoint,
                &candidate->controller_checkpoint,
                sizeof(candidate->controller_checkpoint)
            ) != 0) {
            errno = EINVAL;
            return -1;
        }
    }
    else if (state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] != NULL
        || checkpoint->status != AQT_CHOREOGRAPHY_WITNESS_PREPARED
        || checkpoint->install_or_terminal_state_revision
            != request->controller_checkpoint_initial_status_revision) {
        errno = EINVAL;
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_controller_authority_proof_locked(
    AqtModuleState *module_state,
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int installed,
    int consume_barrier,
    unsigned int *authority_proof_failed
)
{
    if (aqt_issuer_choreography_controller_selected_records_proof_locked(
            shadow,
            request,
            expected,
            candidate,
            installed
        ) < 0) {
        return -1;
    }
    if (!request->source_was_burned
        && aqt_issuer_external_projection_matches(shadow->projection) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    if (aqt_validate_launch_lock_core_locked(shadow->launch_lease) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    if (consume_barrier) {
        aqt_run_issuer_external_projection_barrier(module_state);
    }
    if (request->source_was_burned) {
        if (aqt_validate_launch_lock_core_locked(shadow->launch_lease) < 0) {
            *authority_proof_failed = 1U;
            return -1;
        }
    }
    else if (aqt_issuer_external_projection_matches(shadow->projection) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    return 0;
}

static void
aqt_issuer_choreography_publish_controller_candidate_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *candidate,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    AqtIssuerChoreographyRecord *post_effect = request->post_effect_record;
    AqtIssuerChoreographyRecord *checkpoint =
        request->controller_checkpoint_record;
    uint64_t revision = candidate->revision;

    if (cell == NULL
        || !aqt_issuer_choreography_controller_candidate_matches_request(
            request,
            &state->value,
            candidate
        )
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != claim
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] != NULL
        || checkpoint->status != AQT_CHOREOGRAPHY_WITNESS_PREPARED) {
        abort();
    }
    if (candidate->phase
            == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONSUMING) {
        aqt_issuer_choreography_record_incref(checkpoint);
        state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] = checkpoint;
        checkpoint->status = AQT_CHOREOGRAPHY_WITNESS_INSTALLED;
        checkpoint->install_or_terminal_state_revision = revision;
    }
    else if (candidate->phase
                == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED
        && candidate->action_active == 0U) {
        checkpoint->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        checkpoint->install_or_terminal_state_revision = revision;
    }
    else if (candidate->phase
                == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED
        || candidate->phase == AQT_CHOREOGRAPHY_PHASE_EXPIRED) {
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] = NULL;
        state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] = NULL;
        aqt_issuer_choreography_detached_record_append_locked(detached, lease);
        aqt_issuer_choreography_detached_record_append_locked(detached, recovery);
        aqt_issuer_choreography_detached_record_append_locked(detached, post_effect);
        aqt_issuer_choreography_detached_record_append_locked(detached, claim);
        lease->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        recovery->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        post_effect->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        claim->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        checkpoint->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        lease->install_or_terminal_state_revision = revision;
        recovery->install_or_terminal_state_revision = revision;
        post_effect->install_or_terminal_state_revision = revision;
        claim->install_or_terminal_state_revision = revision;
        checkpoint->install_or_terminal_state_revision = revision;
    }
    else {
        abort();
    }
    state->value = *candidate;
    memset(&state->failclosed_origin, 0, sizeof(state->failclosed_origin));
    cell->persistent_state_revision = revision;
}

static int
aqt_issuer_choreography_controller_cleanup_lifecycle_is_exact_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerTransitionRequest *request
)
{
    const AqtIssuerChoreographyAuthorityCell *cell;

    if (shadow == NULL || request == NULL
        || request->source_launch_lease == NULL
        || request->source_launch_lease != shadow->launch_lease
        || shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED
        || shadow->revision != 4U
        || shadow->poisoned != 1U
        || shadow->closed != 0U
        || shadow->lease_was_closed != 0U
        || !aqt_issuer_projection_is_roots_only(shadow->projection)
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)) {
        return 0;
    }
    if (request->source_was_burned) {
        if (request->source_lifecycle_revision != 4U
            || request->source_projection == NULL
            || request->source_projection != shadow->projection
            || !aqt_issuer_projection_is_roots_only(
                request->source_projection
            )) {
            return 0;
        }
    }
    else if (request->source_lifecycle_revision != 3U
        || request->source_projection == NULL
        || aqt_issuer_projection_is_roots_only(request->source_projection)
        || request->source_projection == shadow->projection) {
        return 0;
    }
    cell = shadow->choreography_authority_cell;
    return cell != NULL
        && cell->alive == 1U
        && cell->action_live == 0U
        && cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_BURNED;
}

static int
aqt_issuer_choreography_controller_cleanup_records_are_exact_locked(
    const AqtIssuerChoreographyControllerTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int candidate_was_stored,
    const AqtIssuerChoreographyState *state,
    const AqtIssuerChoreographyAuthorityCell *cell
)
{
    const AqtIssuerChoreographyStateValue *target;
    const AqtIssuerChoreographyFailclosedOrigin *origin;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *claim;
    AqtIssuerChoreographyRecord *post_effect;
    AqtIssuerChoreographyRecord *checkpoint;
    uint64_t terminal_revision;
    size_t index;

    if (request == NULL || expected == NULL || candidate == NULL
        || state == NULL || cell == NULL
        || candidate_was_stored < 0 || candidate_was_stored > 1
        || (candidate_was_stored
            && !aqt_issuer_choreography_controller_candidate_matches_request(
                request,
                expected,
                candidate
            ))) {
        return 0;
    }
    target = &state->value;
    origin = &state->failclosed_origin;
    lease = request->lease_record;
    recovery = request->recovery_record;
    claim = request->claim_record;
    post_effect = request->post_effect_record;
    checkpoint = request->controller_checkpoint_record;
    terminal_revision = target->revision;
    if (lease == NULL || recovery == NULL || claim == NULL
        || post_effect == NULL || checkpoint == NULL
        || !claim->wrapper_live || !post_effect->wrapper_live
        || !checkpoint->wrapper_live
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            checkpoint,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )
        || !aqt_issuer_choreography_post_effect_requirement_immutable_lineage_is_exact_locked(
            lease,
            recovery,
            claim,
            post_effect,
            expected,
            target
        )
        || checkpoint->prepared_at_revision != expected->revision
        || checkpoint->prepared_time_selector_present != 1U
        || checkpoint->prepared_time_selector != request->selector
        || checkpoint->prepared_source_last_monotonic_ns
            != expected->last_monotonic_ns
        || checkpoint->payload.controller_checkpoint.projection.outcome_kind
            != request->outcome_kind
        || checkpoint->payload.controller_checkpoint.projection
                .observed_monotonic_ns
            != request->observed_monotonic_ns
        || !aqt_issuer_choreography_controller_checkpoint_summary_matches_value(
            &checkpoint->payload.controller_checkpoint,
            expected,
            0
        )) {
        return 0;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        unsigned int present =
            (target->authority_record_presence_mask & (1U << index)) != 0U;

        if (present != (state->authority_records[index] != NULL)) {
            return 0;
        }
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        unsigned int present =
            (target->witness_record_presence_mask & (1U << index)) != 0U;

        if (present != (state->witness_records[index] != NULL)) {
            return 0;
        }
    }
    if (origin->committed_is_present) {
        if (!candidate_was_stored
            || candidate->phase
                != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONSUMING
            || memcmp(&origin->committed, candidate, sizeof(*candidate)) != 0
            || memcmp(
                &checkpoint->payload.controller_checkpoint,
                &origin->committed.controller_checkpoint,
                sizeof(origin->committed.controller_checkpoint)
            ) != 0) {
            return 0;
        }
    }
    else if (candidate_was_stored
        && memcmp(target, candidate, sizeof(*candidate)) != 0) {
        return 0;
    }
    if (target->phase == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED) {
        return target->action_active == 0U
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] == lease
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] == recovery
            && state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ] == post_effect
            && state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
            ] == claim
            && state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
            ] == NULL
            && lease->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && post_effect->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
            && claim->status == AQT_CHOREOGRAPHY_WITNESS_INSTALLED
            && checkpoint->status == AQT_CHOREOGRAPHY_WITNESS_CLEARED
            && lease->install_or_terminal_state_revision
                == request->lease_initial_status_revision
            && recovery->install_or_terminal_state_revision
                == request->recovery_initial_status_revision
            && post_effect->install_or_terminal_state_revision
                == request->post_effect_initial_status_revision
            && claim->install_or_terminal_state_revision
                == request->claim_initial_status_revision
            && checkpoint->install_or_terminal_state_revision
                == terminal_revision;
    }
    if (target->phase != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED
        && target->phase != AQT_CHOREOGRAPHY_PHASE_EXPIRED) {
        return 0;
    }
    return state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] == NULL
        && state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] == NULL
        && state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] == NULL
        && state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] == NULL
        && state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] == NULL
        && lease->status == AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        && recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        && post_effect->status == AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        && claim->status == AQT_CHOREOGRAPHY_WITNESS_CLEARED
        && checkpoint->status == AQT_CHOREOGRAPHY_WITNESS_CLEARED
        && lease->install_or_terminal_state_revision == terminal_revision
        && recovery->install_or_terminal_state_revision == terminal_revision
        && post_effect->install_or_terminal_state_revision == terminal_revision
        && claim->install_or_terminal_state_revision == terminal_revision
        && checkpoint->install_or_terminal_state_revision == terminal_revision
        && memcmp(&claim->payload.claim, &target->claim, sizeof(target->claim))
            == 0
        && (aqt_issuer_choreography_record_key_is_empty(
                &target->controller_checkpoint.key
            )
            || memcmp(
                &checkpoint->payload.controller_checkpoint,
                &target->controller_checkpoint,
                sizeof(target->controller_checkpoint)
            ) == 0);
}

static int
aqt_issuer_choreography_controller_cleanup_reconcile_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerTransitionRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int candidate_was_stored,
    AqtIssuerActivationProjection **prepared_roots,
    AqtIssuerActivationProjection **detached_projection,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyStateValue target;
    AqtIssuerChoreographyFailclosedOrigin origin;
    unsigned int target_policy;
    int committed_is_present;
    size_t index;

    aqt_issuer_choreography_build_controller_cleanup_target_locked(
        expected,
        candidate,
        candidate_was_stored,
        &target,
        &target_policy,
        &committed_is_present
    );
    aqt_issuer_choreography_build_controller_failclosed_origin(
        expected,
        candidate,
        committed_is_present,
        target_policy,
        &target,
        &origin
    );
    if (cell != NULL
        && cell->persistent_state_revision == target.revision
        && memcmp(&state->value, &target, sizeof(target)) == 0
        && memcmp(&state->failclosed_origin, &origin, sizeof(origin)) == 0) {
        return aqt_issuer_choreography_controller_cleanup_lifecycle_is_exact_locked(
                shadow,
                request
            )
            && aqt_issuer_choreography_controller_cleanup_records_are_exact_locked(
                request,
                expected,
                candidate,
                candidate_was_stored,
                state,
                cell
            )
            && aqt_issuer_choreography_controller_failclosed_origin_is_exact_locked(
                state
            )
            && aqt_issuer_choreography_cell_is_exact_locked(shadow);
    }
    if (cell == NULL
        || cell->persistent_state_revision
            != expected->revision + (candidate_was_stored ? 1U : 0U)
        || memcmp(
            &state->value,
            candidate_was_stored ? candidate : expected,
            sizeof(state->value)
        ) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )) {
        return 0;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->authority_records[index];

        if (record != NULL
            && (target.authority_record_presence_mask & (1U << index)) == 0U) {
            aqt_issuer_choreography_detached_record_append_locked(
                detached,
                record
            );
            state->authority_records[index] = NULL;
        }
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->witness_records[index];

        if (record != NULL
            && (target.witness_record_presence_mask & (1U << index)) == 0U) {
            aqt_issuer_choreography_detached_record_append_locked(
                detached,
                record
            );
            state->witness_records[index] = NULL;
        }
    }
    if (target.phase == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED) {
        request->controller_checkpoint_record->status =
            AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        request->controller_checkpoint_record
            ->install_or_terminal_state_revision = target.revision;
    }
    else if (target.phase
                == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED
        || target.phase == AQT_CHOREOGRAPHY_PHASE_EXPIRED) {
        request->lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->post_effect_record->status =
            AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        request->claim_record->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        request->controller_checkpoint_record->status =
            AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        request->lease_record->install_or_terminal_state_revision =
            target.revision;
        request->recovery_record->install_or_terminal_state_revision =
            target.revision;
        request->post_effect_record->install_or_terminal_state_revision =
            target.revision;
        request->claim_record->install_or_terminal_state_revision =
            target.revision;
        request->controller_checkpoint_record
            ->install_or_terminal_state_revision = target.revision;
    }
    else {
        return 0;
    }
    state->value = target;
    state->failclosed_origin = origin;
    cell->persistent_state_revision = target.revision;
    if (!request->source_was_burned) {
        aqt_issuer_choreography_recovery_burn_locked(
            shadow,
            prepared_roots,
            detached_projection
        );
    }
    return aqt_issuer_choreography_controller_cleanup_lifecycle_is_exact_locked(
            shadow,
            request
        )
        && aqt_issuer_choreography_controller_cleanup_records_are_exact_locked(
            request,
            expected,
            candidate,
            candidate_was_stored,
            state,
            cell
        )
        && aqt_issuer_choreography_controller_failclosed_origin_is_exact_locked(
            state
        )
        && aqt_issuer_choreography_cell_is_exact_locked(shadow);
}

static PyObject *
aqt_issuer_choreography_controller_transition(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerTransitionRequest *request
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerFailure failure = {0};
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int saved_errno = 0;
    int semantic_error = 0;
    int candidate_was_stored = 0;
    int committed_is_present = 0;
    int terminal_proof_completed = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int fork_commit_completed = 0;
    int index;

    memset(&expected, 0, sizeof(expected));
    memset(&candidate, 0, sizeof(candidate));
    if (module_state == NULL || request == NULL) {
        return NULL;
    }
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        aqt_clear_issuer_external_projection_barrier(module_state);
        return NULL;
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        PyErr_Clear();
        aqt_clear_issuer_external_projection_barrier(module_state);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller outcome retention is unavailable"
        );
    }
    if (shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY) {
        prepared_roots = aqt_clone_issuer_roots_projection(shadow->projection);
        if (prepared_roots == NULL) {
            aqt_clear_issuer_external_projection_barrier(module_state);
            return NULL;
        }
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_controller_transition_source_is_exact_locked(
            shadow,
            request,
            current_thread,
            current_thread_id
        )) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller outcome retention is unavailable"
        );
    }
    expected = shadow->choreography_state.value;
    request->source_lifecycle_revision = shadow->revision;
    request->source_projection = shadow->projection;
    request->source_launch_lease = shadow->launch_lease;
    request->lease_initial_status_revision =
        request->lease_record->install_or_terminal_state_revision;
    request->recovery_initial_status_revision =
        request->recovery_record->install_or_terminal_state_revision;
    request->claim_initial_status_revision =
        request->claim_record->install_or_terminal_state_revision;
    request->post_effect_initial_status_revision =
        request->post_effect_record->install_or_terminal_state_revision;
    request->controller_checkpoint_initial_status_revision =
        request->controller_checkpoint_record
            ->install_or_terminal_state_revision;
    request->observed_monotonic_ns = request->controller_checkpoint_record
        ->payload.controller_checkpoint.projection.observed_monotonic_ns;
    if (fault_plan->row_count != 0
        && fault_plan->group == 3
        && atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller fault and fork plans conflict"
        );
    }
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            AQT_CHOREOGRAPHY_OPERATION_BEGIN_CONTROLLER,
            expected.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller outcome retention is unavailable"
        );
    }
    aqt_issuer_choreography_resolve_controller_candidate_locked(
        &expected,
        &request->controller_checkpoint_record->payload.controller_checkpoint,
        request->selector,
        &candidate
    );
    if (aqt_issuer_choreography_controller_authority_proof_locked(
            module_state,
            shadow,
            request,
            &expected,
            &candidate,
            0,
            0,
            &request->authority_proof_failed
        ) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
    }
    if (saved_errno == 0) {
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && saved_errno == 0) {
        aqt_issuer_choreography_publish_controller_candidate_locked(
            shadow,
            request,
            &candidate,
            &detached
        );
        candidate_was_stored = 1;
        committed_is_present = candidate.phase
            == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONSUMING;
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_controller_transition_locked(
                shadow,
                &expected,
                &candidate,
                1,
                request
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = 1;
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
            aqt_unlock_owner_list_or_fail_stop();
            if (aqt_issuer_foreign_fork_wait_for_value(
                    &module_state->issuer_foreign_fork_plan.worker_completed,
                    1
                ) < 0) {
                aqt_fail_stop(
                    "native issuer controller foreign-fork worker timed out"
                );
            }
            aqt_lock_owner_list_or_fail_stop();
            if (memcmp(
                    &shadow->choreography_state.value,
                    &candidate,
                    sizeof(candidate)
                ) != 0
                || !aqt_issuer_choreography_memory_is_zero(
                    &shadow->choreography_state.failclosed_origin,
                    sizeof(shadow->choreography_state.failclosed_origin)
                )) {
                aqt_fail_stop(
                    "native issuer controller changed across foreign fork"
                );
            }
        }
        if (committed_is_present) {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
                1,
                current_pid,
                current_interpreter
            );
        }
        else {
            semantic_error = 1;
        }
    }
    if (primary_kind < 0 && saved_errno == 0 && committed_is_present) {
        if (aqt_issuer_choreography_controller_authority_proof_locked(
                module_state,
                shadow,
                request,
                &expected,
                &candidate,
                1,
                1,
                &request->authority_proof_failed
            ) < 0) {
            saved_errno = errno != 0 ? errno : EIO;
        }
        else {
            terminal_proof_completed = 1;
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && committed_is_present && terminal_proof_completed) {
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
            primary_kind = AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR;
        }
        else {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
        }
    }
    if (primary_kind < 0 && saved_errno == 0 && !semantic_error) {
        if (!aqt_issuer_choreography_cell_is_exact_locked(shadow)) {
            abort();
        }
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        aqt_free_issuer_projection(&detached_projection);
        aqt_issuer_choreography_detached_records_release(&detached);
        Py_RETURN_NONE;
    }
    if (fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
        aqt_issuer_foreign_fork_bind_controller_transition_locked(
            shadow,
            &expected,
            candidate_was_stored ? &candidate : NULL,
            candidate_was_stored,
            request
        );
        if (aqt_issuer_foreign_fork_interpose_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ) < 0) {
            abort();
        }
        fork_was_triggered = 1;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_controller_cleanup_reconcile_locked(
                shadow,
                request,
                &expected,
                &candidate,
                candidate_was_stored,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography controller cleanup attempt failed"
            );
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_controller_cleanup_reconcile_locked(
            shadow,
            request,
            &expected,
            &candidate,
            candidate_was_stored,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography controller cleanup confirmation failed"
        );
    }
    if (fork_was_triggered && !fork_commit_completed) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
        fork_commit_completed = 1;
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered && fork_commit_completed
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed,
            1
        ) < 0) {
        aqt_fail_stop(
            "native issuer controller cleanup foreign-fork worker timed out"
        );
    }
    aqt_clear_issuer_external_projection_barrier(module_state);
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    else if (saved_errno != 0) {
        aqt_issuer_failure_record_errno(&failure, saved_errno);
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0
            && (!semantic_error
                || cleanup_kinds[index]
                    != AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR)) {
            aqt_issuer_failure_record_synthetic(
                &failure,
                cleanup_kinds[index]
            );
        }
    }
    if (failure.has_selected) {
        return aqt_issuer_choreography_failure_raise(&failure);
    }
    return aqt_issuer_choreography_runtime_error(
        "native issuer choreography controller outcome retention is unavailable"
    );
}

static PyObject *
aqt_issuer_choreography_begin_controller(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerTransitionRequest *request
)
{
    return aqt_issuer_choreography_controller_transition(
        module,
        shadow,
        request
    );
}

static int
aqt_issuer_choreography_controller_confirmation_source_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerConfirmationRequest *request,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *claim;
    AqtIssuerChoreographyRecord *post_effect;
    AqtIssuerChoreographyRecord *checkpoint;
    AqtIssuerChoreographyRecord *receipt = request != NULL
        ? request->controller_receipt_record
        : NULL;
    int source_was_burned;

    if (request == NULL
        || request->operation_tag
            != AQT_CHOREOGRAPHY_OPERATION_CONFIRM_CONTROLLER
        || request->selector >= AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT
        || receipt == NULL
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || (shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
            && shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED)
        || shadow->closed != 0U || shadow->busy != 0U
        || shadow->runtime_ready != 0U || shadow->projection == NULL
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || cell == NULL || cell->alive != 1U
        || cell->pending_scope_generation != 0U
        || !shadow->choreography_state_present
        || state->value.revision > UINT64_MAX - 2U
        || state->value.revision != cell->persistent_state_revision
        || state->value.binding_generation != cell->binding_generation
        || state->value.scope_generation != cell->current_scope_generation
        || !aqt_issuer_choreography_controller_confirmation_source_value_is_exact(
            &state->value
        )
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )
        || !receipt->wrapper_live || !receipt->wrapper_was_created
        || receipt->status != AQT_CHOREOGRAPHY_WITNESS_PREPARED
        || receipt->prepared_at_revision != state->value.revision
        || receipt->install_or_terminal_state_revision != 0U
        || !aqt_issuer_choreography_record_is_exact_locked(
            receipt,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        )
        || receipt->payload.controller_receipt.mode
            != AQT_CHOREOGRAPHY_RECEIPT_PREPARED
        || !aqt_issuer_choreography_controller_receipt_summary_matches_value(
            &receipt->payload.controller_receipt,
            &state->value
        )) {
        return 0;
    }
    source_was_burned = shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED;
    if ((source_was_burned
            && state->value.controller_checkpoint.projection.outcome_kind
                != AQT_CHOREOGRAPHY_OUTCOME_FAILURE)
        || (source_was_burned
            ? (shadow->revision != 4U || shadow->poisoned != 1U
                || !aqt_issuer_projection_is_roots_only(shadow->projection)
                || cell->action_live != 0U
                || cell->lifecycle_disposition
                    != AQT_CHOREOGRAPHY_CELL_BURNED)
            : (shadow->revision != 3U || shadow->poisoned != 0U
                || aqt_issuer_projection_is_roots_only(shadow->projection)
                || cell->action_live != 1U
                || cell->lifecycle_disposition
                    != AQT_CHOREOGRAPHY_CELL_ACTIVE))) {
        return 0;
    }
    lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    post_effect = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
    ];
    claim = state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
    ];
    checkpoint = state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
    ];
    if (lease == NULL || recovery == NULL || claim == NULL
        || post_effect == NULL || checkpoint == NULL
        || request->post_effect_record != post_effect
        || request->controller_checkpoint_record != checkpoint
        || !post_effect->wrapper_live || !checkpoint->wrapper_live
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != NULL
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || claim->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        || checkpoint->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            checkpoint, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )
        || !aqt_issuer_choreography_post_effect_requirement_immutable_lineage_is_exact_locked(
            lease,
            recovery,
            claim,
            post_effect,
            &state->value,
            &state->value
        )
        || memcmp(
            &checkpoint->payload.controller_checkpoint,
            &state->value.controller_checkpoint,
            sizeof(state->value.controller_checkpoint)
        ) != 0) {
        return 0;
    }
    request->lease_record = lease;
    request->recovery_record = recovery;
    request->claim_record = claim;
    request->source_was_burned = source_was_burned ? 1U : 0U;
    return 1;
}

static int
aqt_issuer_choreography_controller_confirmation_selected_records_proof_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerConfirmationRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int installed
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    AqtIssuerChoreographyRecord *post_effect = request->post_effect_record;
    AqtIssuerChoreographyRecord *checkpoint =
        request->controller_checkpoint_record;
    AqtIssuerChoreographyRecord *receipt =
        request->controller_receipt_record;
    const AqtIssuerChoreographyStateValue *required_value =
        installed ? candidate : expected;

    if (cell == NULL || lease == NULL || recovery == NULL || claim == NULL
        || post_effect == NULL || checkpoint == NULL || receipt == NULL
        || !aqt_issuer_choreography_controller_confirmation_candidate_matches_request(
            request,
            expected,
            candidate
        )
        || !post_effect->wrapper_live || !checkpoint->wrapper_live
        || !receipt->wrapper_live
        || !aqt_issuer_choreography_cell_is_exact_locked(shadow)
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            checkpoint, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            receipt, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        )
        || !aqt_issuer_choreography_post_effect_requirement_immutable_lineage_is_exact_locked(
            lease,
            recovery,
            claim,
            post_effect,
            expected,
            required_value
        )
        || !aqt_issuer_choreography_controller_receipt_summary_matches_value(
            &receipt->payload.controller_receipt,
            expected
        )
        || memcmp(&state->value, required_value, sizeof(*required_value)) != 0
        || lease->install_or_terminal_state_revision
            != request->lease_initial_status_revision
        || recovery->install_or_terminal_state_revision
            != request->recovery_initial_status_revision
        || post_effect->install_or_terminal_state_revision
            != request->post_effect_initial_status_revision) {
        errno = EINVAL;
        return -1;
    }
    if (!installed) {
        if (state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ] != lease
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ] != recovery
            || state->authority_records[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ] != post_effect
            || state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
            ] != claim
            || state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
            ] != checkpoint
            || state->witness_records[
                AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
            ] != NULL
            || claim->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
            || checkpoint->status != AQT_CHOREOGRAPHY_WITNESS_INSTALLED
            || receipt->status != AQT_CHOREOGRAPHY_WITNESS_PREPARED
            || claim->install_or_terminal_state_revision
                != request->claim_initial_status_revision
            || checkpoint->install_or_terminal_state_revision
                != request->controller_checkpoint_initial_status_revision
            || receipt->install_or_terminal_state_revision
                != request->controller_receipt_initial_status_revision
            || memcmp(
                &claim->payload.claim,
                &expected->claim,
                sizeof(expected->claim)
            ) != 0
            || memcmp(
                &checkpoint->payload.controller_checkpoint,
                &expected->controller_checkpoint,
                sizeof(expected->controller_checkpoint)
            ) != 0) {
            errno = EINVAL;
            return -1;
        }
        return 0;
    }
    if (candidate == NULL
        || candidate->phase
            != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONFIRMED
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != receipt
        || claim->status
            != AQT_CHOREOGRAPHY_WITNESS_DEPENDENCY_TOMBSTONE
        || checkpoint->status
            != AQT_CHOREOGRAPHY_WITNESS_DEPENDENCY_TOMBSTONE
        || receipt->status
            != AQT_CHOREOGRAPHY_WITNESS_INSTALLED_PREPARED
        || claim->install_or_terminal_state_revision != candidate->revision
        || checkpoint->install_or_terminal_state_revision
            != candidate->revision
        || receipt->install_or_terminal_state_revision != candidate->revision
        || memcmp(
            &claim->payload.claim,
            &candidate->claim,
            sizeof(candidate->claim)
        ) != 0
        || memcmp(
            &checkpoint->payload.controller_checkpoint,
            &candidate->controller_checkpoint,
            sizeof(candidate->controller_checkpoint)
        ) != 0
        || memcmp(
            &receipt->payload.controller_receipt,
            &candidate->controller_receipt,
            sizeof(candidate->controller_receipt)
        ) != 0) {
        errno = EINVAL;
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_controller_confirmation_authority_proof_locked(
    AqtModuleState *module_state,
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerConfirmationRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int installed,
    int consume_barrier,
    unsigned int *authority_proof_failed
)
{
    if (aqt_issuer_choreography_controller_confirmation_selected_records_proof_locked(
            shadow,
            request,
            expected,
            candidate,
            installed
        ) < 0) {
        return -1;
    }
    if (!request->source_was_burned
        && aqt_issuer_external_projection_matches(shadow->projection) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    if (aqt_validate_launch_lock_core_locked(shadow->launch_lease) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    if (consume_barrier) {
        aqt_run_issuer_external_projection_barrier(module_state);
    }
    if (request->source_was_burned) {
        if (aqt_validate_launch_lock_core_locked(shadow->launch_lease) < 0) {
            *authority_proof_failed = 1U;
            return -1;
        }
    }
    else if (aqt_issuer_external_projection_matches(shadow->projection) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    return 0;
}

static void
aqt_issuer_choreography_publish_controller_confirmation_candidate_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerConfirmationRequest *request,
    const AqtIssuerChoreographyStateValue *candidate,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *claim = request->claim_record;
    AqtIssuerChoreographyRecord *post_effect = request->post_effect_record;
    AqtIssuerChoreographyRecord *checkpoint =
        request->controller_checkpoint_record;
    AqtIssuerChoreographyRecord *receipt =
        request->controller_receipt_record;
    uint64_t revision = candidate->revision;

    if (cell == NULL
        || !aqt_issuer_choreography_controller_confirmation_candidate_matches_request(
            request,
            &state->value,
            candidate
        )
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != claim
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] != checkpoint
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != NULL
        || receipt->status != AQT_CHOREOGRAPHY_WITNESS_PREPARED) {
        abort();
    }
    if (candidate->phase
            == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONFIRMED) {
        state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] = NULL;
        state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] = NULL;
        aqt_issuer_choreography_detached_record_append_locked(detached, claim);
        aqt_issuer_choreography_detached_record_append_locked(
            detached,
            checkpoint
        );
        claim->status = AQT_CHOREOGRAPHY_WITNESS_DEPENDENCY_TOMBSTONE;
        checkpoint->status =
            AQT_CHOREOGRAPHY_WITNESS_DEPENDENCY_TOMBSTONE;
        claim->install_or_terminal_state_revision = revision;
        checkpoint->install_or_terminal_state_revision = revision;
        aqt_issuer_choreography_record_incref(receipt);
        state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] = receipt;
        receipt->status = AQT_CHOREOGRAPHY_WITNESS_INSTALLED_PREPARED;
        receipt->install_or_terminal_state_revision = revision;
    }
    else if (candidate->phase
            == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED) {
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] = NULL;
        state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] = NULL;
        state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] = NULL;
        state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] = NULL;
        aqt_issuer_choreography_detached_record_append_locked(detached, lease);
        aqt_issuer_choreography_detached_record_append_locked(detached, recovery);
        aqt_issuer_choreography_detached_record_append_locked(detached, post_effect);
        aqt_issuer_choreography_detached_record_append_locked(detached, claim);
        aqt_issuer_choreography_detached_record_append_locked(detached, checkpoint);
        lease->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        recovery->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        post_effect->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
        claim->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        checkpoint->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        receipt->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        lease->install_or_terminal_state_revision = revision;
        recovery->install_or_terminal_state_revision = revision;
        post_effect->install_or_terminal_state_revision = revision;
        claim->install_or_terminal_state_revision = revision;
        checkpoint->install_or_terminal_state_revision = revision;
        receipt->install_or_terminal_state_revision = revision;
    }
    else {
        abort();
    }
    state->value = *candidate;
    memset(&state->failclosed_origin, 0, sizeof(state->failclosed_origin));
    cell->persistent_state_revision = revision;
}

static int
aqt_issuer_choreography_controller_confirmation_cleanup_lifecycle_is_exact_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerConfirmationRequest *request
)
{
    const AqtIssuerChoreographyAuthorityCell *cell;

    if (shadow == NULL || request == NULL
        || request->source_launch_lease == NULL
        || request->source_launch_lease != shadow->launch_lease
        || shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED
        || shadow->revision != 4U || shadow->poisoned != 1U
        || shadow->closed != 0U || shadow->lease_was_closed != 0U
        || !aqt_issuer_projection_is_roots_only(shadow->projection)
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)) {
        return 0;
    }
    if (request->source_was_burned) {
        if (request->source_lifecycle_revision != 4U
            || request->source_projection == NULL
            || request->source_projection != shadow->projection
            || !aqt_issuer_projection_is_roots_only(
                request->source_projection
            )) {
            return 0;
        }
    }
    else if (request->source_lifecycle_revision != 3U
        || request->source_projection == NULL
        || aqt_issuer_projection_is_roots_only(request->source_projection)
        || request->source_projection == shadow->projection) {
        return 0;
    }
    cell = shadow->choreography_authority_cell;
    return cell != NULL && cell->alive == 1U && cell->action_live == 0U
        && cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_BURNED;
}

static int
aqt_issuer_choreography_controller_confirmation_cleanup_records_are_exact_locked(
    const AqtIssuerChoreographyControllerConfirmationRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int candidate_was_stored,
    const AqtIssuerChoreographyState *state,
    const AqtIssuerChoreographyAuthorityCell *cell
)
{
    const AqtIssuerChoreographyStateValue *target;
    const AqtIssuerChoreographyFailclosedOrigin *origin;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *claim;
    AqtIssuerChoreographyRecord *post_effect;
    AqtIssuerChoreographyRecord *checkpoint;
    AqtIssuerChoreographyRecord *receipt;
    uint64_t terminal_revision;
    int committed;
    size_t index;

    if (request == NULL || expected == NULL || candidate == NULL
        || state == NULL || cell == NULL
        || candidate_was_stored < 0 || candidate_was_stored > 1
        || (candidate_was_stored
            && !aqt_issuer_choreography_controller_confirmation_candidate_matches_request(
                request,
                expected,
                candidate
            ))) {
        return 0;
    }
    target = &state->value;
    origin = &state->failclosed_origin;
    lease = request->lease_record;
    recovery = request->recovery_record;
    claim = request->claim_record;
    post_effect = request->post_effect_record;
    checkpoint = request->controller_checkpoint_record;
    receipt = request->controller_receipt_record;
    terminal_revision = target->revision;
    committed = origin->committed_is_present != 0U;
    if (lease == NULL || recovery == NULL || claim == NULL
        || post_effect == NULL || checkpoint == NULL || receipt == NULL
        || !post_effect->wrapper_live || !checkpoint->wrapper_live
        || !receipt->wrapper_live
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            claim, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            checkpoint, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            receipt, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        )
        || !aqt_issuer_choreography_post_effect_requirement_immutable_lineage_is_exact_locked(
            lease,
            recovery,
            claim,
            post_effect,
            expected,
            target
        )
        || memcmp(
            &checkpoint->payload.controller_checkpoint,
            &expected->controller_checkpoint,
            sizeof(expected->controller_checkpoint)
        ) != 0
        || !aqt_issuer_choreography_controller_receipt_summary_matches_value(
            &receipt->payload.controller_receipt,
            expected
        )) {
        return 0;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        if (state->authority_records[index] != NULL) {
            return 0;
        }
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        if (state->witness_records[index] != NULL) {
            return 0;
        }
    }
    if (target->phase != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || receipt->status != AQT_CHOREOGRAPHY_WITNESS_CLEARED
        || lease->install_or_terminal_state_revision != terminal_revision
        || recovery->install_or_terminal_state_revision != terminal_revision
        || post_effect->install_or_terminal_state_revision != terminal_revision
        || receipt->install_or_terminal_state_revision != terminal_revision
        || memcmp(&claim->payload.claim, &target->claim, sizeof(target->claim))
            != 0
        || memcmp(
            &checkpoint->payload.controller_checkpoint,
            &target->controller_checkpoint,
            sizeof(target->controller_checkpoint)
        ) != 0) {
        return 0;
    }
    if (committed) {
        return candidate_was_stored
            && candidate->phase
                == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONFIRMED
            && memcmp(&origin->committed, candidate, sizeof(*candidate)) == 0
            && claim->status
                == AQT_CHOREOGRAPHY_WITNESS_DEPENDENCY_TOMBSTONE
            && checkpoint->status
                == AQT_CHOREOGRAPHY_WITNESS_DEPENDENCY_TOMBSTONE
            && claim->install_or_terminal_state_revision
                == candidate->revision
            && checkpoint->install_or_terminal_state_revision
                == candidate->revision;
    }
    return claim->status == AQT_CHOREOGRAPHY_WITNESS_CLEARED
        && checkpoint->status == AQT_CHOREOGRAPHY_WITNESS_CLEARED
        && claim->install_or_terminal_state_revision == terminal_revision
        && checkpoint->install_or_terminal_state_revision == terminal_revision
        && (!candidate_was_stored
            || memcmp(target, candidate, sizeof(*candidate)) == 0);
}

static int
aqt_issuer_choreography_controller_confirmation_cleanup_reconcile_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerConfirmationRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int candidate_was_stored,
    AqtIssuerActivationProjection **prepared_roots,
    AqtIssuerActivationProjection **detached_projection,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyStateValue target;
    AqtIssuerChoreographyFailclosedOrigin origin;
    int committed_is_present;
    size_t index;

    aqt_issuer_choreography_build_controller_confirmation_cleanup_target_locked(
        expected,
        candidate,
        candidate_was_stored,
        &target,
        &committed_is_present
    );
    aqt_issuer_choreography_build_controller_confirmation_failclosed_origin(
        expected,
        candidate,
        committed_is_present,
        &target,
        &origin
    );
    if (cell != NULL
        && cell->persistent_state_revision == target.revision
        && memcmp(&state->value, &target, sizeof(target)) == 0
        && memcmp(&state->failclosed_origin, &origin, sizeof(origin)) == 0) {
        return aqt_issuer_choreography_controller_confirmation_cleanup_lifecycle_is_exact_locked(
                shadow,
                request
            )
            && aqt_issuer_choreography_controller_confirmation_cleanup_records_are_exact_locked(
                request,
                expected,
                candidate,
                candidate_was_stored,
                state,
                cell
            )
            && aqt_issuer_choreography_controller_confirmation_failclosed_origin_is_exact_locked(
                state
            )
            && aqt_issuer_choreography_cell_is_exact_locked(shadow);
    }
    if (cell == NULL
        || cell->persistent_state_revision
            != expected->revision + (candidate_was_stored ? 1U : 0U)
        || memcmp(
            &state->value,
            candidate_was_stored ? candidate : expected,
            sizeof(state->value)
        ) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin,
            sizeof(state->failclosed_origin)
        )) {
        return 0;
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->authority_records[index];
        if (record != NULL) {
            aqt_issuer_choreography_detached_record_append_locked(detached, record);
            state->authority_records[index] = NULL;
        }
    }
    for (index = 0;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->witness_records[index];
        if (record != NULL) {
            aqt_issuer_choreography_detached_record_append_locked(detached, record);
            state->witness_records[index] = NULL;
        }
    }
    request->lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    request->recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    request->post_effect_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    request->controller_receipt_record->status =
        AQT_CHOREOGRAPHY_WITNESS_CLEARED;
    request->lease_record->install_or_terminal_state_revision = target.revision;
    request->recovery_record->install_or_terminal_state_revision = target.revision;
    request->post_effect_record->install_or_terminal_state_revision =
        target.revision;
    request->controller_receipt_record->install_or_terminal_state_revision =
        target.revision;
    if (!committed_is_present) {
        request->claim_record->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        request->controller_checkpoint_record->status =
            AQT_CHOREOGRAPHY_WITNESS_CLEARED;
        request->claim_record->install_or_terminal_state_revision =
            target.revision;
        request->controller_checkpoint_record
            ->install_or_terminal_state_revision = target.revision;
    }
    state->value = target;
    state->failclosed_origin = origin;
    cell->persistent_state_revision = target.revision;
    if (!request->source_was_burned) {
        aqt_issuer_choreography_recovery_burn_locked(
            shadow,
            prepared_roots,
            detached_projection
        );
    }
    return aqt_issuer_choreography_controller_confirmation_cleanup_lifecycle_is_exact_locked(
            shadow,
            request
        )
        && aqt_issuer_choreography_controller_confirmation_cleanup_records_are_exact_locked(
            request,
            expected,
            candidate,
            candidate_was_stored,
            state,
            cell
        )
        && aqt_issuer_choreography_controller_confirmation_failclosed_origin_is_exact_locked(
            state
        )
        && aqt_issuer_choreography_cell_is_exact_locked(shadow);
}

static PyObject *
aqt_issuer_choreography_controller_confirmation_transition(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerConfirmationRequest *request
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerFailure failure = {0};
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    uint64_t sampled_now = 0U;
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int saved_errno = 0;
    int semantic_error = 0;
    int candidate_was_stored = 0;
    int committed_is_present = 0;
    int terminal_proof_completed = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int fork_commit_completed = 0;
    int index;

    memset(&expected, 0, sizeof(expected));
    memset(&candidate, 0, sizeof(candidate));
    if (module_state == NULL || request == NULL) {
        return NULL;
    }
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        aqt_clear_issuer_external_projection_barrier(module_state);
        return NULL;
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        PyErr_Clear();
        aqt_clear_issuer_external_projection_barrier(module_state);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller outcome retention completion is unavailable"
        );
    }
    if (shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY) {
        prepared_roots = aqt_clone_issuer_roots_projection(shadow->projection);
        if (prepared_roots == NULL) {
            aqt_clear_issuer_external_projection_barrier(module_state);
            return NULL;
        }
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_controller_confirmation_source_is_exact_locked(
            shadow,
            request,
            current_thread,
            current_thread_id
        )) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller outcome retention completion is unavailable"
        );
    }
    expected = shadow->choreography_state.value;
    request->source_lifecycle_revision = shadow->revision;
    request->source_projection = shadow->projection;
    request->source_launch_lease = shadow->launch_lease;
    request->lease_initial_status_revision =
        request->lease_record->install_or_terminal_state_revision;
    request->recovery_initial_status_revision =
        request->recovery_record->install_or_terminal_state_revision;
    request->claim_initial_status_revision =
        request->claim_record->install_or_terminal_state_revision;
    request->post_effect_initial_status_revision =
        request->post_effect_record->install_or_terminal_state_revision;
    request->controller_checkpoint_initial_status_revision =
        request->controller_checkpoint_record
            ->install_or_terminal_state_revision;
    request->controller_receipt_initial_status_revision =
        request->controller_receipt_record
            ->install_or_terminal_state_revision;
    if (fault_plan->row_count != 0 && fault_plan->group == 3
        && atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller fault and fork plans conflict"
        );
    }
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            AQT_CHOREOGRAPHY_OPERATION_CONFIRM_CONTROLLER,
            expected.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller outcome retention completion is unavailable"
        );
    }
    if (request->selector == AQT_CHOREOGRAPHY_TIME_SAMPLE
        && aqt_issuer_choreography_sample_continuous_ns(&sampled_now) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
    }
    request->observed_monotonic_ns = request->selector
            == AQT_CHOREOGRAPHY_TIME_SAMPLE
        ? sampled_now
        : request->selector == AQT_CHOREOGRAPHY_TIME_ACTION_DEADLINE
            ? expected.action_deadline_monotonic_ns
            : request->selector == AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE
                ? expected.retention_deadline_monotonic_ns
                : expected.last_monotonic_ns;
    aqt_issuer_choreography_resolve_controller_confirmation_candidate_locked(
        &expected,
        &request->controller_receipt_record->payload.controller_receipt,
        request->selector,
        sampled_now,
        &candidate
    );
    if (saved_errno == 0
        && aqt_issuer_choreography_controller_confirmation_authority_proof_locked(
            module_state,
            shadow,
            request,
            &expected,
            &candidate,
            0,
            0,
            &request->authority_proof_failed
        ) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
    }
    if (saved_errno == 0) {
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && saved_errno == 0) {
        aqt_issuer_choreography_publish_controller_confirmation_candidate_locked(
            shadow,
            request,
            &candidate,
            &detached
        );
        candidate_was_stored = 1;
        committed_is_present = candidate.phase
            == AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONFIRMED;
        request->semantic_false = committed_is_present ? 0U : 1U;
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_controller_confirmation_locked(
                shadow,
                &expected,
                &candidate,
                1,
                request
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = 1;
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
            aqt_unlock_owner_list_or_fail_stop();
            if (aqt_issuer_foreign_fork_wait_for_value(
                    &module_state->issuer_foreign_fork_plan.worker_completed,
                    1
                ) < 0) {
                aqt_fail_stop(
                    "native issuer controller confirmation foreign-fork worker timed out"
                );
            }
            aqt_lock_owner_list_or_fail_stop();
            if (memcmp(
                    &shadow->choreography_state.value,
                    &candidate,
                    sizeof(candidate)
                ) != 0
                || !aqt_issuer_choreography_memory_is_zero(
                    &shadow->choreography_state.failclosed_origin,
                    sizeof(shadow->choreography_state.failclosed_origin)
                )) {
                aqt_fail_stop(
                    "native issuer controller confirmation changed across foreign fork"
                );
            }
        }
        if (committed_is_present) {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
                1,
                current_pid,
                current_interpreter
            );
        }
        else {
            semantic_error = 1;
        }
    }
    if (primary_kind < 0 && saved_errno == 0 && committed_is_present) {
        if (aqt_issuer_choreography_controller_confirmation_authority_proof_locked(
                module_state,
                shadow,
                request,
                &expected,
                &candidate,
                1,
                1,
                &request->authority_proof_failed
            ) < 0) {
            saved_errno = errno != 0 ? errno : EIO;
        }
        else {
            terminal_proof_completed = 1;
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && committed_is_present && terminal_proof_completed) {
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
            primary_kind = AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR;
        }
        else {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
        }
    }
    if (primary_kind < 0 && saved_errno == 0 && !semantic_error) {
        if (!aqt_issuer_choreography_cell_is_exact_locked(shadow)) {
            abort();
        }
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        aqt_free_issuer_projection(&detached_projection);
        aqt_issuer_choreography_detached_records_release(&detached);
        Py_RETURN_NONE;
    }
    if (fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
        aqt_issuer_foreign_fork_bind_controller_confirmation_locked(
            shadow,
            &expected,
            candidate_was_stored ? &candidate : NULL,
            candidate_was_stored,
            request
        );
        if (aqt_issuer_foreign_fork_interpose_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ) < 0) {
            abort();
        }
        fork_was_triggered = 1;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_controller_confirmation_cleanup_reconcile_locked(
                shadow,
                request,
                &expected,
                &candidate,
                candidate_was_stored,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography controller confirmation cleanup attempt failed"
            );
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_controller_confirmation_cleanup_reconcile_locked(
            shadow,
            request,
            &expected,
            &candidate,
            candidate_was_stored,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography controller confirmation cleanup confirmation failed"
        );
    }
    if (fork_was_triggered && !fork_commit_completed) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
        fork_commit_completed = 1;
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered && fork_commit_completed
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed,
            1
        ) < 0) {
        aqt_fail_stop(
            "native issuer controller confirmation cleanup foreign-fork worker timed out"
        );
    }
    aqt_clear_issuer_external_projection_barrier(module_state);
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    else if (saved_errno != 0) {
        aqt_issuer_failure_record_errno(&failure, saved_errno);
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0
            && (!semantic_error
                || cleanup_kinds[index]
                    != AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR)) {
            aqt_issuer_failure_record_synthetic(
                &failure,
                cleanup_kinds[index]
            );
        }
    }
    if (failure.has_selected) {
        return aqt_issuer_choreography_failure_raise(&failure);
    }
    return aqt_issuer_choreography_runtime_error(
        "native issuer choreography controller outcome retention completion is unavailable"
    );
}

static PyObject *
aqt_issuer_choreography_confirm_controller(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerConfirmationRequest *request
)
{
    return aqt_issuer_choreography_controller_confirmation_transition(
        module,
        shadow,
        request
    );
}

static int
aqt_issuer_choreography_controller_durability_source_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerDurabilityRequest *request,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *post_effect;
    AqtIssuerChoreographyRecord *receipt = request != NULL
        ? request->controller_receipt_record : NULL;
    int source_was_burned;

    if (request == NULL
        || request->operation_tag
            != AQT_CHOREOGRAPHY_OPERATION_ATTEST_CONTROLLER_DURABLE
        || receipt == NULL
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || (shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
            && shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED)
        || shadow->closed != 0U || shadow->busy != 0U
        || shadow->runtime_ready != 0U || shadow->projection == NULL
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || cell == NULL || cell->alive != 1U
        || cell->pending_scope_generation != 0U
        || !shadow->choreography_state_present
        || !aqt_issuer_choreography_controller_durability_source_value_is_exact(
            &state->value
        )
        || state->value.revision != cell->persistent_state_revision
        || state->value.binding_generation != cell->binding_generation
        || state->value.scope_generation != cell->current_scope_generation
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin, sizeof(state->failclosed_origin)
        )
        || !receipt->wrapper_live || !receipt->wrapper_was_created
        || receipt->status
            != AQT_CHOREOGRAPHY_WITNESS_INSTALLED_PREPARED
        || receipt->prepared_at_revision != state->value.revision - 1U
        || receipt->install_or_terminal_state_revision
            != state->value.revision
        || receipt->controller_durability_binding != NULL
        || !aqt_issuer_choreography_record_is_exact_locked(
            receipt,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        )
        || memcmp(
            &receipt->payload.controller_receipt,
            &state->value.controller_receipt,
            sizeof(state->value.controller_receipt)
        ) != 0) {
        return 0;
    }
    source_was_burned = shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED;
    if ((source_was_burned
            && state->value.controller_checkpoint.projection.outcome_kind
                != AQT_CHOREOGRAPHY_OUTCOME_FAILURE)
        || (source_was_burned
            ? (shadow->revision != 4U || shadow->poisoned != 1U
                || !aqt_issuer_projection_is_roots_only(shadow->projection)
                || cell->action_live != 0U
                || cell->lifecycle_disposition
                    != AQT_CHOREOGRAPHY_CELL_BURNED)
            : (shadow->revision != 3U || shadow->poisoned != 0U
                || aqt_issuer_projection_is_roots_only(shadow->projection)
                || cell->action_live != 1U
                || cell->lifecycle_disposition
                    != AQT_CHOREOGRAPHY_CELL_ACTIVE))) {
        return 0;
    }
    lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    post_effect = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
    ];
    if (lease == NULL || recovery == NULL || post_effect == NULL
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != receipt
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || memcmp(
            &lease->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ],
            sizeof(lease->key)
        ) != 0
        || memcmp(
            &recovery->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ],
            sizeof(recovery->key)
        ) != 0
        || memcmp(
            &post_effect->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ],
            sizeof(post_effect->key)
        ) != 0) {
        return 0;
    }
    request->lease_record = lease;
    request->recovery_record = recovery;
    request->post_effect_record = post_effect;
    request->source_was_burned = source_was_burned ? 1U : 0U;
    return 1;
}

static int
aqt_issuer_choreography_controller_durability_selected_records_proof_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerDurabilityRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int installed,
    const AqtIssuerChoreographyControllerDurabilityBinding *binding
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyRecord *lease = request->lease_record;
    AqtIssuerChoreographyRecord *recovery = request->recovery_record;
    AqtIssuerChoreographyRecord *post_effect = request->post_effect_record;
    AqtIssuerChoreographyRecord *receipt =
        request->controller_receipt_record;
    const AqtIssuerChoreographyStateValue *required =
        installed ? candidate : expected;

    if (cell == NULL || lease == NULL || recovery == NULL
        || post_effect == NULL || receipt == NULL
        || !aqt_issuer_choreography_controller_durability_source_value_is_exact(
            expected
        )
        || (installed
            && !aqt_issuer_choreography_controller_durability_candidate_value_is_exact(
                expected, candidate
            ))
        || memcmp(&state->value, required, sizeof(*required)) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin, sizeof(state->failclosed_origin)
        )
        || !aqt_issuer_choreography_cell_is_exact_locked(shadow)
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != receipt
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            receipt, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        )
        || lease->install_or_terminal_state_revision
            != request->lease_initial_status_revision
        || recovery->install_or_terminal_state_revision
            != request->recovery_initial_status_revision
        || post_effect->install_or_terminal_state_revision
            != request->post_effect_initial_status_revision
        || receipt->prepared_at_revision != expected->revision - 1U) {
        errno = EINVAL;
        return -1;
    }
    if (!installed) {
        if (receipt->status
                != AQT_CHOREOGRAPHY_WITNESS_INSTALLED_PREPARED
            || receipt->install_or_terminal_state_revision
                != request->controller_receipt_initial_status_revision
            || receipt->controller_durability_binding != NULL
            || memcmp(
                &receipt->payload.controller_receipt,
                &expected->controller_receipt,
                sizeof(expected->controller_receipt)
            ) != 0) {
            errno = EINVAL;
            return -1;
        }
        return 0;
    }
    if (binding == NULL
        || receipt->status
            != AQT_CHOREOGRAPHY_WITNESS_INSTALLED_DURABLE
        || receipt->install_or_terminal_state_revision != candidate->revision
        || receipt->controller_durability_binding != binding
        || !aqt_issuer_choreography_controller_durability_binding_matches_record(
            binding, receipt, cell
        )
        || !aqt_issuer_choreography_controller_durability_binding_matches_publications(
            binding,
            expected,
            lease,
            recovery,
            post_effect,
            request->lease_initial_status_revision,
            request->recovery_initial_status_revision,
            request->post_effect_initial_status_revision,
            request->source_lifecycle_revision,
            request->source_was_burned,
            request->source_launch_lease
        )
        || !aqt_issuer_choreography_controller_durability_live_publication_revisions_are_exact(
            binding,
            lease,
            recovery,
            post_effect
        )
        || memcmp(
            &receipt->payload.controller_receipt,
            &candidate->controller_receipt,
            sizeof(candidate->controller_receipt)
        ) != 0
        || memcmp(
            binding->binding_sha256,
            candidate->controller_receipt.durability_binding_sha256,
            sizeof(binding->binding_sha256)
        ) != 0) {
        errno = EINVAL;
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_controller_durability_authority_proof_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerDurabilityRequest *request,
    AqtIssuerControllerDurabilityScratch *scratch,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int installed,
    const AqtIssuerChoreographyControllerDurabilityBinding *binding,
    unsigned int *authority_proof_failed
)
{
    if (aqt_issuer_choreography_controller_durability_selected_records_proof_locked(
            shadow, request, expected, candidate, installed, binding
        ) < 0) {
        errno = EIO;
        *authority_proof_failed = 1U;
        return -1;
    }
    if (request->source_was_burned) {
        if (shadow->projection != request->source_projection
            || !aqt_issuer_projection_is_roots_only(shadow->projection)) {
            errno = EIO;
            *authority_proof_failed = 1U;
            return -1;
        }
    }
    else if (aqt_issuer_choreography_controller_durability_external_projection_proof(
            shadow->projection
        ) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    if (aqt_issuer_choreography_controller_durability_launch_lock_proof(
            request,
            scratch,
            expected
        ) < 0) {
        *authority_proof_failed = 1U;
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_controller_durability_binding_initialize_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerDurabilityRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    AqtIssuerChoreographyControllerDurabilityBinding *binding
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    int written;

    memset(binding, 0, sizeof(*binding));
    binding->lifetime_generation = cell->lifetime_generation;
    binding->scope_generation = expected->scope_generation;
    binding->binding_generation = expected->binding_generation;
    binding->prepared_state_revision = expected->revision;
    binding->phase = expected->phase;
    binding->last_monotonic_ns = expected->last_monotonic_ns;
    binding->started_monotonic_ns = expected->started_monotonic_ns;
    binding->action_deadline_monotonic_ns =
        expected->action_deadline_monotonic_ns;
    binding->retention_deadline_monotonic_ns =
        expected->retention_deadline_monotonic_ns;
    binding->action_active = expected->action_active;
    binding->roots_are_present = expected->roots_are_present;
    binding->source_lifecycle_revision = request->source_lifecycle_revision;
    binding->source_cell_disposition = cell->lifecycle_disposition;
    binding->source_action_live = cell->action_live;
    binding->lease_key = request->lease_record->key;
    binding->recovery_key = request->recovery_record->key;
    binding->post_effect_key = request->post_effect_record->key;
    binding->lease_initial_status_revision =
        request->lease_initial_status_revision;
    binding->recovery_initial_status_revision =
        request->recovery_initial_status_revision;
    binding->post_effect_initial_status_revision =
        request->post_effect_initial_status_revision;
    binding->controller_receipt_prepared_at_revision =
        request->controller_receipt_record->prepared_at_revision;
    binding->controller_receipt_installed_prepared_revision =
        request->controller_receipt_initial_status_revision;
    binding->prepared_receipt = expected->controller_receipt;
    memcpy(
        binding->artifact_directory,
        expected->artifact_directory,
        expected->artifact_directory_length + 1U
    );
    binding->artifact_directory_length = expected->artifact_directory_length;
    memcpy(
        binding->ignored_root,
        expected->ignored_root,
        expected->ignored_root_length + 1U
    );
    binding->ignored_root_length = expected->ignored_root_length;
    written = snprintf(
        binding->outcome_basename,
        sizeof(binding->outcome_basename),
        AQT_ISSUER_CONTROLLER_DURABILITY_OUTCOME_PREFIX "%s"
            AQT_ISSUER_CONTROLLER_DURABILITY_OUTCOME_SUFFIX,
        expected->controller_receipt.projection.outcome_sha256
    );
    if (written <= 0
        || (size_t)written >= sizeof(binding->outcome_basename)) {
        errno = EOVERFLOW;
        return -1;
    }
    binding->outcome_basename_length = (size_t)written;
    return 0;
}

static void
aqt_issuer_choreography_publish_controller_durability_candidate_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerDurabilityRequest *request,
    const AqtIssuerChoreographyStateValue *candidate,
    AqtIssuerChoreographyControllerDurabilityBinding **binding
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyRecord *receipt =
        request->controller_receipt_record;

    if (*binding == NULL || receipt->controller_durability_binding != NULL
        || !aqt_issuer_choreography_controller_durability_candidate_value_is_exact(
            &shadow->choreography_state.value, candidate
        )) {
        abort();
    }
    receipt->controller_durability_binding = *binding;
    *binding = NULL;
    receipt->payload.controller_receipt = candidate->controller_receipt;
    receipt->status = AQT_CHOREOGRAPHY_WITNESS_INSTALLED_DURABLE;
    receipt->install_or_terminal_state_revision = candidate->revision;
    shadow->choreography_state.value = *candidate;
    cell->persistent_state_revision = candidate->revision;
}

static int
aqt_issuer_choreography_controller_durability_cleanup_reconcile_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerDurabilityRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyStateValue *candidate,
    int candidate_was_stored,
    int safe,
    AqtIssuerActivationProjection **prepared_roots,
    AqtIssuerActivationProjection **detached_projection,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyStateValue target;
    AqtIssuerChoreographyFailclosedOrigin origin;
    size_t index;

    aqt_issuer_choreography_build_controller_durability_cleanup_target_locked(
        expected,
        candidate,
        candidate_was_stored,
        safe,
        &target
    );
    aqt_issuer_choreography_build_controller_durability_failclosed_origin(
        expected,
        candidate,
        candidate_was_stored,
        safe,
        &target,
        &origin
    );
    if (memcmp(&state->value, &target, sizeof(target)) == 0
        && memcmp(&state->failclosed_origin, &origin, sizeof(origin)) == 0) {
        return aqt_issuer_choreography_controller_durability_failclosed_origin_is_exact_locked(
                state
            )
            && aqt_issuer_choreography_cell_is_exact_locked(shadow);
    }
    if (safe) {
        if (!candidate_was_stored
            || memcmp(&state->value, candidate, sizeof(*candidate)) != 0
            || request->controller_receipt_record->status
                != AQT_CHOREOGRAPHY_WITNESS_INSTALLED_DURABLE) {
            return 0;
        }
        state->value = target;
        state->failclosed_origin = origin;
        cell->persistent_state_revision = target.revision;
        return aqt_issuer_choreography_controller_durability_failclosed_origin_is_exact_locked(
                state
            )
            && aqt_issuer_choreography_cell_is_exact_locked(shadow);
    }
    if (memcmp(
            &state->value,
            candidate_was_stored ? candidate : expected,
            sizeof(state->value)
        ) != 0) {
        return 0;
    }
    for (index = 0U;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        AqtIssuerChoreographyRecord *record = state->authority_records[index];
        if (record != NULL) {
            aqt_issuer_choreography_detached_record_append_locked(
                detached, record
            );
            state->authority_records[index] = NULL;
        }
    }
    if (state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != request->controller_receipt_record) {
        return 0;
    }
    aqt_issuer_choreography_detached_record_append_locked(
        detached, request->controller_receipt_record
    );
    state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
    ] = NULL;
    request->lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    request->recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    request->post_effect_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    request->controller_receipt_record->status =
        AQT_CHOREOGRAPHY_WITNESS_CLEARED;
    request->lease_record->install_or_terminal_state_revision = target.revision;
    request->recovery_record->install_or_terminal_state_revision =
        target.revision;
    request->post_effect_record->install_or_terminal_state_revision =
        target.revision;
    request->controller_receipt_record->install_or_terminal_state_revision =
        target.revision;
    state->value = target;
    state->failclosed_origin = origin;
    cell->persistent_state_revision = target.revision;
    if (!request->source_was_burned) {
        aqt_issuer_choreography_recovery_burn_locked(
            shadow, prepared_roots, detached_projection
        );
    }
    return aqt_issuer_choreography_controller_durability_failclosed_origin_is_exact_locked(
            state
        )
        && aqt_issuer_choreography_cell_is_exact_locked(shadow);
}

static int
aqt_issuer_choreography_controller_durability_cleanup_reproof_should_run(
    int candidate_was_stored,
    const AqtIssuerChoreographyControllerDurabilityRequest *request
)
{
    return candidate_was_stored
        && request != NULL
        && request->terminal_reproof_attempted == 0U
        && request->cleanup_reproof_attempted == 0U;
}

static int
aqt_issuer_choreography_controller_durability_cached_cleanup_is_safe(
    int candidate_was_stored,
    const AqtIssuerChoreographyControllerDurabilityRequest *request
)
{
    return candidate_was_stored
        && request != NULL
        && ((request->terminal_reproof_attempted == 1U
                && request->terminal_reproof_completed == 1U)
            || (request->cleanup_reproof_attempted == 1U
                && request->cleanup_reproof_completed == 1U));
}

static int
aqt_issuer_choreography_controller_durability_cleanup_fault_occurrence_is_reachable(
    unsigned int occurrence
)
{
    return occurrence >= 1U && occurrence <= 4U;
}

static PyObject *
aqt_issuer_choreography_controller_durability_transition(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerDurabilityRequest *request
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerChoreographyControllerDurabilityBinding *binding = NULL;
    AqtIssuerControllerDurabilityScratch *scratch = NULL;
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerFailure failure = {0};
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int saved_errno = 0;
    int cleanup_proof_errno = 0;
    int candidate_was_stored = 0;
    int safe_cleanup = 0;
    int plan_began = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int fork_commit_completed = 0;
    int index;

    memset(&expected, 0, sizeof(expected));
    memset(&candidate, 0, sizeof(candidate));
    if (module_state == NULL || request == NULL) {
        return NULL;
    }
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        return NULL;
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        PyErr_Clear();
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller durability attestation is unavailable"
        );
    }
    if (shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY) {
        prepared_roots = aqt_clone_issuer_roots_projection(shadow->projection);
        if (prepared_roots == NULL) {
            return NULL;
        }
    }
    binding = PyMem_Calloc(1U, sizeof(*binding));
    scratch = PyMem_Calloc(1U, sizeof(*scratch));
    if (binding == NULL || scratch == NULL) {
        PyErr_NoMemory();
        goto pre_latch_cleanup;
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_controller_durability_source_is_exact_locked(
            shadow, request, current_thread, current_thread_id
        )
        || (!request->source_was_burned && prepared_roots == NULL)) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography controller durability attestation is unavailable"
        );
        goto pre_latch_cleanup;
    }
    expected = shadow->choreography_state.value;
    request->source_lifecycle_revision = shadow->revision;
    request->source_projection = shadow->projection;
    request->source_launch_lease = shadow->launch_lease;
    request->lease_initial_status_revision =
        request->lease_record->install_or_terminal_state_revision;
    request->recovery_initial_status_revision =
        request->recovery_record->install_or_terminal_state_revision;
    request->post_effect_initial_status_revision =
        request->post_effect_record->install_or_terminal_state_revision;
    request->controller_receipt_initial_status_revision =
        request->controller_receipt_record
            ->install_or_terminal_state_revision;
    if (fault_plan->row_count != 0 && fault_plan->group == 3
        && atomic_load_explicit(
            &aqt_active_issuer_foreign_fork_plan,
            memory_order_acquire
        ) != NULL) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography controller durability fault and fork plans conflict"
        );
        goto pre_latch_cleanup;
    }
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            AQT_CHOREOGRAPHY_OPERATION_ATTEST_CONTROLLER_DURABLE,
            expected.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography controller durability attestation is unavailable"
        );
        goto pre_latch_cleanup;
    }
    plan_began = 1;
    if (aqt_issuer_choreography_controller_durability_authority_proof_locked(
            shadow,
            request,
            scratch,
            &expected,
            NULL,
            0,
            NULL,
            &request->authority_proof_failed
        ) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
        request->durability_proof_failed = 1U;
    }
    if (saved_errno == 0
        && aqt_issuer_choreography_controller_durability_binding_initialize_locked(
            shadow, request, &expected, binding
        ) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
        request->durability_proof_failed = 1U;
    }
    if (saved_errno == 0
        && aqt_issuer_choreography_controller_durability_capture_locked(
            request,
            scratch,
            binding,
            AQT_ISSUER_CONTROLLER_DURABILITY_CAPTURE_PREPARED
        ) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
        request->durability_proof_failed = 1U;
    }
    if (saved_errno == 0) {
        aqt_run_issuer_external_projection_barrier(module_state);
        if (aqt_issuer_choreography_controller_durability_authority_proof_locked(
                shadow,
                request,
                scratch,
                &expected,
                NULL,
                0,
                NULL,
                &request->authority_proof_failed
            ) < 0) {
            saved_errno = errno != 0 ? errno : EIO;
            request->durability_proof_failed = 1U;
        }
    }
    if (saved_errno == 0
        && aqt_issuer_choreography_controller_durability_capture_locked(
            request,
            scratch,
            binding,
            AQT_ISSUER_CONTROLLER_DURABILITY_CAPTURE_DURABLE
        ) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
        request->durability_proof_failed = 1U;
    }
    if (saved_errno == 0
        && aqt_issuer_choreography_controller_durability_binding_sha256(
            binding, binding->binding_sha256
        ) < 0) {
        saved_errno = errno != 0 ? errno : EIO;
        request->durability_proof_failed = 1U;
    }
    if (saved_errno == 0
        && (!aqt_issuer_choreography_controller_durability_binding_is_exact(
                binding
            )
            || !aqt_issuer_choreography_controller_durability_binding_matches_publications(
                binding,
                &expected,
                request->lease_record,
                request->recovery_record,
                request->post_effect_record,
                request->lease_initial_status_revision,
                request->recovery_initial_status_revision,
                request->post_effect_initial_status_revision,
                request->source_lifecycle_revision,
                request->source_was_burned,
                request->source_launch_lease
            )
            || !aqt_issuer_choreography_controller_durability_live_publication_revisions_are_exact(
                binding,
                request->lease_record,
                request->recovery_record,
                request->post_effect_record
            ))) {
        saved_errno = EIO;
        request->durability_proof_failed = 1U;
    }
    if (saved_errno == 0) {
        aqt_issuer_choreography_build_controller_durable_candidate_locked(
            &expected, binding->binding_sha256, &candidate
        );
        if (!aqt_issuer_choreography_controller_durability_candidate_value_is_exact(
                &expected, &candidate
            )) {
            abort();
        }
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && saved_errno == 0) {
        aqt_issuer_choreography_publish_controller_durability_candidate_locked(
            shadow, request, &candidate, &binding
        );
        candidate_was_stored = 1;
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_controller_durability_locked(
                shadow,
                &expected,
                &candidate,
                1,
                request
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = 1;
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
            aqt_unlock_owner_list_or_fail_stop();
            if (aqt_issuer_foreign_fork_wait_for_value(
                    &module_state->issuer_foreign_fork_plan.worker_completed,
                    1
                ) < 0) {
                aqt_fail_stop(
                    "native issuer controller durability foreign-fork worker timed out"
                );
            }
            aqt_lock_owner_list_or_fail_stop();
            if (memcmp(
                    &shadow->choreography_state.value,
                    &candidate,
                    sizeof(candidate)
                ) != 0
                || request->controller_receipt_record
                    ->controller_durability_binding == NULL
                || memcmp(
                    request->controller_receipt_record
                        ->controller_durability_binding->binding_sha256,
                    candidate.controller_receipt
                        .durability_binding_sha256,
                    sizeof(
                        candidate.controller_receipt
                            .durability_binding_sha256
                    )
                ) != 0) {
                aqt_fail_stop(
                    "native issuer controller durability changed across foreign fork"
                );
            }
        }
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && saved_errno == 0 && candidate_was_stored) {
        request->terminal_reproof_attempted = 1U;
        if (aqt_issuer_choreography_controller_durability_authority_proof_locked(
                shadow,
                request,
                scratch,
                &expected,
                &candidate,
                1,
                request->controller_receipt_record
                    ->controller_durability_binding,
                &request->authority_proof_failed
            ) < 0
            || aqt_issuer_choreography_controller_durability_capture_locked(
                request,
                scratch,
                request->controller_receipt_record
                    ->controller_durability_binding,
                AQT_ISSUER_CONTROLLER_DURABILITY_CAPTURE_TERMINAL
            ) < 0) {
            saved_errno = errno != 0 ? errno : EIO;
            request->durability_proof_failed = 1U;
        }
        else {
            request->terminal_reproof_completed = 1U;
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && request->terminal_reproof_completed) {
        primary_kind = fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ? AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR
            : aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
    }
    if (primary_kind < 0 && saved_errno == 0
        && request->terminal_reproof_completed) {
        if (!aqt_issuer_choreography_cell_is_exact_locked(shadow)
            || request->durability_open_fd_count != 0U) {
            abort();
        }
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        aqt_clear_issuer_external_projection_barrier(module_state);
        aqt_free_issuer_projection(&prepared_roots);
        aqt_free_issuer_projection(&detached_projection);
        aqt_issuer_choreography_detached_records_release(&detached);
        memset(scratch, 0, sizeof(*scratch));
        PyMem_Free(scratch);
        Py_RETURN_NONE;
    }
    if (aqt_issuer_choreography_controller_durability_cleanup_reproof_should_run(
            candidate_was_stored, request
        )) {
        request->cleanup_reproof_attempted = 1U;
        if (aqt_issuer_choreography_controller_durability_authority_proof_locked(
                shadow,
                request,
                scratch,
                &expected,
                &candidate,
                1,
                request->controller_receipt_record
                    ->controller_durability_binding,
                &request->authority_proof_failed
            ) < 0
            || aqt_issuer_choreography_controller_durability_capture_locked(
                request,
                scratch,
                request->controller_receipt_record
                    ->controller_durability_binding,
                AQT_ISSUER_CONTROLLER_DURABILITY_CAPTURE_TERMINAL
            ) < 0) {
            cleanup_proof_errno = errno != 0 ? errno : EIO;
            request->durability_proof_failed = 1U;
        }
        else {
            request->cleanup_reproof_completed = 1U;
        }
    }
    safe_cleanup =
        aqt_issuer_choreography_controller_durability_cached_cleanup_is_safe(
            candidate_was_stored, request
        );
    if (fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
        aqt_issuer_foreign_fork_bind_controller_durability_locked(
            shadow,
            &expected,
            candidate_was_stored ? &candidate : NULL,
            candidate_was_stored,
            request
        );
        if (aqt_issuer_foreign_fork_interpose_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ) < 0) {
            abort();
        }
        fork_was_triggered = 1;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_controller_durability_cleanup_fault_occurrence_is_reachable(
                (unsigned int)index + 1U
            )) {
            abort();
        }
        if (!aqt_issuer_choreography_controller_durability_cleanup_reconcile_locked(
                shadow,
                request,
                &expected,
                &candidate,
                candidate_was_stored,
                safe_cleanup,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography controller durability cleanup attempt failed"
            );
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_controller_durability_cleanup_reconcile_locked(
            shadow,
            request,
            &expected,
            &candidate,
            candidate_was_stored,
            safe_cleanup,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography controller durability cleanup confirmation failed"
        );
    }
    if (fork_was_triggered && !fork_commit_completed) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
        fork_commit_completed = 1;
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered && fork_commit_completed
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed,
            1
        ) < 0) {
        aqt_fail_stop(
            "native issuer controller durability cleanup foreign-fork worker timed out"
        );
    }
    aqt_clear_issuer_external_projection_barrier(module_state);
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    if (binding != NULL) {
        memset(binding, 0, sizeof(*binding));
        PyMem_Free(binding);
        binding = NULL;
    }
    memset(scratch, 0, sizeof(*scratch));
    PyMem_Free(scratch);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    else if (saved_errno != 0) {
        aqt_issuer_failure_record_errno(&failure, saved_errno);
    }
    else if (cleanup_proof_errno != 0) {
        aqt_issuer_failure_record_errno(&failure, cleanup_proof_errno);
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0) {
            aqt_issuer_failure_record_synthetic(
                &failure, cleanup_kinds[index]
            );
        }
    }
    return aqt_issuer_choreography_failure_raise(&failure);

pre_latch_cleanup:
    aqt_free_issuer_projection(&prepared_roots);
    if (binding != NULL) {
        memset(binding, 0, sizeof(*binding));
        PyMem_Free(binding);
    }
    if (scratch != NULL) {
        memset(scratch, 0, sizeof(*scratch));
        PyMem_Free(scratch);
    }
    if (plan_began) {
        abort();
    }
    return NULL;
}

static PyObject *
aqt_issuer_choreography_attest_controller_durable(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerDurabilityRequest *request
)
{
    return aqt_issuer_choreography_controller_durability_transition(
        module, shadow, request
    );
}

static int
aqt_issuer_choreography_controller_abandon_source_is_exact_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerAbandonRequest *request,
    PyThreadState *current_thread,
    uint64_t current_thread_id
)
{
    AqtIssuerChoreographyControllerDurabilityRequest *durability;
    AqtIssuerChoreographyAuthorityCell *cell;
    AqtIssuerChoreographyState *state;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *post_effect;
    AqtIssuerChoreographyRecord *checkpoint;
    AqtIssuerChoreographyRecord *receipt;
    AqtIssuerChoreographyControllerDurabilityBinding *binding;
    AqtIssuerChoreographyStateValue prepared;
    AqtIssuerChoreographyStateValue durable;
    int source_was_burned;

    if (shadow == NULL || request == NULL
        || request->durability.operation_tag
            != AQT_CHOREOGRAPHY_OPERATION_ABANDON_CONTROLLER
        || request->controller_checkpoint_is_present > 1U) {
        return 0;
    }
    durability = &request->durability;
    cell = shadow->choreography_authority_cell;
    state = &shadow->choreography_state;
    post_effect = durability->post_effect_record;
    checkpoint = request->controller_checkpoint_record;
    receipt = durability->controller_receipt_record;
    if (post_effect == NULL || receipt == NULL
        || (request->controller_checkpoint_is_present
            ? checkpoint == NULL : checkpoint != NULL)
        || !aqt_issuer_shadow_invariants_are_exact_locked(shadow)
        || shadow->activation_thread_state != current_thread
        || shadow->activation_thread_id != current_thread_id
        || (shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
            && shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED)
        || shadow->closed != 0U || shadow->busy != 0U
        || shadow->runtime_ready != 0U || shadow->projection == NULL
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || cell == NULL || cell->alive != 1U
        || cell->pending_scope_generation != 0U
        || !shadow->choreography_state_present
        || !aqt_issuer_choreography_controller_abandon_source_value_is_exact(
            &state->value
        )
        || state->value.revision != cell->persistent_state_revision
        || state->value.binding_generation != cell->binding_generation
        || state->value.scope_generation != cell->current_scope_generation
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin, sizeof(state->failclosed_origin)
        )
        || !post_effect->wrapper_live || !post_effect->wrapper_was_created
        || !receipt->wrapper_live || !receipt->wrapper_was_created
        || receipt->status
            != AQT_CHOREOGRAPHY_WITNESS_INSTALLED_DURABLE
        || receipt->prepared_at_revision != state->value.revision - 2U
        || receipt->install_or_terminal_state_revision
            != state->value.revision
        || receipt->controller_durability_binding == NULL
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            receipt,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        )
        || memcmp(
            &receipt->payload.controller_receipt,
            &state->value.controller_receipt,
            sizeof(state->value.controller_receipt)
        ) != 0) {
        return 0;
    }
    source_was_burned = shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED;
    if ((source_was_burned
            && state->value.controller_checkpoint.projection.outcome_kind
                != AQT_CHOREOGRAPHY_OUTCOME_FAILURE)
        || (source_was_burned
            ? (shadow->revision != 4U || shadow->poisoned != 1U
                || !aqt_issuer_projection_is_roots_only(shadow->projection)
                || cell->action_live != 0U
                || cell->lifecycle_disposition
                    != AQT_CHOREOGRAPHY_CELL_BURNED)
            : (shadow->revision != 3U || shadow->poisoned != 0U
                || aqt_issuer_projection_is_roots_only(shadow->projection)
                || cell->action_live != 1U
                || cell->lifecycle_disposition
                    != AQT_CHOREOGRAPHY_CELL_ACTIVE))) {
        return 0;
    }
    lease = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ];
    recovery = state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ];
    if (lease == NULL || recovery == NULL
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] != NULL
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != receipt
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || !aqt_issuer_choreography_record_key_equals(
            &lease->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &recovery->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &post_effect->key,
            &state->value.authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ]
        )) {
        return 0;
    }
    if (request->controller_checkpoint_is_present
        && (!checkpoint->wrapper_live || !checkpoint->wrapper_was_created
            || checkpoint->status
                != AQT_CHOREOGRAPHY_WITNESS_DEPENDENCY_TOMBSTONE
            || checkpoint->install_or_terminal_state_revision
                != state->value.revision - 1U
            || checkpoint->prepared_at_revision
                != state->value.revision - 3U
            || !aqt_issuer_choreography_record_is_exact_locked(
                checkpoint,
                cell,
                AQT_CHOREOGRAPHY_RECORD_WITNESS,
                AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
            )
            || !aqt_issuer_choreography_record_key_equals(
                &checkpoint->key,
                &state->value.controller_checkpoint.key
            )
            || memcmp(
                &checkpoint->payload.controller_checkpoint,
                &state->value.controller_checkpoint,
                sizeof(state->value.controller_checkpoint)
            ) != 0)) {
        return 0;
    }
    binding = receipt->controller_durability_binding;
    aqt_issuer_choreography_controller_durability_binding_source_value(
        binding,
        &prepared
    );
    aqt_issuer_choreography_build_controller_durable_candidate_locked(
        &prepared,
        binding->binding_sha256,
        &durable
    );
    if (!aqt_issuer_choreography_controller_durability_binding_is_exact(
            binding
        )
        || !aqt_issuer_choreography_controller_durability_binding_matches_record(
            binding,
            receipt,
            cell
        )
        || prepared.revision != state->value.revision - 1U
        || memcmp(&durable, &state->value, sizeof(durable)) != 0
        || !aqt_issuer_choreography_controller_durability_binding_matches_publications(
            binding,
            &prepared,
            lease,
            recovery,
            post_effect,
            binding->lease_initial_status_revision,
            binding->recovery_initial_status_revision,
            binding->post_effect_initial_status_revision,
            binding->source_lifecycle_revision,
            source_was_burned ? 1U : 0U,
            shadow->launch_lease
        )
        || !aqt_issuer_choreography_controller_durability_live_publication_revisions_are_exact(
            binding,
            lease,
            recovery,
            post_effect
        )) {
        return 0;
    }
    durability->lease_record = lease;
    durability->recovery_record = recovery;
    durability->source_was_burned = source_was_burned ? 1U : 0U;
    durability->lease_initial_status_revision =
        lease->install_or_terminal_state_revision;
    durability->recovery_initial_status_revision =
        recovery->install_or_terminal_state_revision;
    durability->post_effect_initial_status_revision =
        post_effect->install_or_terminal_state_revision;
    durability->controller_receipt_initial_status_revision =
        receipt->install_or_terminal_state_revision;
    durability->source_lifecycle_revision = shadow->revision;
    durability->source_projection = shadow->projection;
    durability->source_launch_lease = shadow->launch_lease;
    request->controller_checkpoint_initial_status_revision =
        request->controller_checkpoint_is_present
            ? checkpoint->install_or_terminal_state_revision : 0U;
    return 1;
}

static int
aqt_issuer_choreography_controller_abandon_selected_records_proof_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerAbandonRequest *request,
    const AqtIssuerChoreographyStateValue *expected
)
{
    const AqtIssuerChoreographyControllerDurabilityRequest *durability;
    AqtIssuerChoreographyAuthorityCell *cell;
    AqtIssuerChoreographyState *state;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *post_effect;
    AqtIssuerChoreographyRecord *checkpoint;
    AqtIssuerChoreographyRecord *receipt;
    AqtIssuerChoreographyControllerDurabilityBinding *binding;
    AqtIssuerChoreographyStateValue prepared;
    AqtIssuerChoreographyStateValue durable;

    if (shadow == NULL || request == NULL || expected == NULL) {
        errno = EIO;
        return -1;
    }
    durability = &request->durability;
    cell = shadow->choreography_authority_cell;
    state = &shadow->choreography_state;
    lease = durability->lease_record;
    recovery = durability->recovery_record;
    post_effect = durability->post_effect_record;
    checkpoint = request->controller_checkpoint_record;
    receipt = durability->controller_receipt_record;
    binding = receipt != NULL
        ? receipt->controller_durability_binding : NULL;
    if (durability->operation_tag
            != AQT_CHOREOGRAPHY_OPERATION_ABANDON_CONTROLLER
        || request->controller_checkpoint_is_present > 1U
        || (request->controller_checkpoint_is_present
            ? checkpoint == NULL : checkpoint != NULL)
        || cell == NULL || lease == NULL || recovery == NULL
        || post_effect == NULL || receipt == NULL || binding == NULL
        || !aqt_issuer_choreography_controller_abandon_source_value_is_exact(
            expected
        )
        || memcmp(&state->value, expected, sizeof(*expected)) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin, sizeof(state->failclosed_origin)
        )
        || !aqt_issuer_choreography_cell_is_exact_locked(shadow)
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != lease
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != recovery
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != post_effect
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_CLAIM_BINDER
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RETAINED_CLAIM
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        ] != NULL
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != receipt
        || !post_effect->wrapper_live || !receipt->wrapper_live
        || !aqt_issuer_choreography_record_is_exact_locked(
            lease, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect, cell, AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            receipt, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        )
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED
        || receipt->status
            != AQT_CHOREOGRAPHY_WITNESS_INSTALLED_DURABLE
        || lease->install_or_terminal_state_revision
            != durability->lease_initial_status_revision
        || recovery->install_or_terminal_state_revision
            != durability->recovery_initial_status_revision
        || post_effect->install_or_terminal_state_revision
            != durability->post_effect_initial_status_revision
        || receipt->install_or_terminal_state_revision
            != durability->controller_receipt_initial_status_revision
        || receipt->install_or_terminal_state_revision != expected->revision
        || receipt->prepared_at_revision != expected->revision - 2U
        || memcmp(
            &receipt->payload.controller_receipt,
            &expected->controller_receipt,
            sizeof(expected->controller_receipt)
        ) != 0
        || durability->source_was_burned > 1U
        || durability->source_lifecycle_revision != shadow->revision
        || durability->source_projection != shadow->projection
        || durability->source_launch_lease != shadow->launch_lease
        || (durability->source_was_burned
            ? (shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED
                || shadow->revision != 4U || shadow->poisoned != 1U
                || cell->lifecycle_disposition
                    != AQT_CHOREOGRAPHY_CELL_BURNED
                || cell->action_live != 0U
                || !aqt_issuer_projection_is_roots_only(shadow->projection)
                || expected->controller_checkpoint.projection.outcome_kind
                    != AQT_CHOREOGRAPHY_OUTCOME_FAILURE)
            : (shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY
                || shadow->revision != 3U || shadow->poisoned != 0U
                || cell->lifecycle_disposition
                    != AQT_CHOREOGRAPHY_CELL_ACTIVE
                || cell->action_live != 1U
                || aqt_issuer_projection_is_roots_only(shadow->projection)))) {
        errno = EIO;
        return -1;
    }
    if (request->controller_checkpoint_is_present
        && (!checkpoint->wrapper_live || !checkpoint->wrapper_was_created
            || !aqt_issuer_choreography_record_is_exact_locked(
                checkpoint, cell, AQT_CHOREOGRAPHY_RECORD_WITNESS,
                AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
            )
            || checkpoint->status
                != AQT_CHOREOGRAPHY_WITNESS_DEPENDENCY_TOMBSTONE
            || checkpoint->install_or_terminal_state_revision
                != request->controller_checkpoint_initial_status_revision
            || checkpoint->install_or_terminal_state_revision
                != expected->revision - 1U
            || checkpoint->prepared_at_revision != expected->revision - 3U
            || !aqt_issuer_choreography_record_key_equals(
                &checkpoint->key, &expected->controller_checkpoint.key
            )
            || memcmp(
                &checkpoint->payload.controller_checkpoint,
                &expected->controller_checkpoint,
                sizeof(expected->controller_checkpoint)
            ) != 0)) {
        errno = EIO;
        return -1;
    }
    aqt_issuer_choreography_controller_durability_binding_source_value(
        binding, &prepared
    );
    aqt_issuer_choreography_build_controller_durable_candidate_locked(
        &prepared, binding->binding_sha256, &durable
    );
    if (!aqt_issuer_choreography_controller_durability_binding_is_exact(
            binding
        )
        || !aqt_issuer_choreography_controller_durability_binding_matches_record(
            binding, receipt, cell
        )
        || prepared.revision != expected->revision - 1U
        || memcmp(&durable, expected, sizeof(durable)) != 0
        || !aqt_issuer_choreography_controller_durability_binding_matches_publications(
            binding,
            &prepared,
            lease,
            recovery,
            post_effect,
            durability->lease_initial_status_revision,
            durability->recovery_initial_status_revision,
            durability->post_effect_initial_status_revision,
            durability->source_lifecycle_revision,
            durability->source_was_burned,
            durability->source_launch_lease
        )
        || !aqt_issuer_choreography_controller_durability_live_publication_revisions_are_exact(
            binding, lease, recovery, post_effect
        )) {
        errno = EIO;
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_controller_abandon_current_proof_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerAbandonRequest *request,
    AqtIssuerControllerDurabilityScratch *scratch,
    const AqtIssuerChoreographyStateValue *expected,
    int terminal
)
{
    AqtIssuerChoreographyControllerDurabilityRequest *durability =
        &request->durability;
    AqtIssuerChoreographyControllerDurabilityBinding *binding = durability
        ->controller_receipt_record->controller_durability_binding;

    if (aqt_issuer_choreography_controller_abandon_selected_records_proof_locked(
            shadow, request, expected
        ) < 0) {
        errno = EIO;
        durability->authority_proof_failed = 1U;
        durability->durability_proof_failed = 1U;
        return -1;
    }
    if (durability->source_was_burned) {
        if (shadow->projection != durability->source_projection
            || !aqt_issuer_projection_is_roots_only(shadow->projection)) {
            errno = EIO;
            durability->authority_proof_failed = 1U;
            durability->durability_proof_failed = 1U;
            return -1;
        }
    }
    else if (aqt_issuer_choreography_controller_durability_external_projection_proof(
            shadow->projection
        ) < 0) {
        durability->authority_proof_failed = 1U;
        durability->durability_proof_failed = 1U;
        return -1;
    }
    if (aqt_issuer_choreography_controller_durability_launch_lock_proof(
            durability, scratch, expected
        ) < 0) {
        durability->authority_proof_failed = 1U;
        durability->durability_proof_failed = 1U;
        return -1;
    }
    if (!terminal) {
        return 0;
    }
    if (aqt_issuer_choreography_controller_durability_capture_locked(
            durability,
            scratch,
            binding,
            AQT_ISSUER_CONTROLLER_DURABILITY_CAPTURE_TERMINAL
        ) < 0) {
        durability->durability_proof_failed = 1U;
        return -1;
    }
    if (aqt_issuer_choreography_controller_abandon_selected_records_proof_locked(
            shadow, request, expected
        ) < 0) {
        errno = EIO;
        durability->authority_proof_failed = 1U;
        durability->durability_proof_failed = 1U;
        return -1;
    }
    return 0;
}

static int
aqt_issuer_choreography_controller_abandon_projection_roots_are_exact(
    const AqtIssuerActivationProjection *source,
    const AqtIssuerActivationProjection *roots
)
{
    return source != NULL && roots != NULL
        && source->ignored_root != NULL
        && source->artifact_directory != NULL
        && roots->ignored_root != NULL
        && roots->artifact_directory != NULL
        && source->ignored_root_length == roots->ignored_root_length
        && source->artifact_directory_length
            == roots->artifact_directory_length
        && source->ignored_root_length > 0U
        && source->artifact_directory_length > 0U
        && source->ignored_root[source->ignored_root_length] == '\0'
        && roots->ignored_root[roots->ignored_root_length] == '\0'
        && source->artifact_directory[
            source->artifact_directory_length
        ] == '\0'
        && roots->artifact_directory[roots->artifact_directory_length] == '\0'
        && memcmp(
            source->ignored_root,
            roots->ignored_root,
            source->ignored_root_length
        ) == 0
        && memcmp(
            source->artifact_directory,
            roots->artifact_directory,
            source->artifact_directory_length
        ) == 0;
}

static int
aqt_issuer_choreography_controller_abandon_hard_lifecycle_is_exact_locked(
    const AqtTopologyObservationIssuerShadow *shadow,
    const AqtIssuerChoreographyControllerAbandonRequest *request,
    AqtIssuerActivationProjection *const *prepared_roots,
    AqtIssuerActivationProjection *const *detached_projection
)
{
    const AqtIssuerChoreographyControllerDurabilityRequest *durability;
    const AqtIssuerChoreographyAuthorityCell *cell;

    if (shadow == NULL || request == NULL
        || prepared_roots == NULL || detached_projection == NULL) {
        return 0;
    }
    durability = &request->durability;
    cell = shadow->choreography_authority_cell;
    if (durability->source_was_burned > 1U
        || durability->source_projection == NULL
        || durability->source_launch_lease == NULL
        || durability->source_launch_lease != shadow->launch_lease
        || *prepared_roots != NULL
        || shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED
        || shadow->revision != 4U
        || shadow->poisoned != 1U
        || shadow->closed != 0U
        || shadow->lease_was_closed != 0U
        || !aqt_issuer_projection_is_roots_only(shadow->projection)
        || !aqt_issuer_shadow_has_live_lease_locked(shadow)
        || cell == NULL || cell->alive != 1U
        || cell->action_live != 0U
        || cell->lifecycle_disposition != AQT_CHOREOGRAPHY_CELL_BURNED) {
        return 0;
    }
    if (durability->source_was_burned) {
        return durability->source_lifecycle_revision == 4U
            && durability->source_projection == shadow->projection
            && *detached_projection == NULL
            && aqt_issuer_projection_is_roots_only(
                durability->source_projection
            );
    }
    return durability->source_lifecycle_revision == 3U
        && durability->source_projection != shadow->projection
        && *detached_projection == durability->source_projection
        && !aqt_issuer_projection_is_roots_only(
            durability->source_projection
        )
        && aqt_issuer_choreography_controller_abandon_projection_roots_are_exact(
            durability->source_projection,
            shadow->projection
        );
}

static int
aqt_issuer_choreography_controller_abandon_hard_records_are_exact_locked(
    const AqtIssuerChoreographyControllerAbandonRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    const AqtIssuerChoreographyState *state,
    const AqtIssuerChoreographyAuthorityCell *cell
)
{
    const AqtIssuerChoreographyControllerDurabilityRequest *durability;
    const AqtIssuerChoreographyStateValue *target;
    AqtIssuerChoreographyRecord *lease;
    AqtIssuerChoreographyRecord *recovery;
    AqtIssuerChoreographyRecord *post_effect;
    AqtIssuerChoreographyRecord *checkpoint;
    AqtIssuerChoreographyRecord *receipt;
    AqtIssuerChoreographyControllerDurabilityBinding *binding;
    AqtIssuerChoreographyStateValue prepared;
    AqtIssuerChoreographyStateValue durable;
    size_t index;

    if (request == NULL || expected == NULL || state == NULL || cell == NULL
        || !aqt_issuer_choreography_controller_abandon_source_value_is_exact(
            expected
        )) {
        return 0;
    }
    durability = &request->durability;
    target = &state->value;
    lease = durability->lease_record;
    recovery = durability->recovery_record;
    post_effect = durability->post_effect_record;
    checkpoint = request->controller_checkpoint_record;
    receipt = durability->controller_receipt_record;
    binding = receipt != NULL
        ? receipt->controller_durability_binding : NULL;
    if (lease == NULL || recovery == NULL || post_effect == NULL
        || receipt == NULL || binding == NULL
        || request->controller_checkpoint_is_present > 1U
        || (request->controller_checkpoint_is_present
            ? checkpoint == NULL : checkpoint != NULL)
        || target->revision != expected->revision + 1U
        || cell->persistent_state_revision != target->revision) {
        return 0;
    }
    for (index = 0U;
         index < AQT_ISSUER_CHOREOGRAPHY_AUTHORITY_KIND_COUNT;
         index++) {
        if (state->authority_records[index] != NULL) {
            return 0;
        }
    }
    for (index = 0U;
         index < AQT_ISSUER_CHOREOGRAPHY_WITNESS_KIND_COUNT;
         index++) {
        if (state->witness_records[index] != NULL) {
            return 0;
        }
    }
    if (!aqt_issuer_choreography_record_is_exact_locked(
            lease,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            recovery,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            post_effect,
            cell,
            AQT_CHOREOGRAPHY_RECORD_AUTHORITY,
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        )
        || !aqt_issuer_choreography_record_is_exact_locked(
            receipt,
            cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        )
        || lease->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || recovery->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || post_effect->status != AQT_CHOREOGRAPHY_AUTHORITY_REVOKED
        || receipt->status != AQT_CHOREOGRAPHY_WITNESS_CLEARED
        || lease->install_or_terminal_state_revision != target->revision
        || recovery->install_or_terminal_state_revision != target->revision
        || post_effect->install_or_terminal_state_revision != target->revision
        || receipt->install_or_terminal_state_revision != target->revision
        || receipt->prepared_at_revision != expected->revision - 2U
        || !aqt_issuer_choreography_record_key_equals(
            &lease->key,
            &expected->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &recovery->key,
            &expected->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
            ]
        )
        || !aqt_issuer_choreography_record_key_equals(
            &post_effect->key,
            &expected->authority_keys[
                AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
            ]
        )
        || aqt_issuer_choreography_memory_is_zero(
            &lease->payload, sizeof(lease->payload)
        ) == 0
        || aqt_issuer_choreography_memory_is_zero(
            &recovery->payload, sizeof(recovery->payload)
        ) == 0
        || aqt_issuer_choreography_memory_is_zero(
            &post_effect->payload, sizeof(post_effect->payload)
        ) == 0
        || memcmp(
            &receipt->payload.controller_receipt,
            &expected->controller_receipt,
            sizeof(expected->controller_receipt)
        ) != 0
        || !aqt_issuer_choreography_controller_durability_binding_is_exact(
            binding
        )
        || !aqt_issuer_choreography_controller_durability_binding_matches_record(
            binding, receipt, cell
        )) {
        return 0;
    }
    if (request->controller_checkpoint_is_present
        && (!checkpoint->wrapper_live || !checkpoint->wrapper_was_created
            || !aqt_issuer_choreography_record_is_exact_locked(
                checkpoint,
                cell,
                AQT_CHOREOGRAPHY_RECORD_WITNESS,
                AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
            )
            || checkpoint->status
                != AQT_CHOREOGRAPHY_WITNESS_DEPENDENCY_TOMBSTONE
            || checkpoint->prepared_at_revision != expected->revision - 3U
            || checkpoint->install_or_terminal_state_revision
                != expected->revision - 1U
            || request->controller_checkpoint_initial_status_revision
                != expected->revision - 1U
            || !aqt_issuer_choreography_record_key_equals(
                &checkpoint->key, &expected->controller_checkpoint.key
            )
            || memcmp(
                &checkpoint->payload.controller_checkpoint,
                &expected->controller_checkpoint,
                sizeof(expected->controller_checkpoint)
            ) != 0)) {
        return 0;
    }
    aqt_issuer_choreography_controller_durability_binding_source_value(
        binding, &prepared
    );
    aqt_issuer_choreography_build_controller_durable_candidate_locked(
        &prepared, binding->binding_sha256, &durable
    );
    return prepared.revision == expected->revision - 1U
        && memcmp(&durable, expected, sizeof(durable)) == 0
        && aqt_issuer_choreography_controller_durability_binding_matches_publications(
            binding,
            &prepared,
            lease,
            recovery,
            post_effect,
            durability->lease_initial_status_revision,
            durability->recovery_initial_status_revision,
            durability->post_effect_initial_status_revision,
            durability->source_lifecycle_revision,
            durability->source_was_burned,
            durability->source_launch_lease
        );
}

static int
aqt_issuer_choreography_controller_abandon_cleanup_reconcile_locked(
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerAbandonRequest *request,
    const AqtIssuerChoreographyStateValue *expected,
    int safe,
    AqtIssuerActivationProjection **prepared_roots,
    AqtIssuerActivationProjection **detached_projection,
    AqtIssuerChoreographyDetachedRecords *detached
)
{
    AqtIssuerChoreographyControllerDurabilityRequest *durability =
        &request->durability;
    AqtIssuerChoreographyAuthorityCell *cell =
        shadow->choreography_authority_cell;
    AqtIssuerChoreographyState *state = &shadow->choreography_state;
    AqtIssuerChoreographyStateValue target;
    AqtIssuerChoreographyFailclosedOrigin origin;
    AqtIssuerChoreographyRecord *records[4] = {
        durability->lease_record,
        durability->recovery_record,
        durability->post_effect_record,
        durability->controller_receipt_record,
    };
    size_t index;

    if (safe) {
        return memcmp(&state->value, expected, sizeof(*expected)) == 0
            && aqt_issuer_choreography_memory_is_zero(
                &state->failclosed_origin, sizeof(state->failclosed_origin)
            )
            && aqt_issuer_choreography_controller_abandon_selected_records_proof_locked(
                shadow, request, expected
            ) == 0;
    }
    aqt_issuer_choreography_build_controller_abandon_failclosed_target_locked(
        expected, &target
    );
    aqt_issuer_choreography_build_controller_abandon_failclosed_origin(
        expected, &target, &origin
    );
    if (memcmp(&state->value, &target, sizeof(target)) == 0
        && memcmp(&state->failclosed_origin, &origin, sizeof(origin)) == 0) {
        return aqt_issuer_choreography_controller_abandon_failclosed_origin_is_exact_locked(
                state
            )
            && aqt_issuer_choreography_cell_is_exact_locked(shadow)
            && aqt_issuer_choreography_controller_abandon_hard_lifecycle_is_exact_locked(
                shadow,
                request,
                prepared_roots,
                detached_projection
            )
            && aqt_issuer_choreography_controller_abandon_hard_records_are_exact_locked(
                request, expected, state, cell
            );
    }
    if (memcmp(&state->value, expected, sizeof(*expected)) != 0
        || !aqt_issuer_choreography_memory_is_zero(
            &state->failclosed_origin, sizeof(state->failclosed_origin)
        )
        || !aqt_issuer_choreography_controller_abandon_latched_lineage_is_exact_locked(
            shadow, request, expected
        )
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
        ] != records[0]
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
        ] != records[1]
        || state->authority_records[
            AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
        ] != records[2]
        || state->witness_records[
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
        ] != records[3]) {
        return 0;
    }
    for (index = 0U; index < 3U; index++) {
        aqt_issuer_choreography_detached_record_append_locked(
            detached, records[index]
        );
    }
    aqt_issuer_choreography_detached_record_append_locked(
        detached, records[3]
    );
    state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_CHOREOGRAPHY_LEASE
    ] = NULL;
    state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_RECOVERY_RETENTION_CAPABILITY
    ] = NULL;
    state->authority_records[
        AQT_CHOREOGRAPHY_AUTHORITY_POST_EFFECT_OUTCOME_CAPABILITY
    ] = NULL;
    state->witness_records[
        AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_RECEIPT
    ] = NULL;
    records[0]->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    records[1]->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    records[2]->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;
    records[3]->status = AQT_CHOREOGRAPHY_WITNESS_CLEARED;
    for (index = 0U; index < 4U; index++) {
        records[index]->install_or_terminal_state_revision = target.revision;
    }
    state->value = target;
    state->failclosed_origin = origin;
    cell->persistent_state_revision = target.revision;
    if (!durability->source_was_burned) {
        aqt_issuer_choreography_recovery_burn_locked(
            shadow, prepared_roots, detached_projection
        );
    }
    return aqt_issuer_choreography_controller_abandon_cleanup_reconcile_locked(
        shadow,
        request,
        expected,
        0,
        prepared_roots,
        detached_projection,
        detached
    );
}

static int
aqt_issuer_choreography_controller_abandon_cleanup_reproof_should_run(
    const AqtIssuerChoreographyControllerAbandonRequest *request
)
{
    return request != NULL
        && request->durability.terminal_reproof_attempted == 0U
        && request->durability.cleanup_reproof_attempted == 0U;
}

static int
aqt_issuer_choreography_controller_abandon_cached_cleanup_is_safe(
    const AqtIssuerChoreographyControllerAbandonRequest *request
)
{
    return request != NULL
        && ((request->durability.terminal_reproof_attempted == 1U
                && request->durability.terminal_reproof_completed == 1U)
            || (request->durability.cleanup_reproof_attempted == 1U
                && request->durability.cleanup_reproof_completed == 1U));
}

static PyObject *
aqt_issuer_choreography_controller_abandon_transition(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerAbandonRequest *request
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerChoreographyControllerDurabilityRequest *durability;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerControllerDurabilityScratch *scratch = NULL;
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerFailure failure = {0};
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int ordinary_proof_errno = 0;
    int initial_proof_completed = 0;
    int logical_selection = 0;
    int safe_cleanup = 0;
    int plan_began = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int fork_commit_completed = 0;
    int index;

    memset(&expected, 0, sizeof(expected));
    if (module_state == NULL || request == NULL) {
        return NULL;
    }
    durability = &request->durability;
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        PyErr_Clear();
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller outcome retention abandonment is unavailable"
        );
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        PyErr_Clear();
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography controller outcome retention abandonment is unavailable"
        );
    }
    if (shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY) {
        prepared_roots = aqt_clone_issuer_roots_projection(shadow->projection);
        if (prepared_roots == NULL) {
            return NULL;
        }
    }
    scratch = PyMem_Calloc(1U, sizeof(*scratch));
    if (scratch == NULL) {
        PyErr_NoMemory();
        goto pre_latch_cleanup;
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_controller_abandon_source_is_exact_locked(
            shadow, request, current_thread, current_thread_id
        )
        || (!durability->source_was_burned && prepared_roots == NULL)) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography controller outcome retention abandonment is unavailable"
        );
        goto pre_latch_cleanup;
    }
    expected = shadow->choreography_state.value;
    if ((fault_plan->row_count != 0 && fault_plan->group == 3
            && atomic_load_explicit(
                &aqt_active_issuer_foreign_fork_plan,
                memory_order_acquire
            ) != NULL)
        || atomic_load_explicit(
            &module_state->issuer_external_projection_barrier,
            memory_order_acquire
        ) != 0U) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography controller outcome retention abandonment is unavailable"
        );
        goto pre_latch_cleanup;
    }
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            AQT_CHOREOGRAPHY_OPERATION_ABANDON_CONTROLLER,
            expected.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography controller outcome retention abandonment is unavailable"
        );
        goto pre_latch_cleanup;
    }
    plan_began = 1;
    if (aqt_issuer_choreography_controller_abandon_current_proof_locked(
            shadow, request, scratch, &expected, 0
        ) < 0) {
        ordinary_proof_errno = errno != 0 ? errno : EIO;
    }
    else {
        initial_proof_completed = 1;
    }
    if (durability->durability_open_fd_count != 0U) {
        abort();
    }
    if (ordinary_proof_errno == 0) {
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && ordinary_proof_errno == 0) {
        logical_selection = 1;
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_controller_abandon_locked(
                shadow, &expected, request
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = 1;
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
            aqt_unlock_owner_list_or_fail_stop();
            if (aqt_issuer_foreign_fork_wait_for_value(
                    &module_state->issuer_foreign_fork_plan.worker_completed,
                    1
                ) < 0) {
                aqt_fail_stop(
                    "native issuer controller abandonment foreign-fork worker timed out"
                );
            }
            aqt_lock_owner_list_or_fail_stop();
            if (aqt_issuer_choreography_controller_abandon_selected_records_proof_locked(
                    shadow, request, &expected
                ) < 0
                || durability->durability_open_fd_count != 0U) {
                aqt_fail_stop(
                    "native issuer controller abandonment changed across foreign fork"
                );
            }
        }
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && ordinary_proof_errno == 0
        && logical_selection) {
        durability->terminal_reproof_attempted = 1U;
        if (aqt_issuer_choreography_controller_abandon_current_proof_locked(
                shadow, request, scratch, &expected, 1
            ) < 0) {
            ordinary_proof_errno = errno != 0 ? errno : EIO;
        }
        else {
            durability->terminal_reproof_completed = 1U;
        }
    }
    if (primary_kind < 0 && ordinary_proof_errno == 0
        && durability->terminal_reproof_completed) {
        primary_kind = fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ? AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR
            : aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
    }
    if (primary_kind < 0 && ordinary_proof_errno == 0
        && durability->terminal_reproof_completed) {
        if (aqt_issuer_choreography_controller_abandon_selected_records_proof_locked(
                shadow, request, &expected
            ) < 0) {
            ordinary_proof_errno = EIO;
            durability->terminal_reproof_completed = 0U;
            durability->authority_proof_failed = 1U;
            durability->durability_proof_failed = 1U;
        }
    }
    if (primary_kind < 0 && ordinary_proof_errno == 0
        && durability->terminal_reproof_completed) {
        if (durability->durability_open_fd_count != 0U
            || !aqt_issuer_choreography_cell_is_exact_locked(shadow)) {
            abort();
        }
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        memset(scratch, 0, sizeof(*scratch));
        PyMem_Free(scratch);
        Py_RETURN_NONE;
    }
    if (initial_proof_completed
        && aqt_issuer_choreography_controller_abandon_cleanup_reproof_should_run(
            request
        )) {
        durability->cleanup_reproof_attempted = 1U;
        if (aqt_issuer_choreography_controller_abandon_current_proof_locked(
                shadow, request, scratch, &expected, 1
            ) < 0) {
            ordinary_proof_errno = errno != 0 ? errno : EIO;
        }
        else {
            durability->cleanup_reproof_completed = 1U;
        }
    }
    if (durability->durability_open_fd_count != 0U) {
        abort();
    }
    safe_cleanup =
        aqt_issuer_choreography_controller_abandon_cached_cleanup_is_safe(
            request
        );
    if (fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
        aqt_issuer_foreign_fork_bind_controller_abandon_locked(
            shadow, &expected, request
        );
        if (aqt_issuer_foreign_fork_interpose_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ) < 0) {
            abort();
        }
        fork_was_triggered = 1;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_controller_durability_cleanup_fault_occurrence_is_reachable(
                (unsigned int)index + 1U
            )) {
            abort();
        }
        if (!aqt_issuer_choreography_controller_abandon_cleanup_reconcile_locked(
                shadow,
                request,
                &expected,
                safe_cleanup,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography controller abandonment cleanup attempt failed"
            );
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_controller_abandon_cleanup_reconcile_locked(
            shadow,
            request,
            &expected,
            safe_cleanup,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography controller abandonment cleanup confirmation failed"
        );
    }
    if (fork_was_triggered && !fork_commit_completed) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
        fork_commit_completed = 1;
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered && fork_commit_completed
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed,
            1
        ) < 0) {
        aqt_fail_stop(
            "native issuer controller abandonment cleanup foreign-fork worker timed out"
        );
    }
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    memset(scratch, 0, sizeof(*scratch));
    PyMem_Free(scratch);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0) {
            aqt_issuer_failure_record_synthetic(
                &failure, cleanup_kinds[index]
            );
        }
    }
    if (failure.has_selected) {
        return aqt_issuer_choreography_failure_raise(&failure);
    }
    Py_RETURN_NONE;

pre_latch_cleanup:
    aqt_free_issuer_projection(&prepared_roots);
    if (scratch != NULL) {
        memset(scratch, 0, sizeof(*scratch));
        PyMem_Free(scratch);
    }
    if (plan_began) {
        abort();
    }
    return NULL;
}

static PyObject *
aqt_issuer_choreography_abandon_controller(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyControllerAbandonRequest *request
)
{
    return aqt_issuer_choreography_controller_abandon_transition(
        module, shadow, request
    );
}

static PyObject *
aqt_issuer_choreography_formal_expire_transition(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyFormalExpireRequest *request
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerFailure failure = {0};
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int saved_errno = 0;
    int candidate_was_stored = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int fork_commit_completed = 0;
    int index;

    memset(&expected, 0, sizeof(expected));
    memset(&candidate, 0, sizeof(candidate));
    if (module_state == NULL || shadow == NULL || request == NULL) {
        return NULL;
    }
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        PyErr_Clear();
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography formal expiration is unavailable"
        );
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        PyErr_Clear();
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography formal expiration is unavailable"
        );
    }
    if (shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY) {
        prepared_roots = aqt_clone_issuer_roots_projection(
            shadow->projection
        );
        if (prepared_roots == NULL) {
            return NULL;
        }
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_formal_expire_source_is_exact_locked(
            shadow, request, current_thread, current_thread_id
        )
        || (!request->source_was_burned && prepared_roots == NULL)) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography formal expiration is unavailable"
        );
    }
    expected = shadow->choreography_state.value;
    if ((fault_plan->row_count != 0 && fault_plan->group == 3
            && atomic_load_explicit(
                &aqt_active_issuer_foreign_fork_plan,
                memory_order_acquire
            ) != NULL)
        || atomic_load_explicit(
            &module_state->issuer_external_projection_barrier,
            memory_order_acquire
        ) != 0U) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography formal expiration is unavailable"
        );
    }
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            AQT_CHOREOGRAPHY_OPERATION_FORMAL_EXPIRE,
            expected.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography formal expiration is unavailable"
        );
    }
    if (aqt_issuer_choreography_formal_expire_selected_records_proof_locked(
            shadow, request, &expected
        ) < 0) {
        saved_errno = EIO;
        request->authority_proof_failed = 1U;
    }
    if (saved_errno == 0) {
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && saved_errno == 0) {
        aqt_issuer_choreography_build_formal_expired_candidate_locked(
            &expected, &candidate
        );
        aqt_issuer_choreography_publish_formal_expired_candidate_locked(
            shadow, request, &candidate, &detached
        );
        candidate_was_stored = 1;
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_formal_expire_locked(
                shadow, &expected, &candidate, 1, request
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = 1;
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
            aqt_unlock_owner_list_or_fail_stop();
            if (aqt_issuer_foreign_fork_wait_for_value(
                    &module_state->issuer_foreign_fork_plan.worker_completed,
                    1
                ) < 0) {
                aqt_fail_stop(
                    "native issuer formal expiration foreign-fork worker timed out"
                );
            }
            aqt_lock_owner_list_or_fail_stop();
            if (!aqt_issuer_choreography_formal_expire_normal_is_exact_locked(
                    shadow, request, &expected, &candidate
                )) {
                saved_errno = EIO;
                request->authority_proof_failed = 1U;
            }
        }
        if (saved_errno == 0) {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
                1,
                current_pid,
                current_interpreter
            );
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && candidate_was_stored
        && !aqt_issuer_choreography_formal_expire_normal_is_exact_locked(
            shadow, request, &expected, &candidate
        )) {
        saved_errno = EIO;
        request->authority_proof_failed = 1U;
    }
    if (primary_kind < 0 && saved_errno == 0 && candidate_was_stored) {
        primary_kind = fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ? AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR
            : aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
    }
    if (primary_kind < 0 && saved_errno == 0 && candidate_was_stored) {
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        aqt_issuer_choreography_detached_records_release(&detached);
        Py_RETURN_NONE;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_formal_expire_cleanup_reconcile_locked(
                shadow,
                request,
                &expected,
                &candidate,
                candidate_was_stored,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography formal expiration cleanup attempt failed"
            );
        }
        if (index == 0
            && fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_formal_expire_locked(
                shadow,
                &expected,
                &candidate,
                candidate_was_stored,
                request
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = 1;
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_formal_expire_cleanup_reconcile_locked(
            shadow,
            request,
            &expected,
            &candidate,
            candidate_was_stored,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography formal expiration cleanup confirmation failed"
        );
    }
    if (fork_was_triggered && !fork_commit_completed) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
        fork_commit_completed = 1;
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered && fork_commit_completed
        && fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed, 1
        ) < 0) {
        aqt_fail_stop(
            "native issuer formal expiration cleanup foreign-fork worker timed out"
        );
    }
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    else {
        aqt_issuer_failure_record_errno(
            &failure, saved_errno != 0 ? saved_errno : EIO
        );
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0) {
            aqt_issuer_failure_record_synthetic(
                &failure, cleanup_kinds[index]
            );
        }
    }
    return aqt_issuer_choreography_failure_raise(&failure);
}

