static int
aqt_issuer_choreography_formal_force_revoke_fault_fork_conflict_locked(
    const AqtIssuerChoreographyFaultPlan *fault_plan,
    const AqtIssuerForeignForkPlan *fork_plan
)
{
    return fault_plan != NULL
        && fault_plan->row_count != 0
        && fault_plan->group == 3
        && fork_plan != NULL
        && (fork_plan->point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            || fork_plan->point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT);
}

static PyObject *
aqt_issuer_choreography_formal_force_revoke_transition(
    PyObject *module,
    AqtTopologyObservationIssuerShadow *shadow,
    AqtIssuerChoreographyFormalForceRevokeRequest *request
)
{
    AqtModuleState *module_state = (AqtModuleState *)PyModule_GetState(module);
    AqtIssuerChoreographyFaultPlan *fault_plan;
    AqtIssuerActivationProjection *prepared_roots = NULL;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};
    AqtIssuerChoreographyStateValue expected;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerFailure failure = {0};
    AqtIssuerForeignForkPlan *active_fork_plan;
    PyThreadState *current_thread = PyThreadState_Get();
    PyInterpreterState *current_interpreter = PyInterpreterState_Get();
    uint64_t current_thread_id = PyThreadState_GetID(current_thread);
    pid_t current_pid = getpid();
    int primary_kind = -1;
    int cleanup_kinds[4] = {-1, -1, -1, -1};
    int saved_errno = 0;
    int candidate_was_stored = 0;
    int fork_point = -1;
    int fork_was_triggered = 0;
    int fork_commit_completed = 0;
    int index;

    memset(&expected, 0, sizeof(expected));
    memset(&candidate, 0, sizeof(candidate));
    if (module_state == NULL || shadow == NULL || request == NULL) {
        return NULL;
    }
    if (aqt_issuer_foreign_fork_require_transition_operation(shadow) < 0) {
        PyErr_Clear();
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography formal force revocation is unavailable"
        );
    }
    if (aqt_issuer_shadow_require_identity(shadow) < 0
        || aqt_issuer_shadow_require_activation_thread(shadow) < 0
        || !aqt_issuer_shadow_invariants_are_exact(shadow)) {
        PyErr_Clear();
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography formal force revocation is unavailable"
        );
    }
    if (shadow->state == AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY) {
        prepared_roots = aqt_clone_issuer_roots_projection(
            shadow->projection
        );
        if (prepared_roots == NULL) {
            return NULL;
        }
    }
    fault_plan = &module_state->issuer_choreography_fault_plan;
    aqt_lock_owner_list_or_fail_stop();
    if (!aqt_issuer_choreography_formal_force_revoke_source_is_exact_locked(
            shadow, request, current_thread, current_thread_id
        )
        || (!request->source_was_burned && prepared_roots == NULL)) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography formal force revocation is unavailable"
        );
    }
    expected = shadow->choreography_state.value;
    active_fork_plan = atomic_load_explicit(
        &aqt_active_issuer_foreign_fork_plan,
        memory_order_acquire
    );
    if (aqt_issuer_choreography_formal_force_revoke_fault_fork_conflict_locked(
            fault_plan, active_fork_plan
        )
        || atomic_load_explicit(
            &module_state->issuer_external_projection_barrier,
            memory_order_acquire
        ) != 0U) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography formal force revocation is unavailable"
        );
    }
    fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(
        shadow
    );
    if (aqt_issuer_choreography_fault_plan_begin_locked(
            fault_plan,
            3,
            AQT_CHOREOGRAPHY_OPERATION_FORMAL_FORCE_REVOKE,
            expected.revision,
            shadow,
            current_pid,
            current_interpreter
        ) < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        return aqt_issuer_choreography_runtime_error(
            "native issuer choreography formal force revocation is unavailable"
        );
    }
    if (aqt_issuer_choreography_formal_force_revoke_selected_records_proof_locked(
            shadow, request, &expected
        ) < 0) {
        saved_errno = EIO;
        request->authority_proof_failed = 1U;
    }
    if (saved_errno == 0) {
        primary_kind = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE,
            1,
            current_pid,
            current_interpreter
        );
    }
    if (primary_kind < 0 && saved_errno == 0) {
        aqt_issuer_choreography_build_formal_force_revoked_candidate_locked(
            &expected, &candidate
        );
        aqt_issuer_choreography_publish_formal_force_revoked_candidate_locked(
            shadow, request, &candidate, &detached
        );
        candidate_was_stored = 1;
        if (fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_formal_force_revoke_locked(
                shadow, &expected, &candidate, 1, request
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = 1;
            aqt_issuer_foreign_fork_commit_locked(
                shadow,
                AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
            );
            fork_commit_completed = 1;
            aqt_unlock_owner_list_or_fail_stop();
            if (aqt_issuer_foreign_fork_wait_for_value(
                    &module_state->issuer_foreign_fork_plan.worker_completed,
                    1
                ) < 0) {
                aqt_fail_stop(
                    "native issuer formal force revocation foreign-fork worker timed out"
                );
            }
            aqt_lock_owner_list_or_fail_stop();
            if (!aqt_issuer_choreography_formal_force_revoke_normal_is_exact_locked(
                    shadow, request, &expected, &candidate
                )) {
                saved_errno = EIO;
                request->authority_proof_failed = 1U;
            }
        }
        if (saved_errno == 0) {
            primary_kind = aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE,
                1,
                current_pid,
                current_interpreter
            );
        }
    }
    if (primary_kind < 0 && saved_errno == 0
        && candidate_was_stored
        && !aqt_issuer_choreography_formal_force_revoke_normal_is_exact_locked(
            shadow, request, &expected, &candidate
        )) {
        saved_errno = EIO;
        request->authority_proof_failed = 1U;
    }
    if (primary_kind < 0 && saved_errno == 0 && candidate_was_stored) {
        primary_kind = fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
            ? AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR
            : aqt_issuer_choreography_fault_take_locked(
                fault_plan,
                shadow,
                AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
                1,
                current_pid,
                current_interpreter
            );
    }
    if (primary_kind < 0 && saved_errno == 0 && candidate_was_stored) {
        aqt_issuer_choreography_fault_plan_clear(fault_plan);
        aqt_unlock_owner_list_or_fail_stop();
        aqt_free_issuer_projection(&prepared_roots);
        aqt_issuer_choreography_detached_records_release(&detached);
        Py_RETURN_NONE;
    }
    for (index = 0; index < 4; index++) {
        if (!aqt_issuer_choreography_formal_force_revoke_cleanup_reconcile_locked(
                shadow,
                request,
                &expected,
                &candidate,
                candidate_was_stored,
                &prepared_roots,
                &detached_projection,
                &detached
            )) {
            aqt_fail_stop(
                "native issuer choreography formal force revocation cleanup attempt failed"
            );
        }
        if (index == 0
            && fork_point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT) {
            aqt_issuer_foreign_fork_bind_formal_force_revoke_locked(
                shadow,
                &expected,
                &candidate,
                candidate_was_stored,
                request
            );
            if (aqt_issuer_foreign_fork_interpose_locked(
                    shadow,
                    AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
                ) < 0) {
                abort();
            }
            fork_was_triggered = 1;
        }
        cleanup_kinds[index] = aqt_issuer_choreography_fault_take_locked(
            fault_plan,
            shadow,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT,
            index + 1,
            current_pid,
            current_interpreter
        );
    }
    if (!aqt_issuer_choreography_formal_force_revoke_cleanup_reconcile_locked(
            shadow,
            request,
            &expected,
            &candidate,
            candidate_was_stored,
            &prepared_roots,
            &detached_projection,
            &detached
        )) {
        aqt_fail_stop(
            "native issuer choreography formal force revocation cleanup confirmation failed"
        );
    }
    if (fork_was_triggered && !fork_commit_completed) {
        aqt_issuer_foreign_fork_commit_locked(
            shadow,
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        );
        fork_commit_completed = 1;
    }
    aqt_issuer_choreography_fault_plan_clear(fault_plan);
    aqt_unlock_owner_list_or_fail_stop();
    if (fork_was_triggered && fork_commit_completed
        && fork_point
            == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT
        && aqt_issuer_foreign_fork_wait_for_value(
            &module_state->issuer_foreign_fork_plan.worker_completed, 1
        ) < 0) {
        aqt_fail_stop(
            "native issuer formal force revocation cleanup foreign-fork worker timed out"
        );
    }
    aqt_free_issuer_projection(&prepared_roots);
    aqt_free_issuer_projection(&detached_projection);
    aqt_issuer_choreography_detached_records_release(&detached);
    if (primary_kind >= 0) {
        aqt_issuer_failure_record_synthetic(&failure, primary_kind);
    }
    else {
        aqt_issuer_failure_record_errno(
            &failure, saved_errno != 0 ? saved_errno : EIO
        );
    }
    for (index = 0; index < 4; index++) {
        if (cleanup_kinds[index] >= 0) {
            aqt_issuer_failure_record_synthetic(
                &failure, cleanup_kinds[index]
            );
        }
    }
    return aqt_issuer_choreography_failure_raise(&failure);
}

