static void
aqt_issuer_choreography_checkpoint_h_record_initialize(
    AqtIssuerChoreographyRecord *record,
    AqtIssuerChoreographyAuthorityCell *cell,
    AqtIssuerChoreographyRecordKey key,
    unsigned int record_class,
    unsigned int kind,
    unsigned int status,
    uint64_t prepared_at_revision,
    uint64_t terminal_revision
)
{
    memset(record, 0, sizeof(*record));
    atomic_init(&record->reference_count, 2U);
    record->cell = cell;
    record->key = key;
    record->prepared_at_revision = prepared_at_revision;
    record->install_or_terminal_state_revision = terminal_revision;
    record->record_class = record_class;
    record->kind = kind;
    record->status = status;
    record->wrapper_live = 1U;
    record->wrapper_was_created = 1U;
}

