typedef struct {
    AqtIssuerChoreographyCheckpointIFixture i;
    AqtIssuerChoreographyRecord controller_checkpoint_record;
    AqtIssuerChoreographyControllerTransitionRequest request;
} AqtIssuerChoreographyCheckpointJFixture;

static int
aqt_issuer_choreography_checkpoint_j_fixture_initialize(
    AqtIssuerChoreographyCheckpointJFixture *fixture,
    unsigned int outcome_kind,
    unsigned int selector,
    uint64_t sampled_now
)
{
    AqtIssuerChoreographyControllerPreparationRequest preparation;
    AqtIssuerChoreographyRecordKey checkpoint_key;

    if (fixture == NULL
        || outcome_kind > AQT_CHOREOGRAPHY_OUTCOME_FAILURE
        || selector >= AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT
        || !aqt_issuer_choreography_checkpoint_i_fixture_initialize(
            &fixture->i
        )) {
        return 0;
    }
    memset(&preparation, 0, sizeof(preparation));
    memset(&fixture->request, 0, sizeof(fixture->request));
    checkpoint_key = (AqtIssuerChoreographyRecordKey){1U, 3U, 6U};
    fixture->i.h.cell.checked_serial = checkpoint_key.serial;
    preparation.selector = selector;
    preparation.outcome_kind = outcome_kind;
    preparation.claim_record = &fixture->i.h.claim_record;
    aqt_issuer_choreography_checkpoint_h_record_initialize(
        &fixture->controller_checkpoint_record,
        &fixture->i.h.cell,
        checkpoint_key,
        AQT_CHOREOGRAPHY_RECORD_WITNESS,
        AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT,
        AQT_CHOREOGRAPHY_WITNESS_PREPARED,
        fixture->i.post_effect_armed.revision,
        0U
    );
    aqt_issuer_choreography_build_controller_preparation_payload_locked(
        &preparation,
        &fixture->i.post_effect_armed,
        sampled_now,
        &fixture->controller_checkpoint_record.payload
    );
    fixture->controller_checkpoint_record.payload.controller_checkpoint.key =
        checkpoint_key;
    fixture->controller_checkpoint_record.prepared_time_selector_present = 1U;
    fixture->controller_checkpoint_record.prepared_time_selector = selector;
    fixture->controller_checkpoint_record.prepared_source_last_monotonic_ns =
        fixture->i.post_effect_armed.last_monotonic_ns;
    fixture->request.operation_tag =
        AQT_CHOREOGRAPHY_OPERATION_BEGIN_CONTROLLER;
    fixture->request.selector = selector;
    fixture->request.outcome_kind = outcome_kind;
    fixture->request.lease_record = &fixture->i.h.lease_record;
    fixture->request.recovery_record = &fixture->i.h.recovery_record;
    fixture->request.claim_record = &fixture->i.h.claim_record;
    fixture->request.post_effect_record = &fixture->i.h.post_effect_record;
    fixture->request.controller_checkpoint_record =
        &fixture->controller_checkpoint_record;
    fixture->request.lease_initial_status_revision =
        fixture->i.h.lease_record.install_or_terminal_state_revision;
    fixture->request.recovery_initial_status_revision =
        fixture->i.h.recovery_record.install_or_terminal_state_revision;
    fixture->request.claim_initial_status_revision =
        fixture->i.h.claim_record.install_or_terminal_state_revision;
    fixture->request.post_effect_initial_status_revision =
        fixture->i.h.post_effect_record.install_or_terminal_state_revision;
    fixture->request.controller_checkpoint_initial_status_revision = 0U;
    fixture->request.source_lifecycle_revision = 3U;
    fixture->request.observed_monotonic_ns =
        fixture->controller_checkpoint_record.payload.controller_checkpoint
            .projection.observed_monotonic_ns;
    fixture->request.source_projection = &fixture->i.h.full_projection;
    fixture->request.source_launch_lease = &fixture->i.h.launch_lease;
    return aqt_issuer_choreography_controller_source_value_is_exact(
            &fixture->i.post_effect_armed
        )
        && aqt_issuer_choreography_record_is_exact_locked(
            &fixture->controller_checkpoint_record,
            &fixture->i.h.cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )
        && aqt_issuer_choreography_controller_checkpoint_summary_matches_value(
            &fixture->controller_checkpoint_record.payload
                .controller_checkpoint,
            &fixture->i.post_effect_armed,
            0
        )
        && aqt_issuer_choreography_cell_is_exact_locked(
            &fixture->i.h.shadow
        );
}

static void
aqt_issuer_choreography_checkpoint_j_publish_fixture_candidate(
    AqtIssuerChoreographyCheckpointJFixture *fixture,
    const AqtIssuerChoreographyStateValue *candidate
)
{
    AqtIssuerChoreographyDetachedRecords detached = {0};

    aqt_issuer_choreography_publish_controller_candidate_locked(
        &fixture->i.h.shadow,
        &fixture->request,
        candidate,
        &detached
    );
}

static int
aqt_issuer_choreography_checkpoint_j_publish_fixture_cleanup(
    AqtIssuerChoreographyCheckpointJFixture *fixture,
    const AqtIssuerChoreographyStateValue *candidate,
    int candidate_was_stored
)
{
    AqtIssuerActivationProjection *prepared_roots =
        &fixture->i.h.roots_projection;
    AqtIssuerActivationProjection *detached_projection = NULL;
    AqtIssuerChoreographyDetachedRecords detached = {0};

    return aqt_issuer_choreography_controller_cleanup_reconcile_locked(
        &fixture->i.h.shadow,
        &fixture->request,
        &fixture->i.post_effect_armed,
        candidate,
        candidate_was_stored,
        &prepared_roots,
        &detached_projection,
        &detached
    );
}

static int
aqt_issuer_choreography_checkpoint_j_controller_transition_self_test(void)
{
    AqtIssuerChoreographyCheckpointJFixture fixture;
    AqtIssuerChoreographyStateValue candidate;
    AqtIssuerChoreographyStateValue zero_candidate;
    AqtIssuerChoreographyRecordKey saved_key;
    unsigned int outcome;
    unsigned int selector;

    for (outcome = AQT_CHOREOGRAPHY_OUTCOME_SUCCESS;
         outcome <= AQT_CHOREOGRAPHY_OUTCOME_FAILURE;
         outcome++) {
        for (selector = AQT_CHOREOGRAPHY_TIME_SAME;
             selector < AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT;
             selector++) {
            if (!aqt_issuer_choreography_checkpoint_j_fixture_initialize(
                    &fixture,
                    outcome,
                    selector,
                    101U
                )) {
                return 0;
            }
            aqt_issuer_choreography_resolve_controller_candidate_locked(
                &fixture.i.post_effect_armed,
                &fixture.controller_checkpoint_record.payload
                    .controller_checkpoint,
                selector,
                &candidate
            );
            if (!aqt_issuer_choreography_controller_candidate_value_is_exact(
                    &fixture.i.post_effect_armed,
                    &candidate
                )) {
                return 0;
            }
            if (selector == AQT_CHOREOGRAPHY_TIME_ROLLBACK
                && candidate.phase
                    != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_UNCONFIRMED) {
                return 0;
            }
            if (outcome == AQT_CHOREOGRAPHY_OUTCOME_SUCCESS
                && (selector == AQT_CHOREOGRAPHY_TIME_ACTION_DEADLINE
                    || selector
                        == AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE)
                && (candidate.phase
                        != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_ARMED
                    || candidate.action_active != 0U
                    || candidate.last_monotonic_ns
                        != fixture.i.post_effect_armed.last_monotonic_ns)) {
                return 0;
            }
            if (outcome == AQT_CHOREOGRAPHY_OUTCOME_FAILURE
                && selector == AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE
                && candidate.phase != AQT_CHOREOGRAPHY_PHASE_EXPIRED) {
                return 0;
            }
            if (selector == AQT_CHOREOGRAPHY_TIME_SAME
                && candidate.phase
                    != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONSUMING) {
                return 0;
            }
        }
    }
    if (!aqt_issuer_choreography_checkpoint_j_fixture_initialize(
            &fixture,
            AQT_CHOREOGRAPHY_OUTCOME_SUCCESS,
            AQT_CHOREOGRAPHY_TIME_SAME,
            0U
        )) {
        return 0;
    }
    aqt_issuer_choreography_resolve_controller_candidate_locked(
        &fixture.i.post_effect_armed,
        &fixture.controller_checkpoint_record.payload.controller_checkpoint,
        fixture.request.selector,
        &candidate
    );
    if (!aqt_issuer_choreography_controller_candidate_matches_request(
            &fixture.request,
            &fixture.i.post_effect_armed,
            &candidate
        )) {
        return 0;
    }
    aqt_issuer_choreography_build_controller_unconfirmed_value(
        &fixture.i.post_effect_armed,
        fixture.i.post_effect_armed.revision + 1U,
        0,
        &candidate
    );
    if (aqt_issuer_choreography_controller_candidate_matches_request(
            &fixture.request,
            &fixture.i.post_effect_armed,
            &candidate
        )) {
        return 0;
    }
    if (!aqt_issuer_choreography_checkpoint_j_fixture_initialize(
            &fixture,
            AQT_CHOREOGRAPHY_OUTCOME_SUCCESS,
            AQT_CHOREOGRAPHY_TIME_SAMPLE,
            100U
        )) {
        return 0;
    }
    fixture.controller_checkpoint_record.prepared_time_selector_present = 0U;
    if (aqt_issuer_choreography_record_is_exact_locked(
            &fixture.controller_checkpoint_record,
            &fixture.i.h.cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )) {
        return 0;
    }
    fixture.controller_checkpoint_record.prepared_time_selector_present = 1U;
    fixture.controller_checkpoint_record.payload.controller_checkpoint
        .projection.selected_deadline_monotonic_ns++;
    if (aqt_issuer_choreography_record_is_exact_locked(
            &fixture.controller_checkpoint_record,
            &fixture.i.h.cell,
            AQT_CHOREOGRAPHY_RECORD_WITNESS,
            AQT_CHOREOGRAPHY_WITNESS_CONTROLLER_CHECKPOINT
        )) {
        return 0;
    }
    if (!aqt_issuer_choreography_checkpoint_j_fixture_initialize(
            &fixture,
            AQT_CHOREOGRAPHY_OUTCOME_SUCCESS,
            AQT_CHOREOGRAPHY_TIME_SAME,
            0U
        )) {
        return 0;
    }
    aqt_issuer_choreography_resolve_controller_candidate_locked(
        &fixture.i.post_effect_armed,
        &fixture.controller_checkpoint_record.payload.controller_checkpoint,
        AQT_CHOREOGRAPHY_TIME_SAME,
        &candidate
    );
    aqt_issuer_choreography_checkpoint_j_publish_fixture_candidate(
        &fixture,
        &candidate
    );
    if (candidate.phase != AQT_CHOREOGRAPHY_PHASE_POST_EFFECT_CONSUMING
        || !aqt_issuer_choreography_state_snapshot_phase_is_available(
            candidate.phase
        )
        || !aqt_issuer_choreography_state_snapshot_controller_checkpoint_key_is_present(
            &candidate
        )) {
        return 0;
    }
    saved_key = candidate.controller_checkpoint.key;
    memset(
        &candidate.controller_checkpoint.key,
        0,
        sizeof(candidate.controller_checkpoint.key)
    );
    if (aqt_issuer_choreography_state_snapshot_controller_checkpoint_key_is_present(
            &candidate
        )) {
        return 0;
    }
    candidate.controller_checkpoint.key = saved_key;
    if (!aqt_issuer_choreography_checkpoint_j_publish_fixture_cleanup(
            &fixture,
            &candidate,
            1
        )
        || !aqt_issuer_choreography_controller_cleanup_records_are_exact_locked(
            &fixture.request,
            &fixture.i.post_effect_armed,
            &candidate,
            1,
            &fixture.i.h.shadow.choreography_state,
            &fixture.i.h.cell
        )) {
        return 0;
    }
    fixture.i.h.lease_record.key.serial++;
    if (aqt_issuer_choreography_controller_cleanup_records_are_exact_locked(
            &fixture.request,
            &fixture.i.post_effect_armed,
            &candidate,
            1,
            &fixture.i.h.shadow.choreography_state,
            &fixture.i.h.cell
        )) {
        return 0;
    }
    fixture.i.h.lease_record.key.serial--;
    fixture.i.h.recovery_record.payload.claim.key.serial = 1U;
    if (aqt_issuer_choreography_controller_cleanup_records_are_exact_locked(
            &fixture.request,
            &fixture.i.post_effect_armed,
            &candidate,
            1,
            &fixture.i.h.shadow.choreography_state,
            &fixture.i.h.cell
        )) {
        return 0;
    }
    fixture.i.h.recovery_record.payload.claim.key.serial = 0U;
    fixture.controller_checkpoint_record.install_or_terminal_state_revision--;
    if (aqt_issuer_choreography_controller_cleanup_records_are_exact_locked(
            &fixture.request,
            &fixture.i.post_effect_armed,
            &candidate,
            1,
            &fixture.i.h.shadow.choreography_state,
            &fixture.i.h.cell
        )) {
        return 0;
    }
    fixture.controller_checkpoint_record.install_or_terminal_state_revision++;
    fixture.i.h.shadow.choreography_state.failclosed_origin.operation_tag =
        AQT_CHOREOGRAPHY_OPERATION_REQUIRE_POST_EFFECT;
    if (aqt_issuer_choreography_controller_failclosed_origin_is_exact_locked(
            &fixture.i.h.shadow.choreography_state
        )) {
        return 0;
    }

    memset(&zero_candidate, 0, sizeof(zero_candidate));
    return aqt_issuer_choreography_memory_is_zero(
        &zero_candidate,
        sizeof(zero_candidate)
    );
}

static void
aqt_issuer_foreign_fork_checkpoint_j_plan_initialize(
    AqtIssuerForeignForkPlan *plan,
    AqtIssuerChoreographyCheckpointJFixture *fixture,
    const AqtIssuerChoreographyStateValue *candidate,
    int candidate_is_present,
    int point
)
{
    aqt_issuer_foreign_fork_plan_initialize(plan);
    plan->shadow = &fixture->i.h.shadow;
    plan->point = point;
    plan->choreography_operation_tag =
        AQT_CHOREOGRAPHY_OPERATION_BEGIN_CONTROLLER;
    plan->choreography_candidate_is_present = candidate_is_present;
    plan->choreography_source_was_burned =
        (int)fixture->request.source_was_burned;
    plan->choreography_authority_proof_failed =
        (int)fixture->request.authority_proof_failed;
    plan->choreography_controller_outcome_kind =
        (int)fixture->request.outcome_kind;
    plan->choreography_controller_time_selector =
        (int)fixture->request.selector;
    plan->choreography_expected = fixture->i.post_effect_armed;
    if (candidate_is_present) {
        plan->choreography_candidate = *candidate;
    }
    plan->choreography_lease_record = &fixture->i.h.lease_record;
    plan->choreography_recovery_record = &fixture->i.h.recovery_record;
    plan->choreography_claim_record = &fixture->i.h.claim_record;
    plan->choreography_post_effect_record = &fixture->i.h.post_effect_record;
    plan->choreography_controller_checkpoint_record =
        &fixture->controller_checkpoint_record;
    plan->choreography_lease_initial_status_revision =
        fixture->request.lease_initial_status_revision;
    plan->choreography_recovery_initial_status_revision =
        fixture->request.recovery_initial_status_revision;
    plan->choreography_claim_initial_status_revision =
        fixture->request.claim_initial_status_revision;
    plan->choreography_post_effect_initial_status_revision =
        fixture->request.post_effect_initial_status_revision;
    plan->choreography_controller_checkpoint_initial_status_revision =
        fixture->request.controller_checkpoint_initial_status_revision;
    plan->choreography_observed_monotonic_ns =
        fixture->request.observed_monotonic_ns;
    plan->choreography_source_lifecycle_revision =
        fixture->request.source_lifecycle_revision;
    plan->choreography_source_projection = fixture->request.source_projection;
    plan->choreography_source_launch_lease =
        fixture->request.source_launch_lease;
}

