static int
aqt_issuer_foreign_fork_checkpoint_m_flag_matrix_self_test(void)
{
    static const int points[] = {
        AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT,
        AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT,
    };
    size_t point_index;
    unsigned int bits;

    for (point_index = 0U;
         point_index < sizeof(points) / sizeof(points[0]);
         point_index++) {
        for (bits = 0U; bits < 64U; bits++) {
            unsigned int authority_failed = bits & 1U;
            unsigned int durability_failed = (bits >> 1U) & 1U;
            unsigned int terminal_attempted = (bits >> 2U) & 1U;
            unsigned int terminal_completed = (bits >> 3U) & 1U;
            unsigned int cleanup_attempted = (bits >> 4U) & 1U;
            unsigned int cleanup_completed = (bits >> 5U) & 1U;
            int expected_valid;
            int observed_valid;

            if (points[point_index]
                    == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT) {
                expected_valid = bits == 0U;
            }
            else {
                int safe_terminal = authority_failed == 0U
                    && durability_failed == 0U
                    && terminal_attempted == 1U
                    && terminal_completed == 1U
                    && cleanup_attempted == 0U
                    && cleanup_completed == 0U;
                int safe_cleanup = authority_failed == 0U
                    && durability_failed == 0U
                    && terminal_attempted == 0U
                    && terminal_completed == 0U
                    && cleanup_attempted == 1U
                    && cleanup_completed == 1U;
                int hard_initial = authority_failed == 1U
                    && durability_failed == 1U
                    && terminal_attempted == 0U
                    && terminal_completed == 0U
                    && cleanup_attempted == 0U
                    && cleanup_completed == 0U;
                int hard_terminal = authority_failed <= durability_failed
                    && durability_failed == 1U
                    && terminal_attempted == 1U
                    && terminal_completed == 0U
                    && cleanup_attempted == 0U
                    && cleanup_completed == 0U;
                int hard_cleanup = authority_failed <= durability_failed
                    && durability_failed == 1U
                    && terminal_attempted == 0U
                    && terminal_completed == 0U
                    && cleanup_attempted == 1U
                    && cleanup_completed == 0U;

                expected_valid = safe_terminal || safe_cleanup
                    || hard_initial || hard_terminal || hard_cleanup;
            }
            observed_valid =
                aqt_issuer_foreign_fork_controller_abandon_flag_tuple_is_exact(
                    points[point_index],
                    authority_failed,
                    durability_failed,
                    terminal_attempted,
                    terminal_completed,
                    cleanup_attempted,
                    cleanup_completed
                );
            if (observed_valid != expected_valid) {
                return 0;
            }
        }
    }
    return !aqt_issuer_foreign_fork_controller_abandon_flag_tuple_is_exact(
            -1, 0U, 0U, 0U, 0U, 0U, 0U
        )
        && !aqt_issuer_foreign_fork_controller_abandon_flag_tuple_is_exact(
            AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT,
            2U, 1U, 0U, 0U, 0U, 0U
        );
}

