    wrong_outcome = outcome_kind == AQT_CHOREOGRAPHY_OUTCOME_SUCCESS
        ? (int)AQT_CHOREOGRAPHY_OUTCOME_FAILURE
        : (int)AQT_CHOREOGRAPHY_OUTCOME_SUCCESS;
    plan.choreography_controller_outcome_kind = wrong_outcome;
