static PyObject *
aqt_fstat_owned(PyObject *module, PyObject *owner_object)
{
    struct stat metadata;
    int fd;
    int result;
    int saved_errno;

    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    aqt_lock_owner_list_or_fail_stop();
    fd = aqt_live_owner_fd_locked(owner_object);
    if (fd < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            fd == -2 ? PyExc_TypeError : PyExc_ValueError,
            fd == -2 ? "owner must be an exact native owned file descriptor" : "owner is closed"
        );
        return NULL;
    }
    result = fstat(fd, &metadata);
    saved_errno = errno;
    aqt_unlock_owner_list_or_fail_stop();
    if (result < 0) {
        errno = saved_errno;
        return PyErr_SetFromErrno(PyExc_OSError);
    }
    return aqt_stat_identity(&metadata);
}

static PyObject *
aqt_statat_owned(PyObject *module, PyObject *args)
{
    PyObject *directory_object;
    PyObject *path;
    PyObject *path_bytes = NULL;
    const char *path_data = NULL;
    struct stat metadata;
    int directory_fd;
    int result;
    int saved_errno;

    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    if (!PyArg_ParseTuple(args, "OO:_statat", &directory_object, &path)) {
        return NULL;
    }
    if (aqt_exact_relative_component(path, &path_bytes, &path_data) < 0) {
        return NULL;
    }
    aqt_lock_owner_list_or_fail_stop();
    directory_fd = aqt_live_owner_profile_fd_locked(
        directory_object,
        AQT_PROFILE_DIRECTORY
    );
    if (directory_fd < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        Py_DECREF(path_bytes);
        PyErr_SetString(
            directory_fd == -2 ? PyExc_TypeError : PyExc_ValueError,
            directory_fd == -2
                ? "directory owner must be an exact native owned file descriptor"
                : (directory_fd == -3
                    ? "directory owner has the wrong native authority profile"
                    : "directory owner is closed")
        );
        return NULL;
    }
    result = fstatat(directory_fd, path_data, &metadata, AT_SYMLINK_NOFOLLOW);
    saved_errno = errno;
    aqt_unlock_owner_list_or_fail_stop();
    Py_DECREF(path_bytes);
    if (result < 0) {
        errno = saved_errno;
        return PyErr_SetFromErrnoWithFilenameObject(PyExc_OSError, path);
    }
    return aqt_stat_identity(&metadata);
}

static PyObject *
aqt_read_snapshot(PyObject *module, PyObject *args)
{
    PyObject *owner_object;
    PyObject *maximum_object;
    PyObject *payload = NULL;
    PyObject *before_identity = NULL;
    PyObject *after_identity = NULL;
    PyObject *result = NULL;
    struct stat before;
    struct stat after;
    long maximum;
    Py_ssize_t total = 0;
    int fd;
    int operation_errno = 0;

    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    if (!PyArg_ParseTuple(args, "OO:_read_snapshot", &owner_object, &maximum_object)) {
        return NULL;
    }
    if (aqt_exact_int(
            maximum_object,
            "maximum_bytes",
            0,
            AQT_MAX_SNAPSHOT_BYTES,
            &maximum
        ) < 0) {
        return NULL;
    }
    payload = PyBytes_FromStringAndSize(NULL, (Py_ssize_t)maximum + 1);
    if (payload == NULL) {
        return NULL;
    }

    aqt_lock_owner_list_or_fail_stop();
    fd = aqt_live_owner_fd_locked(owner_object);
    if (fd < 0) {
        operation_errno = fd == -2 ? EINVAL : EBADF;
    }
    else if (fstat(fd, &before) < 0) {
        operation_errno = errno;
    }
    else if (!S_ISREG(before.st_mode)) {
        operation_errno = EINVAL;
    }
    else {
        while (total < (Py_ssize_t)maximum + 1) {
            ssize_t count = pread(
                fd,
                PyBytes_AS_STRING(payload) + total,
                (size_t)((Py_ssize_t)maximum + 1 - total),
                (off_t)total
            );
            if (count > 0) {
                total += count;
                continue;
            }
            if (count == 0) {
                break;
            }
            if (errno == EINTR) {
                continue;
            }
            operation_errno = errno;
            break;
        }
        if (operation_errno == 0 && fstat(fd, &after) < 0) {
            operation_errno = errno;
        }
    }
    aqt_unlock_owner_list_or_fail_stop();

    if (operation_errno != 0) {
        Py_DECREF(payload);
        if (fd == -2) {
            PyErr_SetString(PyExc_TypeError, "owner must be an exact native owned file descriptor");
            return NULL;
        }
        if (fd == -1) {
            PyErr_SetString(PyExc_ValueError, "owner is closed");
            return NULL;
        }
        errno = operation_errno;
        return PyErr_SetFromErrno(PyExc_OSError);
    }
    if (total > (Py_ssize_t)maximum) {
        Py_DECREF(payload);
        PyErr_SetString(PyExc_ValueError, "owned file snapshot exceeds its byte bound");
        return NULL;
    }
    if (_PyBytes_Resize(&payload, total) < 0) {
        return NULL;
    }
    before_identity = aqt_stat_identity(&before);
    if (before_identity != NULL) {
        after_identity = aqt_stat_identity(&after);
    }
    if (after_identity != NULL) {
        result = PyTuple_Pack(3, payload, before_identity, after_identity);
    }
    Py_XDECREF(after_identity);
    Py_XDECREF(before_identity);
    Py_DECREF(payload);
    return result;
}

typedef struct {
    char *data;
    size_t length;
} AqtDirectoryName;

static void
aqt_free_directory_names(AqtDirectoryName *names, size_t count)
{
    size_t index;

    for (index = 0; index < count; index++) {
        free(names[index].data);
    }
    free(names);
}

static int
aqt_compare_directory_names(const void *left_pointer, const void *right_pointer)
{
    const AqtDirectoryName *left = (const AqtDirectoryName *)left_pointer;
    const AqtDirectoryName *right = (const AqtDirectoryName *)right_pointer;
    size_t common = left->length < right->length ? left->length : right->length;
    int compared = memcmp(left->data, right->data, common);

    if (compared != 0) {
        return compared;
    }
    if (left->length < right->length) {
        return -1;
    }
    if (left->length > right->length) {
        return 1;
    }
    return 0;
}

static PyObject *
aqt_list_snapshot(PyObject *module, PyObject *owner_object)
{
    AqtDirectoryName *names = NULL;
    size_t count = 0;
    size_t capacity = 0;
    size_t total_bytes = 0;
    struct stat before;
    struct stat after;
    DIR *directory = NULL;
    int owner_fd;
    int scan_fd = -1;
    int operation_errno = 0;
    PyObject *name_tuple = NULL;
    PyObject *before_identity = NULL;
    PyObject *after_identity = NULL;
    PyObject *result = NULL;
    size_t index;

    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    aqt_lock_owner_list_or_fail_stop();
    owner_fd = aqt_live_owner_profile_fd_locked(
        owner_object,
        AQT_PROFILE_DIRECTORY
    );
    if (owner_fd < 0) {
        operation_errno = owner_fd == -2 ? EINVAL : EBADF;
    }
    else if (fstat(owner_fd, &before) < 0) {
        operation_errno = errno;
    }
    else if (!S_ISDIR(before.st_mode)) {
        operation_errno = ENOTDIR;
    }
    else {
        scan_fd = openat(owner_fd, ".", O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        if (scan_fd < 0) {
            operation_errno = errno;
        }
    }
    if (operation_errno == 0) {
        directory = fdopendir(scan_fd);
        if (directory == NULL) {
            operation_errno = errno;
            if (close(scan_fd) < 0) {
                aqt_fail_stop("native directory snapshot fdopendir cleanup failed");
            }
        }
    }
    while (operation_errno == 0 && directory != NULL) {
        struct dirent *entry;
        size_t length;
        char *copied;

        errno = 0;
        entry = readdir(directory);
        if (entry == NULL) {
            if (errno != 0) {
                operation_errno = errno;
            }
            break;
        }
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        length = strnlen(entry->d_name, AQT_MAX_DIRECTORY_NAME_BYTES + 1);
        if (length == 0
            || length > AQT_MAX_DIRECTORY_NAME_BYTES
            || count >= AQT_MAX_DIRECTORY_ENTRIES
            || total_bytes > AQT_MAX_DIRECTORY_TOTAL_BYTES - length) {
            operation_errno = EOVERFLOW;
            break;
        }
        if (count == capacity) {
            size_t next_capacity = capacity == 0 ? 16 : capacity * 2;
            AqtDirectoryName *resized = realloc(
                names,
                next_capacity * sizeof(AqtDirectoryName)
            );
            if (resized == NULL) {
                operation_errno = ENOMEM;
                break;
            }
            names = resized;
            capacity = next_capacity;
        }
        copied = malloc(length);
        if (copied == NULL) {
            operation_errno = ENOMEM;
            break;
        }
        memcpy(copied, entry->d_name, length);
        names[count].data = copied;
        names[count].length = length;
        count++;
        total_bytes += length;
    }
    if (directory != NULL && closedir(directory) < 0) {
        aqt_fail_stop("native directory snapshot close failed");
    }
    if (operation_errno == 0 && fstat(owner_fd, &after) < 0) {
        operation_errno = errno;
    }
    aqt_unlock_owner_list_or_fail_stop();

    if (operation_errno != 0) {
        aqt_free_directory_names(names, count);
        if (owner_fd == -2) {
            PyErr_SetString(
                PyExc_TypeError,
                "owner must be an exact native owned file descriptor"
            );
            return NULL;
        }
        if (owner_fd == -1) {
            PyErr_SetString(PyExc_ValueError, "owner is closed");
            return NULL;
        }
        if (owner_fd == -3) {
            PyErr_SetString(
                PyExc_ValueError,
                "owner has the wrong native authority profile"
            );
            return NULL;
        }
        if (operation_errno == ENOMEM) {
            return PyErr_NoMemory();
        }
        errno = operation_errno;
        return PyErr_SetFromErrno(PyExc_OSError);
    }

    if (count > 1) {
        qsort(names, count, sizeof(AqtDirectoryName), aqt_compare_directory_names);
    }
    for (index = 1; index < count; index++) {
        if (aqt_compare_directory_names(&names[index - 1], &names[index]) == 0) {
            aqt_free_directory_names(names, count);
            PyErr_SetString(PyExc_RuntimeError, "native directory snapshot contains duplicates");
            return NULL;
        }
    }
    name_tuple = PyTuple_New((Py_ssize_t)count);
    if (name_tuple != NULL) {
        for (index = 0; index < count; index++) {
            PyObject *name = PyUnicode_DecodeFSDefaultAndSize(
                names[index].data,
                (Py_ssize_t)names[index].length
            );
            if (name == NULL) {
                Py_CLEAR(name_tuple);
                break;
            }
            PyTuple_SET_ITEM(name_tuple, (Py_ssize_t)index, name);
        }
    }
    aqt_free_directory_names(names, count);
    if (name_tuple != NULL) {
        before_identity = aqt_stat_identity(&before);
    }
    if (before_identity != NULL) {
        after_identity = aqt_stat_identity(&after);
    }
    if (after_identity != NULL) {
        result = PyTuple_Pack(3, name_tuple, before_identity, after_identity);
    }
    Py_XDECREF(after_identity);
    Py_XDECREF(before_identity);
    Py_XDECREF(name_tuple);
    return result;
}

static PyObject *
aqt_flock_owned(PyObject *module, PyObject *args)
{
    PyObject *owner_object;
    PyObject *operation_object;
    long operation;
    int fd;
    int call_result;
    int saved_errno;

    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    if (!PyArg_ParseTuple(args, "OO:_flock", &owner_object, &operation_object)) {
        return NULL;
    }
    if (aqt_exact_int(operation_object, "operation", 0, INT_MAX, &operation) < 0) {
        return NULL;
    }
    if (operation != (LOCK_SH | LOCK_NB)
        && operation != (LOCK_EX | LOCK_NB)
        && operation != LOCK_UN) {
        PyErr_SetString(
            PyExc_ValueError,
            "flock operation must be nonblocking shared, nonblocking exclusive, or unlock"
        );
        return NULL;
    }

    aqt_lock_owner_list_or_fail_stop();
    fd = aqt_live_owner_fd_locked(owner_object);
    if (fd < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            fd == -2 ? PyExc_TypeError : PyExc_ValueError,
            fd == -2 ? "owner must be an exact native owned file descriptor" : "owner is closed"
        );
        return NULL;
    }
    do {
        call_result = flock(fd, (int)operation);
    } while (call_result < 0 && errno == EINTR);
    saved_errno = errno;
    aqt_unlock_owner_list_or_fail_stop();
    if (call_result < 0) {
        errno = saved_errno;
        return PyErr_SetFromErrno(PyExc_OSError);
    }
    Py_RETURN_NONE;
}

static PyObject *
aqt_fsync_owned(PyObject *module, PyObject *owner_object)
{
    int fd;
    int call_result;
    int saved_errno;

    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    aqt_lock_owner_list_or_fail_stop();
    fd = aqt_live_owner_fd_locked(owner_object);
    if (fd < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            fd == -2 ? PyExc_TypeError : PyExc_ValueError,
            fd == -2 ? "owner must be an exact native owned file descriptor" : "owner is closed"
        );
        return NULL;
    }
    do {
        call_result = fsync(fd);
    } while (call_result < 0 && errno == EINTR);
    saved_errno = errno;
    aqt_unlock_owner_list_or_fail_stop();
    if (call_result < 0) {
        errno = saved_errno;
        return PyErr_SetFromErrno(PyExc_OSError);
    }
    Py_RETURN_NONE;
}

static PyObject *
aqt_write_all_owned(PyObject *module, PyObject *args)
{
    PyObject *owner_object;
    PyObject *payload;
    const char *payload_data;
    Py_ssize_t payload_length;
    Py_ssize_t written = 0;
    struct stat metadata;
    int fd;
    int operation_errno = 0;

    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    if (!PyArg_ParseTuple(args, "OO:_write_all", &owner_object, &payload)) {
        return NULL;
    }
    if (!PyBytes_CheckExact(payload)) {
        PyErr_SetString(PyExc_TypeError, "payload must be exact bytes");
        return NULL;
    }
    payload_data = PyBytes_AS_STRING(payload);
    payload_length = PyBytes_GET_SIZE(payload);
    if (payload_length > AQT_MAX_SNAPSHOT_BYTES) {
        PyErr_SetString(PyExc_ValueError, "payload exceeds the native write bound");
        return NULL;
    }

    aqt_lock_owner_list_or_fail_stop();
    fd = aqt_live_owner_profile_fd_locked(
        owner_object,
        AQT_PROFILE_WRITE_REGULAR
    );
    if (fd < 0) {
        operation_errno = fd == -2 ? EINVAL : EBADF;
    }
    else if (fstat(fd, &metadata) < 0) {
        operation_errno = errno;
    }
    else if (!S_ISREG(metadata.st_mode)) {
        operation_errno = EINVAL;
    }
    while (operation_errno == 0 && written < payload_length) {
        ssize_t count = pwrite(
            fd,
            payload_data + written,
            (size_t)(payload_length - written),
            (off_t)written
        );

        if (count > 0) {
            written += count;
        }
        else if (count < 0 && errno == EINTR) {
            continue;
        }
        else {
            operation_errno = count == 0 ? EIO : errno;
        }
    }
    aqt_unlock_owner_list_or_fail_stop();

    if (operation_errno != 0) {
        if (fd == -2) {
            PyErr_SetString(PyExc_TypeError, "owner must be an exact native owned file descriptor");
            return NULL;
        }
        if (fd == -1) {
            PyErr_SetString(PyExc_ValueError, "owner is closed");
            return NULL;
        }
        if (fd == -3) {
            PyErr_SetString(PyExc_ValueError, "owner is not a writable regular-file authority");
            return NULL;
        }
        errno = operation_errno;
        return PyErr_SetFromErrno(PyExc_OSError);
    }
    Py_RETURN_NONE;
}

static PyObject *
aqt_ftruncate_owned(PyObject *module, PyObject *args)
{
    PyObject *owner_object;
    PyObject *length_object;
    long length;
    int fd;
    int call_result;
    int saved_errno;

    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    if (!PyArg_ParseTuple(args, "OO:_ftruncate", &owner_object, &length_object)) {
        return NULL;
    }
    if (aqt_exact_int(
            length_object,
            "length",
            0,
            AQT_MAX_SNAPSHOT_BYTES,
            &length
        ) < 0) {
        return NULL;
    }
    aqt_lock_owner_list_or_fail_stop();
    fd = aqt_live_owner_profile_fd_locked(
        owner_object,
        AQT_PROFILE_WRITE_REGULAR
    );
    if (fd < 0) {
        aqt_unlock_owner_list_or_fail_stop();
        PyErr_SetString(
            fd == -2 ? PyExc_TypeError : PyExc_ValueError,
            fd == -2
                ? "owner must be an exact native owned file descriptor"
                : (fd == -3
                    ? "owner is not a writable regular-file authority"
                    : "owner is closed")
        );
        return NULL;
    }
    do {
        call_result = ftruncate(fd, (off_t)length);
    } while (call_result < 0 && errno == EINTR);
    saved_errno = errno;
    aqt_unlock_owner_list_or_fail_stop();
    if (call_result < 0) {
        errno = saved_errno;
        return PyErr_SetFromErrno(PyExc_OSError);
    }
    Py_RETURN_NONE;
}

