static PyObject *
aqt_open_owned_native(
    PyObject *path,
    AqtOwnedFileDescriptor *directory_owner,
    int flags,
    mode_t mode,
    int expected_kind,
    unsigned int owner_profile
)
{
    PyObject *path_bytes = NULL;
    const char *path_data = NULL;
    AqtOwnedFileDescriptor *owner = NULL;
    int directory_fd = -1;
    int opened_fd;
    int saved_errno;
    int validation_result = 0;
    Py_ssize_t path_length;
    struct stat opened_metadata;

    if (aqt_exact_path_bytes(path, &path_bytes, &path_data, &path_length) < 0) {
        return NULL;
    }
    if (directory_owner == NULL && (path_length != 1 || path_data[0] != '/')) {
        Py_DECREF(path_bytes);
        PyErr_SetString(PyExc_ValueError, "path must be the absolute root without dir_fd");
        return NULL;
    }
    if (directory_owner != NULL) {
        if (path_data[0] == '/'
            || memchr(path_data, '/', (size_t)path_length) != NULL
            || (path_length == 1 && path_data[0] == '.')
            || (path_length == 2 && path_data[0] == '.' && path_data[1] == '.')) {
            Py_DECREF(path_bytes);
            PyErr_SetString(PyExc_ValueError, "path must be one relative component with dir_fd");
            return NULL;
        }
    }
    owner = aqt_allocate_owner(owner_profile);
    if (owner == NULL) {
        Py_DECREF(path_bytes);
        return NULL;
    }

    aqt_lock_owner_list_or_fail_stop();
    if (directory_owner != NULL) {
        directory_fd = aqt_live_owner_profile_fd_locked(
            (PyObject *)directory_owner,
            AQT_PROFILE_DIRECTORY
        );
        if (directory_fd < 0) {
            aqt_unlock_owner_list_or_fail_stop();
            Py_DECREF(path_bytes);
            Py_DECREF(owner);
            PyErr_SetString(
                PyExc_ValueError,
                directory_fd == -3
                    ? "directory owner has the wrong native authority profile"
                    : "directory owner is closed"
            );
            return NULL;
        }
    }

    aqt_link_owner_locked(&owner->owner);
    if (directory_owner == NULL) {
        opened_fd = aqt_open_path_native(
            path_data,
            flags,
            mode,
            &owner->owner
        );
    }
    else {
        opened_fd = aqt_openat_native(
            directory_fd,
            path_data,
            flags,
            mode,
            &owner->owner
        );
    }
    saved_errno = errno;
    if (opened_fd >= 0) {
        /* No Python API, callback, signal check, or GIL release precedes this store. */
        atomic_store_explicit(&owner->owner.fd, opened_fd, memory_order_release);
        validation_result = fstat(opened_fd, &opened_metadata);
        if (validation_result < 0) {
            saved_errno = errno;
        }
        else if ((expected_kind == AQT_EXPECT_DIRECTORY
                    && !S_ISDIR(opened_metadata.st_mode))
                || (expected_kind == AQT_EXPECT_REGULAR
                    && !S_ISREG(opened_metadata.st_mode))) {
            validation_result = -1;
            saved_errno = expected_kind == AQT_EXPECT_DIRECTORY ? ENOTDIR : EINVAL;
        }
        if (validation_result < 0) {
            int close_errno = 0;

            if (aqt_close_owner_locked(&owner->owner, &close_errno) < 0) {
                aqt_fail_stop("native owned-file-descriptor validation cleanup failed");
            }
            opened_fd = -1;
        }
    }
    else {
        aqt_unlink_owner_locked(&owner->owner);
    }
    aqt_unlock_owner_list_or_fail_stop();

    Py_DECREF(path_bytes);
    if (opened_fd < 0) {
        Py_DECREF(owner);
        errno = saved_errno;
        return PyErr_SetFromErrnoWithFilenameObject(PyExc_OSError, path);
    }
    return (PyObject *)owner;
}

static PyObject *
aqt_open_root_directory(PyObject *module, PyObject *Py_UNUSED(ignored))
{
    PyObject *path;
    PyObject *result;

    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    path = PyUnicode_FromString("/");
    if (path == NULL) {
        return NULL;
    }
    result = aqt_open_owned_native(
        path,
        NULL,
        O_RDONLY | O_CLOEXEC | O_DIRECTORY | O_NOFOLLOW,
        0,
        AQT_EXPECT_DIRECTORY,
        AQT_PROFILE_DIRECTORY
    );
    Py_DECREF(path);
    return result;
}

static PyObject *
aqt_open_child_with_profile(
    PyObject *args,
    int flags,
    mode_t mode,
    const char *parse_name,
    unsigned int owner_profile
)
{
    PyObject *directory_object;
    PyObject *path;

    if (!PyArg_ParseTuple(args, parse_name, &directory_object, &path)) {
        return NULL;
    }
    if (!Py_IS_TYPE(directory_object, &AqtOwnedFileDescriptorType)) {
        PyErr_SetString(
            PyExc_TypeError,
            "directory owner must be an exact native owned file descriptor"
        );
        return NULL;
    }
    return aqt_open_owned_native(
        path,
        (AqtOwnedFileDescriptor *)directory_object,
        flags,
        mode,
        flags & O_DIRECTORY ? AQT_EXPECT_DIRECTORY : AQT_EXPECT_REGULAR,
        owner_profile
    );
}

static PyObject *
aqt_open_child_directory(PyObject *module, PyObject *args)
{
    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    return aqt_open_child_with_profile(
        args,
        O_RDONLY | O_CLOEXEC | O_DIRECTORY | O_NOFOLLOW,
        0,
        "OO:_open_child_directory",
        AQT_PROFILE_DIRECTORY
    );
}

static PyObject *
aqt_open_child_regular(PyObject *module, PyObject *args)
{
    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    return aqt_open_child_with_profile(
        args,
        O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK | O_NOCTTY,
        0,
        "OO:_open_child_regular",
        AQT_PROFILE_READ_REGULAR
    );
}

static PyObject *
aqt_create_child_regular_exclusive(PyObject *module, PyObject *args)
{
    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    return aqt_open_child_with_profile(
        args,
        O_RDWR | O_CLOEXEC | O_NOFOLLOW | O_CREAT | O_EXCL,
        0600,
        "OO:_create_child_regular_exclusive",
        AQT_PROFILE_WRITE_REGULAR
    );
}

