static PyObject *
aqt_test_configure_topology_observation_issuer_shadow_choreography_failure(
    PyObject *module,
    PyObject *args
)
{
    AqtModuleState *module_state;
    AqtIssuerChoreographyFaultPlan *plan;
    AqtIssuerChoreographyFaultRow *target = NULL;
    AqtIssuerForeignForkPlan *fork_plan;
    PyObject *point_object;
    PyObject *kind_object;
    PyObject *occurrence_object;
    long point;
    long kind;
    long occurrence;
    int group;
    int invalid = 0;
    size_t index;

    if (aqt_require_active_module(module) < 0) {
        return NULL;
    }
    if (!PyArg_ParseTuple(
            args,
            "OOO:_test_configure_topology_observation_issuer_shadow_choreography_failure",
            &point_object,
            &kind_object,
            &occurrence_object
        )) {
        return NULL;
    }
    if (aqt_exact_int(
            point_object,
            "point",
            -1,
            AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN,
            &point
        ) < 0
        || aqt_exact_int(
            kind_object,
            "kind",
            0,
            AQT_ISSUER_FAULT_KIND_SYSTEM_EXIT,
            &kind
        ) < 0
        || aqt_exact_int(
            occurrence_object,
            "occurrence",
            0,
            4,
            &occurrence
        ) < 0) {
        return NULL;
    }
    module_state = (AqtModuleState *)PyModule_GetState(module);
    if (module_state == NULL) {
        return NULL;
    }
    plan = &module_state->issuer_choreography_fault_plan;
    fork_plan = atomic_load_explicit(
        &aqt_active_issuer_foreign_fork_plan,
        memory_order_acquire
    );
    aqt_lock_owner_list_or_fail_stop();
    if (point == -1) {
        invalid = kind != 0 || occurrence != 0 || plan->operation_active;
        if (!invalid) {
            aqt_issuer_choreography_fault_plan_clear(plan);
        }
        aqt_unlock_owner_list_or_fail_stop();
        if (invalid) {
            PyErr_SetString(
                PyExc_ValueError,
                "native issuer choreography fault reset is invalid"
            );
            return NULL;
        }
        Py_RETURN_NONE;
    }
    group = (int)aqt_issuer_choreography_fault_groups[point];
    invalid = occurrence < 1
        || occurrence
            > (long)aqt_issuer_choreography_fault_max_occurrences[point]
        || plan->operation_active
        || plan->row_count >= AQT_ISSUER_CHOREOGRAPHY_FAULT_ROWS
        || (plan->row_count != 0 && plan->group != group)
        || (group == 2
            && fork_plan != NULL
            && fork_plan->point
                == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_REGISTER_POST_STATE_COMMIT)
        || (group == 3
            && fork_plan != NULL
            && (fork_plan->point
                    == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT
                || fork_plan->point
                    == AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT));
    for (index = 0; index < AQT_ISSUER_CHOREOGRAPHY_FAULT_ROWS; index++) {
        AqtIssuerChoreographyFaultRow *row = &plan->rows[index];

        if (row->active
            && row->point == point
            && row->occurrence == occurrence) {
            invalid = 1;
        }
        if (!row->active && target == NULL) {
            target = row;
        }
    }
    if (target == NULL) {
        invalid = 1;
    }
    if (!invalid) {
        target->point = (int)point;
        target->kind = (int)kind;
        target->occurrence = (int)occurrence;
        target->active = 1;
        plan->row_count++;
        plan->group = group;
    }
    aqt_unlock_owner_list_or_fail_stop();
    if (invalid) {
        PyErr_SetString(
            PyExc_RuntimeError,
            "native issuer choreography fault plan is invalid"
        );
        return NULL;
    }
    Py_RETURN_NONE;
}

