static int
aqt_module_exec(PyObject *module)
{
    AqtModuleState *state;
    _Atomic int atomic_probe;
    int once_result;
#if defined(AQT_NATIVE_EMBEDDED_LAUNCHER)
    int expected_activation = 0;
#endif

    state = (AqtModuleState *)PyModule_GetState(module);
    if (state == NULL) {
        return -1;
    }
    if (state->initialized != 0) {
        PyErr_SetString(PyExc_ImportError, "native descriptor module was already initialized");
        return -1;
    }
#if defined(AQT_NATIVE_EMBEDDED_LAUNCHER)
    if (!atomic_compare_exchange_strong_explicit(
            &aqt_process_module_activation,
            &expected_activation,
            1,
            memory_order_acq_rel,
            memory_order_acquire
        )) {
        PyErr_SetString(PyExc_ImportError, "native descriptor process activation was consumed");
        return -1;
    }
#endif
    state->initialized = 1;
    state->issuer_type_phase = 0;
    state->origin_pid = (pid_t)-1;
#if defined(AQT_NATIVE_TEST_HOOKS)
    aqt_issuer_fault_plan_clear(&state->issuer_lifecycle_fault_plan);
    aqt_issuer_choreography_fault_plan_clear(
        &state->issuer_choreography_fault_plan
    );
    atomic_init(&state->issuer_external_projection_barrier, 0U);
    aqt_issuer_foreign_fork_plan_initialize(
        &state->issuer_foreign_fork_plan
    );
#endif
#if defined(AQT_NATIVE_TEST_FAIL_EXEC)
    PyErr_SetString(PyExc_ImportError, "forced native module exec failure for testing");
    return -1;
#endif
    atomic_init(&atomic_probe, -1);
    if (PyInterpreterState_Get() != PyInterpreterState_Main()) {
        PyErr_SetString(
            PyExc_ImportError,
            "native owned-file-descriptor supports only the main interpreter"
        );
        return -1;
    }
    if (!atomic_is_lock_free(&atomic_probe)) {
        PyErr_SetString(PyExc_ImportError, "native descriptor atomics are not lock-free");
        return -1;
    }
    if (aqt_validate_module_origin() < 0) {
        return -1;
    }
#if defined(AQT_NATIVE_TEST_HOOKS)
    if (!aqt_issuer_choreography_manifests_are_exact()
        || !atomic_is_lock_free(
            &aqt_next_issuer_choreography_lifetime_generation
        )
        || !aqt_issuer_foreign_fork_plan_is_absent(
            &state->issuer_foreign_fork_plan
        )) {
        PyErr_SetString(
            PyExc_ImportError,
            "native issuer choreography checkpoint manifest is invalid"
        );
        return -1;
    }
#endif
    once_result = pthread_once(&aqt_atfork_once, aqt_register_atfork);
    if (once_result != 0 || aqt_atfork_registration_error != 0) {
        PyErr_SetString(PyExc_ImportError, "native descriptor atfork registration failed");
        return -1;
    }
    if (PyType_Ready(&AqtOwnedFileDescriptorType) < 0) {
        return -1;
    }
    if (PyType_Ready(&AqtTrustedTimeLaunchLockLeaseType) < 0) {
        return -1;
    }
#if defined(AQT_NATIVE_TEST_HOOKS)
    if (PyType_Ready(&AqtIssuerChoreographyAuthorityType) < 0
        || PyType_Ready(&AqtIssuerChoreographyWitnessType) < 0
        || PyType_Ready(&AqtIssuerClaimedFenceAuthorizationType) < 0
        || PyType_Ready(&AqtTopologyObservationIssuerShadowType) < 0) {
        return -1;
    }
#endif
    if (PyModule_AddObjectRef(
            module,
            "_OwnedFileDescriptor",
            (PyObject *)&AqtOwnedFileDescriptorType
        ) < 0) {
        return -1;
    }
    if (PyModule_AddObjectRef(
            module,
            "_TrustedTimeLaunchLockLease",
            (PyObject *)&AqtTrustedTimeLaunchLockLeaseType
        ) < 0) {
        return -1;
    }
    state->origin_pid = getpid();
    state->initialized = 2;
#if defined(AQT_NATIVE_EMBEDDED_LAUNCHER)
    atomic_store_explicit(&aqt_process_module_activation, 2, memory_order_release);
#endif
    return 0;
}

static int
aqt_module_traverse(PyObject *module, visitproc visit, void *arg)
{
    (void)module;
    (void)visit;
    (void)arg;
    return 0;
}

static int
aqt_module_clear(PyObject *module)
{
#if defined(AQT_NATIVE_TEST_HOOKS)
    AqtModuleState *state = (AqtModuleState *)PyModule_GetState(module);

    if (state != NULL) {
        aqt_issuer_fault_plan_clear(&state->issuer_lifecycle_fault_plan);
        aqt_issuer_choreography_fault_plan_clear(
            &state->issuer_choreography_fault_plan
        );
        aqt_clear_issuer_external_projection_barrier(state);
        aqt_issuer_foreign_fork_cancel_for_module_clear(
            &state->issuer_foreign_fork_plan
        );
    }
#else
    (void)module;
#endif
    return 0;
}

static void
aqt_module_free(void *module)
{
    (void)aqt_module_clear((PyObject *)module);
}

static PyModuleDef_Slot aqt_module_slots[] = {
    {Py_mod_exec, (void *)aqt_module_exec},
    {Py_mod_multiple_interpreters, Py_MOD_MULTIPLE_INTERPRETERS_NOT_SUPPORTED},
    {0, NULL},
};

static struct PyModuleDef aqt_module = {
    PyModuleDef_HEAD_INIT,
    .m_name = AQT_NATIVE_MODULE_NAME,
    .m_doc = "Private native owned-file-descriptor primitive.",
    .m_size = sizeof(AqtModuleState),
    .m_methods = aqt_module_methods,
    .m_slots = aqt_module_slots,
    .m_traverse = aqt_module_traverse,
    .m_clear = aqt_module_clear,
    .m_free = aqt_module_free,
};

PyMODINIT_FUNC
PyInit__native_owned_file_descriptor(void)
{
    return PyModuleDef_Init(&aqt_module);
}
